def _csv_set(name: str):
    """Разобрать список юзернеймов из env (разделитель — запятая/пробел), в lower без @."""
    raw = os.getenv(name, "") or ""
    return {p.strip().lstrip("@").lower() for p in re.split(r"[,\s]+", raw) if p.strip()}


# Право approve/edit/reject. ПУСТОЙ список = любой участник группы может approve.
APPROVER_USERNAMES = _csv_set("APPROVER_USERNAMES")

# Право «учить» бота (перехват реплая-правки/урока на карточке черновика, родитель 292) —
# СТРОЖЕ обычного approve: только владельцы-учителя (Филипп ×2 аккаунта, Даня, Даша).
# Источник — env INTAKE_APPROVERS (CSV юзернеймов); сами юзернеймы в .env, не в коде.
# Пусто → фолбэк на APPROVER_USERNAMES (обучение НЕ шире approve, а не «кто угодно»).
INTAKE_APPROVERS = _csv_set("INTAKE_APPROVERS")

# ----------------------- реестр команды (внутренние аккаунты) ----------------
# ЖЁСТКИЙ блок КОДОМ ДО LLM (родитель: инцидент 15.07 11:23 — userbot сгенерил черновик на
# ЛС офис-менеджера @Pleummmm): сообщения ОТ участников команды и В внутренних группах
# ИСКЛЮЧАЮТСЯ из клиентского конвейера ЦЕЛИКОМ — ни черновиков, ни автоприветствий, ни сбора
# intake. Источник — team_registry.json (usernames/ids вне кода, правится вручную). Сверх файла
# внутренними считаются все approve/intake-аккаунты (staff — НЕ клиенты, черновики им не готовим).
TEAM_REGISTRY_FILE = os.path.join(BASE_DIR, "team_registry.json")


def _norm_window_name(s) -> str:
    """Имя окна к сравнимому виду: lower + ё→е (как в is_partner_chat). Не строка → ''."""
    return str(s or "").strip().lower().replace("ё", "е")


def _load_team_registry(path=None):
    """Прочитать реестр команды из JSON. FAIL-SAFE: нет файла/битый/не-словарь → пустой реестр
    (usernames/user_ids/group_ids + nonclient_*). usernames — lower без @; ids — int (в т.ч.
    отрицательные id групп); nonclient_titles — имена окон, нормализованные lower+ё→е.
    Ключи-мусор игнорируем молча (fail-safe: генерация от реестра не ломается)."""
    path = path or TEAM_REGISTRY_FILE
    try:
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        data = {}
    if not isinstance(data, dict):
        data = {}

    def _ids(seq):
        out = set()
        for x in (seq or []):
            s = str(x).strip()
            if s.lstrip("-").isdigit():
                out.add(int(s))
        return out

    def _unames(seq):
        return {str(u).strip().lstrip("@").lower() for u in (seq or []) if str(u).strip()}

    def _titles(seq):
        return {_norm_window_name(t) for t in (seq or []) if str(t).strip()}

    return {"usernames": _unames(data.get("usernames")),
            "user_ids": _ids(data.get("user_ids")),
            "group_ids": _ids(data.get("group_ids")),
            "nonclient_usernames": _unames(data.get("nonclient_usernames")),
            "nonclient_user_ids": _ids(data.get("nonclient_user_ids")),
            "nonclient_titles": _titles(data.get("nonclient_titles"))}


TEAM_REGISTRY = _load_team_registry()


def reload_team_registry(path=None):
    """Перечитать реестр (горячая замена/тесты). Обновляет глобаль TEAM_REGISTRY, возвращает её."""
    global TEAM_REGISTRY
    TEAM_REGISTRY = _load_team_registry(path)
    return TEAM_REGISTRY


def _team_usernames():
    """Полный набор внутренних usernames: реестр ∪ approve-whitelist ∪ intake-approvers
    (staff-аккаунты — не клиенты; их черновики/приветствия/intake конвейер не готовит)."""
    return TEAM_REGISTRY["usernames"] | APPROVER_USERNAMES | INTAKE_APPROVERS


def is_internal_sender(sender) -> bool:
    """Отправитель — участник команды (по user_id ИЛИ по username)? True → окно диалога
    ИСКЛЮЧАЕТСЯ из клиентского конвейера ЦЕЛИКОМ (ни черновика, ни приветствия, ни intake).
    sender=None → False (обычный путь; блок точечный, не глушит всё при отсутствии данных)."""
    if sender is None:
        return False
    uid = getattr(sender, "id", None)
    if uid is not None and uid in TEAM_REGISTRY["user_ids"]:
        return True
    uname = (getattr(sender, "username", None) or "").lstrip("@").lower()
    return bool(uname) and uname in _team_usernames()


def is_internal_user_id(user_id) -> bool:
    """Второй слой (intake): клиент из intake-записи — участник команды по user_id?
    intake-строка несёт только client_id (без username), поэтому здесь проверка по id."""
    try:
        return int(user_id) in TEAM_REGISTRY["user_ids"]
    except (TypeError, ValueError):
        return False


def is_internal_chat(chat_id) -> bool:
    """Внутренняя (командная/рабочая) группа по id? True → конвейер её не трогает. userbot_listen
    пропускает только ЛС, но групповые/intake-пути должны видеть тот же реестр (defense-in-depth)."""
    try:
        return int(chat_id) in TEAM_REGISTRY["group_ids"]
    except (TypeError, ValueError):
        return False


# --- НЕКЛИЕНТСКИЕ ОКНА, которые НЕ наша команда (партнёры/контрагенты) -------------------------
# Родитель — аудит корпуса 29.07 (docs/artifacts/2026-07-29-draft-audit.md, класс 5): 58 карточек
# из 178 (33%) собраны на окна, где собеседник вообще не клиент. Команду держит is_internal_sender
# (слой 1), но ПАРТНЁР (другой прокат, агент по авто) в реестре команды не значится — и бот отвечал
# ему клиентским прайсом и брал на нас его доставку (живые id=317/342/360, разбор в
# docs/artifacts/2026-07-29-partner-handoff-recon.md). Опознание — ПО ЧИСЛОВОМУ id (главный ключ:
# инцидент 22.07 показал, что username протухает), username/имя окна — ЗАПАСНОЙ путь для окон, чей
# id ещё не снят (группа «Партнёрка STM»). Список — в team_registry.json, дополняется БЕЗ правки кода.
def non_client_window_ref(entity):
    """Окно из НЕклиентского реестра? → метка «кто это и по чему опознан» (непустая строка, для
    лога), иначе None. Порядок: id → username (точно) → имя окна (подстрокой, lower+ё→е).
    entity=None / реестр без ключей nonclient_* (ручной dict в тестах) → None — fail-safe:
    клиентский путь не трогаем. Чистая функция (без сети/LLM)."""
    if entity is None:
        return None
    uname = (getattr(entity, "username", None) or "").lstrip("@").lower()
    uid = getattr(entity, "id", None)
    ref = f"@{uname}" if uname else f"id{uid}"
    try:
        if uid is not None and uid in (TEAM_REGISTRY.get("nonclient_user_ids") or set()):
            return f"{ref} (id {uid}, опознан по id)"
    except TypeError:                       # нехешируемый id — не блокируем (fail-safe)
        pass
    if uname and uname in (TEAM_REGISTRY.get("nonclient_usernames") or set()):
        return f"{ref} (опознан по username)"
    titles = TEAM_REGISTRY.get("nonclient_titles") or set()
    if titles:
        for attr in ("title", "name", "first_name", "last_name"):
            v = getattr(entity, attr, None)
            if isinstance(v, str) and v:
                s = _norm_window_name(v)
                if any(t and t in s for t in titles):
                    return f"«{v}» (опознан по имени окна)"
    return None

