# БЕЛЫЙ СПИСОК УТВЕРЖДАЕМОГО (в промпт ВСЕГДА, рядом с критфактами — высокий приоритет).
# Бот вправе УТВЕРЖДАТЬ клиенту ТОЛЬКО факты из проверяемых источников: цены/депозиты из блока
