# вида «[уточнить: цвет ADV350]». Пометка в квадратных скобках адресована МОДЕРАТОРУ (он уточнит и
# правит перед одобрением) — _strip_service_prefix её не срезает (маркер «[внутренн», не «[уточнить»).
