def _bike_key(name):
    """Имя байка → alnum-ключ (снимаем CC/СС и не-alnum) для матчинга с моделью."""
    s = re.sub(r"(?i)[сc][сc]", "", str(name or ""))   # убрать CC и кириллич. СС
    return re.sub(r"[^a-z0-9]", "", s.lower())


# Откуда взялись имена парка. Разводит случаи, которые раньше сливались в пустой список:
#   live/snapshot — данные есть; empty — мост ответил, парк ПУСТ; none — СБОЙ (попытка была,
#   данных нет ниоткуда); unconfigured — моста в контуре нет вовсе (dev/тесты), это не сбой.
PARK_LIVE, PARK_SNAPSHOT, PARK_EMPTY, PARK_NONE, PARK_UNCONFIGURED = (
    "live", "snapshot", "empty", "none", "unconfigured")


def _read_park_snapshot():
    """Имена из локального снимка park_list.md (Байки.xlsx Лист1). → list[str] ([] если нет)."""
    try:
        names = []
        with open(PARK_LIST_FILE, encoding="utf-8") as f:
            for ln in f:
                if not ln.strip().startswith("|"):
                    continue
                cols = [c.strip() for c in ln.strip().strip("|").split("|")]
                if len(cols) >= 2 and cols[1] and cols[1].lower() not in ("название", "name") \
                        and not set(cols[1]) <= set("- "):   # пропускаем шапку и разделитель |---|
                    names.append(cols[1])
        return names
    except Exception as e:
        log.info(f"park: park_list.md не прочитан ({type(e).__name__})")
        return []


def _park_bike_names_status(getter=None):
    """Имена байков парка + ОТКУДА они взяты. → (list[str], источник из PARK_*).
    Приоритет: живой Bridge (pricing.fleet_status) → снимок park_list.md → ничего."""
    attempted = getter is not None or bool(pricing.BRIDGE_URL and pricing.BRIDGE_TOKEN)
    live_ok = False
    try:
        bikes, live_ok = pricing.fleet_status(_get=getter)
        names = [b.get("name") for b in (bikes or []) if isinstance(b, dict) and b.get("name")]
        if names and live_ok:
            return names, PARK_LIVE
    except Exception as e:
        log.info(f"park: fleet упал ({type(e).__name__}) — пробую park_list.md")
    snap = _read_park_snapshot()
    if snap:
        # Раньше подмена живого парка снимком проходила МОЛЧА — в логе не было ни строки.
        log.warning(f"park: имена взяты из СНИМКА park_list.md ({len(snap)} шт.) — "
                    f"живой парк {'пуст' if live_ok else 'НЕ получен'}")
        return snap, PARK_SNAPSHOT
    if live_ok:
        return [], PARK_EMPTY          # мост ответил: парк действительно пуст — это НЕ сбой
    return [], (PARK_NONE if attempted else PARK_UNCONFIGURED)


def _park_bike_names(getter=None):
    """Имена байков парка (см. _park_bike_names_status). СОВМЕСТИМОСТЬ: только список."""
    return _park_bike_names_status(getter=getter)[0]


def park_allowlist_status(getter=None):
    """Модели парка для показа клиенту + источник. → (list[str] | None, источник).
    None = НЕ ограничивать (fail-safe). Источник PARK_NONE = данных парка нет: вызывающий
    обязан НЕ собирать черновик, а сказать менеджеру."""
    names, source = _park_bike_names_status(getter=getter)
    if not names:
        return None, source
    keys = [_bike_key(n) for n in names]
    allow = [disp for disp, key in KNOWN_MODELS if any(key in k for k in keys)]
    return (allow or None), source   # ни одного совпадения → fail-safe, не ограничиваем на мусоре


def park_allowlist(getter=None):
    """Модели РЕАЛЬНОГО парка (Лист1) для показа клиенту. → list[str] отображаемых имён ИЛИ None.
    None = источник недоступен/пуст → НЕ ограничивать (FAIL-SAFE: бот отвечает как раньше, не онемел).
    СОВМЕСТИМОСТЬ: теряет признак сбоя — новый код зовёт park_allowlist_status()."""
    return park_allowlist_status(getter=getter)[0]


# --- ДЕТЕРМИНИРОВАННЫЙ РЕЗОЛВ МОДЕЛИ (Лист1/_bike_key + алиасы для ВСЕХ моделей) ---------------
# Класс-0 (родитель #253): «XSR 155» детектился в ЛУПНЫЙ canon «XSR» (терялось «155»), а
# pricing._candidates по substring матчил ВСЕ XSR-юниты (155 и 900) — неоднозначно, брал первый
# доступный ⇒ подставлялась ЧУЖАЯ карточка парка (в живом провале — MT-03/≈5166฿, дырой в цене-нот).
# Резолвим детект в КОНКРЕТНУЮ модель парка по _bike_key (тот же нормализатор, что park_allowlist —
# снимает CC/СС). Точная фраза → точная модель; неоднозначная серия (в парке и XSR155, и XSR900) →
# НЕ угадываем и НЕ подставляем — уточняем у клиента.
_KEY_DISPLAY = {key: disp for disp, key in KNOWN_MODELS}   # 'xsr155' -> 'XSR 155'

# Алиас (нормализованный _bike_key детекта) → КОНКРЕТНЫЙ ключ KNOWN_MODELS.
_MODEL_ALIAS = {
    "nmax": "nmax155", "nmax155": "nmax155",
    "xmax": "xmax300", "xmax300": "xmax300",
    "forza": "forza300", "forza300": "forza300",
    "xadv": "xadv750", "xadv750": "xadv750",
    "pcx150": "pcx150", "pcx160": "pcx160",
    "adv150": "adv150", "adv160": "adv160", "adv350": "adv350",
    "xsr155": "xsr155", "xsr900": "xsr900",
    "cb300": "cb300r", "cb300r": "cb300r",
    "cb650": "cb650r", "cb650r": "cb650r",
    "cbr": "cbr650r", "cbr650": "cbr650r", "cbr650r": "cbr650r",
    "rebel": "rebel300", "rebel300": "rebel300",
    "mt": "mt03", "mt03": "mt03",
    "ninja": "ninja400", "ninja400": "ninja400",
    "vulcan": "vulcan650s", "vulcan650": "vulcan650s", "vulcan650s": "vulcan650s",
    "r7": "r7", "click": "click125", "click125": "click125",
}
# СЕРИЯ без уточнения объёма → возможные ключи; конкретную выбираем ПЕРЕСЕЧЕНИЕМ с реальным парком.
_MODEL_SERIES = {
    "xsr": ("xsr155", "xsr900"),
    "adv": ("adv150", "adv160", "adv350"),
    "pcx": ("pcx150", "pcx160"),
    "cb":  ("cb300r", "cb650r"),
}


def _fleet_model_keys(getter=None):
    """Ключи KNOWN_MODELS, реально присутствующие в парке (Лист1) — по _bike_key имён байков.
    Источник недоступен/пуст → None (fail-safe: не резолвим агрессивно, пусть работает как раньше)."""
    names = _park_bike_names(getter=getter)
    if not names:
        return None
    keys = [_bike_key(n) for n in names]
    return {key for _, key in KNOWN_MODELS if any(key in k for k in keys)}


def resolve_park_model(canon, getter=None):
    """Детект модели (canon из _detect_model, напр. «XSR», «XSR 155», «MT-03») → КОНКРЕТНАЯ модель
    парка по Лист1/_bike_key + алиасам. Возвращает (status, display, key):
      'ok'        — однозначная модель парка (display='XSR 155', key='xsr155');
      'ambiguous' — серия (XSR/ADV/…), а в парке НЕСКОЛЬКО вариантов → уточнить у клиента
                    (display=list отображаемых имён, key=None); чужую карточку НЕ подставляем;
      'unknown'   — не распознали / парк недоступен / модель не из серии-развилки → (None, None):
                    fail-safe, вызывающий оставляет исходный canon и идёт прежним путём.
    Инвариант: специфичная фраза клиента резолвится в РОВНО свою модель; голый серийный корень при
    коллизии в парке НЕ угадывается."""
    k = _bike_key(canon)
    if not k:
        return "unknown", None, None
    present = _fleet_model_keys(getter=getter)
    if not present:                                    # парк недоступен → не резолвим (как раньше)
        return "unknown", None, None
    key = _MODEL_ALIAS.get(k)
    if key:
        if key in present:
            return "ok", _KEY_DISPLAY.get(key, canon), key
        return "unknown", None, None                   # известная модель, но НЕ в парке → прежний путь
    if k in _MODEL_SERIES:
        matches = [key for key in _MODEL_SERIES[k] if key in present]
        if len(matches) == 1:
            return "ok", _KEY_DISPLAY.get(matches[0], canon), matches[0]
        if len(matches) >= 2:
            return "ambiguous", [_KEY_DISPLAY.get(x, x) for x in matches], None
        return "unknown", None, None                   # серия не представлена в парке
    return "unknown", None, None


# ------------------------------- playbook (книга правил) ---------------------
# Растущая книга правил (стиль/факты/запреты/выученные правки) — локальный файл. Подмешивается в
# промпт СТРОГО НИЖЕ кап-цены и CRITICAL_FACTS (playbook их НЕ отменяет). Пополняется из одобренных
# правок модератора. Bridge не трогаем — источник локальный.
PLAYBOOK_FILE = os.path.join(BASE_DIR, "manager-bot", "docs", "playbook.md")

# Лимит числа ВЫУЧЕННЫХ правил в книге. Playbook подмешивается в КАЖДЫЙ промпт (и в первичке, и в
# strategy-пути), поэтому не должен расти безгранично — раздутая книга и раздувает промпт, и топит
# свежий урок в старых. При достижении капа новое правило ВЫТЕСНЯЕТ самые ранние (FIFO): последний
# урок учителя важнее давнего. Переопределяется env PLAYBOOK_MAX_RULES; ≤0 → без лимита (fail-open).
PLAYBOOK_MAX_RULES = int(os.getenv("PLAYBOOK_MAX_RULES", "100") or "100")


def load_playbook():
    """Текст книги правил из PLAYBOOK_FILE. Нет файла/пусто/ошибка чтения → '' (FAIL-SAFE:
    генерация не ломается, блок в промпте просто не появляется)."""
    try:
        with open(PLAYBOOK_FILE, encoding="utf-8") as f:
            return f.read().strip()
    except Exception:
        return ""


_LEARNED_HEADER = "## Выученные правила"


def _norm_rule(s):
    """Нормализация правила для дедупа: буквы/цифры/пробелы, нижний регистр, схлопнутые пробелы."""
    return " ".join(re.sub(r"[^0-9a-zа-яё ]+", " ", str(s or "").lower()).split())


def _rules_similar(a, b):
    """Почти-идентичны? (для дедупа): Jaccard слов ≥ 0.6 ИЛИ одно содержится в другом."""
    na, nb = _norm_rule(a), _norm_rule(b)
    if not na or not nb:
        return False
    if na in nb or nb in na:
        return True
    ta, tb = set(na.split()), set(nb.split())
    return (len(ta & tb) / len(ta | tb)) >= 0.6 if (ta and tb) else False


def _playbook_learned_rules(text):
    """Существующие правила из секции «Выученные правила» (без даты-префикса) — для дедупа."""
    out, inside = [], False
    for ln in (text or "").splitlines():
        s = ln.strip()
        if s.startswith("## "):
            inside = s.lower().startswith(_LEARNED_HEADER.lower())
            continue
        if inside and s.startswith("-"):
            r = re.sub(r"^\(\d{4}-\d{2}-\d{2}\)\s*", "", s.lstrip("-").strip())
            if r:
                out.append(r)
    return out


def append_playbook_rule(rule, now=None):
    """Дописать ВЫУЧЕННОЕ правило в playbook.md (секция «Выученные правила», APPEND с датой, не
    перезапись). Дедуп почти-идентичных. → 'added' | 'duplicate' | 'error'.
    FAIL-SAFE: файл недоступен/ошибка записи → 'error' (вызывающий не блокирует отправку черновика)."""
    rule = " ".join(str(rule or "").split()).strip()
    if not rule:
        return "error"
    try:
        with open(PLAYBOOK_FILE, encoding="utf-8") as f:
            text = f.read()
    except Exception:
        return "error"
    if any(_rules_similar(rule, e) for e in _playbook_learned_rules(text)):
        return "duplicate"
    date = (now or datetime.date.today()).isoformat()
    bullet = f"- ({date}) {rule}"
    lines = text.splitlines()
    start = next((i for i, ln in enumerate(lines)
                  if ln.strip().lower().startswith(_LEARNED_HEADER.lower())), None)
    if start is None:                       # секции нет — создаём в конце
        new_text = text.rstrip() + "\n\n" + _LEARNED_HEADER + "\n" + bullet + "\n"
    else:
        end = next((j for j in range(start + 1, len(lines)) if lines[j].strip().startswith("## ")),
                   len(lines))
        # FIFO-вытеснение по лимиту: книга подмешивается в каждый промпт → держим не более
        # PLAYBOOK_MAX_RULES выученных правил. Освобождаем место под новое, удаляя самые РАННИЕ bullets
        # секции (свежий урок важнее давнего); индексы после удаления сдвигаются — границы пересчитываем.
        if PLAYBOOK_MAX_RULES > 0:
            bullets = [j for j in range(start + 1, end) if lines[j].strip().startswith("-")]
            if len(bullets) >= PLAYBOOK_MAX_RULES:
                drop = set(bullets[:len(bullets) - PLAYBOOK_MAX_RULES + 1])   # оставить место под новое
                lines = [ln for i, ln in enumerate(lines) if i not in drop]
                start = next((i for i, ln in enumerate(lines)
                              if ln.strip().lower().startswith(_LEARNED_HEADER.lower())), start)
                end = next((j for j in range(start + 1, len(lines)) if lines[j].strip().startswith("## ")),
                           len(lines))
        while end - 1 > start and not lines[end - 1].strip():   # вставляем после последнего правила
            end -= 1
        lines.insert(end, bullet)
        new_text = "\n".join(lines) + ("\n" if text.endswith("\n") else "")
    try:
        with open(PLAYBOOK_FILE, "w", encoding="utf-8") as f:
            f.write(new_text)
        return "added"
    except Exception:
        return "error"


# --- конфликт/замена выученного правила (родитель 112, шаг 3/8) --------------
# behavior-урок пишется в playbook НЕМЕДЛЕННО, но новое правило может ПРОТИВОРЕЧИТЬ уже записанному
# (та же тема — противоположный смысл: «здоровайся дважды» ↔ «НЕ здоровайся дважды»). Такой клэш
# дедуп _rules_similar НЕ ловит (он про ПОХОЖИЕ той же полярности) — а тут смысл ОБРАТНЫЙ. Ловим по
# ПОЛЯРНОСТИ: одинаковая тема (содержательные слова без отрицаний) + РАЗНОЕ наличие отрицания. Это
# детерминированный сигнал (анти-антонимы вроде «короче»↔«длиннее» намеренно НЕ трогаем — там нет
# чистого маркера, гадать не будем; дирижёр покажет оба и спросит только на явном флипе отрицания).
_NEGATION_TOKENS = frozenset((
    "не", "нельзя", "нет", "без", "никогда", "ни", "запрещено",
    "don't", "dont", "never", "no", "not", "avoid", "without", "stop",
))


def _rule_polarity(s):
    """Полярность правила: True, если несёт отрицание (не/never/don't…)."""
    return any(t in _NEGATION_TOKENS for t in _norm_rule(s).split())


def _rule_topic(s):
    """Содержательные слова правила БЕЗ отрицаний — «о чём» оно (для сравнения тем при поиске клэша)."""
    return {t for t in _norm_rule(s).split() if t not in _NEGATION_TOKENS}


def find_playbook_conflict(rule, text=None):
    """Найти уже записанное выученное правило, КОНФЛИКТУЮЩЕЕ с новым: та же тема (высокое
    пересечение содержательных слов ИЛИ вложенность), но ПРОТИВОПОЛОЖНАЯ полярность (одно с
    отрицанием, другое без). → текст конфликтующего правила ЛИБО '' (клэша нет). Это НЕ дедуп:
    дедуп ловит похожие ОДНОЙ полярности, здесь — похожие ПРОТИВОПОЛОЖНОЙ. text=None → боевой
    playbook (load_playbook); в тестах передаётся явно. FAIL-SAFE: пусто/битьё → ''."""
    rule = " ".join(str(rule or "").split()).strip()
    if not rule:
        return ""
    topic_new = _rule_topic(rule)
    if not topic_new:
        return ""
    pol_new = _rule_polarity(rule)
    text = load_playbook() if text is None else text
    for e in _playbook_learned_rules(text):
        topic_old = _rule_topic(e)
        if not topic_old:
            continue
        inter, union = topic_new & topic_old, topic_new | topic_old
        same_topic = (topic_new <= topic_old or topic_old <= topic_new
                      or (len(inter) / len(union) if union else 0) >= 0.6)
        if same_topic and _rule_polarity(e) != pol_new:
            return e
    return ""


def replace_playbook_rule(old_rule, new_rule, now=None):
    """Заменить конфликтующее выученное правило: удалить bullet(ы), похожие на old_rule (по _rules_
    similar, ЛЮБОЙ полярности) из секции «Выученные правила», затем дописать new_rule штатным append
    (с датой/дедупом/FIFO). Разрешение конфликта «оставить новое». → 'replaced' (старое найдено и
    убрано) | 'added' (старого не нашли — просто дописали) | 'error'. FAIL-SAFE: файл недоступен →
    'error'. Удаление ДО append важно: без него new_rule (обратная полярность old) осел бы как
    'duplicate' (Jaccard с отрицанием ≥0.6) и не записался бы вовсе."""
    new_rule = " ".join(str(new_rule or "").split()).strip()
    if not new_rule:
        return "error"
    try:
        with open(PLAYBOOK_FILE, encoding="utf-8") as f:
            text = f.read()
    except Exception:
        return "error"
    removed = False
    old = str(old_rule or "").strip()
    if old:
        lines = text.splitlines()
        start = next((i for i, ln in enumerate(lines)
                      if ln.strip().lower().startswith(_LEARNED_HEADER.lower())), None)
        if start is not None:
            end = next((j for j in range(start + 1, len(lines))
                        if lines[j].strip().startswith("## ")), len(lines))
            keep = []
            for j, ln in enumerate(lines):
                if start < j < end and ln.strip().startswith("-"):
                    body = re.sub(r"^\(\d{4}-\d{2}-\d{2}\)\s*", "", ln.strip().lstrip("-").strip())
                    if _rules_similar(old, body):
                        removed = True
                        continue                     # выкидываем старое конфликтующее правило
                keep.append(ln)
            if removed:
                text = "\n".join(keep) + ("\n" if text.endswith("\n") else "")
                try:
                    with open(PLAYBOOK_FILE, "w", encoding="utf-8") as f:
                        f.write(text)
                except Exception:
                    return "error"
    res = append_playbook_rule(new_rule, now=now)
    if res == "error":
        return "error"
    return "replaced" if removed else "added"


# --- показ/удаление выученного правила (родитель 112, шаг 5/8) ---------------
# /rules показывает выученные правила С НОМЕРАМИ, удаление — репликой по номеру ИЛИ тексту. Нумерация
# и селектор-номер ОБЯЗАНЫ совпадать: обе берут правила в ПОРЯДКЕ ФАЙЛА (старые→новые, ровно как
# кладёт append). Текстовый селектор матчим тем же _rules_similar, что дедуп/замена — единый матчинг.
def list_playbook_rules(text=None):
    """Выученные правила книги как список dict {'n','date','rule'} в порядке файла (n — 1-based,
    совпадает и с показом /rules, и с номером-селектором remove_playbook_rule). text=None → боевой
    playbook (load_playbook); в тестах передаётся явно. FAIL-SAFE: пусто/битьё → []."""
    text = load_playbook() if text is None else text
    out, inside, n = [], False, 0
    for ln in (text or "").splitlines():
        s = ln.strip()
        if s.startswith("## "):
            inside = s.lower().startswith(_LEARNED_HEADER.lower())
            continue
        if inside and s.startswith("-"):
            raw = s.lstrip("-").strip()
            m = re.match(r"^\((\d{4}-\d{2}-\d{2})\)\s*(.*)$", raw)
            date = m.group(1) if m else ""
            rule = (m.group(2).strip() if m else raw)
            if rule:
                n += 1
                out.append({"n": n, "date": date, "rule": rule})
    return out


def remove_playbook_rule(selector):
    """Удалить ОДНО выученное правило из playbook.md по СЕЛЕКТОРУ — номеру (1-based, как в /rules)
    ЛИБО тексту (нечёткое совпадение _rules_similar, тот же матчинг, что дедуп/замена). Пишем только
    строку правила из секции «Выученные правила», прочее (стиль/факты) не трогаем. → dict:
      {'status':'removed','n':i,'rule':body,'remaining':k} — правило убрано;
      {'status':'not_found'}   — номер вне диапазона / текст ни с чем не сходится;
      {'status':'ambiguous','matches':[{'n','rule'},…]} — текст сходится с >1 правилом (не гадаем);
      {'status':'empty'}       — выученных правил в книге нет;
      {'status':'error'}       — файл недоступен/ошибка записи (FAIL-SAFE).
    Дедуп/лимит — забота append_playbook_rule; здесь точечное удаление по одному правилу."""
    try:
        with open(PLAYBOOK_FILE, encoding="utf-8") as f:
            text = f.read()
    except Exception:
        return {"status": "error"}
    lines = text.splitlines()
    start = next((i for i, ln in enumerate(lines)
                  if ln.strip().lower().startswith(_LEARNED_HEADER.lower())), None)
    bullets = []                                   # (line_index, body) в порядке файла = нумерация /rules
    if start is not None:
        end = next((j for j in range(start + 1, len(lines)) if lines[j].strip().startswith("## ")),
                   len(lines))
        for j in range(start + 1, end):
            s = lines[j].strip()
            if s.startswith("-"):
                body = re.sub(r"^\(\d{4}-\d{2}-\d{2}\)\s*", "", s.lstrip("-").strip())
                if body:
                    bullets.append((j, body))
    if not bullets:
        return {"status": "empty"}
    sel = " ".join(str(selector or "").split()).strip()
    if re.fullmatch(r"\d+", sel):                  # селектор-номер (1-based)
        n = int(sel)
        if not (1 <= n <= len(bullets)):
            return {"status": "not_found"}
        idx = n - 1
    else:                                          # селектор-текст → нечёткое совпадение
        hits = [k for k, (_, body) in enumerate(bullets) if _rules_similar(sel, body)]
        if not hits:
            return {"status": "not_found"}
        if len(hits) > 1:                          # несколько похожих — не гадаем, просим номер
            return {"status": "ambiguous",
                    "matches": [{"n": k + 1, "rule": bullets[k][1]} for k in hits]}
        idx = hits[0]
    j_del, body_del = bullets[idx]
    keep = [ln for i, ln in enumerate(lines) if i != j_del]
    new_text = "\n".join(keep) + ("\n" if text.endswith("\n") else "")
    try:
        with open(PLAYBOOK_FILE, "w", encoding="utf-8") as f:
            f.write(new_text)
    except Exception:
        return {"status": "error"}
    return {"status": "removed", "n": idx + 1, "rule": body_del, "remaining": len(bullets) - 1}


# ------------------------------- рантайм-стоп --------------------------------

_disabled = False  # флип при флуде — авто-стоп до перезапуска/сброса


def is_enabled() -> bool:
    """SUGGEST активен: включён флагом и не остановлен флуд-гардом."""
    return SUGGEST_MODE and not _disabled


def disable(reason: str) -> None:
    global _disabled
    _disabled = True
    log.warning(f"SUGGEST АВТО-СТОП: {reason}")


def reset_disabled() -> None:
    """Только для тестов/ручного сброса."""
    global _disabled
    _disabled = False


# ------------------------------- утилиты -------------------------------------

def _now_iso() -> str:
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


def detect_lang(text: str) -> str:
    """Язык по одному тексту (примитив): есть кириллица → ru, иначе en.
    ВНИМАНИЕ: не использовать для выбора языка ответа на диалог — латинское НАЗВАНИЕ модели
    («Adv 350») ложно даёт en. Для диалога — detect_lang_from_client (по ВСЕМ репликам клиента)."""
    for ch in text or "":
        if "а" <= ch.lower() <= "я" or ch.lower() == "ё":
            return "ru"
    return "en"


_LATIN_WORD_RE = re.compile(r"[a-z]{2,}")


def detect_lang_from_client(transcript: str) -> str:
    """Язык ответа = преобладающий язык ВСЕХ реплик КЛИЕНТА в диалоге (не одной последней).
    Правила:
      • хоть немного кириллицы у клиента где угодно → ru (стабильно, без прыжков RU↔EN);
      • латинские НАЗВАНИЯ моделей (NMAX/ADV/CBR/XMAX/Forza/Vulcan/Ninja/XADV/MT/…), цифры и
        даты за признак EN НЕ считаем — их вырезаем перед проверкой;
      • осмысленные латинские слова (2+ буквы, не только модель+число) → en;
      • содержательного текста нет (только модель+числа) → ru (RU-first магазин, дефолт).
    Инвариант: «Adv 350» в русском диалоге → остаёмся RU (латиница модели EN не триггерит)."""
    joined = " ".join(_client_messages(transcript))   # реплики клиента, уже lowercased
    if re.search(r"[а-яё]", joined):
        return "ru"
    stripped = joined
    for tok in _MODEL_TOKENS:                          # убрать латинские названия моделей
        stripped = stripped.replace(tok, " ")
    return "en" if _LATIN_WORD_RE.search(stripped) else "ru"


def parse_approval(reply_text: str):
    """Разобрать reply менеджера. Возвращает (action, payload):
      approve — '+'/'да'/'да N' (payload=None): отправить черновик как есть;
      reject  — '-'/'нет'      (payload=None): отклонить;
      edit    — любой другой текст (payload=текст): отправить правленую версию.
    """
    t = (reply_text or "").strip()
    low = t.lower()
    if low in ("+", "да", "ок", "ok", "yes", "+1") or low.startswith("да "):
        return "approve", None
    if low in ("-", "нет", "no", "отклонить", "reject"):
        return "reject", None
    if not t:
        return "reject", None
    return "edit", t


# ------------------------------- транскрипт ----------------------------------

async def _resolve_replies(client, entity, msgs):
    """§243/5: у каждого сообщения-reply подтянуть РЕПЛАЕННОЕ сообщение (цель) → attr
    m._reply_target. Цель ищем сперва в уже выбранном окне (по id), иначе дозапрашиваем по id
    (клиент отвечает reply'ем на сообщение из СТАРОЙ переписки — оно вне окна). Read-only,
    fail-safe: любой сбой дозапроса → цель None (черновик от этого не падает). msgs — как
    отдал iter_messages."""
    by_id = {getattr(m, "id", None): m for m in msgs if getattr(m, "id", None) is not None}
    need = {}  # reply_to_id -> [сообщения-reply, ссылающиеся на него]
    for m in msgs:
        rid = getattr(m, "reply_to_msg_id", None)
        if not rid:
            continue
        target = by_id.get(rid)
        if target is not None:
            m._reply_target = target
        else:
            need.setdefault(rid, []).append(m)
    if not need:
        return msgs
    try:                                   # дозапрос целей вне окна (в т.ч. из старой переписки)
        fetched = await client.get_messages(entity, ids=list(need.keys()))
    except Exception as e:
        log.info(f"SUGGEST: дозапрос reply-целей не удался ({type(e).__name__}) — без контекста reply")
        return msgs
    for f in (fetched or []):
        if f is None:
            continue
        for m in need.get(getattr(f, "id", None), []):
            m._reply_target = f
    return msgs


async def _fetch_messages(client, entity, limit: int = MAX_MESSAGES):
    """Выбрать последние сообщения диалога (newest-first, как отдаёт iter_messages) и подтянуть
    цели reply-сообщений (см. _resolve_replies)."""
    msgs = []
    async for m in client.iter_messages(entity, limit=limit):
        msgs.append(m)
    await _resolve_replies(client, entity, msgs)
    return msgs


def _geo_marker(geo) -> str:
    """Маркер локации-ПИНА для транскрипта. С координатами, если гео-объект их несёт (telethon
    GeoPoint: .lat/.long) — тогда «[локация 7.771000,98.327000]»; иначе голый «[локация]».
    Координаты нужны резолверу доставки (пин → зона/цена, как maps-ссылка); сам маркер по-прежнему
    ловится трекером гео (_COLL_GEO по префиксу «[локаци»). Битые/пустые координаты → голый маркер."""
    lat = getattr(geo, "lat", None)
    lon = getattr(geo, "long", getattr(geo, "lon", None))
    try:
        if lat is not None and lon is not None:
            return f"[локация {float(lat):.6f},{float(lon):.6f}]"
    except (TypeError, ValueError):
        pass
    return "[локация]"


def geo_marker(geo) -> str:
    """Публичная обёртка над _geo_marker: гео-ПИН Telegram → маркер «[локация lat,lon]» для
    транскрипта (координаты доходят до резолвера доставки и трекера гео). Нужна внешним путям
    (тренажёр), которые собирают транскрипт не через transcript_from."""
    return _geo_marker(geo)


def _reply_target_snippet(rt, me_id: int):
    """§243/5: краткое СОДЕРЖИМОЕ реплаенного сообщения для контекста черновика: автор +
    гео-ссылка/адрес/телефон/текст и/или пометка о фото (на этапе брони — обычно паспорт).
    Пусто → None (нечего добавлять)."""
    if rt is None:
        return None
    who = "менеджер" if (getattr(rt, "sender_id", None) == me_id) else "клиент"
    parts = []
    if getattr(rt, "photo", None) is not None:
        parts.append("фото (вероятно паспорт)")
    if getattr(rt, "geo", None) is not None:          # локация-пин в reply-цели → маркер вложения (с коорд.)
        parts.append(_geo_marker(rt.geo))
    txt = (getattr(rt, "message", None) or "").strip()
    if txt:
        parts.append(txt.replace("\n", " ⏎ "))
    elif not parts and getattr(rt, "media", None) is not None:
        parts.append("вложение")
    if not parts:
        return None
    return f"{who}: " + " · ".join(parts)


def transcript_from(msgs, me_id: int) -> str:
    """Текст диалога '[менеджер]/[клиент]: ...' в хронологическом порядке (old→new).
    Ручные ответы менеджера видны (они отправлены с этого же аккаунта, sender_id==me).
    §243/5: если сообщение — reply, дописываем содержимое реплаенного (гео/фото-паспорт/
    телефон/текст), чтобы «Вот» реплаем на данные из старой брони попало в контекст черновика."""
    lines = []
    for m in reversed(msgs):
        who = "менеджер" if (getattr(m, "sender_id", None) == me_id) else "клиент"
        body = (getattr(m, "message", None) or "").strip()
        if not body:                                  # медиа без подписи: различаем фото/локацию/прочее,
            if getattr(m, "photo", None) is not None:  # чтобы трекер ловил ВЛОЖЕНИЕ, а не слово-упоминание
                body = "[фото]"
            elif getattr(m, "geo", None) is not None:
                body = _geo_marker(m.geo)              # координаты пина — резолверу доставки (пин → зона)
            else:
                body = "[медиа/без текста]"
        body = body.replace("\n", " ⏎ ")
        snippet = _reply_target_snippet(getattr(m, "_reply_target", None), me_id)
        if snippet:
            body = f"{body} ↩[в ответ на — {snippet}]"
        lines.append(f"[{who}]: {body}")
    return "\n".join(lines)


def first_contact_from(msgs, me_id: int, hours=None, now=None) -> bool:
    """Первый контакт: НЕТ наших (менеджера) сообщений за последние `hours` часов.
    msgs — newest-first. now — инъекция для тестов."""
    hours = FIRST_CONTACT_HOURS if hours is None else hours
    now_dt = now() if now else datetime.datetime.now(datetime.timezone.utc)
    cutoff = now_dt - datetime.timedelta(hours=hours)
    for m in msgs:  # newest-first
        d = getattr(m, "date", None)
        if d is not None and d < cutoff:
            break  # дальше только более старые — выходим из окна
        if getattr(m, "sender_id", None) == me_id and d is not None:
            return False  # мы писали в окне → это продолжение диалога
    return True


_GREETING_RE = re.compile(
    r"^(здравствуй\w*|привет\w*|добр(?:ый|ое|ой)\s+(?:день|утро|вечер|ночи)|"
    r"hello|hi|hey|good\s+(?:morning|afternoon|evening|day)|welcome|greetings)\b",
    re.IGNORECASE)


def greeting_already_sent(transcript: str) -> bool:
    """Уже уходило НАШЕ (менеджера) приветствие в этом диалоге? (автоприветствие ИЛИ прошлый
    наш ответ). Сканируем строки [менеджер]: — если хоть одна НАЧИНАЕТСЯ с приветствия →
    приветствие уже состоялось, генератор не должен здороваться повторно (один раз на диалог)."""
    for ln in (transcript or "").split("\n"):
        if not ln.startswith("[менеджер]:"):
            continue
        body = ln[len("[менеджер]:"):].strip().lstrip("!.,:;-—–()«\"' \t")
        if _GREETING_RE.match(body):
            return True
    return False


# Зачины-приветствия для среза в НАЧАЛЕ нашего ответа (родитель #311, гард повторного
# приветствия). Мирует _GREETING_RE (suggest.py:690, слово-привет RU/EN + \w*/\b) и добавляет
# business-автоприветствия «Спасибо, что написали/выбрали нас» (класс «е» ревизора,
# _REVIZOR_AUTOGREETING_RES → pc_orchestrator.py:3003 — держать сигнатуры синхронными).
_GREETING_PREFIX_RE = re.compile(
    r"(здравствуй\w*"
    r"|привет\w*|приветствую"
    r"|добр(?:ый|ое|ой)\s+(?:день|утро|вечер|ночи)"
    r"|доброго\s+(?:дня|утра|вечера)"
    r"|спасибо,?\s+что\s+(?:написали|выбрали)(?:\s+нас|\s+нам)?"
    r"|hello|hi|hey|good\s+(?:morning|afternoon|evening|day)|welcome|greetings)\b",
    re.IGNORECASE)


def _skip_seps(s: str, i: int = 0) -> int:
    """Индекс первого «значимого» символа с позиции i: пропускаем пробелы, пунктуацию и
    эмодзи (всё, что не буква и не цифра). isalnum() — юникод-осведомлён (кириллица=буква)."""
    n = len(s)
    while i < n and not s[i].isalnum():
        i += 1
    return i


def strip_greeting(text: str) -> str:
    """Срезает вступительное приветствие в НАЧАЛЕ нашего ответа, сохраняя остальной текст и
    поднимая его первую букву в заглавную. Чистая функция (без побочек): вход→выход, ничего
    не мутирует и не пишет. Ловит комбинации нескольких зачинов подряд с любой пунктуацией/
    эмодзи между ними. Если приветствия в начале нет — текст возвращается БЕЗ изменений
    (в т.ч. с ведущими кавычками/скобками — их не трогаем).

    Примеры из ТЗ (родитель #311):
      "Здравствуйте! Аренда 500฿/день"      -> "Аренда 500฿/день"
      "Привет, хочу арендовать байк"        -> "Хочу арендовать байк"
      "Добрый день, какие есть модели?"     -> "Какие есть модели?"
      "Спасибо, что написали! Уже смотрю"   -> "Уже смотрю"
      "Здравствуйте! 😊 Спасибо, что выбрали нас. NMAX свободен"
                                            -> "NMAX свободен"   (комбинация зачинов + эмодзи)
      "Hi there, bikes available"           -> "There, bikes available"
      "Хонда Клик 125 доступна"             -> "Хонда Клик 125 доступна"  (нет зачина — как есть)
      "500฿ в сутки"                        -> "500฿ в сутки"  (первая — цифра, регистр не трогаем)
    """
    if not text:
        return text
    s = text
    stripped_any = False
    while True:
        start = _skip_seps(s)                        # эмодзи/пунктуация/пробелы перед зачином
        m = _GREETING_PREFIX_RE.match(s, start)
        if not m:
            break
        s = s[m.end():]                              # срезаем зачин ВМЕСТЕ с сепараторами до него
        stripped_any = True
    if not stripped_any:
        return text                                  # приветствия нет — исходный текст без правок
    s = s[_skip_seps(s):]                             # хвостовая пунктуация/эмодзи после зачина
    if s and s[0].isalpha():
        s = s[0].upper() + s[1:]                      # первую заглавную остатка восстанавливаем
    return s


# Сигнатуры автоприветствия Telegram Business (обе поколения владельца) — держать СИНХРОННЫМИ с
# _REVIZOR_AUTOGREETING_RES (pc_orchestrator.py:3003). Автогритинг уходит с нашего аккаунта мимо
# бота/модерации, но в транскрипте реальной истории виден как строка [менеджер]:.
_AUTOGREETING_RES = (
    re.compile(r"спасибо\W+что\W+выбрали\W+нас", re.IGNORECASE),
    re.compile(r"уже\W+смотрю\W+ваше\W+сообщени", re.IGNORECASE),
)


def autogreeting_already_sent(transcript: str) -> bool:
    """В окне уже уходило автоприветствие Telegram Business («Спасибо, что выбрали нас…» /
    «Уже смотрю ваше сообщение…»)? Сканируем строки [менеджер]: (автогритинг с нашего аккаунта).
    _GREETING_RE его НЕ ловит (не слово-привет), поэтому greeting_already_sent тут молчит — это
    root cause класса «е»: бот здоровается ПОВЕРХ автоприветствия. Детект детерминированный
    (ё→е, пунктуация-агностично); сигнатуры держать синхронными с _REVIZOR_AUTOGREETING_RES
    (pc_orchestrator.py:3003). Пусто → False."""
    for ln in (transcript or "").split("\n"):
        if not ln.startswith("[менеджер]:"):
            continue
        body = ln[len("[менеджер]:"):].replace("ё", "е")
        if any(rx.search(body) for rx in _AUTOGREETING_RES):
            return True
    return False


def _window_has_our_reply(history: str) -> bool:
    """В окне уже есть НАША строка [менеджер]: — прошлый ответ бота/менеджера ИЛИ автоприветствие
    Telegram Business (оно уходит с нашего аккаунта, sender_id==me, и рендерится как [менеджер]:).
    Значит диалог — ПРОДОЛЖЕНИЕ: второй раз не здороваемся (правило #311 «приветствие один раз»).
    reply-снипет («↩[в ответ на — менеджер: …]») висит на строке [клиент]: — сюда не попадает,
    т.к. проверяем ровно НАЧАЛО строки."""
    for ln in (history or "").split("\n"):
        if ln.startswith("[менеджер]:"):
            return True
    return False


def strip_greeting_for_window(draft: str, history: str) -> str:
    """stripGreeting(draft, history) — гард ПОВТОРНОГО приветствия ПЕРЕД ОТПРАВКОЙ (родитель
    #311 → #56). Если в окне уже было автоприветствие Telegram Business ИЛИ наш прошлый
    отправленный ответ (любая строка [менеджер]: — см. _window_has_our_reply), то вступительный
    зачин «Здравствуйте / Привет / Добрый … / Спасибо, что написали|выбрали нас» в НАЧАЛЕ
    черновика лишний — срезаем его (strip_greeting). Чистое окно (первый контакт, нашей строки
    ещё нет) → черновик возвращается БЕЗ изменений. Чистая функция: вход→выход, без побочек.

    Комбинирует детект по истории окна с чистым срезом текста — единый (draft, history) API
    для путей, где готовый черновик формируется ОТДЕЛЬНО от on_client_message (напр. strategy-
    перегенерация regenerate_draft, чей результат раньше уходил клиенту мимо этого гарда)."""
    if _window_has_our_reply(history):
        return strip_greeting(draft)
    return draft


# Слово-приветствие для ОКОННОГО гарда hasGreetingInWindow (родитель #44): узкий набор из ТЗ шага
# — «здравствуйте / добрый день|вечер|утро / привет», без учёта регистра. Это ОТДЕЛЬНЫЙ детект для
# списка сообщений окна, уже, чем _GREETING_RE (тот — слово-привет RU/EN для транскрипта), и не
# заменяет _GREETING_PREFIX_RE (тот — зачины для СРЕЗА). Матчим в НАЧАЛЕ сообщения.
_WINDOW_GREETING_RE = re.compile(
    r"(?:здравствуйте|добрый\s+(?:день|вечер|утро)|привет)", re.IGNORECASE)


def hasGreetingInWindow(msgs) -> bool:
    """hasGreetingInWindow(msgs) — в окне УЖЕ есть приветствие с нашей стороны? True, если среди
    НАШИХ (исходящих, m.out) сообщений окна есть автоприветствие Telegram Business (_AUTOGREETING_
    RES: «спасибо, что выбрали нас…» / «уже смотрю ваше сообщение…», ё→е, пунктуация-агностично)
    ИЛИ наше сообщение-приветствие («здравствуйте / добрый день|вечер|утро / привет», без учёта
    регистра, в НАЧАЛЕ сообщения — _WINDOW_GREETING_RE). Приветствие КЛИЕНТА нашим не считается:
    фильтр по m.out (Telethon-флаг исходящего, тот же, что в _last_client_photo) — в отличие от
    greeting_already_sent/autogreeting_already_sent по транскрипту, здесь в сигнатуре нет me_id.
    Гард «здороваемся один раз на диалог» для путей, работающих со СПИСКОМ сообщений, а не с
    текстом транскрипта. Пусто / нет наших строк → False (fail-safe)."""
    for m in (msgs or []):
        if not getattr(m, "out", False):
            continue                                  # чужая (клиентская) строка — не наше приветствие
        body = (getattr(m, "message", None) or "").strip()
        if not body:
            continue
        if any(rx.search(body.replace("ё", "е")) for rx in _AUTOGREETING_RES):
            return True                               # автоприветствие Telegram Business
        if _WINDOW_GREETING_RE.match(body.lstrip("!.,:;-—–()«»\"' \t")):
            return True                               # наше слово-приветствие в начале сообщения
    return False


# «Имя, здравствуйте!» — обращение по имени ПЕРЕД зачином. Имя = слово с буквы до первой запятой
# (без цифр/переводов строки, длиной до 40 симв.), а за запятой ОБЯЗАН идти сам зачин — иначе это
# не приветствие, а обычное обращение («Иван, что по цене?»), и трогать его нельзя.
_NAME_ADDRESS_RE = re.compile(r"[^\W\d_][^\n,]{0,40},\s*")


def stripLeadingGreeting(text: str) -> str:
    """stripLeadingGreeting(text) — срез ВСТУПИТЕЛЬНОГО приветствия в начале нашего ответа, ВКЛЮЧАЯ
    обращение по имени «Имя, здравствуйте!», с восстановлением первой заглавной остатка. Надстройка
    над strip_greeting: сперва снимает необязательный зачин-обращение «Имя, » ЕСЛИ сразу за ним
    идёт приветствие (здравствуйте / добрый … / привет / hello / «спасибо, что …» — _GREETING_
    PREFIX_RE), затем срезает само приветствие тем же чистым срезом. Обычное обращение без зачина
    («Иван, что по цене?») НЕ трогаем. Чистая функция (без побочек); пусто/None → как есть.

    Примеры (родитель #44):
      "Имя, здравствуйте! Аренда 500฿/день" -> "Аренда 500฿/день"
      "Анна, добрый день, какие модели?"    -> "Какие модели?"
      "Здравствуйте! NMAX свободен"         -> "NMAX свободен"   (нет имени — как strip_greeting)
      "Иван, что по цене?"                   -> "Иван, что по цене?"  (обращение без зачина — как есть)
    """
    if not text:
        return text
    m = _NAME_ADDRESS_RE.match(text)
    if m and _GREETING_PREFIX_RE.match(text, _skip_seps(text, m.end())):
        return strip_greeting(text[m.end():])         # снять «Имя,» → дальше обычный срез зачина
    return strip_greeting(text)


# --- детект «котируемой» брони на ПЕРВОМ же сообщении (родитель #271, класс «ж») ---------------
# Клиент ПЕРВОЙ репликой даёт модель + старт + срок ⇒ надо КОТИРОВАТЬ, а не слать анкету/список
# вопросов. Детерминированный детект (без сети/LLM): вытаскиваем ровно три обязательных поля.
def _detect_catalog_model(text: str):
    """Модель из КАТАЛОГА KNOWN_MODELS в тексте, нечувствительно к регистру/пробелам
    («xsr 155», «XSR155», «xsr  155» → 'XSR 155'). Матчим по _bike_key (тот же нормализатор, что
    park_allowlist/resolve_park_model — снимает регистр, пробелы, CC/СС и прочий не-alnum). При
    нескольких совпадениях берём самый ДЛИННЫЙ ключ (специфичнее). Модели каталога нет → None.
    Голый серийный корень («xsr» без объёма) не матчит — в каталоге только конкретные модели."""
    key_text = _bike_key(text)
    if not key_text:
        return None
    best = None
    for disp, key in KNOWN_MODELS:
        if key in key_text and (best is None or len(key) > len(best[1])):
            best = (disp, key)
    return best[0] if best else None


def detect_first_message_booking(text: str, today=None):
    """Из ОДНОГО сообщения клиента вытащить котируемую бронь: модель (каталог), дату старта
    («с 15 июля») и срок («на 2 недели» → 14 дней; поддержка дней/недель/месяцев). Возвращает
    {'model': 'XSR 155', 'startDate': 'YYYY-MM-DD', 'days': 14} ИЛИ None, если ХОТЯ БЫ ОДНОГО из
    трёх полей нет. Детерминированно (без сети/LLM), переиспользует _anchor_date/_parse_term."""
    today = today or today_phuket()
    t = (text or "").lower().replace("–", "-").replace("—", "-").replace("ё", "е")
    model = _detect_catalog_model(text)
    anchor = _anchor_date(t, today)          # дата старта («с 15 июля», «завтра», «с 20»)
    term = _parse_term(t)                    # (days, monthly) из «на N дней/недель/месяцев»
    if not (model and anchor and term):
        return None
    return {"model": model, "startDate": anchor.isoformat(), "days": term[0]}


# --- ДЕТЕКТ ТИПА ТС: клиент про АВТО (вне нашего парка) против байка/мото/скутера --------------
# ЖИВОЙ ЗАМЕР 29.07.2026 (корпус: 178 боевых тредов moderation_ipc.db/drafts + 710 диалогов
# client_chats.jsonl; разбор — docs/artifacts/2026-07-29-vehicle-type-live-corpus.md): подстроковый
# матч стемов давал 45 ложных «авто» из 56 — КАЖДЫЙ ЧЕТВЁРТЫЙ живой тред. Ловилось живьём:
#   «авто»  → «автовокзал» (13 тредов: «отвезти брата на автовокзал» — тред про БАЙК), «автомат»/
#             «на автомате» (это коробка скутера!), «автобус», «автосервис», «автомастерской»,
#             «автоответ», «автозаправочной», «автопостинг», «автоматизировано»;
#   «машин» → «машинка»;
#   марка «ауди» → «аудитория» (5 тредов, спам-рассылка), «аудиторов» (12 тредов: «сотрудники у
#             аудиторов на переоформлении»), «аудио» — включая наше же «Аудио от TURBOBABY MOTO».
# Поэтому каждое слово матчится по ГРАНИЦАМ СЛОВА с ЗАКРЫТЫМ списком окончаний: сам список
# окончаний и служит правой границей, поэтому «авто|вокзал» и «ауди|тория» не разбираются вовсе.
_VEH_END = r"(?:ями|ами|ях|ах|ям|ам|ей|ов|ем|ом|ой|ь|ы|а|у|е|и|ю|я)?"
_VEH_L = r"(?<![а-яёa-z])"
_VEH_R = r"(?![а-яёa-z])"

# Авто-слова. «авто» — неизменяемое и ТОЛЬКО отдельным словом; остальные — стем + окончание.
_CAR_WORD_RE = re.compile(
    _VEH_L + r"(?:автомобил" + _VEH_END + r"|авто|машин" + _VEH_END
    + r"|седан(?:чик)?" + _VEH_END + r"|иномар(?:ок|к" + _VEH_END + r"))" + _VEH_R, re.I)

# Марки — ТОЛЬКО авто-производители; байко-моточные бренды (Honda/Yamaha/Suzuki и т.п.) НЕ
# включаем: у нас парк на них, они не признак «клиент про машину». Матч тот же — стем + окончание
# + границы слова. Короткую «ауди» это обезвредило, выбрасывать её из списка не пришлось: «ауди»
# отдельным словом ловится, «аудитория»/«аудиторов»/«аудио» — нет.
_CAR_BRAND_STEMS = (
    "тойот", "ниссан", "мазд", "мицубис", "форд", "мерседес", "ауди", "киа", "хендай",
    "лексус", "вольво", "фольксваген", "рено", "пежо", "шевроле", "субару", "тесла",
    "toyota", "nissan", "mazda", "mitsubishi", "ford", "mercedes", "audi", "kia",
    "hyundai", "lexus", "volvo", "volkswagen", "renault", "peugeot", "chevrolet",
    "subaru", "tesla",
)
_CAR_BRAND_RE = re.compile(
    _VEH_L + r"(?:" + "|".join(_CAR_BRAND_STEMS) + r")" + _VEH_END + _VEH_R, re.I)

# Байк-слова. «мото» остаётся ПРЕФИКСОМ (мотоцикл, мотошлем, мотоправа — всё про наш парк), но
# семья «мотор…» из него вычтена: живьём «моторное масло» и «промыть моторный отсек» давали
# 'bike'. Исключение из исключения — «мотороллер», это скутер.
# «мопед» добавлен 29.07.2026 по живому корпусу: реплика клиента «Мопед, машина» — это СМЕШАННЫЙ
# запрос, а без «мопеда» в словаре она уходила чистым 'car'.
_BIKE_WORD_RE = re.compile(
    _VEH_L + r"(?:(?:мото)?байк" + _VEH_END + _VEH_R
    + r"|скутер" + _VEH_END + _VEH_R
    + r"|мопед" + _VEH_END + _VEH_R
    + r"|мото(?!р(?!оллер)))", re.I)

# --- АНГЛИЙСКИЙ СЛОЙ (29.07.2026) -------------------------------------------------------------
# Контур клиентский RU+EN, а латиницы в СЛОВАХ детекта не было вовсе (в МАРКАХ она была всегда —
# toyota/nissan/… выше). Живьём это значило: тип ТС у англоязычного клиента не определялся НИКОГДА.
# Дословно из корпуса B: «I Need bike» (#173), «Hello, I would like to rent motorcycle for the
# Phuket location» (#543), «Hello , I'm looking for monthly rent motorcycle .» (#400), «Hi! I need
# a sport bike (Yamaha yzf / Honda cbr/ Kawasaki ninja) 300-500 for a week» (#207) — все 'unknown'.
#
# Принцип тот же, что вчера у русского: ГРАНИЦЫ СЛОВА, а не подстрока. Ловушки подстроки — car в
# care/careful/card/cargo/carry/carrier/career/cart/scarf, van в advance/vanilla, auto в
# automatic/automation/automatically. Три из них в корпусе ЖИВЫЕ: «he went to take care of some
# business» (care ×3), «we have his identification card documents» (card ×1), «i would like to
# request an advance of 1,000 bath» (advance ×1).
#
# Границы латиницы СТРОЖЕ русских: кроме букв закрыты ЦИФРЫ и «_». Это тоже живая ловушка, а не
# перестраховка — тред #0, рекламный прайс: «t.me/auto_moto_thailand» (2 совпадения). С русскими
# границами «auto» и «moto» там отдельные токены, и прайс рекламной площадки уезжает в 'mixed'.
_VEH_EN_L = r"(?<![a-zа-яё0-9_])"
_VEH_EN_R = r"(?![a-zа-яё0-9_])"

# Альтернативы — от длинной к короткой (для чтения; re откатывается и порядок на результат не
# влияет). «s?» — английское множественное: cars/sedans/bikes/scooters.
# «truck» и «vehicle» в словарь НЕ взяты — это ЖИВАЯ ловушка корпуса B, а не осторожность. Тайские
# сотрудники пишут через машинный перевод, и รถ выходит как car/truck/vehicle применительно к нашим
# СКУТЕРАМ: «Where does this Max N truck need to be delivered?», «Does the N-Max 4255 truck require
# a deposit?», «Does the X Max 5773 vehicle need to be replaced for the customer again?» (truck ×2,
# vehicle ×8 — все до одного про байки парка). «vehicle» вдобавок родовое: байк — тоже vehicle.
# «taxi» (×5) — не запрос аренды: «staff take a taxi to pick up the car».
_CAR_EN_STEMS = ("automobile", "minivan", "sedan", "auto", "car", "suv", "van")
_CAR_EN_RE = re.compile(
    _VEH_EN_L + r"(?:" + "|".join(_CAR_EN_STEMS) + r")s?" + _VEH_EN_R, re.I)

# «moto» отдельным словом НЕ берём — зеркало русского правила «мото — префикс, а не слово». Живьём
# это бренд и URL: «Аудио от TURBOBABY MOTO PHUKET» (наш собственный текст) и
# «t.me/auto_moto_thailand». Полные слова ниже покрывают то, что клиент пишет на самом деле.
_BIKE_EN_STEMS = ("motorcycle", "motorbike", "scooter", "moped", "bike")
_BIKE_EN_RE = re.compile(
    _VEH_EN_L + r"(?:" + "|".join(_BIKE_EN_STEMS) + r")s?" + _VEH_EN_R, re.I)

# Реплика клиента в транскрипте окна (тот же префикс, что у _client_text ниже).
_CLIENT_LINE_PREFIX = "[клиент]:"


def _vehicle_of(text):
    """Вердикт по ОДНОМУ куску текста, без учёта истории треда. Чистая функция."""
    t = (text or "").lower().replace("ё", "е")
    is_car = (bool(_CAR_WORD_RE.search(t)) or bool(_CAR_BRAND_RE.search(t))
              or bool(_CAR_EN_RE.search(t)))
    is_bike = bool(_BIKE_WORD_RE.search(t)) or bool(_BIKE_EN_RE.search(t))
    if is_car and is_bike:
        return "mixed"
    if is_car:
        return "car"
    if is_bike:
        return "bike"
    return "unknown"


def detectVehicleType(text):
    """Тип ТС по треду: 'car' | 'mixed' | 'bike' | 'unknown'. Чистая функция (без сети/LLM).

    'car'     — авто-слово или авто-марка, а байковых слов НЕТ;
    'mixed'   — в ОДНОМ запросе названы и авто, и байк («права тоже есть на машину и байк»,
                «возвращаю байк, пока на авто передвигаться буду»). Раньше приоритет отдавался
                'car', и честный байковый тред получал ограничение словаря; теперь словарь не
                ограничиваем, а менеджер получает пометку;
    'bike'    — только байк/мото/скутер;
    'unknown' — ни того, ни другого.

    ЧЕЙ ТЕКСТ И КАКОЙ ДАВНОСТИ (29.07.2026). Тред — это ИСТОРИЯ, а тип ТС задаёт ПОСЛЕДНИЙ запрос
    клиента: идём по строкам «[клиент]:» СНИЗУ ВВЕРХ и берём первую, где транспорт назван. Живой
    случай id=353: в январе клиент брал NMAX («В итоге байк будет нужен 6 января»), а 28.07 пишет
    «Подскажите, у вас авто есть?» — это запрос про АВТО, а не смешанный. Без правила давности
    требования «смешанный ≠ car» и «честные авто-треды остаются car» несовместимы: 7 честных
    тредов из 11 уезжали в 'mixed' из-за байка, взятого полгода назад.
    Если клиент транспорт не называл вовсе (или строк «[клиент]:» нет — голая строка в тестах),
    смотрим текст целиком, как раньше: реплика менеджера «байк будет готов» оставляет тред байком.

    Все слова — по границам слова с закрытым списком окончаний (см. комментарий выше):
    «машину»/«машине»/«автомобилей» ловятся, «автовокзал»/«автомат»/«автобус»/«аудитория» — нет.
    Английский (29.07.2026) — тем же принципом и в тех же трёх вердиктах: «I need bike» → 'bike',
    «do you have a car?» → 'car', «a car or a bike» → 'mixed'; care/card/carry/scarf, advance,
    automatic — НЕ ловятся. Разбор на живом корпусе: docs/artifacts/2026-07-29-vehicle-type-en.md."""
    for line in reversed([l for l in (text or "").split("\n")
                          if l.startswith(_CLIENT_LINE_PREFIX)]):
        verdict = _vehicle_of(line)
        if verdict != "unknown":
            return verdict
    return _vehicle_of(text)


# Сущ. «байк/мотобайк» в склонениях. ГРАНИЦЫ СЛОВА ОБЯЗАТЕЛЬНЫ (28.07.2026): прежняя
# «(?:мото)?байк\w*» без левой границы ловила «Квадробайк», «Байкал», «байкер» — и, пока функция
# ЗАМЕНЯЛА слово, рождала «Квадроавто», «Озеро авто», «Наш авто довезёт». Теперь по этой регулярке
# ничего не заменяется, но и ложную пометку модератору она вешать не должна.
# EN-половина (29.07.2026) — иначе дыра, открытая ЭТОЙ ЖЕ правкой: англоязычный тред теперь может
# получить вердикт 'car', а англоязычный черновик («we have scooters and bikes») словом «байк» не
# пишется — и пометка _VEHICLE_NOTE["en"], которая в коде лежит с самого начала, не сработала бы
# НИКОГДА. Список тот же, что у _BIKE_EN_RE, границы те же.
_BIKE_NOUN_RE = re.compile(
    r"(?<![а-яёa-z])(?:мото)?байк(?:ами|ах|ам|ов|ом|а|у|е|и)?(?![а-яёa-z])"
    r"|" + _VEH_EN_L + r"(?:" + "|".join(_BIKE_EN_STEMS) + r")s?" + _VEH_EN_R, re.I)

# Пометка модератору о конфликте типа ТС. Служебный канал карточки — тот же, что «[уточнить: …]»
# и «[собрано: …]»: отдельная строка в квадратных скобках в хвосте, которую перед отправкой
# срезают client_facing_text и stripInternalMarkers. Клиент пометку не видит.
_VEHICLE_NOTE = {
    "ru": "[тип ТС: запрос про авто, а в черновике предложен байк — проверь перед отправкой]",
    "en": "[vehicle type: client asked about a car, the draft offers a bike — check before sending]",
}
# Смешанный запрос (29.07.2026): клиент назвал И авто, И байк. Словарь черновика НЕ ограничиваем —
# он честно говорит о байках; но менеджер обязан знать, что авто прозвучало. Бизнес-правило: авто
# в нашем парке НЕТ, запросить у партнёров можем, поэтому отказ клиенту не даём, а наличие, модели
# и цены по авто не называем — их мы не знаем. Такой запрос ведём к менеджеру.
_VEHICLE_MIXED_NOTE = {
    "ru": "[тип ТС: клиент упомянул авто — наличие, модели и цены по авто не называем, "
          "запрос ведём к менеджеру]",
    "en": "[vehicle type: the client mentioned a car — do not quote car availability, models or "
          "prices, route the request to a manager]",
}


def vehicle_mismatch(draft, vehicle_type) -> bool:
    """Конфликт: тред про АВТО, а в готовом черновике фигурирует байк. Чистая функция."""
    return bool(draft) and vehicle_type == "car" and bool(_BIKE_NOUN_RE.search(draft))


def _vehicle_note_append(draft, notes, lang):
    """Дописать служебную пометку ОТДЕЛЬНОЙ строкой в хвост. Тело черновика не трогаем никогда;
    идемпотентно (повторный вызов второй пометки не добавит); пустой черновик оставляем пустым."""
    if not draft:
        return draft
    note = notes["en" if str(lang or "").lower().startswith("en") else "ru"]
    if note in draft:
        return draft
    return draft.rstrip() + "\n" + note


def enforce_vehicle_word(draft, vehicle_type, lang="ru"):
    """ПОМЕТКА МЕНЕДЖЕРУ вместо слепой замены слова (28.07.2026; смешанный запрос — 29.07.2026).

    Что было: regex «(?:мото)?байк\\w*» → «авто» по ВСЕМУ готовому тексту, без границы слова и без
    разбора контекста. Живые последствия: «байк NMAX» → «авто NMAX» (NMAX — скутер, модель в тексте
    остаётся, а слово рядом врёт), «Квадробайк» → «Квадроавто», «Озеро Байкал» → «Озеро авто»,
    «байкер» → «авто». На смешанном запросе detectVehicleType давал приоритет 'car', поэтому
    переименовывался и честно предложенный байк.

    Что стало: текст черновика НЕ ТРОГАЕМ. Модель направляет промпт-блок «ТИП ТС» ДО генерации
    (make_system_prompt) — это верный слой. Если модель всё равно предложила байк на автомобильном
    запросе, черновик уходит модератору С ПОМЕТКОЙ, и решает человек. 'mixed' (клиент назвал и
    авто, и байк) — своя пометка: словарь не ограничен, но менеджер знает, что авто прозвучало.
    'bike'/'unknown' → черновик БАЙТ-В-БАЙТ, как и раньше."""
    if vehicle_type == "mixed":
        return _vehicle_note_append(draft, _VEHICLE_MIXED_NOTE, lang)
    if not vehicle_mismatch(draft, vehicle_type):
        return draft
    return _vehicle_note_append(draft, _VEHICLE_NOTE, lang)


# --- ГАРД ПАРТНЁРСКИХ ЧАТОВ (шаг 3/6 родитель #4) --------------------------------------------
# Собеседник в партнёрском чате — ПАРТНЁР (другой прокат/координатор), а не конечный клиент. Его
# доставку/подачу байка мы НЕ организуем и НЕ подтверждаем ОТ НАШЕГО лица: черновик, собранный
# клиентским промптом, порой обещает «подадим/привезём» или спрашивает «во сколько подать» — это
# берёт на нас чужую доставку. Гард (страховка кодом поверх LLM) заменяет такие утверждающе-
# организующие формулировки на уточняющий вопрос партнёру БЕЗ обязательств с нашей стороны.
# Маркеры выровнены с export_all.GROUPS_TO_EXPORT: имя партнёрского чата несёт «партнёрк…/turbostm».
_PARTNER_CHAT_MARKERS = ("партнерк", "turbostm", "turbo stm")


def is_partner_chat(entity) -> bool:
    """Партнёрский ли это чат — по title/name/username сущности Telethon (для вызывающего кода, чтобы
    выставить флаг is_partner). Нормализуем lower+ё→е; маркер из _PARTNER_CHAT_MARKERS в любом из полей
    → True. None/без полей/обычный клиентский DM → False (fail-safe: клиентский путь гард не трогает).
    Чистая функция (без сети/LLM)."""
    if entity is None:
        return False
    for attr in ("title", "name", "username", "first_name", "last_name"):
        v = getattr(entity, attr, None)
        if isinstance(v, str) and v:
            s = v.lower().replace("ё", "е")
            if any(m in s for m in _PARTNER_CHAT_MARKERS):
                return True
    return False


# Доставка/подача ОТ НАШЕГО лица (1-е лицо мн.ч.) — обещание, которого в партнёрском чате быть не должно.
# Текст сегмента поступает УЖЕ нормализованным (lower, ё→е), поэтому «привезём» ищем как «привезем».
_PARTNER_COMMIT_RE = re.compile(
    r"(?<![а-яa-z])(?:подадим|привезем|доставим|подвезем|довезем)", re.I)
# Организующий ВОПРОС о подаче/доставке («во сколько подать», «когда привезти», «куда подавать»).
_PARTNER_ORG_Q_RE = re.compile(
    r"(?:во\s+сколько|когда|куда|к\s+как\w+\s+времени)[^.!?\n]{0,40}?"
    r"(?:подать|подавать|подаем|привезти|подвезти|доставить|подадим|привезем)", re.I)
# «организуем …доставку/подачу» — организация чужой доставки нашими силами.
_PARTNER_ORG_RE = re.compile(r"организуем", re.I)
_PARTNER_DELIVERY_NOUN_RE = re.compile(r"доставк|подач|подвоз|привоз|довоз", re.I)
# EN-двойник (партнёр пишет по-английски): «we will deliver/bring/drop off …» — обещание от нас.
# «\bdeliver\b» НЕ ловит существительное «delivery» (нет границы r|y) → канон себя не триггерит.
_PARTNER_COMMIT_EN_RE = re.compile(
    r"\bwe\b[^.!?\n]{0,15}?\b(?:deliver|bring|drop off|drop it off)\b", re.I)
# Границы предложений/строк для посегментной замены (склейка обратно = исходник байт-в-байт).
_PARTNER_SEG_RE = re.compile(r"[^.!?\n]*(?:[.!?]+|\n|$)")

# ОТРИЦАНИЕ — это ровно та формулировка, которой мы и добиваемся («доставку не берём»): пометки
# такой сегмент заслуживать не должен. Текст сегмента приходит УЖЕ нормализованным (lower, ё→е).
_PARTNER_NEG_RE = re.compile(
    r"(?:^|[^а-яa-z])не\s+(?:подадим|привезем|доставим|подвезем|довезем)")

# Пометка модератору — тот же служебный канал карточки, что «[уточнить: …]» и «[тип ТС: …]»:
# отдельная строка в квадратных скобках в хвосте, её срезают client_facing_text и
# stripInternalMarkers. Называет ИМЕННО ЧТО смутило и цитирует фрагмент-триггер.
_PARTNER_NOTE_RU = ("[партнёрский чат: обещание доставки от нашего лица («%s») — "
                    "проверь перед отправкой]")
_PARTNER_NOTE_EN = ("[partner chat: the draft commits to delivery on our side (\"%s\") — "
                    "check before sending]")


def _partner_delivery_offends(seg_norm: str) -> bool:
    """seg_norm — сегмент, УЖЕ приведённый к lower и ё→е. True, если несёт утверждающе-организующую
    доставку ОТ НАШЕГО лица: 1-е лицо мн.ч. (подадим/привезём/доставим/подвезём) ЛИБО организующий
    вопрос «во сколько подать/когда привезти…» ЛИБО «организуем …доставку/подачу». Чистая проверка."""
    return bool(
        _PARTNER_COMMIT_RE.search(seg_norm)
        or _PARTNER_ORG_Q_RE.search(seg_norm)
        or _PARTNER_COMMIT_EN_RE.search(seg_norm)
        or (_PARTNER_ORG_RE.search(seg_norm) and _PARTNER_DELIVERY_NOUN_RE.search(seg_norm)))


def partner_delivery_trigger(draft, is_partner=True) -> str:
    """Фрагмент-триггер: обещание доставки ОТ НАШЕГО лица в партнёрском черновике. «» — чисто.

    Считаем ПОСЕГМЕНТНО, потому что отрицание живёт в своём предложении: «Доставку не берём, но
    привезём документы» обязано дать пометку по второму сегменту, а «Мы не доставим — забирает
    клиент сам» не должно дать её вовсе. Третье лицо («партнёр привезёт») сюда не попадает по
    построению: _PARTNER_COMMIT_RE знает только 1-е лицо мн.ч. Чистая функция."""
    if not is_partner or not draft:
        return ""
    for seg in _PARTNER_SEG_RE.findall(draft):
        if not seg:
            continue
        norm = seg.lower().replace("ё", "е")
        if _PARTNER_NEG_RE.search(norm):
            continue                       # отрицание — это и есть нужная формулировка
        for rx in (_PARTNER_COMMIT_RE, _PARTNER_ORG_Q_RE, _PARTNER_COMMIT_EN_RE):
            m = rx.search(norm)
            if m:
                return m.group(0).strip()
        if _PARTNER_ORG_RE.search(norm) and _PARTNER_DELIVERY_NOUN_RE.search(norm):
            return _PARTNER_ORG_RE.search(norm).group(0).strip()
    return ""


def enforce_partner_delivery_guard(draft, is_partner, lang="ru"):
    """ПОМЕТКА МЕНЕДЖЕРУ вместо переписывания предложения (28.07.2026).

    Что было: offending-ПРЕДЛОЖЕНИЕ целиком заменялось каноном. Прогон по РЕАЛЬНЫМ выгрузкам
    data_export/partners (4139 сообщений, 2024-11-22…2026-05-23) дал 5 попаданий, и замена в них
    уничтожала суть, а не только обещание: «С 12 до 13 нмакс привезем к вам, окей ?» теряло окно
    времени и модель; «Фоточи по колодкам, если что завтра же привезём» превращалось в канон про
    доставку, хотя речь про фото колодок; «Доставка цена от района, куда нужно доставить ?» —
    наш же вопрос о цене — исчезал целиком.

    Что стало: текст черновика НЕ ТРОГАЕМ. Промпт-блок «ПАРТНЁРСКИЙ ЧАТ» работает ДО генерации —
    это верный слой, он остаётся. Если обещание всё же просочилось, черновик уходит модератору С
    ПОМЕТКОЙ, которая НАЗЫВАЕТ, что смутило, и цитирует фрагмент. Отрицание и третье лицо пометки
    не дают. Идемпотентна. Не партнёрский чат → черновик БАЙТ-В-БАЙТ, как и раньше."""
    trig = partner_delivery_trigger(draft, is_partner)
    if not trig:
        return draft
    tmpl = _PARTNER_NOTE_EN if str(lang or "").lower().startswith("en") else _PARTNER_NOTE_RU
    note = tmpl % trig
    if note in draft:
        return draft
    return draft.rstrip() + "\n" + note


async def read_transcript(client, entity, me_id: int, limit: int = MAX_MESSAGES) -> str:
    """Совместимость: выбрать сообщения и собрать транскрипт."""
    return transcript_from(await _fetch_messages(client, entity, limit), me_id)


def is_approver(username) -> bool:
    """Есть ли право approve/edit/reject. Пустой whitelist = можно любому."""
    if not APPROVER_USERNAMES:
        return True
    return (username or "").lstrip("@").lower() in APPROVER_USERNAMES


def is_intake_approver(username) -> bool:
    """Вправе ли username УЧИТЬ бота (правка/урок/не так на карточке черновика). Строже
    approve: только INTAKE_APPROVERS. Список не сконфигурирован (пуст) → фолбэк на общий
    approver-whitelist (обучение не шире approve), но НЕ распахиваем шире approve."""
    if not INTAKE_APPROVERS:
        return is_approver(username)
    return (username or "").lstrip("@").lower() in INTAKE_APPROVERS


# ------------------------------- FAQ / LLM -----------------------------------

def _bridge_read_doc(name: str):
    """read_doc GET по имени дока; вернуть текст или None."""
    if not (BRIDGE_URL and BRIDGE_TOKEN):
        return None
    import urllib.request
    import urllib.parse
    full = BRIDGE_URL + "?" + urllib.parse.urlencode(
        {"action": "read_doc", "name": name, "token": BRIDGE_TOKEN}
    )
    req = urllib.request.Request(full, method="GET")
    with urllib.request.urlopen(req, timeout=30) as resp:
        data = json.loads(resp.read().decode("utf-8"))
    if isinstance(data, dict) and data.get("ok"):
        for k in ("text", "content", "fileContent", "body"):
            if isinstance(data.get(k), str) and data[k].strip():
                return data[k]
    return None


def load_faq(getter=None) -> str:
    """Живой FAQ. Порядок: read_doc name=faq → read_doc name=turbobaby_faq → локальный файл.
    getter(name)->text|None — инъекция для тестов (заменяет чтение из Brain)."""
    read = getter if getter is not None else _bridge_read_doc
    for name in FAQ_DOC_ORDER:
        try:
            t = read(name)
        except Exception as e:
            log.warning(f"SUGGEST: read_doc FAQ '{name}' упал: {e}")
            t = None
        if t and t.strip():
            return t
    try:
        with open(LOCAL_FAQ, encoding="utf-8") as f:
            return f.read()
    except Exception:
        return ""


# --- лёгкий парсер модель+даты из диалога (поля по образцу collect_booking) ---
_MODEL_TOKENS = [
    "nmax", "pcx", "adv350", "adv 350", "adv150", "adv 150", "adv160", "adv 160", "adv",
    "xmax", "forza", "xadv", "xsr", "cb300", "cb 300", "cb650", "cb 650",
    "cbr650", "cbr 650", "cbr", "rebel", "mt-03", "mt03", "mt 03", "ninja", "vulcan", "r7", "click",
]
_MONTHS = ("январ", "феврал", "март", "апрел", "мая", "июн", "июл", "август", "сентябр",
           "октябр", "ноябр", "декабр",
           "jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec")


def _client_text(transcript: str) -> str:
    return "\n".join(l for l in (transcript or "").split("\n") if l.startswith("[клиент]:")).lower()


def _manager_text(transcript: str) -> str:
    """Реплики МЕНЕДЖЕРА окна (то, что клиент от нас уже слышал). Нужен, чтобы не повторять в
    каждом ответе неизменившиеся блоки (тариф доставки) — см. compose_delivery_draft."""
    return "\n".join(l for l in (transcript or "").split("\n") if l.startswith("[менеджер]:"))


# ------------------- «СЕГОДНЯ» — ПО ПХУКЕТУ, а не по локали сервера/UTC -------------------
# Весь клиентский контур живёт по времени Пхукета: «сегодня/завтра», «дата уже прошла» и якорь
# прайса обязаны считаться в Asia/Bangkok. На ГРАНИЦЕ СУТОК UTC даёт ДРУГОЙ день (UTC 21.07 18:30 =
# 22.07 01:30 на Пхукете): по UTC старт «с 21 июля» выглядел бы «сегодня» (котируем), по Пхукету он
# уже ПРОШЁЛ (переспрашиваем) — решение обязано приниматься по Пхукету.
# Смещение ФИКСИРОВАННОЕ (+07:00): Таиланд без перехода на летнее время (UTC+7 с 1920 г.), поэтому
# НЕ тянем zoneinfo — на системном python этого ПК пакета tzdata нет вовсе (ZoneInfoNotFoundError на
# ZoneInfo("Asia/Bangkok")), а голдены обязаны быть зелёными на ЛЮБОМ интерпретаторе, не только в venv.
PHUKET_TZ = datetime.timezone(datetime.timedelta(hours=7), "Asia/Bangkok")


def now_phuket(now=None) -> datetime.datetime:
    """Текущий момент по Пхукету (aware datetime). now — инъекция в тестах: любой datetime; наивный
    трактуем как UTC (а не как локаль машины — иначе тест зависел бы от таймзоны ПК)."""
    dt = now or datetime.datetime.now(datetime.timezone.utc)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    return dt.astimezone(PHUKET_TZ)


def today_phuket(now=None) -> datetime.date:
    """«Сегодня» по Пхукету — ЕДИНАЯ точка правды дат клиентского контура (разбор дат клиента,
    гейт прошедшего старта, якорь прайса). Заменяет datetime.date.today() (локаль сервера)."""
    return now_phuket(now).date()


# EN-месяцы клиентов («July 25», «25 July», «Jul 25-30») — наравне с русскими. Латинские
# основы ТОЛЬКО в \b-границах: без них «may» (модальный глагол), «mar»/«aug» внутри слов дают
# ложные месяцы — ровно та опасность, из-за которой граница жила отдельным голденом.
_MONTH_EN = (r"jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|june?|july?"
             r"|aug(?:ust)?|sept?(?:ember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?")
_MONTH_RE = (r"((?:январ|феврал|март|апрел|ма[йя]|июн|июл|август|сентябр|октябр|ноябр|декабр)"
             r"|\b(?:" + _MONTH_EN + r")\b)")
# EN пишут месяц и ПЕРЕД днём («July 25») — отдельный паттерн ТОЛЬКО для латиницы:
# по-русски «июля 25» не пишут, а трогать RU-разбор без нужды опасно для голденов.
_EN_MONTH_FIRST_RE = re.compile(r"\b(" + _MONTH_EN + r")\b\s+(\d{1,2})\b")
_MON_MAP = {"январ": 1, "феврал": 2, "март": 3, "апрел": 4, "май": 5, "мая": 5,
            "июн": 6, "июл": 7, "август": 8, "сентябр": 9, "октябр": 10,
            "ноябр": 11, "декабр": 12}
_MON_MAP_EN = {"jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
               "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12}


def _mon(stem):
    """Основа месяца → номер. EN-формы (jul/july/sept/september…) канонизируем первыми 3 буквами."""
    if stem and stem[:1].isascii():
        return _MON_MAP_EN.get(stem[:3].lower())
    return _MON_MAP.get(stem)


# «may» — ещё и модальный глагол («may i rent…»): в отрыве от цифры месяцем считаем ТОЛЬКО
# в месячном контексте — цифра вплотную или in/for/of/until/till/during перед словом.
_MAY_MONTH_CTX_RE = re.compile(r"\d\s*-?\s*may\b|\bmay\s*[,.]?\s*\d"
                               r"|\b(?:in|for|of|until|till|during)\s+may\b")


def _standalone_month(t):
    """Месяц, названный СЛОВОМ отдельно от чисел диапазона («в июле с 5 по 10», «in may from
    5 to 10»). EN «may» без месячного контекста пропускаем (модальный глагол), идём к
    следующему месяцу в тексте; ничего не нашли → None."""
    for m in re.finditer(_MONTH_RE, t):
        stem = m.group(1)
        if stem != "may" or _MAY_MONTH_CTX_RE.search(t):
            return _mon(stem)
    return None


# --- ПОРЯДКОВЫЕ ФОРМЫ ДНЯ: «25ого», «30ое», «25-е», «1st» — тоже даты -------------------------
# ЖИВОЙ ПРОВАЛ (тренажёр ТЕСТ-10, 22.07 23:49, транскрипт из moderation_ipc.meta): клиент поправил
# даты дословно «Да, даты с 25ого по 30ое июля» — разбор дат НЕ увидел в этом СТАРТА вообще
# (parse_date_range → (None, None)), окно откатилось на ПРЕДЫДУЩУЮ реплику «с 20 по 25 июля», гейт
# признал её прошедшей → dates ❌ → завершающий вопрос «Подскажите даты…» переспросил ровно то, что
# клиент только что назвал. Корень — не воронка, а НЕРАЗОБРАННАЯ живая форма числа: порядковое
# окончание, приклеенное к цифре. Нормализуем ЕДИНОЙ точкой правды перед любым разбором дат.
# Окончание срезаем ТОЛЬКО приклеенное к цифре (или через дефис): «25ого/25-ого/2-е/1st». Через
# ПРОБЕЛ не режем — иначе «на 3 ей неделе» и прочая живая речь начала бы менять числа.
_ORDINAL_TAIL_RE = re.compile(
    r"(?<=\d)-?(?:ого|его|ому|ему|ые|ое|ый|ий|ой|ей|го|е)\b"
    r"|(?<=\d)(?:st|nd|rd|th)\b", re.I)
# «с 25 числа по 30 число» — слово-паразит между числом и предлогом ломало диапазон.
_DAY_WORD_RE = re.compile(r"(?<=\d)\s+числ\w*", re.I)
# EN-обвязка дня той же нормализацией: артикль перед числом («the 25th») и «of» между днём
# и месяцем («25th of July») — после среза EN-фразы разбирает общий код дат.
_EN_THE_DAY_RE = re.compile(r"\bthe\s+(?=\d)", re.I)
_EN_OF_MONTH_RE = re.compile(r"(?<=\d)\s+of\s+(?=(?:" + _MONTH_EN + r")\b)", re.I)


def norm_day_ordinals(text: str) -> str:
    """Живые порядковые формы дня → голое число: «25ого»→«25», «30-ое»→«30», «1st»→«1»,
    «25 числа»→«25», «the 25th»→«25», «25th of July»→«25 July». ИДЕМПОТЕНТНА (повторный
    вызов ничего не меняет), пустой вход → как есть."""
    if not text:
        return text
    t = _DAY_WORD_RE.sub("", _ORDINAL_TAIL_RE.sub("", text))
    return _EN_OF_MONTH_RE.sub(" ", _EN_THE_DAY_RE.sub("", t))


def _safe_date(y, m, d):
    try:
        return datetime.date(int(y), int(m), int(d))
    except (ValueError, TypeError):
        return None


def _mk(day, month, today, year=None):
    """Дата ближайшего будущего (если год не задан явно)."""
    if year:
        y = int(year)
        if y < 100:
            y += 2000
        return _safe_date(y, month, day)
    dt = _safe_date(today.year, month, day)
    if dt is None:
        return None
    if dt < today:                       # прошло в этом году → следующий год (ТОЛЬКО для старта/якоря)
        dt = _safe_date(today.year + 1, month, day)
    return dt


def _day_anchor(day, today):
    """Дата с днём `day` ближайшего будущего, когда МЕСЯЦ не назван («с 20»): текущий месяц, а если
    день уже прошёл (или невалиден для месяца, напр. 31 фев) — ближайший следующий месяц. Год-ролл
    НЕ делаем как лечение (макс. 12 месяцев вперёд). Не нашли валидную дату → None."""
    if not (1 <= day <= 31):
        return None
    for k in range(0, 13):
        mo = (today.month - 1 + k) % 12 + 1
        yr = today.year + (today.month - 1 + k) // 12
        d = _safe_date(yr, mo, day)
        if d is not None and (k > 0 or d >= today):
            return d
    return None


def _resolve_range(d_s, m_s, d_e, m_e, today, y_s=None, y_e=None):
    """Собрать (start, end) из двух точек. Год-ролл end+1г ТОЛЬКО при реальном переходе через
    год (месяц конца < месяца начала, напр. дек→янв). Перепутанный порядок в одном месяце → SWAP
    (НИКОГДА не превращаем в ~360 дней)."""
    start = _mk(d_s, m_s, today, y_s)
    if start is None:
        return None, None
    if y_e:                                          # у конца явный год
        end = _mk(d_e, m_e, today, y_e)
        if end and end < start:
            return end, start                        # явные годы, но реверс → swap
        return start, end
    end = _safe_date(start.year, m_e, d_e)
    if end is None:
        return start, None
    if end >= start:
        return start, end
    if int(m_e) < int(m_s):                          # дек→янв: легитимный переход через год
        return start, _safe_date(start.year + 1, m_e, d_e)
    return end, start                                # тот же/поздний месяц, но end<start → перепутан → swap


def _parse_term(t):
    """Срок из слов → (days:int, monthly:bool) или None."""
    t = norm_day_ordinals(t or "")     # «на 5ый день»/«на 3-и сутки» — та же нормализация, что у дат
    if re.search(r"\bна\s+месяц\b", t) or re.search(r"\bмесяц\b", t):
        return (30, True)
    m = re.search(r"на\s+(\d{1,3})\s*(нед|недел)", t)
    if m:
        return (int(m.group(1)) * 7, False)
    if re.search(r"\bна\s+недел|\bнеделю\b", t):
        return (7, False)
    m = re.search(r"на\s+(\d{1,3})\s*(дн|дня|дней|день|сут)", t)
    if m:
        return (int(m.group(1)), False)
    m = re.search(r"(?:на|for)\s+(\d{1,3})\s*(day|days|week|weeks|month)", t)
    if m:
        n, u = int(m.group(1)), m.group(2)
        if u.startswith("week"):
            return (n * 7, False)
        if u == "month":
            return (n * 30, True)
        return (n, False)
    return None


# ---------- ДЛИННАЯ АРЕНДА: срок, цену на который согласует ЧЕЛОВЕК, а не расчёт ----------
# ПРАВИЛО ВЛАДЕЛЬЦА. Узел `business_rules`, раздел «РЕАЛЬНЫЕ СРОКИ АРЕНДЫ» — прочитан из ЖИВОГО
# реестра моста по имени 21.08.2026 (строки 391-396 узла), ДОСЛОВНО:
#   «ДЛИНА В ПОЛГОДА: сдаём, но полгода обсуждается отдельно — цена такой аренды не берётся
#    из расчёта, её согласует человек. В этом разговоре обсуждаются две вещи: сам период
#    и размер скидки.»
#   «Величина скидки не фиксирована и правилом НЕ становится: в расчёт не идёт, бот её не
#    называет.»
#
# ГРАНИЦА НАЗВАНА ЧИСЛОМ — РЕШЕНИЕ ВЛАДЕЛЬЦА 21.08.2026. Раздел «ГРАНИЦА ДЛИННОЙ АРЕНДЫ ЧИСЛОМ»
# ТОГО ЖЕ узла, прочитан из ЖИВОГО реестра моста 21.08.2026 (строки 427-444), ДОСЛОВНО:
#   «ЧИСЛО НАЗВАНО: граница длинной аренды 180 суток. Правило владельца от 21.08.2026, данными
#    не проверяется.»
#   «С 180 СУТОК И ДОЛЬШЕ бот цену НЕ называет: он говорит, что такой срок считается отдельно,
#    и передаёт запрос человеку. Ни отказа, ни выдуманного числа, ни среднего от себя.»
#   «КОРОЧЕ 180 СУТОК бот считает сам, как прежде: на этой стороне черты в расчёте не меняется
#    ничего.»
#
# ПРЕЖНЕЕ ОБОСНОВАНИЕ ОТМЕНЕНО ЦЕЛИКОМ, а не подправлено числом. До 21.08 здесь стояло 182 — и
# это было НЕ решение, а рабочая отсечка захода 1459f96: числа в правиле тогда не было вовсе, и
# порог брали от соседней равнозначности _PAST_ROLL_MAX_DAYS = 182 («граница ровно посередине —
# полгода»), честно назвав это догадкой исполнителя. Теперь число есть, и оно другое. Сверка с
# живым узлом 21.08: «182» не встречается в нём НИ РАЗУ, «180» — шесть раз.
#
# _PAST_ROLL_MAX_DAYS СЛЕДОМ НЕ ДВИГАЕТСЯ и остаётся 182: он про то, как далеко назад укатывать
# ПРОШЕДШУЮ дату без явного года, а не про длину аренды. Связь между ними была одноразовой
# подпоркой, и с приходом числа она снята — трогать его здесь значило бы чинить чужой предмет.
#
# ЧЕМ ЧЕРТА ОПЛАЧЕНА (замер 18.08, тот же узел, разбор точности по корзинам): на корзине «от 180
# суток и дольше» расчёт попадает 40 раз из ста, в пять процентов — НОЛЬ из ста, и лежит
# систематически на 16.8 процента НИЖЕ уплаченного. Ниже черту не опускают потому, что соседняя
# корзина «от 30 до 179 суток» держит 42 процента ВСЕЙ выручки при промахе около 7.5 процента:
# замолчать на ней дороже, чем терпеть промах. Помесячная аренда и двухмесячный пик
# экзаменационного случая 4 остаются на расчёте — они по эту сторону черты.
_LONG_TERM_MIN_DAYS = 180

# Словесные формы срока НЕ КОРОЧЕ полугода. _parse_term их не знает ВОВСЕ (он умеет «месяц»,
# «N недель», «N дней», «N months») — ровно поэтому «скутер на полгода» доезжал до цены
# с term_days=None и считался наравне с недельной арендой (экзамен, случай 7).
# ПОБОЧНЫЙ ЭФФЕКТ ЧЕРТЫ 180, названный явно: два входа признака перестали спорить. «for 6 months»
# _parse_term переводит в 6*30 = 180 суток, и при прежнем пороге 182 ЧИСЛО звало этот срок
# коротким, а СЛОВО — длинным; сходилось только потому, что хватало любого из двух. Теперь
# 6 месяцев ложатся ровно НА границу, и оба входа отвечают одинаково.
_LONG_TERM_WORD_RE = re.compile(
    r"пол\s*-?\s*года"                              # полгода / пол года / пол-года
    r"|полугод\w*"                                  # полугодие / полугода
    r"|half\s+a\s+year"
    r"|(?:6|шесть|six)\s*(?:мес|month)\w*"          # 6 месяцев / six months
    r"|(?:[7-9]|1[0-9]|2[0-4])\s*(?:мес|month)\w*"  # 7-24 месяца
    r"|на\s+год(?!\w)|for\s+a\s+year"
    r"|на\s+\d+\s*(?:год|года|лет)(?!\w)|for\s+\d+\s*years?(?!\w)",
    re.I)
# «взял байк полгода НАЗАД» — это история клиента, а не срок аренды: живой класс, из-за которого
# треды уезжали в 'mixed' (см. комментарий у режима треда выше). Смотрим ТОЛЬКО хвост сразу за
# совпадением, а не всё сообщение: слово «назад» в другом месте фразы срок не отменяет.
_LONG_TERM_PAST_RE = re.compile(r"^(?:назад|тому\s+назад|ago)\b", re.I)


def _long_term_words(text) -> bool:
    """Клиент СЛОВАМИ назвал срок не короче полугода? → True/False.
    Длину в сутках отсюда НЕ возвращаем: на исход влияет сам факт, а число в ценовую записку
    класть нельзя — белый список пост-чека (_pc_wl_price_numbers) берёт ЛЮБЫЕ цифры записки,
    и «180» стало бы разрешённой ценой."""
    t = text or ""
    for m in _LONG_TERM_WORD_RE.finditer(t):
        if _LONG_TERM_PAST_RE.match(t[m.end():].lstrip()):
            continue                      # «…полгода назад» — прошлая аренда, не эта
        return True
    return False


def _anchor_date(t, today):
    """Дата начала для срочных фраз («завтра на 3 дня», «на неделю с 5 июля»)."""
    if "послезавтра" in t:
        return today + datetime.timedelta(days=2)
    if "завтра" in t:
        return today + datetime.timedelta(days=1)
    if "сегодня" in t:
        return today
    m = re.search(r"с\s+(\d{1,2})\s+" + _MONTH_RE, t)
    if m:
        return _mk(int(m.group(1)), _mon(m.group(2)), today)
    m = re.search(r"с\s+(\d{1,2})[./](\d{1,2})(?:[./](\d{2,4}))?", t)
    if m:
        return _mk(int(m.group(1)), int(m.group(2)), today, m.group(3) or None)
    m = re.search(r"(\d{1,2})\s+" + _MONTH_RE, t)
    if m:
        return _mk(int(m.group(1)), _mon(m.group(2)), today)
    m = re.search(r"(\d{1,2})[./](\d{1,2})", t)
    if m:
        return _mk(int(m.group(1)), int(m.group(2)), today)
    m = _EN_MONTH_FIRST_RE.search(t)         # «July 25 for 5 days» (EN, месяц-перед-днём)
    if m:
        return _mk(int(m.group(2)), _mon(m.group(1)), today)
    # ГОЛЫЙ ДЕНЬ БЕЗ МЕСЯЦА: «с 20 [на 2 недели]» → старт = 20-е ближайшего будущего (тек. месяц, а
    # если день уже прошёл — следующий месяц; НЕ следующий год). Фиксирует старт из трекера, когда
    # клиент дал только число+длительность — иначе цена-нот проваливалась в «уточни даты» (дыра, в
    # которую LLM подставлял чужую карточку). Не хватаем «с 20 по/до …» (это диапазон, не старт+срок).
    m = re.search(r"\bс\s+(\d{1,2})\b(?!\s*(?:по|до|-|\d|[./]))", t)
    if m:
        return _day_anchor(int(m.group(1)), today)
    return None


def parse_date_range(text, today=None):
    """Диапазон дат из слов клиента → (iso_start, iso_end) или (None, None).
    Поддержка: «10.07-15.07», «с 5 по 10.07», «5–10 июля», «с 5 по 10 июля», «с 28 декабря по
    3 января» (год-ролл), «на неделю/месяц с 5 июля», «завтра на 3 дня», перепутанный порядок
    (swap); EN-формы наравне с русскими: «July 25», «25 July», «Jul 25-30», «25th of July»,
    смешанные («с 25 July по 30»). Год-ролл end+1г — ТОЛЬКО при реальном переходе через год,
    НЕ как лечение."""
    today = today or today_phuket()
    # Порядковые формы дня («25ого по 30ое июля», «25th of July») нормализуем ДО разбора — иначе
    # живая реплика клиента не даёт ни диапазона, ни старта (корень ТЕСТ-10, см. norm_day_ordinals).
    t = norm_day_ordinals(
        (text or "").lower().replace("–", "-").replace("—", "-").replace("ё", "е"))
    # Точки «день+месяц» ОБОИХ порядков: день-перед-месяцем (RU/EN) и месяц-перед-днём (EN,
    # «July 25»). Месяц-первые матчи, пересекающиеся с день-первыми, отбрасываем — в «25 may
    # 30 june» связка «may 30» не смеет украсть день у соседних точек. Итог — по позиции в тексте.
    dfm = list(re.finditer(r"(\d{1,2})\s+" + _MONTH_RE, t))
    mfm = [m for m in _EN_MONTH_FIRST_RE.finditer(t)
           if not any(m.start() < d.end() and d.start() < m.end() for d in dfm)]
    pts = sorted([(m.start(), m.end(), int(m.group(1)), _mon(m.group(2))) for m in dfm] +
                 [(m.start(), m.end(), int(m.group(2)), _mon(m.group(1))) for m in mfm])
    dmy = re.findall(r"(\d{1,2})[./](\d{1,2})(?:[./](\d{2,4}))?", t)
    # месяц диапазона голых чисел: у ЕДИНСТВЕННОЙ точки он надёжнее слова, взятого поиском по
    # всему тексту («i may arrive 5-10 july» — месяц july, а не модальный may)
    mw = pts[0][3] if len(pts) == 1 else _standalone_month(t)
    rng = re.search(r"(?:с\s*)?(\d{1,2})\s*(?:-|по|до|to|till|until)\s*(\d{1,2})", t)
    term = _parse_term(t)

    s = e = None
    if len(pts) >= 2:                                       # «28 декабря по 3 января» / «July 25 to July 30»
        s, e = _resolve_range(pts[0][2], pts[0][3], pts[1][2], pts[1][3], today)
    elif len(dmy) >= 2:                                      # «10.07-15.07»
        s, e = _resolve_range(int(dmy[0][0]), int(dmy[0][1]), int(dmy[1][0]), int(dmy[1][1]),
                              today, dmy[0][2] or None, dmy[1][2] or None)
    elif rng and (mw or len(dmy) == 1):                     # «с 5 по 10 июля» / «Jul 25-30» / «с 5 по 10.07»
        month = mw if mw else int(dmy[0][1])
        yhint = (dmy[0][2] or None) if len(dmy) == 1 else None
        s, e = _resolve_range(int(rng.group(1)), month, int(rng.group(2)), month, today, yhint, yhint)
    elif len(pts) == 1 and (m2 := re.match(                 # «с 25 July по 30» / «с 25 июля до 30»:
            r"\w*\s*(?:-|по|до|to|till|until)\s*(\d{1,2})\b",  # месяц назван у СТАРТА, конец — голым
            t[pts[0][1]:])):                                   # днём сразу за точкой
        s, e = _resolve_range(pts[0][2], pts[0][3], int(m2.group(1)), pts[0][3], today)
    elif term:                                              # «на неделю с 5 июля» / «завтра на 3 дня»
        anchor = _anchor_date(t, today)
        if anchor:
            s = anchor
            e = anchor + datetime.timedelta(days=term[0])

    if not (s and e):
        return None, None
    if e < s:                                               # финальная страховка: swap, НЕ год-ролл
        s, e = e, s
    return s.isoformat(), e.isoformat()


# ------------------- ГЕЙТ СТАРТА АРЕНДЫ: прошедшие даты НЕ котируем -------------------
# ЖИВОЙ ДЕФЕКТ (тренажёр ТЕСТ-7, 22.07): клиент «с 20 по 25 июля», сегодня 22 июля → бот МОЛЧА выдал
# котировку. Механика: _mk() роллит уже прошедшую дату на СЛЕДУЮЩИЙ год (parse_date_range вернул
# 2027-07-20…2027-07-25) — год-ролл нужен для «в декабре про январь», но на «позавчера» он молча
# превращает описку/прошлое в бронь через год, и цена уезжает клиенту без единого вопроса.
#
# ПРАВИЛО «БЛИЖАЙШЕЕ ВХОЖДЕНИЕ»: у даты без явного года два прочтения — в этом году и в следующем;
# клиент имел в виду то, что БЛИЖЕ к сегодня.
#   • «20 июля» при 22 июля: −2 дня против +363 → ближайшее ПРОШЛОЕ → переспрос БЕЗ цены;
#   • «5 января» при 22 декабря: −351 против +14 → ближайшее БУДУЩЕЕ → штатная котировка (год-ролл цел).
# Граница ровно посередине — полгода. Явный год в тексте («с 20 июля 2027») читаем БУКВАЛЬНО, без
# поиска ближайшего вхождения: клиент сам снял неоднозначность.
# Сравнение — с «сегодня» ПО ПХУКЕТУ (today_phuket), не по UTC/локали: см. PHUKET_TZ.
_PAST_ROLL_MAX_DAYS = 182
_EXPLICIT_YEAR_RE = re.compile(r"\b(?:19|20)\d{2}\b")


def _iso_date(iso):
    try:
        return datetime.date.fromisoformat(str(iso))
    except (ValueError, TypeError):
        return None


def _nearest_start(iso_start, today, text=None):
    """Дата старта В ПРОЧТЕНИИ КЛИЕНТА — ближайшее к `today` вхождение названного дня/месяца.
    parse_date_range уже перенёс прошедшую дату на +1 год; если её вхождение в ПРОШЛОМ ближе
    (не дальше _PAST_ROLL_MAX_DAYS назад) и явного года в тексте НЕТ — клиент имел в виду именно
    его. → date | None (дату не разобрали)."""
    d = _iso_date(iso_start)
    if d is None:
        return None
    if text and _EXPLICIT_YEAR_RE.search(text):
        return d                                    # год назван явно → читаем буквально
    prev = _safe_date(d.year - 1, d.month, d.day)   # 29 фев в невисокосном → None (падаем на d)
    if prev and prev < today and (today - prev).days <= _PAST_ROLL_MAX_DAYS:
        return prev
    return d


def start_date_status(iso_start, today=None, text=None):
    """Статус старта аренды для гейта котировки → 'past' | 'today' | 'tomorrow' | 'future' | None.
    None — старта нет/не разобрали (гейт молчит, прежние ветки не трогаем). text — сообщение
    клиента, из которого взяты даты (нужен, чтобы увидеть ЯВНЫЙ год)."""
    today = today or today_phuket()
    d = _nearest_start(iso_start, today, text)
    if d is None:
        return None
    if d < today:
        return "past"
    if d == today:
        return "today"
    if d == today + datetime.timedelta(days=1):
        return "tomorrow"
    return "future"


def _client_messages(transcript: str):
    """Реплики КЛИЕНТА (не менеджера) в хронологическом порядке, lowercased."""
    return [ln[len("[клиент]:"):].strip().lower()
            for ln in (transcript or "").split("\n") if ln.startswith("[клиент]:")]


def _detect_model(text: str):
    for tok in _MODEL_TOKENS:
        if tok in text:
            return tok.upper().replace(" ", "")
    return None


def _detect_models(text: str):
    """ВСЕ модели, упомянутые в тексте (для запроса нескольких байков сразу). Порядок
    появления, без дублей; «ADV» отбрасываем, если есть более точная «ADV350» и т.п."""
    found = []
    for tok in _MODEL_TOKENS:
        if tok in text:
            canon = tok.upper().replace(" ", "")
            if canon not in found:
                found.append(canon)
    # снять префиксы, поглощённые более длинной моделью (ADV ⊂ ADV350, CBR ⊂ CBR650)
    return [c for c in found if not any(o != c and o.startswith(c) for o in found)]


# --- класс байка → минимальный срок аренды (правила цен v2, п.2) ---------------
# Скутеры сдаём от 5 дней (XSR155 тоже 5), мотоциклы — от 3.
SCOOTER_MIN_DAYS = 5
MOTO_MIN_DAYS = 3
_MOTO_PREFIXES = ("CB300", "CB650", "CBR", "REBEL", "MT", "NINJA", "VULCAN", "R7")
_SCOOTER_PREFIXES = ("PCX", "NMAX", "FORZA", "XMAX", "XADV", "ADV")


def bike_class(model):
    """(kind, min_days, label) для модели или None, если класс неизвестен.
    kind: 'scooter'|'moto'. label — как называть тип в сообщении клиенту."""
    m = re.sub(r"[^A-Z0-9]", "", (model or "").upper())
    if not m:
        return None
    if m.startswith("XSR"):
        if "900" in m:                       # XSR900 — большой мотоцикл (3)
            return ("moto", MOTO_MIN_DAYS, "мотоциклы")
        return ("scooter", SCOOTER_MIN_DAYS, "этот байк")   # XSR155 → минимум как у скутеров (5)
    for t in _MOTO_PREFIXES:
        if m.startswith(t):
            return ("moto", MOTO_MIN_DAYS, "мотоциклы")
    for t in _SCOOTER_PREFIXES:
        if m.startswith(t):
            return ("scooter", SCOOTER_MIN_DAYS, "скутеры")
    return None


# --- XMAX 300: ДВА ПОКОЛЕНИЯ = ДВА ПРОДУКТА --------------------------------------
# В парке (Лист1) XMAX двух поколений с РАЗНЫМИ тарифами: старое 2020-2022 (юниты БЕЗ токена «NEW»
# в имени, дешевле, депозит 5000) и новое 2023+ («…CC NEW …» в имени, дороже, депозит 7000). Раньше
# сетка/точечный quote схлопывали их МИНИМУМОМ по вариантам в одну строку — наценка нового поколения
# пропадала. Теперь это ДВА продукта отдельными строками, каждый с ЖИВЫМИ цифрами по своим юнитам;
# правило «минимум по вариантам» снято ТОЛЬКО для XMAX (для прочих моделей оно сохраняется).
_XMAX_KEY = _bike_key("XMAX 300")          # 'xmax300'


def _is_xmax_model(model) -> bool:
    """Модель — это XMAX (в любой форме: «XMAX 300», «XMAX300», голый canon «XMAX» из детекта).
    В парке XMAX только 300cc, поэтому ключа с префиксом 'xmax' достаточно."""
    return _bike_key(model).startswith("xmax")


def _xmax_is_new_gen(unit_name) -> bool:
    """Юнит XMAX нового поколения — в имени отдельный токен NEW (Лист1: «XMAX 300CC NEW …»)."""
    return bool(re.search(r"(?i)\bnew\b", str(unit_name or "")))


# Год выпуска поколения в СЫРОМ имени юнита (J-текст Bridge несёт имя вида «…XMAX 300 NEW 2023-…»)
# течёт клиенту в quote-хвост черновика. Поколение обязано нести МЕТКА (New Gen) — как в клиентском
# теле по правилу промпта (GEN_DEFAULT_RULE: «НЕ пиши года выпуска»), а год выпуска клиенту не
# показываем. Чистим год-в-имени (диапазон «2020-2022» / «2023+» / «2021 года» / одиночный 20xx),
# но НЕ цену: год-токен перед валютой (฿/бат/THB/baht) — это сумма, его не трогаем.
# ПРАВАЯ ГРАНИЦА (?!\d) — не косметика: без неё «2000» матчилось ВНУТРИ пятизначной суммы «20000 ฿»
# (лукахед на валюту не спасал — сразу за «2000» стоит пятая цифра, а не ฿). Цена этого на ОБЕИХ
# полосах, замер 31.07 (docs/artifacts/2026-07-31-revizor-false-findings-audit.md, §Гипотеза 2):
#   • проверяльщик #92 «нет годов» — 6 ложных находок ревизора «годы в тексте: 2000» на прайс-блоках,
#     где депозит мотоцикла 20000 ฿ (CBR 650R, CB 650R, NINJA 400, VULCAN 650S);
#   • БОЕВОЙ контур — _scrub_gen_year на живой строке J превращал «депозит: 20000 бат» в
#     «депозит: 0 бат». Мина была заряжена, но по корпусу (376 строк прода) ещё не выстрелила.
_GEN_YEAR_RE = re.compile(
    r"\b20\d\d(?:\s*[-–]\s*20\d\d|\s*\+|\s*года?)?(?!\d)(?!\s*(?:฿|бат|thb|baht))",
    re.I)


def _scrub_gen_year(text: str) -> str:
    """Убрать год выпуска поколения из клиентской строки цены (поколение несёт метка New Gen, не год).
    Цену не трогаем — год-токен перед валютой (฿/бат/THB) сохраняем. Осиротевший после выреза дефис
    («NEW 2023-» → «NEW -») и сдвоенные пробелы схлопываем."""
    s = _GEN_YEAR_RE.sub("", str(text or ""))
    s = re.sub(r"\s+[-–](?=\s|$)", "", s)          # висячий дефис от «2023-»
    s = re.sub(r"\(\s*\)|\[\s*\]", "", s)          # осиротевшие скобки от «(2020-2022)»/«(2023+)»
    s = re.sub(r"\s+([,.;:!?])", r"\1", s)         # пробел, оставшийся перед знаком препинания
    s = re.sub(r"\s{2,}", " ", s).strip()
    return s


# Продукты XMAX: (метка клиенту, предикат по имени юнита). Порядок = порядок строк в сетке/quote.
_XMAX_PRODUCTS = (
    ("XMAX 300", lambda nm: not _xmax_is_new_gen(nm)),          # старое поколение (без «NEW»)
    ("XMAX 300 New Gen", _xmax_is_new_gen),                     # новое поколение 2023+
)


def _model_products_for_quote(model, want_old_gen=False):
    """Модель → продукты для ТОЧЕЧНОГО quote: [(метка, name_filter)]. ЕДИНЫЙ гэттер поколений (тот же
    в первичной генерации и в strategy-перегенерации — год поколения в клиентское тело не течёт нигде):
      • XMAX по умолчанию (want_old_gen=False) → ТОЛЬКО актуальное поколение (New Gen) ОДНОЙ строкой,
        без годов и без «старый/новый» вопроса (глобальное правило поколений, кейс @cryptopeppa 15.07);
      • XMAX + явный запрос клиента про прежнее поколение (want_old_gen=True, «а старый xmax есть?») →
        ОБА поколения отдельными строками (старое / New Gen), как каталог по явной просьбе;
      • прочие модели — один продукт с name_filter=None (поведение как раньше)."""
    if _is_xmax_model(model):
        prods = _XMAX_PRODUCTS if want_old_gen else _XMAX_PRODUCTS[1:]   # [1:] = только New Gen
        return [(label, pred) for label, pred in prods]
    return [(model, None)]


# Клиент ЯВНО просит ПРЕЖНЕЕ поколение (XMAX): «старый xmax», «старое поколение», «прежнее»,
# «не новый», «old (gen)», модель-годы 2018-2022. Только тогда показываем оба поколения; иначе
# по умолчанию — лишь актуальное (New Gen). Формы «стар…» перечислены явно, чтобы НЕ ловить «старт».
_OLD_GEN_RE = re.compile(
    r"стар(?:ый|ое|ую|ая|ого|ом|ым|ой|ше|еньк\w*)"        # старый/старое поколение, старше (не «старт»)
    r"|прежн\w+"                                            # прежнее поколение
    r"|\bold(?:er)?\b|old[-\s]?gen|previous\s+gen"         # old / older / old gen / previous gen
    r"|не\s+нов\w+|not\s+new"                               # не новый / not new
    r"|\b20(?:1[89]|2[0-2])\b",                             # модель-годы 2018-2022 (прежнее поколение)
    re.I)


def _asks_old_gen(newest: str, recent: str) -> bool:
    """Клиент ЯВНО просит прежнее поколение модели (см. _OLD_GEN_RE) → True. Ищем во ВСЁМ окне
    (newest+recent): запрос про «старый xmax» часто приходит РЕПЛИКОЙ ПОЗЖЕ дат первичной брони."""
    return bool(_OLD_GEN_RE.search(f"{newest or ''}\n{recent or ''}"))


# --- ДВЕ РУЧКИ ПОДБОРА ПО КЛАССУ (правило владельца «подбор по классу 20.08») -------------------
# Обе открывает ТОЛЬКО клиент своими словами; сам бот ни одну не включает.
#
# ТЯЖЁЛЫЙ КЛАСС (X-ADV 750) — «только если клиент САМ сказал про мощность, размер или опыт».
# Слово «опыт» здесь двусмысленно, и разводить его обязательно: «опыта нет» — это тоже разговор про
# опыт, но поднимать новичка в тяжёлый класс на этом основании было бы прямым нарушением
# EXPERIENCE_SAFETY_RULE. Поэтому отрицание опыта ЗАКРЫВАЕТ ручку, а не открывает.
_HEAVY_OK_RE = re.compile(
    r"мощн\w*|помощнее|мощ[её]й"                                  # мощность
    r"|кубат\w*|\d{3}\s*(?:куб\w*|cc|сс|см3)|куб\w+"              # кубатура словами клиента
    r"|крупн\w*|побольше|поболь\w*|тяж[её]л\w*|большой\s+байк\w*|большие\s+байк\w*"   # размер
    r"|\bопыт\w*|стаж\w*|ездил\w*|катал\w*|управлял\w*|права\s+категор\w*"            # опыт
    r"|powerful|more\s+power|bigger|big\s+bike|heavy\s+bike"
    r"|experienc\w*|been\s+riding|have\s+ridden|ride[dn]?\s+for\s+\d",
    re.I)
# Отрицание опыта/новичок — ручка тяжёлого класса ЗАКРЫТА, чем бы её ни открывали выше.
_HEAVY_BLOCK_RE = re.compile(
    r"без\s+опыт\w*|не\s*т\s+опыт\w*|нет\s+опыт\w*|опыта\s+нет|не\s+было\s+опыт\w*"
    r"|новичок|новичк\w*|нович[её]к|впервые|первый\s+раз|никогда\s+не\s+ездил\w*"
    r"|no\s+experience|never\s+ridden|never\s+rode|beginner|first\s+time|newbie",
    re.I)
# КЛАСС НИЖЕ — только по прямой просьбе клиента «дешевле / проще». Формы перечислены явно, чтобы не
# ловить «проще говоря» и «дешевле, чем у соседей» (второе — торг о цене, а не просьба другого класса).
_CHEAPER_RE = re.compile(
    r"подешевл\w*|дешевл\w+\s+(?:есть|вариант\w*|что|чего|модел\w*|байк\w*)|"
    r"есть\s+(?:что[- ])?(?:нибудь\s+)?(?:подешевле|дешевле|попроще|проще)|"
    r"попроще|что[- ]нибудь\s+проще|поменьше\s+(?:кубат\w*|байк\w*)|"
    r"бюджетн\w*|эконом(?:ич\w*|н\w*|)\b|"
    r"cheaper|cheapest|budget\s+option|something\s+simpler|simpler\s+one|less\s+powerful|smaller\s+bike",
    re.I)


def _asks_heavy_class_ok(newest: str, recent: str) -> bool:
    """Клиент САМ заговорил про мощность/размер/опыт → тяжёлый класс предлагать МОЖНО.
    Отрицание опыта («без опыта», «новичок») закрывает ручку целиком — правило безопасности выше."""
    text = f"{newest or ''}\n{recent or ''}"
    if _HEAVY_BLOCK_RE.search(text):
        return False
    return bool(_HEAVY_OK_RE.search(text))


def _asks_cheaper_or_simpler(newest: str, recent: str) -> bool:
    """Клиент САМ попросил дешевле/проще → и только тогда бот вправе спуститься классом НИЖЕ."""
    return bool(_CHEAPER_RE.search(f"{newest or ''}\n{recent or ''}"))


def _asks_deposit_reduction_multi(newest: str, recent: str, models) -> bool:
    """Явный вопрос клиента про уменьшение депозита при нескольких байках (правила цен v2, п.4).
    newest — последняя реплика клиента, recent — склейка последних реплик, models — найденные модели."""
    dep = re.search(r"депозит|залог|deposit", newest or "")
    less = re.search(r"меньше|уменьш|сниз|скид|дешевл|пониз|lower|reduce|discount|less", newest or "")
    multi = re.search(r"нескольк|два\b|две\b|\bоба\b|\bобе\b|байка|байков|мотик|two|both|several",
                      recent or "")
    return bool(dep and less and (multi or len(models or []) >= 2))


# Клиент ЯВНО выбрал ПАСПОРТ как депозит (KB: депозит = деньги ЛИБО паспорт, не оба). Ловим ДВА
# сигнала В ОДНОЙ реплике — «паспорт» И депозит-контекст (залог/депозит/«вместо денег»): «фото
# паспорта пришлю» + отдельный вопрос «какой депозит?» НЕ должны давать ложный выбор паспорта.
_DP_PASSPORT_RE = re.compile(r"паспорт|passport", re.I)
_DP_DEPOSIT_CTX_RE = re.compile(
    r"залог|депозит|deposit|вместо\s+денег|вместо\s+деньг\w*|вместо\s+нал\w*"
    r"|instead\s+of\s+(?:the\s+)?(?:money|cash|deposit)", re.I)


def _deposit_passport_chosen(window) -> bool:
    """Клиент выбрал ПАСПОРТ вместо денежного депозита → True. window — реплики клиента (любой
    порядок); ОБА сигнала (паспорт + залог/депозит/«вместо денег») обязаны быть в ОДНОЙ реплике."""
    for msg in (window or []):
        s = msg or ""
        if _DP_PASSPORT_RE.search(s) and _DP_DEPOSIT_CTX_RE.search(s):
            return True
    return False


# Строка цены несёт сумму депозита из Bridge («депозит 3000 ฿», «депозит 3000 бат», «deposit 3000 THB»)
# — при выборе паспорта её меняем на «депозит: паспорт» без числа (тело ответа и quote-хвост не
# противоречат друг другу). Сама цена/итог не трогается — совпадение только на депозит-сумме.
_DEPOSIT_SUM_RE = re.compile(
    r"(?:депозит|залог|deposit)\w*\s*[:\-—]?\s*\d[\d\s]*\s*(?:฿|бат\w*|(?:thb|baht)\b)", re.I)


def _deposit_as_passport(phrase: str, lang: str = "ru") -> str:
    """Клиент выбрал ПАСПОРТ (KB: депозит = деньги ЛИБО паспорт, не оба): сумму депозита из Bridge в
    строке цены заменяем на «депозит: паспорт» (без числа). Нет суммы во фразе → дописываем явно."""
    repl = "deposit: passport" if lang == "en" else "депозит: паспорт"
    new, n = _DEPOSIT_SUM_RE.subn(repl, phrase or "")
    if n:
        return new
    base = (phrase or "").rstrip().rstrip(".")
    return (base + "; " + repl) if base else repl


def _explicit_monthly(text: str) -> bool:
    """monthly ТОЛЬКО по явному слову клиента, НЕ по длительности диапазона."""
    return bool(re.search(r"месяц|\bmonth\b|monthly", text or ""))


# «N юнитов ОДНОЙ модели»: клиент просит несколько единиц одной модели («пара XMAX», «два скутера»,
# «2 xmax»). Цена/депозит Bridge на такой запрос — ЗА КАЖДЫЙ юнит; общий итог НЕ выдумываем (числа
# только из quote, KB правила цен v2 п.4 «депозит при нескольких байках»). Слово-число («пара/два»)
# считаем ЮНИТАМИ лишь при байк/юнит-контексте (скутер/байк/шт) ИЛИ явной модели — «два дня/недели»
# (срок) исключаем хвост-проверкой. Цифра+существительное («2 скутера») самодостаточна.
_UNITS_DIGIT_RE = re.compile(
    r"\b([2-9]|1[0-9])\s*(?:шт\b|штук\w*|юнит\w*|единиц\w*|байк\w*|скутер\w*|мотоцикл\w*|мотик\w*"
    r"|bike|scooter|unit)", re.I)
_UNITS_CTX_RE = re.compile(
    r"скутер|байк|мотоцикл|мотик|штук|\bшт\b|юнит|единиц|\bbike|\bscooter|\bunit", re.I)
_UNITS_TIME_TAIL_RE = re.compile(
    r"\s*(?:дн\w*|недел\w*|нед\b|месяц\w*|сут\w*|day|week|month)", re.I)
_UNITS_WORD_MAP = (
    (re.compile(r"пар[ауеы]|\bpair\b|\bcouple\b", re.I), 2),
    (re.compile(r"\bдв[ае]\b|\bдвух\b|\bоб[ае]\b|\bboth\b|\btwo\b", re.I), 2),
    (re.compile(r"\bтр[её]х\b|\bтри\b|\bthree\b", re.I), 3),
    (re.compile(r"\bчетыр[её]х\b|\bчетыре\b|\bfour\b", re.I), 4),
)


def _units_count(newest: str, models):
    """Сколько ЮНИТОВ одной модели просит клиент («пара»/«два»/«2 скутера») → int ≥ 2 или None.
    Разные модели (len(models) ≥ 2) — это НЕ N юнитов одной модели, а разные модели (их считает
    путь буллетов) → None. Слово-число без байк/юнит-контекста и без модели («на два дня») НЕ в счёт."""
    t = newest or ""
    md = _UNITS_DIGIT_RE.search(t)
    if md:
        return int(md.group(1))
    if len(models or []) >= 2:
        return None
    has_ctx = bool(_UNITS_CTX_RE.search(t))
    single_model = bool(models) and len(models) == 1
    if not (has_ctx or single_model):
        return None
    for rx, n in _UNITS_WORD_MAP:
        m = rx.search(t)
        if m and not _UNITS_TIME_TAIL_RE.match(t[m.end():]):    # «два дня/недели» — срок, не юниты
            return n
    return None


def _units_count_note(n, lang="ru") -> str:
    """Довесок к блоку ЦЕНА: клиент просит N юнитов одной модели → цена/депозит Bridge выше = ЗА
    КАЖДЫЙ юнит; общий итог за N штук НЕ считаем и НЕ выдумываем (числа только из quote — п.4).
    Строка начинается с пробела (клеится к note, как DEPOSIT_MULTI_NOTE)."""
    if lang == "en":
        return (f" MULTIPLE UNITS: the client asks for {n} units of this model — the price AND "
                f"deposit above are PER UNIT (say «each»); do NOT compute or invent a grand total "
                f"for {n} units, the manager will confirm the total for the quantity.")
    return (f" НЕСКОЛЬКО ЮНИТОВ: клиент просит {n} ед. этой модели — цена И депозит выше указаны "
            f"ЗА КАЖДЫЙ юнит (так и подпиши: «за каждый»); общую сумму за {n} шт. сам НЕ считай и "
            f"НЕ выдумывай — итог по количеству уточнит менеджер.")


def _units_per_each_line(n, lang="ru") -> str:
    """Клиентская строка ХВОСТОМ точечного quote-блока N юнитов (compose_quote_draft): цена/депозит
    Bridge выше — ЗА КАЖДЫЙ юнит; итог за N шт. КОД не суммирует и не выдумывает (уточнит менеджер).
    В отличие от _units_count_note (инструкция LLM) это ДОСЛОВНЫЙ клиентский текст — попадает в тело
    как есть, если strategy-перегенерация теряет цену."""
    if lang == "en":
        return (f"Price and deposit above are PER UNIT (the client asks for {n}); the total for the "
                f"quantity will be confirmed by the manager.")
    return (f"Цена и депозит выше — ЗА КАЖДЫЙ юнит (клиент просит {n} шт.); итог по количеству "
            f"уточнит менеджер.")


# «сколько будет N%» / «N% это какая сумма» — клиент просит ПОСЧИТАТЬ процент от суммы расчёта
# (шаг 2/7 #253). Нужны ОБА: сам процент (число+% / «процентов» / percent) И вопрос-о-сумме
# («сколько/какая сумма/это сколько/how much»). Просто «скидка 10%» без вопроса-о-сумме сюда НЕ
# попадает (это не запрос посчитать). Процент считаем КОДОМ от total живого quote (не LLM).
_PCT_TOKEN_RE = re.compile(r"(\d{1,3})\s*(?:%|процент\w*|percent)", re.I)
_PCT_ASK_RE = re.compile(
    r"скольк|как(?:ая|ую|ой)\s+сумм|это\s+скольк|\bсумм\w*|\bэто\b|how\s+much|what.?s\b|составит|получ",
    re.I)


def _asks_percent_amount(newest: str, recent: str):
    """Клиент спрашивает «сколько будет N%» / «N% это какая сумма» → N (int 1..100) или None.
    Ищем в последней реплике, затем в окне; процент И вопрос-о-сумме обязаны быть вместе."""
    for src in (newest or "", recent or ""):
        mt = _PCT_TOKEN_RE.search(src)
        if mt and _PCT_ASK_RE.search(src):
            n = int(mt.group(1))
            if 1 <= n <= 100:
                return n
    return None


def _has_date_signal(text: str) -> bool:
    text = norm_day_ordinals(text or "")     # «с 25ого по 30ое» — тоже сигнал дат
    if re.search(r"\d{1,2}[.\-/]\d{1,2}", text or ""):
        return True
    if _parse_term(text):
        return True
    if re.search(r"с\s+\d{1,2}\s+(?:по|до)\s+\d{1,2}", text or ""):
        return True
    return any(mo in (text or "") for mo in _MONTHS)


def _has_start_signal(text: str) -> bool:
    """Конкретный СТАРТ аренды (в отличие от одной лишь ДЛИТЕЛЬНОСТИ): число+месяц («15 июля»),
    dd.mm («15.07», «с 15.07»), «с 15 …», «завтра/послезавтра/сегодня» (в т.ч. «с завтрашнего»).
    Одна длительность («на 10 дней», «на неделю») старта НЕ задаёт — сюда НЕ входит."""
    t = norm_day_ordinals((text or "").lower())
    if re.search(r"послезавтра|завтра|сегодня", t):
        return True
    if re.search(r"\d{1,2}[.\-/]\d{1,2}", t):                 # 15.07 / 15/07
        return True
    if re.search(r"\d{1,2}\s+" + _MONTH_RE, t):               # 15 июля / 15 July
        return True
    if _EN_MONTH_FIRST_RE.search(t):                          # July 15 (EN, месяц-перед-днём)
        return True
    return False


# --- намерение «прайс по всему парку / все модели / прайс-лист» (сценарий price_sheet) --------
# Позитив: «цены на все модели», «прайс», «прайс-лист», «весь парк», «по всем байкам сколько».
# Негатив: «сколько стоит NMAX» (одна модель), «всё включено?», «все новые байки?» (нет цены/парка).
_PS_ALL_SCOPE = re.compile(
    r"вс[еёх]\w*\s+(?:модел|байк|скутер|мотоцикл|вариант)"
    r"|весь\s+парк|всего\s+парка|по\s+всему\s+парку|на\s+вс[её]\s+модел"
    r"|all\s+(?:the\s+)?(?:models|bikes|scooters|motos)|whole\s+fleet|entire\s+fleet"
    r"|full\s+(?:list|range|fleet)|every\s+(?:model|bike)", re.I)
_PS_PRICE_LIST = re.compile(
    r"прайс[\s\-]?лист|прайс[- ]?лист|\bпрайс\b|price\s*-?\s*list|pricelist"
    r"|список\s+(?:модел|байк|цен|тариф)|list\s+of\s+(?:models|bikes|prices)", re.I)
_PS_PRICE_WORD = re.compile(
    r"цен[аыуэ]|цены|стоимост|стоит|сколько|тариф|расцен|price|cost|how\s+much|\brate", re.I)

# --- смысловые признаки (классификация, а НЕ бесконечный список ключевиков) --------------------
# Клиент реально просит либо ПЕРЕЧЕНЬ моделей, либо ЦЕНЫ-В-ЦЕЛОМ (не по одной названной модели).
# Признак «перечень» = вопрос/предложение-цель + собирательное «модели/байки/марки».
_PS_ENUM_CUE = re.compile(
    r"как(?:ие|ой|их|ого)\b|что\s+(?:за|есть|у\s+вас|вы|предлаг)"
    r"|какой\s+выбор|ассортимент|перечень|каталог|модельн\w*\s+ряд|линейк"
    r"|предлаг\w*|сдаёте|сдаете|в\s+нали\w*"
    r"|\bwhat\b|\bwhich\b|list\s+of\b|range\s+of\b|(?:do\s+you|you)\s+(?:have|offer|rent)"
    r"|available|selection|catalog|line\s*-?up", re.I)
_PS_FLEET_NOUN = re.compile(
    r"марк\w*|модел\w*|байк\w*|скутер\w*|мотоцикл\w*|мопед\w*|мотик\w*|транспорт\w*|вариант\w*"
    r"|bikes?|scooters?|models?|brands?|mopeds?|motos?|motorcycles?|options?", re.I)
# Признак «цены-в-целом» = ценовое слово ВМЕСТЕ с арендой / сроком / вопросительным «сколько/какие».
_PS_RENTAL = re.compile(r"аренд\w*|прокат\w*|снять|снима\w*|rent\w*|hire|rental", re.I)
_PS_DURATION = re.compile(
    r"\bдень\b|\bдня\b|\bдней\b|сут(?:к|очн)\w*|недел\w*|месяц\w*|мес\b"
    r"|\bday\b|\bweek\b|\bmonth\b|daily|weekly|monthly", re.I)
_PS_ASK_CUE = re.compile(
    r"\bсколько\b|как(?:ие|ая|ов[аы])\b|\bпочём\b|\bпочем\b|\bчто\s+по\b"
    r"|\bhow\s+much\b|\bwhat\b|\bwhich\b", re.I)


def _asks_price_sheet(newest: str, recent: str) -> bool:
    """Детект СМЫСЛА «дай перечень моделей и/или цены по парку». Классификация, не список слов
    (ДЕТЕРМИНИРОВАННО, без LLM — покрывается юнитами напрямую):
      • явный «прайс»/«price list» ИЛИ «все модели/весь парк»+цена → True (как раньше);
      • иначе — вопрос про ПЕРЕЧЕНЬ моделей/каталог (какие модели/байки предлагаете) ИЛИ про
        ЦЕНЫ-В-ЦЕЛОМ (ценовое слово + аренда/срок/«сколько/какие») → True;
      • названа КОНКРЕТНАЯ модель (NMAX / ADV350 / …) И это НЕ каталог-вопрос → False:
        точечный/мульти-quote. КОРЕНЬ живого провала 22:27: модель-гард раньше сканировал ВСЁ
        окно (newest+recent) и БЕЗУСЛОВНО возвращал False — стоило клиенту раньше в окне упомянуть
        байк («интересует nmax»), как текущий каталог-вопрос «какие модели и цены?» терял сетку и
        уходил в гейт дат. Теперь явный каталог-запрос (enum) сетку НЕ отменяет, даже если рядом
        (в этой или прошлой реплике окна) названа модель — смещение к показу прайса.
    Негативы: одна модель без каталог-вопроса, приветствие, вопрос ТОЛЬКО про депозит,
    «всё включено в цену?»."""
    t = f"{newest or ''}\n{recent or ''}"
    if _PS_PRICE_LIST.search(t):
        return True
    if _PS_ALL_SCOPE.search(t) and _PS_PRICE_WORD.search(t):
        return True
    # Собирательный интерес: КАТАЛОГ/перечень моделей (enum) ИЛИ цены-в-целом (price_q).
    enum = bool(_PS_ENUM_CUE.search(t)) and bool(_PS_FLEET_NOUN.search(t))
    price_q = bool(_PS_PRICE_WORD.search(t)) and bool(
        _PS_RENTAL.search(t) or _PS_DURATION.search(t) or _PS_ASK_CUE.search(t))
    if not (enum or price_q):
        return False
    # Названа конкретная модель (в текущей ИЛИ прежних репликах окна) И НЕ каталог-вопрос → это
    # точечный/мульти-quote, а не сетка. Явный каталог-вопрос (enum) veto НЕ включает.
    if _detect_models(t.lower()) and not enum:
        return False
    return True


# --- подвыборка прайса: класс (scooter/moto) + рабочий объём cc, ДЕТЕРМИНИРОВАННО из СЛОВ клиента --
# Клиент сужает сетку: «скутеры 200+», «мотоциклы до 400». Разбор — строкой (не LLM): границы
# отдаём в filter_sheet_rows, отбор моделей делает КОД по данным сетки. Потому XADV 750 в «скутерах
# 200+» не теряется (у LLM-отбора терялся — живой черновик 12.07 15:46).
_SF_SCOOTER_RE = re.compile(r"скутер\w*|мопед\w*|scooter\w*|moped\w*", re.I)
_SF_MOTO_RE = re.compile(r"мотоцикл\w*|мотоцик\w*|мотик\w*|motorcycl\w*|\bmoto\b", re.I)
# нижняя граница: «от 200», «(не «не»)больше/более 200», «свыше 200», «200+», «200 и больше/выше»,
# «from/over/above 200». «не больше 200» — это ВЕРХНЯЯ граница, поэтому «больше/более» с «не» перед
# ними в min НЕ ловим (lookbehind).
_SF_MIN_RE = re.compile(
    r"(?:(?:от|свыше|начиная\s+(?:от|с)|from|over|above|starting)|(?<!не )(?:больше|более))\s*(\d{2,4})"
    r"|(\d{2,4})\s*(?:куб\w*\s*)?(?:\+|и\s*(?:больше|выше|более|старше)|and\s+(?:up|more|above|over))",
    re.I)
# верхняя граница: «до 400», «меньше/менее 400», «не больше/не более 400», «400 и меньше»,
# «under/below/up to/max 400».
_SF_MAX_RE = re.compile(
    r"(?:до|меньше|менее|не\s+(?:больше|более)|под|under|below|up\s*to|max(?:imum)?|less\s+than)\s*(\d{2,4})"
    r"|(\d{2,4})\s*(?:куб\w*\s*)?(?:и\s*)?(?:меньше|менее|ниже|or\s+less|and\s+(?:below|under))",
    re.I)
# Меньше 50 — это не рабочий объём (дата «до 15», срок «на 7 дней»): такую «границу» игнорируем.
_SF_CC_MIN_PLAUSIBLE = 50


def _parse_sheet_filter(newest: str, recent: str):
    """Подвыборка сетки из СЛОВ клиента: класс (scooter/moto из скутер/мотоцикл-слов) и границы cc.
    → dict {kind, cc_min, cc_max} или None (сужения нет). Оба класс-слова сразу (скутеры И мотоциклы)
    → kind=None (весь парк). Отбор моделей по границам делает КОД (filter_sheet_rows), НЕ LLM."""
    t = f"{newest or ''}\n{recent or ''}"
    sc, mo = bool(_SF_SCOOTER_RE.search(t)), bool(_SF_MOTO_RE.search(t))
    kind = "scooter" if (sc and not mo) else ("moto" if (mo and not sc) else None)

    def _bound(rx):
        for m in rx.finditer(t):
            v = m.group(1) or m.group(2)
            if v and int(v) >= _SF_CC_MIN_PLAUSIBLE:
                return int(v)
        return None

    cc_min, cc_max = _bound(_SF_MIN_RE), _bound(_SF_MAX_RE)
    if kind is None and cc_min is None and cc_max is None:
        return None
    return {"kind": kind, "cc_min": cc_min, "cc_max": cc_max}


# --- запрошенные клиентом МОДЕЛИ/КЛАСС (гвард-модель, шаг 2/7 родителя #274) -------------------
# Экстрактор «ЧТО клиент явно просил» — вход будущего гварда сверки черновика с запросом
# (docs/guard-model.md): конкретные модели (PCX / NMax / MT-03 …) и/или класс по кубатуре.
# Регистронезависимо: латиница из _MODEL_TOKENS + кириллические написания. «160 кубов» — это
# КЛАСС 150–160cc, не точное число: в речи клиента малые скутеры 150/155/160 — один класс,
# точное 160 отсекло бы NMAX 155. Числа-ГРАНИЦЫ («от 200 кубов», «до 400cc») классом НЕ
# считаем — их разбирает _parse_sheet_filter (подвыборка сетки).
_MODEL_SYNONYMS = {   # кириллическое написание → латинский токен _MODEL_TOKENS (canon единый)
    "нмакс": "nmax", "н-макс": "nmax",
    "пцх": "pcx",
    "хмакс": "xmax", "х-макс": "xmax",
    "форза": "forza",
    "адв": "adv",
    "мт-03": "mt-03", "мт03": "mt-03", "мт 03": "mt-03",
    "ниндзя": "ninja",
    "ребел": "rebel", "ребель": "rebel",
    "вулкан": "vulcan",
    "клик": "click",
}
# Синоним матчится ЦЕЛЫМ словом (лукэраунды по буквам, цифры вплотную можно): «адв 350»/«адв350» —
# да, «адвокат»/«кликните» — нет. Латиница остаётся на substring-семантике _MODEL_TOKENS.
_MODEL_SYNONYM_RES = [
    (re.compile(r"(?<![a-zа-яё])" + re.escape(syn) + r"(?![a-zа-яё])"), tok)
    for syn, tok in _MODEL_SYNONYMS.items()
]
# Полосы cc-классов (по кубатурам парка Лист1): упомянутая кубатура → накрывающая полоса;
# вне полос — точечный класс (cc, cc).
_CC_CLASS_BANDS = (
    (125, 125),
    (150, 160),     # PCX/NMAX/ADV/XSR малые — один класс в речи клиента
    (300, 350),     # XMAX/FORZA/CB300/REBEL 300 + ADV 350
    (400, 400),
    (650, 700),
    (750, 750),
    (900, 900),
)
# Упоминание кубатуры: число + куб-слово (кубов/кубиков/cc/сс/см3). ГОЛОЕ число кубатурой не
# считаем — иначе даты («до 15») и сроки («на 10 дней») стали бы «классом».
_CC_MENTION_RE = re.compile(r"(\d{2,4})\s*(?:куб\w*|cc|сс|см3|см³)\b", re.I)


def _cc_class(cc):
    """Кубатура из речи клиента → класс (cc_min, cc_max): накрывающая полоса _CC_CLASS_BANDS
    («160» → 150–160), вне полос — точечный класс (cc, cc)."""
    for lo, hi in _CC_CLASS_BANDS:
        if lo <= cc <= hi:
            return lo, hi
    return cc, cc


def _cc_bound_spans(t):
    """Спаны выражений-ГРАНИЦ cc («от 200», «до 400 кубов», «200+») — упоминание кубатуры внутри
    них НЕ запрос класса (это подвыборка _parse_sheet_filter)."""
    out = []
    for rx in (_SF_MIN_RE, _SF_MAX_RE):
        out.extend(m.span() for m in rx.finditer(t))
    return out


def extract_requested_models(text):
    """ЯВНО запрошенные клиентом модели/класс из его текста (регистронезависимо). → список
    элементов в порядке появления во фразе ИЛИ None, если явного запроса нет:
      {"type": "model", "canon": "PCX"}  — конкретная модель/серия (canon как у _detect_models);
      {"type": "cc_class", "cc_min": 150, "cc_max": 160, "label": "150–160cc"} — класс по кубатуре.
    «160 кубов и PCX» → [класс 150–160cc, PCX]. Кубатура вплотную к модели («PCX 160cc») — это
    сама модель, отдельный класс не заявлен; границы («от 200 кубов») — тоже не класс."""
    t = str(text or "").lower()
    if not t.strip():
        return None
    pos = {}                                            # canon → позиция ПЕРВОГО упоминания
    for tok in _MODEL_TOKENS:
        i = t.find(tok)
        if i >= 0:
            canon = tok.upper().replace(" ", "")
            if i < pos.get(canon, len(t) + 1):
                pos[canon] = i
    for rx, tok in _MODEL_SYNONYM_RES:
        m = rx.search(t)
        if m:
            canon = tok.upper().replace(" ", "")
            if m.start() < pos.get(canon, len(t) + 1):
                pos[canon] = m.start()
    # снять префикс, поглощённый более длинной моделью (ADV ⊂ ADV160) — как в _detect_models
    items = [(i, {"type": "model", "canon": c}) for c, i in pos.items()
             if not any(o != c and o.startswith(c) for o in pos)]
    bounds = _cc_bound_spans(t)
    seen = set()
    for m in _CC_MENTION_RE.finditer(t):
        s = m.start(1)
        if any(bs <= s < be for bs, be in bounds):
            continue                                    # число-граница, не класс
        head = t[:s].rstrip(" -–")
        if any(head.endswith(x) for x in _MODEL_TOKENS) \
                or any(head.endswith(x) for x in _MODEL_SYNONYMS):
            continue                                    # «PCX 160cc» — кубатура модели, не класс
        cc = int(m.group(1))
        if cc < _SF_CC_MIN_PLAUSIBLE:
            continue                                    # «до 15», «10 дней» — не рабочий объём
        lo, hi = _cc_class(cc)
        if (lo, hi) in seen:
            continue
        seen.add((lo, hi))
        label = f"{lo}–{hi}cc" if lo != hi else f"{lo}cc"
        items.append((s, {"type": "cc_class", "cc_min": lo, "cc_max": hi, "label": label}))
    if not items:
        return None
    return [it for _, it in sorted(items, key=lambda x: x[0])]


def _catalog_scope_asked(text) -> bool:
    """Реплика просит ПЕРЕЧЕНЬ («какие модели/байки у вас…») или охват «все модели/весь парк» —
    признаки те же, что в _asks_price_sheet (enum / all-scope). Для гвард-модели (шаг 3/7 #274):
    при таком вопросе полная сетка и есть ответ — модель-пример рядом («например nmax») перечень
    НЕ сужает (владельческое смещение к показу прайса, класс 22:27)."""
    t = str(text or "")
    if _PS_ALL_SCOPE.search(t):
        return True
    return bool(_PS_ENUM_CUE.search(t)) and bool(_PS_FLEET_NOUN.search(t))


# Несдаваемые модели: физически в парке (Лист1), но правило KB/CRITICAL_FACTS «НЕ сдаём» —
# в прайс по парку НЕ включаем (Honda Click 125). Ключи нормализованы как _bike_key.
_NON_RENTABLE_KEYS = {_bike_key("CLICK 125")}   # {'click125'}


BOOKING_WINDOW = 3  # сколько последних реплик клиента смотрим, чтобы дособрать ОДНУ бронь


# Гео-ПИН с координатами в маркере «[локация lat,lon]» (ставит _geo_marker в transcript_from при
# Telegram-локации). Требуем десятичную точку в обоих числах — как в maps-парсере delivery._LATLON.
_GEO_PIN_RE = re.compile(r"\[локаци\w*\s+(-?\d{1,3}\.\d+)\s*,\s*(-?\d{1,3}\.\d+)\]")


def extract_booking_hints(transcript: str, today=None) -> dict:
    """Модель + даты ТОЛЬКО из ПОСЛЕДНЕЙ релевантной брони клиента (не из всего диалога).
    База — последняя реплика клиента; до 2 предыдущих его реплик смотрим лишь чтобы дособрать
    НЕДОСТАЮЩЕЕ той же брони. Разные модели / разные даты = разные брони: приоритет у последней,
    старую отбрасываем (не смешиваем). Возвращает {model, date_start, date_end, iso_start,
    iso_end, term_days, hint_days, monthly, has_dates}."""
    window = _client_messages(transcript)[-BOOKING_WINDOW:][::-1]  # новейшая первой
    newest = window[0] if window else ""
    recent = " ".join(window)

    model = iso_start = iso_end = term_days = None
    monthly = False
    iso_src = None            # РЕПЛИКА, из которой взяты даты (окно, а не одно сообщение) — по ней
                              # гейт старта видит ЯВНЫЙ год клиента (см. start_date_status)

    for idx, msg in enumerate(window):
        m_model = _detect_model(msg)
        s, e = parse_date_range(msg, today)
        t = _parse_term(msg)
        if idx == 0:
            model = m_model
            if s and e:
                iso_start, iso_end = s, e
                iso_src = msg
            if t:
                term_days = t[0]
            monthly = _explicit_monthly(msg)
            if model and (iso_start or term_days):
                break  # последняя реплика самодостаточна — назад не идём
            continue
        # предыдущая реплика окна: СТОП при признаках ДРУГОЙ брони (другая модель)
        if m_model and model and m_model != model:
            break
        # дособираем ТОЛЬКО недостающее (даты/срок), если у нас их ещё нет
        if iso_start is None and term_days is None:
            if s and e:
                iso_start, iso_end = s, e
                iso_src = msg
                monthly = monthly or _explicit_monthly(msg)
            elif t:
                term_days = t[0]
                monthly = monthly or _explicit_monthly(msg)
        if model is None and m_model:
            model = m_model
        if model and (iso_start or term_days):
            break

    hint_days = None
    if iso_start and iso_end:
        try:
            hint_days = (datetime.date.fromisoformat(iso_end)
                         - datetime.date.fromisoformat(iso_start)).days
        except Exception:
            hint_days = None
    if hint_days is None:
        hint_days = term_days
    # ДЛИННАЯ АРЕНДА (правило владельца, раздел «РЕАЛЬНЫЕ СРОКИ АРЕНДЫ»): срок от полугода
    # получает цену не от расчёта, а от человека. Признак собираем ДВУМЯ независимыми входами,
    # потому что по отдельности не хватает ни одного: даты дают длину только когда разобрался
    # ВЕСЬ диапазон (у «на полгода с 1 сентября» конца нет вовсе — hint_days=None), а слова —
    # только когда клиент назвал срок словом (у «с 1 сентября по 1 марта» слова нет).
    long_term_days = hint_days if (hint_days and hint_days >= _LONG_TERM_MIN_DAYS) else None
    long_term = bool(long_term_days) or _long_term_words(newest) or _long_term_words(recent)
    has_dates = bool(iso_start or term_days) or _has_date_signal(newest)
    has_start = bool(iso_start) or _has_start_signal(newest)   # конкретный старт, НЕ просто длительность

    # ГЕЙТ СТАРТА (прошедшие даты не котируем): статус считаем ЗДЕСЬ — только тут виден исходный
    # текст реплики (явный год) вместе с уже разобранной датой. Даты из ОКНА последних реплик —
    # статус берётся от той реплики, что реально дала даты (iso_src), а не от новейшей.
    _today = today or today_phuket()
    date_status = start_date_status(iso_start, _today, iso_src) if iso_start else None
    _seen = _nearest_start(iso_start, _today, iso_src) if iso_start else None

    # Несколько моделей в ОДНОМ запросе (правила цен v2, п.3) — берём из последней реплики;
    # одна/ноль → падаем на единственную разрешённую модель окна.
    newest_models = _detect_models(newest)
    if len(newest_models) >= 2:
        models = newest_models
    elif model:
        models = [model]
    else:
        models = newest_models
    deposit_multi_q = _asks_deposit_reduction_multi(newest, recent, models)
    price_sheet_q = _asks_price_sheet(newest, recent)
    sheet_filter = _parse_sheet_filter(newest, recent)
    # Гвард-модель (шаг 3/7 #274): ЯВНО запрошенные модели/класс — из ПОСЛЕДНЕЙ реплики, не всего
    # окна (старое «интересует nmax» не должно резать каталог-ответ — класс живого провала 22:27).
    # Каталог-вопрос сохраняет ПЕРЕЧЕНЬ: модель-пример в нём запрос не сужает (model-элементы
    # выкидываем), а явный класс («какие модели 160 кубов») — сужает (cc_class остаётся).
    requested_models = extract_requested_models(newest)
    if requested_models and _catalog_scope_asked(newest):
        requested_models = [it for it in requested_models if it["type"] != "model"] or None
    percent_q = _asks_percent_amount(newest, recent)   # «сколько будет N%» → процент от суммы расчёта
    units_count = _units_count(newest, models)         # «пара/два юнита одной модели» → цена «за каждый»
    old_gen_q = _asks_old_gen(newest, recent)          # «а старый xmax есть?» → прежнее поколение по запросу
    # Две ручки подбора по классу (правило владельца 20.08): обе открывает ТОЛЬКО клиент словами.
    heavy_ok = _asks_heavy_class_ok(newest, recent)    # мощность/размер/опыт → тяжёлый класс можно
    cheaper_ok = _asks_cheaper_or_simpler(newest, recent)   # «дешевле/проще» → можно классом НИЖЕ
    deposit_passport_q = _deposit_passport_chosen(window)   # «паспорт в залог» → депозит без суммы

    # Гео для ДОСТАВКИ (шаг 5/7 #12): первая maps-ссылка в репликах клиента (новейшая первой). Ловим
    # ТОЛЬКО саму ссылку (упоминание «вилла/локация» без URL — не гео); питает резолвер доставки в
    # build_pricing_note. Локация «липкая» — берём по всему диалогу, не только по booking-окну.
    # Сканируем СЫРЫЕ строки клиента (не _client_messages: тот lowercase'ит — токен короткой goo.gl-
    # ссылки регистрозависим, разворот редиректом сломался бы).
    maps_link = None
    geo_pin = None
    for ln in reversed((transcript or "").split("\n")):
        if ln.startswith("[клиент]:"):
            if maps_link is None:
                ml = delivery.extract_maps_link(ln[len("[клиент]:"):])
                if ml:
                    maps_link = ml
            if geo_pin is None:
                # гео-ПИН Telegram: координаты уже в маркере «[локация lat,lon]» (см. _geo_marker/
                # transcript_from) — источник координат доставки, когда клиент кинул пин, а не ссылку.
                mg = _GEO_PIN_RE.search(ln)
                if mg:
                    try:
                        geo_pin = (float(mg.group(1)), float(mg.group(2)))
                    except (TypeError, ValueError):
                        geo_pin = None
            if maps_link is not None and geo_pin is not None:
                break

    return {"model": model, "models": models, "date_start": iso_start, "date_end": iso_end,
            "iso_start": iso_start, "iso_end": iso_end, "term_days": term_days,
            "hint_days": hint_days, "monthly": monthly, "has_dates": has_dates,
            "has_start": has_start,
            "long_term": long_term,                                       # срок от полугода
            "long_term_days": long_term_days,                             # длина, если ИЗМЕРЕНА датами
            "date_status": date_status,                                   # past|today|tomorrow|future|None
            "start_seen": _seen.isoformat() if _seen else None,           # дата в прочтении клиента
            "deposit_multi_q": deposit_multi_q, "price_sheet_q": price_sheet_q,
            "sheet_filter": sheet_filter, "requested_models": requested_models,
            "percent_q": percent_q, "units_count": units_count,
            "old_gen_q": old_gen_q, "deposit_passport_q": deposit_passport_q,
            "heavy_ok": heavy_ok, "cheaper_ok": cheaper_ok,
            "maps_link": maps_link, "geo_pin": geo_pin}


# ------------------- §243/6: трекер собранного по диалогу + reply-вложениям -------------------
# Что клиент УЖЕ прислал (по окну диалога и подтянутым reply-вложениям из transcript_from): модель,
# срок/даты, гео, фото паспорта, телефон, оплата. Собранное НЕ переспрашиваем; в промпт кладём
# «уже получено — подтверди и не проси повторно», в черновик — пометку модератору «собрано: …».
# Скан по КЛИЕНТСКИМ строкам (reply-содержимое встроено в них через transcript_from).

# ★ ПРАВИЛО (шаг 3/7 #253; уточнено #242): сущность ✅ ТОЛЬКО по ФАКТУ вложения/данных в сообщении
# клиента, а НЕ по слову-упоминанию И НЕ по обещанию прислать позже. Гео — реальная ссылка/координаты/
# локация-пин; паспорт — реально пришедшее ФОТО/ФАЙЛ документа В ОКНЕ (медиа-сообщение «[фото]» или reply
# на фото → маркер «вероятно паспорт»); телефон — реально присланный НОМЕР (цифры); оплата —
# ПОДТВЕРЖДЁННАЯ (прошедшее «оплатил/перевёл/внёс», «вот чек», «скрин оплаты»), а НЕ вопрос «криптой
# можно?»/«оплатить криптой?» и НЕ назначение предоплаты. Слова «паспорт»/«вилла»/«оплата»/«предоплата»/
# «телефон» сами по себе (без вложения/цифр) — ВСЕГДА ❌. ОБЕЩАНИЕ («пришлю завтра», «I'll send tomorrow/
# later») — это намерение, не полученный документ: паспорт ✅ ставим лишь когда фото/файл РЕАЛЬНО в окне.

# Гео: ссылка на карты / geo-координаты / локация-пин (маркер «[локация]» из вложения) ЛИБО
# ЯВНО НАЗВАННОЕ жильё через поле-метку «Hotel Name: …» / «Название отеля: …» (клиент сам заполнил
# имя проживания — это данные, а не упоминание: вопрос «как называется ваш отель/апартаменты» закрыт).
# Голое слово «вилла/апартаменты/локация/отель» БЕЗ ссылки/пина И БЕЗ метки-имени — НЕ гео (#253:
# упоминание ≠ данные). Живой кейс окна client_id=766498048 (родитель #241): первое сообщение клиента
# «Hotel Name: Cape Sienna Gourmet Hotel & Villas» → отель назван, «name of your apartment/hotel» не спрашиваем.
_COLL_GEO = re.compile(
    r"maps\.app\.goo\.gl|goo\.gl/maps|google\.[a-z.]+/maps|maps\.google|geo:\s*-?\d"
    r"|@-?\d{1,2}\.\d{3,},-?\d{1,3}\.\d{3,}"
    r"|\[локаци\w*"          # «[локация]» ИЛИ «[локация lat,lon]» (пин с координатами) — по префиксу
    r"|(?:hotel|apartment|accommodation|villa)\s+name\s*[:\-—]\s*\S"        # «Hotel Name: Cape Sienna …»
    r"|назван\w+\s+(?:отел|апартамент|виллы|жиль|жилищ)\w*\s*[:\-—]?\s*\S",  # «Название отеля: …»
    re.I)
# Паспорт: ✅ ТОЛЬКО по ФАКТУ пришедшего фото/файла документа В ОКНЕ — прямое медиа «[фото]» ИЛИ
# reply-маркер «вероятно паспорт» (оба ставятся лишь на реальном вложении, см. transcript_from /
# _reply_target_snippet). Слово «паспорт/passport/id» БЕЗ фото — НЕ считаем (упоминание ≠ вложение).
# ОБЕЩАНИЕ прислать позже — НАМЕРЕНИЕ, а не полученный документ: «фото паспорта пришлю завтра»,
# «I'll send the passport photo tomorrow/later» — паспорт ❌, пока файл реально не в окне. Поэтому в
# паттерне НЕТ голого текста «passport photo» (он ловил бы такое обещание как ✅) — только маркеры
# вложения: ✅ ставим на ФАКТ файла, а не на слова о нём.
_COLL_PASSPORT = re.compile(r"вероятно\s+паспорт|\[фото\]", re.I)
# Телефон: реально присланный номер — международный (+..) ИЛИ длинный прогон цифр ИЛИ ключевик+цифры.
# Голое слово «телефон/номер» без цифр — НЕ считаем.
_COLL_PHONE = re.compile(r"\+\d[\d\s\-()]{7,}\d|\b\d{9,}\b"
                         r"|(?:тел|номер|phone|whats\s*app|whatsapp|вайбер|viber)\D{0,12}\d[\d\s\-()]{5,}\d",
                         re.I)
# Оплата: ТОЛЬКО подтверждённая — прошедшее действие оплаты/перевода/взноса ИЛИ чек/скрин оплаты.
# Вопрос «криптой можно?»/«оплатить криптой?», назначение предоплаты и голые «оплата/предоплата/
# перевод/депозит» — НЕ оплата (это упоминание/намерение/вопрос, а не факт совершённой оплаты).
_COLL_PAYMENT = re.compile(
    r"оплатил\w*|оплачен\w*|заплатил\w*|заплачен\w*|перев[её]л\w*"
    r"|(?:внёс|внес|внесла|внесли)\b"
    r"|вот\s+чек|чек\s+(?:об\s+)?оплат|скрин\w*\s+(?:оплат\w*|перевод\w*)"
    r"|\bpaid\b|already\s+paid|payment\s+(?:made|done|sent|completed)"
    r"|\btransferred\b|deposit\s+paid", re.I)


def collected_facts(transcript: str, hints: dict = None, today=None) -> dict:
    """§243/6: что клиент УЖЕ прислал по окну диалога + reply-вложениям (см. transcript_from).
    Ключи-булевы: model, term, dates, geo, passport, phone, payment. model/term/dates — из
    extract_booking_hints (переиспользуем ту же логику последней брони), остальное — детерминированный
    скан клиентских строк (reply-содержимое встроено в них). term = ДЛИТЕЛЬНОСТЬ известна («на 10 дней»,
    диапазон); dates = конкретный СТАРТ известен (число+месяц, «с завтрашнего», dd.mm). Слова длительности
    старта НЕ дают.
    ★ ШАГ 3/7 #253 (уточнено #242): geo/passport/phone/payment помечаем ✅ ТОЛЬКО по ФАКТУ вложения/
    данных в сообщении клиента (ссылка/пин, фото, номер, подтверждённая оплата/чек), а НЕ по слову-
    упоминанию И НЕ по обещанию прислать позже — голые «паспорт/вилла/оплата/предоплата/телефон», вопрос
    «криптой можно?» и обещание «фото паспорта пришлю завтра»/«I'll send it tomorrow» дают ❌ (см. _COLL_*).
    Ничего не найдено → все False (fail-safe: просто нет пометки)."""
    h = hints if hints is not None else extract_booking_hints(transcript, today=today)
    ctext = _client_text(transcript)   # только [клиент]: строки, lower, с встроенным reply-содержимым
    # ПРОШЕДШИЙ СТАРТ — даты НЕ считаем собранными: старт назван, но невалиден (гейт как раз просит
    # его уточнить). Иначе в ОДНОМ промпте жили бы два противоположных указания: трекер «даты уже
    # получены — не переспрашивай» и ЦЕНА «уточни даты, они прошли». Длительность (term) при этом
    # известна и остаётся ✅ — переспрашивать надо именно СТАРТ.
    start_past = _gate_start_date(h, today)[0] == "past"
    return {
        "model": bool(h.get("model")),
        "term":  bool(h.get("term_days") or (h.get("iso_start") and h.get("iso_end"))),
        "dates": bool(h.get("iso_start") or h.get("has_start")) and not start_past,
        "geo": bool(_COLL_GEO.search(ctext)),
        "passport": bool(_COLL_PASSPORT.search(ctext)),
        "phone": bool(_COLL_PHONE.search(ctext)),
        "payment": bool(_COLL_PAYMENT.search(ctext)),
    }


# Порядок и подписи собранного: (ключ, метка-для-промпта-RU/EN, короткая-метка-для-пометки-RU/EN).
_COLL_LABELS = [
    ("model",    ("модель",         "model"),    ("модель",  "model")),
    ("term",     ("срок",           "term"),     ("срок",    "term")),
    ("dates",    ("даты",           "dates"),    ("даты",    "dates")),
    ("geo",      ("локация",        "location"), ("гео",     "geo")),
    ("passport", ("фото паспорта",  "passport photo"), ("паспорт", "passport")),
    ("phone",    ("телефон",        "phone"),    ("тел",     "phone")),
    ("payment",  ("оплата",         "payment"),  ("оплата",  "payment")),
]


def _confirm_example(facts: dict, en: bool) -> str:
    """Пример-подсказка подтверждения. Урок №292: отражает РОВНО собранное (не хвалится «данные» на
    любой набор). Дефект #303/2 (лексика «факты ≠ артефакты»): «получили» — ТОЛЬКО про реальное
    ВЛОЖЕНИЕ (фото паспорта / оплата); ИНФОРМАЦИЮ (локация/модель/срок/даты/телефон) подтверждаем
    «учли», а НЕ «получили». Фото+оплата → «фото и оплату получили»; вложение + инфо → «… получили,
    остальное учли»; только локация → «локацию учли»; только прочая инфа → «всё учли»."""
    has_photo = bool(facts.get("passport"))
    has_pay = bool(facts.get("payment"))
    has_info = any(facts.get(k) for k in ("model", "term", "dates", "geo", "phone"))
    if has_photo or has_pay:                          # реальные вложения → «получили»
        if en:
            got = " and ".join(w for w in (("photo" if has_photo else None),
                                           ("payment" if has_pay else None)) if w)
            return f"got your {got}" + (", the rest noted" if has_info else "")
        got = " и ".join(w for w in (("фото" if has_photo else None),
                                     ("оплату" if has_pay else None)) if w)
        return f"{got} получили" + (", остальное учли" if has_info else "")
    # только ИНФОРМАЦИЯ (вложений нет) → «учли», не «получили»
    only_geo = bool(facts.get("geo")) and not any(facts.get(k) for k in ("model", "term", "dates", "phone"))
    if only_geo:
        return "noted your location" if en else "локацию учли"
    return "noted your details" if en else "всё учли"


def collected_prompt_note(facts: dict, lang: str = "ru") -> str:
    """Блок в system-промпт: перечень уже полученного + запрет переспрашивать. Пусто → ''."""
    if not facts:
        return ""
    en = (lang == "en")
    got = [lbl[1 if en else 0] for key, lbl, _ in _COLL_LABELS if facts.get(key)]
    if not got:
        return ""
    example = _confirm_example(facts, en)
    if en:
        return ("\n\n★ ALREADY PROVIDED BY THE CLIENT (in the dialog/attachments — do NOT ask "
                "again): " + ", ".join(got) + f". Briefly acknowledge it (e.g. «{example}») "
                "and move to the next step — acknowledge ONLY what is listed above, never claim data "
                "the client has not sent, and never re-request what the client has already sent. "
                "Say «received/got» ONLY about a real attachment (photo/payment); for information "
                "(model/dates/location/phone) say «noted».")
    return ("\n\n★ УЖЕ ПОЛУЧЕНО ОТ КЛИЕНТА (есть в диалоге/вложениях — НЕ переспрашивай): "
            + ", ".join(got) + f". Коротко подтверди (напр. «{example}») "
            "и переходи к следующему шагу — подтверждай ТОЛЬКО перечисленное выше, НЕ приписывай "
            "данные, которых клиент не присылал, и НЕ проси повторно то, что клиент уже прислал. "
            "Слово «получили» — ТОЛЬКО про реальное вложение (фото/оплата); про информацию "
            "(модель/даты/локацию/телефон) говори «учли/понял».")


def unconfirmed_fields(transcript: str, facts: dict = None, today=None) -> set:
    """Поля, про которые клиент что-то СКАЗАЛ, но подтверждёнными они НЕ считаются → в пометке
    модератору идут с «❓», а не «✅». Живой ТЕСТ-10: старт «20 июля» уже прошёл → dates ❌, а
    длительность (term) при этом ✅ — и пометка «[собрано: срок ✅]» врала о состоянии диалога
    (срок посчитан по НЕПОДТВЕРЖДЁННЫМ датам). Правило: клиент СТАРТ назвал (`_has_start_signal`),
    но гейт его не принял → и «даты», и «срок» помечаем ❓. Старта клиент не называл вовсе (одна
    длительность «на 5 дней») → ничего не помечаем: это не «неоднозначно», это просто не собрано,
    а сама длительность подтверждена честно."""
    facts = facts if facts is not None else collected_facts(transcript, today=today)
    if facts.get("dates"):
        return set()
    if not _has_start_signal(_client_text(transcript or "")):
        return set()
    out = {"dates"}
    if facts.get("term"):
        out.add("term")
    return out


def collected_manager_note(facts: dict, lang: str = "ru", unconfirmed=None) -> str:
    """СЛУЖЕБНАЯ пометка модератору о собранном — в квадратных скобках, как «[уточнить: …]»
    (шаг 4/7 #253): «[собрано: гео ✅ паспорт ✅ тел ✅]». Скобки → это служебный канал карточки,
    а не тело ответа; client_facing_text её срезает (клиент «собрано:» не видит). Ничего не
    собрано → '' (пометки нет).
    unconfirmed — поля, названные клиентом, но НЕ подтверждённые (прошедший старт / неоднозначно):
    выводим их с «❓» ВНЕ зависимости от значения facts. Пометка обязана отражать реальное
    состояние диалога, а не радовать галочкой (живой ТЕСТ-10: «срок ✅» при прошедших датах)."""
    en = (lang == "en")
    unconfirmed = set(unconfirmed or ())
    if not facts and not unconfirmed:
        return ""
    facts = facts or {}
    parts = []
    for key, _, lbl in _COLL_LABELS:
        name = lbl[1 if en else 0]
        if key in unconfirmed:
            parts.append(name + " ❓")
        elif facts.get(key):
            parts.append(name + " ✅")
    if not parts:
        return ""
    head = "[collected: " if en else "[собрано: "
    return head + " ".join(parts) + "]"


# ------------------- фильтр списка вопросов брони по уже собранным полям (шаг 2/5 #241) -------------------
# Сам список вопросов оформления брони (что и какими словами спросить у клиента) живёт в LLM-промпте/
# playbook/KB (частично на VPS) — см. docs/task-2026-07-20-questions-filter.md. Здесь — детерминированный
# фильтр обратной половины: перед отправкой клиенту вычёркиваем пункты, данные по которым клиент УЖЕ дал
# в окне (collected_facts). Каждый вопрос сопоставляем с полем(ями) по ключевым словам (RU/EN) и исключаем
# ТОЛЬКО когда ВСЕ затронутые вопросом поля уже собраны (составной вопрос про ещё-неизвестное поле
# остаётся — реальный вопрос не теряем). Вопрос без совпадения с полем оставляем (не знаем — не режем).
# Каждый вычеркнутый пункт логируем (аудит: что и почему исключили). Поля — те же ключи, что в _COLL_LABELS.
_QUESTION_FIELD_PATTERNS = [
    ("model", re.compile(
        r"модел|байк|скутер|мотоцикл|какую\s+(?:технику|машину|модель)"
        r"|\bmodel\b|\bbike\b|scooter|motorbike|which.*(?:model|bike|scooter)", re.I)),
    ("dates", re.compile(
        r"как(?:ую|ие)\s+дат|на\s+как(?:ое|ие)\s+числ|с\s+как(?:ого|ой)\s+(?:числа|даты)"
        r"|когда\s+(?:вам\s+)?(?:нужен|заб|нача|приед|приле|старт|аренд)|дат\w*\s+(?:заезда|начала|старта|аренды)"
        r"|заезд|check[-\s]?in|what.*date|when.*(?:start|need|arrive|rent|pick|begin)|start\s+date", re.I)),
    ("term", re.compile(
        r"на\s+сколько|сколько\s+дней|как\s+долго|срок\s+аренд|длительн|период\s+аренд"
        r"|how\s+long|how\s+many\s+days|rental\s+period|duration", re.I)),
    ("geo", re.compile(
        r"отел|адрес|апартамент|вилл\w*|где\s+(?:вы\s+)?(?:останов|прожив|живёте|живете|находит)"
        r"|куда\s+(?:вам\s+)?(?:до)?став|локац|район\s+прожив|name\s+of\s+your\s+(?:apartment|hotel)"
        r"|\bhotel\b|apartment|\baddress\b|where.*(?:stay|located|deliver)|delivery\s+(?:address|location)", re.I)),
    ("passport", re.compile(
        r"паспорт|фото\s+документ|скан\s+документ|документ\w*\s+(?:пришл|скинь|фото)"
        r"|passport|\bid\s+(?:photo|card|copy)\b|photo\s+of\s+your\s+(?:passport|id)", re.I)),
    ("phone", re.compile(
        r"телефон|ваш\s+номер|номер\s+(?:телефона|для\s+связи|whats\s*app)|контактн\w*\s+(?:номер|телефон)"
        r"|для\s+связи|whats\s*app|whatsapp|\bphone\b|contact\s+number|your\s+(?:phone\s+)?number", re.I)),
    ("payment", re.compile(
        r"оплат|как\s+(?:вам\s+)?удобн\w*\s+(?:внести|заплат|оплат)|способ\s+оплат|предоплат"
        r"|\bpay\b|payment\s+method|how.*(?:pay|deposit)|\bdeposit\b", re.I)),
]


def filter_booking_questions(questions, facts: dict, lang: str = "ru"):
    """Шаг 2/5 (родитель #241): убрать из списка вопросов оформления брони пункты, данные по которым
    клиент УЖЕ дал в окне. facts — из collected_facts (булевы model/term/dates/geo/passport/phone/payment).
    Каждый вопрос сопоставляем с полем(ями) по ключевым словам (_QUESTION_FIELD_PATTERNS, RU/EN) и
    исключаем ТОЛЬКО если ВСЕ затронутые вопросом поля уже собраны — составной вопрос про ещё-неизвестное
    поле остаётся (реальный вопрос не теряем). Вопрос без совпадения с полем оставляем (не знаем — не режем).
    Возвращает НОВЫЙ список оставшихся вопросов в исходном порядке; каждый вычеркнутый пункт логируем."""
    items = list(questions or [])
    if not items:
        return items
    facts = facts or {}
    collected = {k for k, v in facts.items() if v}
    if not collected:
        return items   # нечего исключать — вернуть как есть
    label = {key: lbl[0 if lang != "en" else 1] for key, lbl, _ in _COLL_LABELS}
    kept = []
    for q in items:
        text = q if isinstance(q, str) else str(q)
        matched = {key for key, pat in _QUESTION_FIELD_PATTERNS if pat.search(text)}
        if matched and matched <= collected:
            log.info("filter_booking_questions: вычеркнут вопрос [уже собрано: %s] — %r",
                     ", ".join(sorted(label.get(k, k) for k in matched)), text)
            continue
        kept.append(q)
    return kept


# ---------- ЗАВЕРШАЮЩИЙ ВОПРОС: каждый ответ двигает клиента ровно на ОДИН шаг ----------
# Живой ТЕСТ-7 (22.07.2026): бот назвал цену и доставку и ЗАМОЛЧАЛ — паспорт/телефон/время и точка
# подачи не собраны, диалог к брони никто не двигал. Методика выведена из ЖИВЫХ успешных окон
# (docs/sales-method-2026-07-22.md; client_chats.jsonl, 9 разобранных диалогов + частотка по 15 845
# сообщениям менеджера): 84% сообщений менеджера БЕЗ вопроса, 14% — РОВНО ОДИН, два и более ≈0%.
# Порядок недостающего у живых менеджеров:
#   даты подтверждены → фото паспорта → телефон → время и точка подачи → подтверждение брони,
# причём паспорт/апартаменты/шлемы просят ТОЛЬКО когда клиент готов бронировать («Возьму», «Бронируем»)
# — до этого закрывают вопросом готовности «Бронируем ?» (Этап 3 сценария, не забегаем вперёд).
# ГЕЙТ ДАТ ПРИОРИТЕТНЕЕ ВОРОНКИ: прошедший старт → collected_facts даёт dates=False (см. #735ffa5),
# значит завершающий вопрос = уточнение дат, а не следующий шаг воронки (иначе бронь на несуществующие
# даты). В sheet-режиме (ПРАЙС ПО ПАРКУ) даты спрашивать НЕЛЬЗЯ (ANTI_LOOP_NOTE) → закрываем выбором модели.
_NEXT_STEP_QUESTIONS = {
    "dates":    ("Подскажите даты — с какого числа и на какой срок?",
                 "Could you tell me the dates — from when and for how long?"),
    # Клиент даты В ЭТОМ СООБЩЕНИИ НАЗВАЛ, но старт не проходит гейт (прошедший/неоднозначный):
    # переспрашивать «подскажите даты» НЕЛЬЗЯ — это выглядит как «я тебя не слушал». Спрашиваем
    # ИМЕННО поправку (живой ТЕСТ-10: «даты учли» и тут же «подскажите даты» в одном сообщении).
    "dates_fix": ("Названная дата уже прошла — подскажите, пожалуйста, актуальные: с какого числа "
                  "и на какой срок?",
                  "The date you named has already passed — could you confirm the actual ones: from "
                  "when and for how long?"),
    "model":    ("Какая модель интересует?",
                 "Which model are you interested in?"),
    "offer":    ("Бронируем?",
                 "Shall we book it?"),
    "passport": ("Пришлёте качественное фото паспорта?",
                 "Could you send a clear photo of your passport?"),
    "phone":    ("Подскажете номер телефона с доступом в WhatsApp?",
                 "Could you share a phone number with WhatsApp access?"),
    "pickup":   ("Во сколько и куда удобно подать байк?",
                 "What time and where would you like the bike delivered?"),
    "confirm":  ("Всё есть — подтверждаем бронь?",
                 "Everything is in — shall I confirm the booking?"),
}

# Человекочитаемая подпись шага для промпта (RU/EN).
_NEXT_STEP_LABELS = {
    "dates":    ("уточнить даты аренды", "clarify the rental dates"),
    "dates_fix": ("попросить ПОПРАВИТЬ даты (названная уже прошла) — не спрашивать их заново",
                  "ask to CORRECT the dates (the one named has passed) — do not ask for them anew"),
    "model":    ("узнать, какая модель интересует", "ask which model they want"),
    "offer":    ("предложить оформить бронь", "offer to book"),
    "passport": ("попросить качественное фото паспорта", "ask for a clear passport photo"),
    "phone":    ("попросить номер телефона (с доступом в WhatsApp)",
                 "ask for a phone number (with WhatsApp access)"),
    "pickup":   ("уточнить время и точку подачи байка",
                 "ask for the delivery time and place"),
    "confirm":  ("предложить подтвердить бронь", "offer to confirm the booking"),
}

# Клиент СОГЛАСИЛСЯ / готов оформлять — живые формулировки из дампа («Возьму.», «Бронируем»,
# «Давайте», «Подходит», «Его»). До этого сигнала паспорт/шлемы/апартаменты НЕ просим.
_READY_RE = re.compile(
    r"\bберу\b|\bвозьму\b|брониру\w*|заброни\w*|оформля\w*|оформи\w*"
    r"|давайте\s+(?:оформ\w*|брон\w*|так|этот|эту|его|её|ее)|подходит\b|устраивает\b"
    r"|готов\w*\s+(?:брон\w*|оформ\w*|взять)"
    r"|let'?s\s+book|shall\s+we\s+book|book\s+it|i'?ll\s+take\s+it|i\s+want\s+to\s+book"
    r"|works\s+for\s+me|sounds\s+good", re.I)


def client_ready_to_book(transcript: str) -> bool:
    """Клиент готов оформлять бронь: явный сигнал согласия в его репликах ЛИБО он уже прислал
    данные оформления (фото паспорта / телефон / оплату) — тогда этап брони начат по факту.
    Локация сама по себе готовности НЕ даёт (её называют ещё на этапе расчёта доставки)."""
    ctext = _client_text(transcript or "")
    if _READY_RE.search(ctext):
        return True
    f = collected_facts(transcript or "")
    return bool(f.get("passport") or f.get("phone") or f.get("payment"))


def last_client_message(transcript: str) -> str:
    """ПОСЛЕДНЯЯ реплика клиента окна (без метки роли). Нет клиентских строк → ''."""
    msgs = [ln[len("[клиент]:"):].strip()
            for ln in (transcript or "").split("\n") if ln.startswith("[клиент]:")]
    return msgs[-1] if msgs else ""


def client_just_provided(transcript: str, today=None) -> set:
    """Поля, которые клиент дал ИМЕННО В ТЕКУЩЕМ (последнем) сообщении, — их переспрашивать
    ЗАПРЕЩЕНО (живой ТЕСТ-10: «даты учли» + «Подскажите даты …» в одном ответе).
    Считаем ТЕМИ ЖЕ детекторами, что collected_facts, но по ОДНОЙ реплике; для дат добавляем
    СЫРОЙ сигнал старта (`_has_start_signal`) — клиент даты назвал, даже если гейт их не принял
    (прошедший старт). → множество ключей из _COLL_LABELS. Пустая реплика → set()."""
    last = last_client_message(transcript)
    if not last.strip():
        return set()
    one = "[клиент]: " + last
    got = {k for k, v in collected_facts(one, today=today).items() if v}
    if _has_start_signal(last):
        got.add("dates")
    return got


def next_step(facts: dict, sheet_mode: bool = False, ready: bool = False, just=None) -> str:
    """ОДИН следующий шаг по приоритету недостающего в collected_facts → ключ _NEXT_STEP_QUESTIONS.
    Приоритет: даты → (готовность) → паспорт → телефон → время и точка подачи → подтверждение брони.
    Даты ❌ (в т.ч. ПРОШЕДШИЙ старт — трекер их не считает собранными) перебивают всю воронку;
    в sheet-режиме вместо дат закрываем выбором модели (даты там спрашивать запрещено).
    just — поля из ТЕКУЩЕЙ реплики клиента (client_just_provided): поле, названное клиентом прямо
    сейчас, НЕ переспрашиваем «с нуля» — для дат это шаг 'dates_fix' (попроси ПОПРАВИТЬ), для
    остальных полей шаг просто пропускаем и идём дальше по воронке."""
    facts = facts or {}
    just = just or set()
    if not facts.get("dates"):
        if sheet_mode:
            return "model"
        return "dates_fix" if "dates" in just else "dates"
    if not ready:
        return "offer"          # рано просить документы — сперва согласие клиента (Этап 3)
    if not facts.get("passport"):
        return "passport"
    if not facts.get("phone"):
        return "phone"
    if not facts.get("geo"):
        return "pickup"
    return "confirm"


def next_step_question(step: str, lang: str = "ru") -> str:
    """Готовая формулировка завершающего вопроса для шага. Неизвестный шаг → ''."""
    pair = _NEXT_STEP_QUESTIONS.get(step)
    return "" if not pair else pair[1 if lang == "en" else 0]


def next_step_note(facts: dict, lang: str = "ru", sheet_mode: bool = False,
                   ready: bool = False, just=None) -> str:
    """Блок в system-промпт: закончи ответ РОВНО ОДНИМ следующим шагом. Пусто не бывает —
    шаг есть всегда (даже «нечего спрашивать» → предложение подтвердить бронь).
    just — поля из ТЕКУЩЕЙ реплики клиента: их переспрашивать запрещено (см. next_step)."""
    step = next_step(facts, sheet_mode, ready, just)
    en = (lang == "en")
    label = _NEXT_STEP_LABELS.get(step, ("", ""))[1 if en else 0]
    example = next_step_question(step, lang)
    # Ссылку на блок собранного даём ТОЛЬКО когда он реально есть: иначе маркер «УЖЕ ПОЛУЧЕНО» /
    # «ALREADY PROVIDED» просочился бы в промпт при пустом трекере (ложный след для читателя и тестов).
    has_collected = any((facts or {}).values())
    # Поля из ТЕКУЩЕЙ реплики — отдельным жёстким запретом (живой ТЕСТ-10: «даты учли» и тут же
    # «Подскажите даты …»). Пусто → строки нет (промпт не мусорим).
    label_of = {key: lbl[1 if en else 0] for key, lbl, _ in _COLL_LABELS}
    fresh = [label_of[k] for k, _, _ in _COLL_LABELS if k in (just or set())]
    if en:
        just_note = (" The client named this IN THE CURRENT message: " + ", ".join(fresh) +
                     " — asking for it again is FORBIDDEN.") if fresh else ""
        seen = " (see ALREADY PROVIDED above)" if has_collected else ""
        return ("\n\n★ CLOSING QUESTION (STRICT): every reply must END with ONE next step — never "
                "answer and go silent. Your next step now: " + label + " (e.g. «" + example + "»). "
                "Ask EXACTLY ONE question per reply — no questionnaires, no second question, no "
                "listing everything you still need. Never re-ask what the client has already sent"
                + seen + "." + just_note + " If the PRICE instruction above already prescribes a "
                "specific closing question (confirm the dates / pick-up time) — ask THAT one, it IS "
                "the closing question and it stays the only one.")
    just_note = ("  Клиент назвал это В ТЕКУЩЕМ сообщении: " + ", ".join(fresh) +
                 " — переспрашивать это ЗАПРЕЩЕНО.") if fresh else ""
    seen = " (см. блок выше)" if has_collected else ""
    return ("\n\n★ ЗАВЕРШАЮЩИЙ ВОПРОС (ЖЁСТКО): каждый ответ ЗАКАНЧИВАЕТСЯ ОДНИМ следующим шагом — "
            "не отвечай «в пустоту» и не замолкай. Твой следующий шаг сейчас: " + label +
            " (напр. «" + example + "»). Задай РОВНО ОДИН вопрос за ответ — никаких анкет, "
            "второго вопроса и перечисления всего, чего ещё не хватает. НЕ переспрашивай то, что "
            "клиент уже прислал" + seen + "." + just_note + " Если инструкция ЦЕНА выше уже задала конкретный "
            "вопрос (уточнить даты / время подачи) — задай ИМЕННО его, он и есть завершающий и "
            "остаётся единственным.")


# Инструкция про депозит при нескольких байках (правила цен v2, п.4).
DEPOSIT_MULTI_NOTE = ("ДЕПОЗИТ: клиент спрашивает про уменьшение депозита при нескольких байках "
                      "— сам скидку/снижение депозита НЕ предлагай и НЕ обещай; ответь ровно: "
                      "«уточню у менеджера».")


def _iso_plus(iso_date, n_days):
    """iso-дата + n_days дней → iso-строка или None."""
    try:
        return (datetime.date.fromisoformat(iso_date) + datetime.timedelta(days=int(n_days))).isoformat()
    except Exception:
        return None


def _safe_quote_for_model(model, ds, de, getter=None, name_filter=None):
    """pricing.quote_for_model без падений → всегда dict {status, quote}. name_filter сужает юниты
    (напр. поколение XMAX); getter инъектируется в тестах (боевой путь — None, живой Bridge).

    ЕДИНСТВЕННАЯ ТОЧКА ТОЧЕЧНОЙ КОТИРОВКИ — через неё идут обе ветки `_resolve_model_price`
    (штатная и «минимальный срок»), поэтому сезонная поправка врезается ровно здесь и ровно один
    раз. Прайс-сетка парка (`price_sheet`) сюда НЕ ходит — она зовёт `pricing.quote`
    напрямую и остаётся прежней: у неё нет дат клиента (якорь — завтра), а сезон файл приписывает
    по дате НАЧАЛА АРЕНДЫ.

    ЗАНЯТОСТЬ судит по-прежнему живая дверь: `available` и выбор конкретного юнита приходят из
    `quote_for_model` и правкой не затрагиваются — файл её не заменяет и заменить не может.
    Ручка откинута в лист → `reprice` отдаёт тот же объект, поведение побайтно прежнее.

    СТОРОЖ СВЕЖЕСТИ СТОИТ ЗДЕСЬ ЖЕ и включён ВМЕСТЕ с переключением источника — так велит
    сам узел бизнес-правил, назвавший его «ОБЯЗАТЕЛЬНЫМ УСЛОВИЕМ ПЕРЕХОДА». Порядок веток
    не косметический: сторож спрашивается ПОСЛЕ живой котировки (её `status` решает про
    занятость и без цены) и ДО счёта по файлу — считать цену, которую запрещено называть,
    незачем. Несвежее правило и непроверяемое правило ведут себя ОДИНАКОВО: цена гасится
    в молчание, владелец позван. Вчерашнее число клиенту не уходит ни одной дорогой."""
    try:
        res = pricing.quote_for_model(model, ds, de, _get=getter, name_filter=name_filter)
    except Exception:
        res = None
    if not isinstance(res, dict):
        return {"status": "error", "quote": None}
    try:
        on = price_source.enabled()
    except Exception:                          # ручка не прочиталась → это НЕ откат к листу
        on = True
    if not on:
        return res                             # объявленный откат к листу — путь прежний
    try:
        may, card = price_gate.allow()
    except Exception as e:                     # сторож не отработал → это НЕ разрешение
        may, card = False, ("ЦЕНА НЕ НАЗВАНА: сторож свежести не отработал (%s)."
                            % type(e).__name__)
    if not may:
        log.warning("price_gate: %s (модель %s)", card, model)
        return {"status": "error", "quote": None}
    try:
        return price_source.reprice(res, model, ds, de, _bike_key)
    except Exception as e:
        # Источник цены НЕ смеет ронять путь ответа. И НЕ смеет молча вернуть слепое к сезону
        # число: при поднятом флаге цена бывает только из файла, сбой ветки = молчание.
        log.info(f"price_source: ветка упала ({type(e).__name__}) — цену гасим")
        return {"status": "error", "quote": None}


_CAP_MIN_DAYS = 30      # потолок МЕСЯЧНЫЙ: единица кепки — «฿ за месяц (30 суток)» (price_source.json
                        # → low_season_caps.unit). Откат ветки: поставить 1 — вернётся правило до 18.08.


def _cap_applies(q) -> bool:
    """ЕДИНСТВЕННОЕ место, решающее, звучит ли «аренда от <cap> ฿/мес» вместо дословной цены.

    Правило цен v2 п.1 (94ed7ad, 05.07.2026) писалось так: `cap_active И сумма_за_период >
    cap_price`. ЗАЧЕМ — кепка есть АКЦИЯ НИЗКОГО СЕЗОНА: как только расчёт перерастает
    объявленный потолок, клиенту называют потолок, а не формулу. Посылка у него была одна и
    невысказанная — что котировка, которую судят, МЕСЯЧНАЯ.

    Мина: сравниваются РАЗНЫЕ ЕДИНИЦЫ — сумма за период против МЕСЯЧНОГО капа (названо самим
    источником, `low_season_caps.unit_mix_mine`). Срока условие не спрашивало вовсе, поэтому
    фраза «от 9 900 ฿/мес» звучала клиенту, спросившему про ДЕСЯТЬ суток. Замер 18.08 на корпусе
    1243 броней (docs/artifacts/2026-08-17-price-accuracy-working-range.md §2.5, развилка №1):
    на рабочем диапазоне 7-14 суток кепка била у 63 броней из 381 и роняла попадание в ±15 %
    с 62.7 до 52.5 при росте денег ошибки на 62.6 %; на корзине 15-29 суток — у 101 из 124,
    ±15 % с 49.2 до 19.4.

    Решение владельца 18.08: потолок МЕСЯЧНЫЙ, к сроку короче 30 суток он не относится.

    ЧТО ЭТОТ ЗАМОК НЕ ЛОМАЕТ (соседняя посылка, проверена числом). Месячная колонка прайса
    (`_sheet_q_month`/`_sheet_month_cell`) квотируется ровно на 30 суток (`_SHEET_TERMS`), то
    есть остаётся под кепкой; корзина 30-179 суток, где сидит 42 % всех денег, не меняется
    НИ ОДНОЙ броней — её минимальный срок и есть 30 суток (замер: срабатываний 210 до и 210
    после, все показатели побайтно те же).

    Срок неизвестен → судим ПО-СТАРОМУ (кепка применяется): на клиентском пути этой ветки не
    бывает — `pricing.sanity_days_ok` режет котировку без валидного `days` РАНЬШЕ, чем сюда
    доходит дело (_resolve_model_price), а месячная колонка сетки месячная по построению.
    """
    if not isinstance(q, dict):
        return False
    total, cap_price = q.get("total"), q.get("cap_price")
    if not q.get("cap_active") or cap_price is None or total is None or total <= cap_price:
        return False
    try:
        return int(q.get("days")) >= _CAP_MIN_DAYS
    except (TypeError, ValueError):
        return True


def _client_price(q: dict) -> str:
    """Фраза ЦЕНЫ клиенту из quote. Правила цен v2, п.1 и п.5:
    кап (низкий сезон, срок от месяца, total>cap_price) → «аренда от <cap> ฿/мес …» вместо J-цены
    (+депозит/наличие) — предикат один на все четыре точки, см. _cap_applies;
    иначе — поле text из quote ДОСЛОВНО (цена J); иначе — сборка из day_price/total/deposit."""
    cap_price = q.get("cap_price")
    if _cap_applies(q):
        parts = [f"аренда от {cap_price} ฿/мес — предложение низкого сезона"]
        if q.get("deposit") is not None:
            parts.append(f"депозит {q['deposit']} ฿")
        if q.get("available"):
            parts.append("свободен на эти даты")
        return "; ".join(parts)
    if isinstance(q.get("text"), str) and q["text"].strip():
        phrase = q["text"].strip()             # J-цена дословно (п.5)
        # шаг 2/7 #253: депозит модели ОБЯЗАН быть в котировке (клиент назвал модель+срок → его
        # депозит выводим из quote). J-текст Календаря депозит не всегда несёт — дописываем из
        # поля deposit, если его числа ещё нет во фразе (иначе не дублируем).
        dep = q.get("deposit")
        if dep is not None and str(dep) not in phrase:
            phrase += f"; депозит {dep} ฿"
        return phrase
    parts = []
    if q.get("day_price") is not None:
        parts.append(f"{q['day_price']} ฿/день")
    if q.get("total") is not None:
        parts.append(f"итого {q['total']} ฿")
    if q.get("deposit") is not None:
        parts.append(f"депозит {q['deposit']} ฿")
    if q.get("available"):
        parts.append("свободен на эти даты")
    return "; ".join(parts)


def _quote_j_line(q, phrase, passport_dep=False) -> str:
    """Строка ЦЕНЫ для СЛУЖЕБНОГО quote-блока (fail-safe хвост) — ДОСЛОВНАЯ строка столбца J листа
    (q["text"]: несёт «(Скидка за срок N%, … в день)») БЕЗ пересборки. J-текст Календаря депозит
    НЕ ВСЕГДА несёт (см. _client_price / #253): если его числа во фразе нет — дописываем «; депозит
    N ฿» из поля deposit ТЕМ ЖЕ инвариантом, что клиентский путь (иначе quote-хвост теряет депозит —
    регрессия #92 на ветке «живой J без депозита», ловится голденом пары XMAX). Гард `str(dep) not
    in phrase` не даёт задвоить депозит, когда J его уже несёт словами. ИНВАРИАНТЫ клиентской фразы,
    обязанные доехать в хвост целиком, оставляют phrase (полную сборку клиентского пути):
      • выбор паспорта как депозита (#22 шаг4: хвост без суммы) — passport_dep;
      • кап низкого сезона (J-текст переопределён на «аренда от cap ฿/мес») — _cap_applies.
    Нет J-текста (сборка из day/total/deposit) → phrase (прежний путь)."""
    if passport_dep or not isinstance(q, dict):
        return phrase
    if _cap_applies(q):                        # ТОТ ЖЕ предикат, что у клиентской фразы
        return phrase                          # кап-переопределение J-текста доезжает в хвост
    txt = q.get("text")
    if isinstance(txt, str) and txt.strip():
        phrase_j = txt.strip()                 # столбец J ДОСЛОВНО (со «Скидкой за срок»)
        dep = q.get("deposit")                 # депозит из поля quote, если J его не несёт (#253)
        if dep is not None and str(dep) not in phrase_j:
            phrase_j += f"; депозит {dep} ฿"
        return phrase_j
    return phrase


def _resolve_model_price(model, ds, de, hint_days, monthly, getter=None, name_filter=None):
    """Цена для ОДНОЙ модели по датам ds..de. Возвращает (kind, phrase, quote):
      ok    — цену использовать дословно (кап/J-текст/сборка внутри _client_price);
      min   — срок короче минимального: «<тип> сдаём от N дней» + цена на минимум;
      sanity/none/error — фолбэк без числа.
    quote — dict котировки, из которой собрана фраза (или None, если числа нет): нужен вызывающему
    для деривативов (процент от суммы этого расчёта, шаг 2/7 #253). name_filter сужает юниты модели
    (поколение XMAX); getter инъектируется в тестах."""
    cls = bike_class(model)
    # (п.2) минимальный срок аренды: короче → предлагаем минимум и цену на него
    if cls and hint_days is not None and hint_days < cls[1]:
        min_days, label = cls[1], cls[2]
        de_min = _iso_plus(ds, min_days)
        q = None
        if de_min:
            res = _safe_quote_for_model(model, ds, de_min, getter=getter, name_filter=name_filter)
            if res.get("status") == "ok" and res.get("quote") and \
                    pricing.sanity_days_ok(res["quote"].get("days"), min_days, monthly):
                q = res["quote"]
        base = f"{label} сдаём от {min_days} дней (короче срок не оформляем)"
        if q:
            return ("min", f"{base}; цена за {min_days} дн: {_client_price(q)}", q)
        return ("min", f"{base}; точную цену за {min_days} дн уточню и вернусь", None)
    res = _safe_quote_for_model(model, ds, de, getter=getter, name_filter=name_filter)
    status, q = res.get("status"), res.get("quote")
    if status == "ok" and q:
        # SANITY-ГАРД: сверяем days из quote с длительностью из слов клиента.
        if not pricing.sanity_days_ok(q.get("days"), hint_days, monthly):
            return ("sanity", "расчёт по датам не сходится (длительность подозрительная) — НЕ "
                              "называй никакого числа; ответь, что уточню цену по датам и вернусь", None)
        return ("ok", _client_price(q), q)
    if status == "none_available":
        return ("none", "на эти даты все подходящие байки заняты — НЕ называй числа; ответь, что "
                        "уточню наличие и цену на эти даты и вернусь", None)
    return ("error", "точная цена из Календаря сейчас недоступна — НЕ называй никакого числа "
                     "(в т.ч. из FAQ); ответь, что уточнишь цену и вернёшься", None)


def _wrap_single(kind: str, phrase: str) -> str:
    """Инструкция ЦЕНА для ОДНОЙ посчитанной модели.

    ЗАПРЕТ СУЖЕН 20.08.2026 (правило владельца «подбор по классу 20.08»): раньше здесь стояло
    «цены/депозиты ДРУГИХ моделей в этом ответе НЕ приводи», и оно запрещало называть другие модели
    ВООБЩЕ. Охранял этот запрет не молчание о парке, а НЕПОСЧИТАННЫЕ ЧИСЛА — посчитана была ровно
    одна модель, и цифра по соседней могла прийти только из головы LLM или из FAQ. Теперь запрет
    назван своей посылкой: не называть цен по моделям, которых в расчёте НЕТ. Разбор забора —
    в секции «ПОДБОР ПО КЛАССУ» ниже."""
    if kind == "ok":
        return ("ЦЕНА из Календаря бронирования (использовать ДОСЛОВНО, не пересчитывать, не "
                "округлять и НЕ переформатировать — приведи строку как есть и НЕ опускай её часть "
                "про скидку за срок «(Скидка за срок N%, … в день)», если она в строке; посчитана "
                "ТОЛЬКО эта модель — цены и депозиты моделей, которых в расчёте нет, НЕ называй и "
                "НЕ выдумывай): " + phrase + ".")
    return "ЦЕНА: " + phrase + "."


def _quote_marker_note() -> str:
    """Инструкция ЦЕНА МАРКЕРНОГО quote-режима (вариант Б развилки #274, шаг 7): каноническую
    строку ЦЕНЫ (столбец J листа, цифры — код) в финал вставляет КОД на место метки [QUOTE] —
    ТОТ ЖЕ класс, что [PRICE_SHEET]. LLM цифры НЕ видит → перефразировать нечего; инвариант #92
    «строка J дословно» выполняется ПО ПОСТРОЕНИЮ (живой смоук 23.07: sonnet-5 переносил цифры
    парафразом, дедуп #365 склейку пропускал — канонической строки у клиента не было).
    Префикс «ЦЕНА из Календаря бронирования» сохранён: якорь _PRICE_OK_MARKS и тестов."""
    return ("ЦЕНА из Календаря бронирования ПОСЧИТАНА (посчитана ТОЛЬКО эта модель — цены и "
            "депозиты моделей, которых в расчёте нет, НЕ называй и НЕ выдумывай). Каноническую строку цены "
            "вставит КОД ДОСЛОВНО на место метки [QUOTE]: выведи метку [QUOTE] ОТДЕЛЬНОЙ строкой "
            "там, где в ответе должна звучать цена; сам НИКАКИЕ числа цены/итога/депозита НЕ "
            "называй, НЕ пересказывай и НЕ выдумывай (ни из FAQ, ни ориентиров) — цифры уже "
            "посчитаны и придут кодом. «Уточню цену и вернусь» НЕ пиши: цена уже есть.")


def _percent_amount(pct, total):
    """N% от суммы расчёта → целое число ฿ (округление к ближайшему), или None если сумма не задана."""
    try:
        return round(int(total) * int(pct) / 100)
    except (TypeError, ValueError):
        return None


def _percent_line(pct, q) -> str:
    """Инструкция-довесок к ЦЕНЕ: клиент спросил «сколько будет N%» → считаем N% от total этого
    quote КОДОМ и кладём готовое число в блок ЦЕНА (оно попадает в белый список пост-чека → LLM
    вправе его назвать). Нет total → просим уточнить без числа. Строка начинается с пробела."""
    total = q.get("total") if isinstance(q, dict) else None
    amount = _percent_amount(pct, total)
    if amount is None:
        return (f" Клиент спрашивает, сколько будет {pct}% — точную сумму назову после расчёта по "
                f"датам, БЕЗ числа.")
    return (f" Клиент спрашивает, сколько будет {pct}%: это {pct}% от суммы этого расчёта "
            f"({total} ฿) = {amount} ฿ — назови клиенту именно это число.")


# ============================ ПРАЙС ПО ВСЕМУ ПАРКУ (price_sheet) ============================
# Сценарий «клиент просит цены на ВСЕ модели / прайс-лист». Черновик обязан дать РЕАЛЬНЫЕ цифры
# (день/7 дней/месяц по каждой сдаваемой модели), а не переспрашивать модель/опыт и не обещать
# «пришлю позже». Источник — ТОЛЬКО живой Bridge (та же точка правды, что quote_price): по каждой
# модели allowlist три quote() на 1/7/30 дней от даты-якоря. Цифры рендерит КОД детерминированно
# (инвариант как у кап-подстановки) — LLM их не сочиняет и не переформатирует.
#
# ЗАБОР ЧЕСТЕРТОНА (почему сетка изначально шла по ВСЕМУ парку — и что это держало). Сетка отвечает
# на КАТАЛОГ-вопрос («какие модели есть и почём»), а не на бронь: дат клиента у неё в 37 % случаев
# нет вовсе (172 черновика из 470, замер 17.08) — тогда якорь = ЗАВТРА, а «сроки» 1/7/30 суток
# синтетические. Прайс-лист в этой рамке — витрина тарифов, и занятость ему была не нужна: сказать
# «свободен» бот всё равно не имеет права (AVAILABILITY_INVARIANT_RULE), значит цифра читалась как
# тариф, а не как предложение конкретного юнита. Что на этом стояло, проверено поимённо: цену
# модели, которой сейчас нет, показывал ИМЕННО этот путь — и точечная котировка тут ни при чём, у
# неё своя дверь (_resolve_model_price → quote_for_model, ветка none_available). Опираются на
# полноту сетки ещё трое, и все трое переживают отсев: filter_sheet_rows / filter_rows_by_requested
# при пустом пересечении падают на ПОЛНУЮ сетку (владельческий анти-луп), а model_claim_mismatch
# бракует черновик, где заявлена одна модель, а карточки чужие, — теперь он может сработать на
# ЗАНЯТОЙ модели, названной клиентом, и это верное поведение: цены занятого мы не называем.
_SHEET_TERMS = ((1, "day"), (7, "week"), (30, "month"))     # дни аренды от даты-якоря → ключ ячейки
_SHEET_TTL = int(os.getenv("PRICE_SHEET_TTL_SEC", "180") or "180")   # кэш прайса, минуты (не сутки)
# Параллельность живых quote при построении сетки (класс-фикс регресса 20:59 после 551987e:
# минимум-по-вариантам квотирует ВСЕ живые юниты — ~12 моделей × ~3 юнита × 3 срока ≈ сотня GET;
# ПОСЛЕДОВАТЕЛЬНО по ~3.4с это 6м16с живого билда и замороженный Telethon-цикл. Пул сокращает
# стену до десятков секунд; само МНОЖЕСТВО quote НЕ ослаблено — меняется только конкурентность).
_SHEET_WORKERS = int(os.getenv("PRICE_SHEET_WORKERS", "8") or "8")
# Дедлайн построения целиком: юнит, не успевший к дедлайну (висящий HTTP и т.п.), пропускается
# С ЛОГОМ — сетка выходит из живых остальных, один битый юнит НЕ валит прайс целиком.
_SHEET_DEADLINE = int(os.getenv("PRICE_SHEET_DEADLINE_SEC", "120") or "120")
_sheet_cache = {"key": None, "ts": 0.0, "rows": None, "skipped": None}


def _sheet_variants(model, bikes):
    """ВСЕ живые байки-варианты модели в парке (старый/новый юнит и т.п.). → list[str] имён (может
    быть пуст). Тариф в Календаре Bridge отдаёт по ИМЕНИ юнита, и у вариантов одной модели он может
    РАЗЛИЧАТЬСЯ (напр. XMAX старый 2020-2022 дешевле нового 2023+). Раньше брали одного представителя
    и завышали, если жив дешёвый старый юнит; теперь колонки сетки = МИНИМУМ по вариантам (см.
    price_sheet). Матчим ТЕМ ЖЕ _bike_key, что и park_allowlist (снимает CC/СС): иначе «CB 300R» не
    сойдётся с именем «CB 300CC R 9011» (pricing._candidates по _norm_alnum спотыкается о CC)."""
    mk = _bike_key(model)
    if not mk:
        return []
    out = []
    for b in (bikes or []):
        nm = b.get("name") if isinstance(b, dict) else None
        if nm and mk in _bike_key(nm):
            out.append(nm)
    return out


def _sheet_q_total(q):
    """Числовая величина суточной/недельной колонки квоты (сумма аренды) или None."""
    return q.get("total") if isinstance(q, dict) else None


def _sheet_q_month(q):
    """Числовая величина МЕСЯЧНОЙ колонки квоты — РОВНО как показывает _sheet_month_cell: кап-«от»
    имеет приоритет (_cap_applies → cap_price), иначе сумма месяца. → число|None.
    Колонка квотируется на 30 суток (_SHEET_TERMS), то есть срочный замок кепки её пропускает."""
    if not isinstance(q, dict):
        return None
    if _cap_applies(q):
        return q.get("cap_price")
    return q.get("total")


def _sheet_min_variant(quotes, value_fn):
    """Из квот вариантов модели выбрать ту, что даёт МИНИМАЛЬНУЮ колонку (по value_fn); None-значения
    пропускаем. → квота-победитель (самосогласованный dict — рендер/кап берёт из неё) или None (нет
    ни одной цифры). Для одной-единственной модели-варианта == та самая квота (регресс без изменений)."""
    best = best_v = None
    for q in quotes:
        v = value_fn(q)
        if v is None:
            continue
        if best_v is None or v < best_v:
            best_v, best = v, q
    return best


def _sheet_products(model, variants):
    """Продукты модели для сетки: (метка, свои_варианты). XMAX → ДВА поколения (старое / New Gen)
    отдельными строками — минимум-по-вариантам для XMAX снят (тарифы поколений разные, минимум их
    схлопнул бы в одну цену). Прочие модели — ОДИН продукт со всеми вариантами (минимум-по-вариантам
    сохранён). Пустые поколения (нет живых юнитов) отбрасываем."""
    if _is_xmax_model(model):
        out = []
        for label, pred in _XMAX_PRODUCTS:
            vs = [v for v in variants if pred(v)]
            if vs:
                out.append((label, vs))
        return out
    return [(model, variants)]


def _sheet_min_deposit(term_quotes):
    """Минимальный депозит по ВСЕМ вариант-квотам модели (депозит — такая же колонка сетки: МИНИМУМ
    по вариантам; старый юнит XMAX 5000 vs новый 7000 → 5000). → число|None (нет депозита)."""
    deps = [q.get("deposit") for qs in term_quotes.values() for q in qs
            if isinstance(q, dict) and q.get("deposit") is not None]
    return min(deps) if deps else None


# --- ЗАНЯТОСТЬ В СЕТКЕ (20.08.2026) --------------------------------------------------------------
# ДО этой правки сетка квотировала ВЕСЬ парк и называла цену забронированного байка не поморщившись:
# разведка 17.08 (docs/artifacts/2026-08-17-fleet-availability.md §4, «Остатки») мерила это дословно
# — «прайс-лист парка занятость игнорирует полностью, слова available в ветке нет вовсе», точка
# касания названа там же: _sheet_q_total/_sheet_min_variant. Признак при этом ПРИХОДИТ по КАЖДОМУ
# юниту тем же полем `available` двери quote_price, которым уже живёт точечная котировка
# (pricing.quote_for_model: перебор юнитов, первый available → ok, иначе none_available).
#
# ТРИ состояния, а не два. Молчание источника занятостью НЕ является: признака нет → «не проверено»,
# и такая модель в подбор тоже не идёт, но по ДРУГОЙ причине. Слить их в одно значило бы называть
# «занято» там, где просто не удалось прочитать, — ровно та ложь, которой этот слой должен мешать.
_SHEET_FREE, _SHEET_BUSY, _SHEET_UNCHECKED = "free", "busy", "unchecked"
_SHEET_SKIP_WORD = {_SHEET_BUSY: "все юниты ЗАНЯТЫ на эти даты",
                    _SHEET_UNCHECKED: "занятость НЕ ПРОВЕРЕНА (признака нет в ответе)"}
# Откат ветки одной ручкой, без коммита: сетка снова строится по всему парку, побайтно как до 20.08.
_SHEET_AVAIL_OFF = (os.getenv("PRICE_SHEET_AVAIL_OFF", "").strip() not in ("", "0"))


def _sheet_unit_free(q):
    """Свободен ли ЮНИТ на период своей котировки. → True (свободен) / False (занят) / None
    (признака нет — «не проверено»).

    Истинность поля читаем ТЕМ ЖЕ правилом, что боевой точечный путь (`pricing.quote_for_model` →
    `if q.get("available")`): одна дверь не должна судиться двумя мерками. Отличие ровно одно и оно
    намеренное — ОТСУТСТВУЮЩЕЕ поле (или null) там неотличимо от «занят», а здесь становится
    третьим исходом. Живой формат поля — JSON-bool (мост считает его пересечением запрошенного
    периода со строками вкладки «клиенты», QuotePrice.js), поэтому bool() достаточно, и догадок про
    строки «FALSE»/числа здесь НЕ заводим: их живой ответ не присылает."""
    if not isinstance(q, dict) or q.get("available") is None:
        return None
    return bool(q["available"])


def _sheet_free_quotes(quotes):
    """Только котировки СВОБОДНЫХ юнитов. «Занят» и «не проверено» одинаково не годятся в колонку:
    цену называем лишь за то, что клиент реально может забрать."""
    return [q for q in quotes if _sheet_unit_free(q) is True]


def _sheet_availability(term_quotes):
    """Вердикт по МОДЕЛИ из котировок всех её юнитов на всех сроках. → free | busy | unchecked.
    Хоть один свободный юнит → модель в подборе (цель правки; у NMAX их десять, у FORZA один).
    Свободных нет, но занятые ПРОЧТЕНЫ → busy. Ни одного прочитанного признака → unchecked."""
    states = [_sheet_unit_free(q) for qs in term_quotes.values() for q in qs]
    if any(s is True for s in states):
        return _SHEET_FREE
    if any(s is False for s in states):
        return _SHEET_BUSY
    return _SHEET_UNCHECKED


# --- ОДИН ИСТОЧНИК ЦЕНЫ НА ОБА ПУТИ (21.08.2026) -------------------------------------------------
# ЗАЧЕМ. 20.08 на ЗАПИСАННОЕ ПРАВИЛО переехала только ТОЧЕЧНАЯ котировка (_safe_quote_for_model);
# сетка парка осталась на живом листе — и это не догадка, а замер: повтор экзамена 21.08 (`ab16dcd`,
# docs/artifacts/2026-08-21-exam-rerun.md) дал в случаях 4 и 7 ТЕ ЖЕ числа, что до переключения,
# при том что одиночная котировка на тех же датах уже различала сезоны (298 / 298 / 437 / 397).
# Цена расхождения названа деньгами: в ОДНОМ сообщении клиенту спрошенная модель звучала по
# правилу, а список альтернатив — по слепому к сезону листу, и на пике это 27.7-31.7 % разницы
# за одно и то же (замер 17.08, `69a6c9f`).
#
# ЗАБОР ЧЕСТЕРТОНА — почему сетка ИЗНАЧАЛЬНО шла своей дорогой. Причина названа докстрокой врезки
# 20.08 дословно: «у неё нет дат клиента (якорь — завтра), а сезон файл приписывает по дате НАЧАЛА
# АРЕНДЫ». Посылка ВЕРНА ровно наполовину и проверена числом: дат нет у 37 % черновиков (172 из 470,
# замер 17.08) — то есть у 63 % даты ЕСТЬ, и у сетки они те же самые, `hints["iso_start"]`
# (build_price_sheet_note: «Даты в диалоге → считаем по ним»). Случай 4 экзамена — ровно этот: якорь
# 2026-12-20, чистый пик P5. А там, где дат правда нет, якорь «завтра» — ЗАКОННАЯ дата начала, и
# правило судит её так же честно, как любую другую: витрина тарифов на ближайшую дату.
# Опирается ли на прежний путь что-то ещё — проверено поимённо: занятость (`available`), выбор юнита
# и ДЕПОЗИТ приходят из живой двери и остаются её словом (правило их не знает и не подменяет —
# `reprice` копирует квоту и трогает только day_price/total/cap_*); подбор по классу и подвыборки
# (`filter_sheet_rows`, `filter_rows_by_requested`, `_class_offer_block`) берут ТЕ ЖЕ rows и потому
# едут следом сами; `model_claim_mismatch` судит имена, а не числа.
_SHEET_NORULE = "norule"
_SHEET_SKIP_WORD[_SHEET_NORULE] = "ЗАПИСАННОЕ ПРАВИЛО её НЕ СУДИТ (цену по ней не называем)"
# Откат ветки одной ручкой, без коммита: сетка снова считается живым листом, побайтно как до 21.08.
_SHEET_RULE_OFF = (os.getenv("PRICE_SHEET_RULE_OFF", "").strip() not in ("", "0"))


def _sheet_rule_low_season(ds):
    """Низкий ли сезон ПО ПРАВИЛУ на дату-якорь ds. → True | False | None (правило не прочиталось).

    Нужен НЕ для цены (её считает `price_source.reprice`), а для СЛУЖЕБНОЙ пометки модератору
    `_sheet_season_note`: она читает `cap_active`/`season` из квоты, и строка `season` — слово
    ЖИВОГО ЛИСТА о ЖИВОМ ЛИСТЕ. Пока лист был источником цены, слово было согласовано с числом;
    как только число считает правило, «низкий сезон, цены до 31 октября» рядом с ПИКОВОЙ ценой
    становится противоречием, которого до правки не было. Низкий сезон = все множители периода
    ровно 1.000 (формулировка самого файла: «season_of_base — низкий сезон, множитель 1.000»)."""
    try:
        per = price_source.period_of(price_source.load(), datetime.date.fromisoformat(str(ds)))
        mult = [float(v) for v in (per.get("multiplier") or {}).values()]
    except Exception:
        return None
    return bool(mult) and all(m == 1.0 for m in mult)


def _sheet_rule_quotes(term_quotes, label, ds, keep_season=True):
    """Квоты ОДНОГО продукта сетки → пересчитанные ЗАПИСАННЫМ ПРАВИЛОМ. → dict сроков | None.

    None означает «правило эту модель НЕ СУДИТ (или ветка сорвалась)», и тогда модель уходит из
    сетки ЦЕЛИКОМ — половины прайса с ценами не бывает. Строгость здесь намеренная: `reprice`
    гасит цену молчанием (`status='error'`), и пропусти мы такую модель дальше, она встала бы в
    сетку с прочерками рядом с ценами соседей, то есть выглядела бы «пока не считали», а не
    «цену за неё называть нельзя».

    Срок каждой колонки — свой (`_SHEET_TERMS`: 1/7/30 суток от якоря), поэтому и правило
    спрашивается по КАЖДОЙ колонке отдельно: корзина ступени у суток, недели и месяца разная
    (0.97 / 1.000 / 0.53), и одной ценой их не накрыть."""
    out = {}
    for n, key in _SHEET_TERMS:
        src = term_quotes.get(key) or []
        de = _iso_plus(ds, n)
        priced = []
        for q in src:
            try:
                res = price_source.reprice({"status": "ok", "quote": q}, label, ds, de, _bike_key)
            except Exception as e:
                log.info(f"SHEET: правило цены упало на {label} ({type(e).__name__}) — модель не котируем")
                return None
            q2 = res.get("quote") if isinstance(res, dict) else None
            if not (isinstance(res, dict) and res.get("status") == "ok" and isinstance(q2, dict)):
                return None
            if not keep_season:
                q2.pop("season", None)
            priced.append(q2)
        if src and not priced:
            return None
        out[key] = priced
    return out


def price_sheet_status(ds, getter=None, _now=None, _fleet=None, _gate=None):
    """Прайс по СВОБОДНОМУ парку на дату-якорь ds (iso) + ЧЕСТНЫЙ разрез отсеянного.
    → (rows, skipped): rows — как у price_sheet; skipped — list[{model, reason}], reason ∈
    {busy, unchecked, norule}. Пустой rows при непустом skipped читается «свободных нет / не
    проверено», а не «источника нет», — те два случая до 20.08 были неразличимы (тот же класс, что
    pricing.fleet → fleet_status).

    По каждой модели allowlist (кроме несдаваемых) — три quote() (1/7/30 дней) ЖИВЫМ Bridge по
    КАЖДОМУ юниту; в колонки идут ТОЛЬКО свободные юниты, модель без единого свободного в сетку не
    попадает вовсе. Кэш _SHEET_TTL сек по ds (только боевой путь; при инъекции getter — без кэша).
    getter/_now/_fleet инъектируются в тестах (боевой Bridge не дёргаем).

    ЦЕНУ СЧИТАЕТ ТО ЖЕ ЗАПИСАННОЕ ПРАВИЛО, ЧТО И ТОЧЕЧНУЮ КОТИРОВКУ (21.08). Живая дверь остаётся
    источником ЗАНЯТОСТИ, депозита и имени юнита; числами распоряжается `price_source.reprice` —
    ровно тот же вызов с тем же ключом `_bike_key`, что в `_safe_quote_for_model`. Оба пути ответа
    берут цену из одного места, и в одном сообщении клиенту больше не могут стоять два прайса.

    СТОРОЖ СВЕЖЕСТИ СПРАШИВАЕТСЯ ОДИН РАЗ НА ВСЮ СЕТКУ и ДО живых quote — двумя причинами. Первая:
    «не половина списка с ценами, а весь целиком молчит» — вердикт у списка обязан быть один, иначе
    отказ сторожа посреди перебора дал бы прайс, где часть моделей с ценами, а часть без, и клиент
    прочёл бы это как «остального нет». Вторая: считать цену, которую запрещено называть, незачем —
    отказ снимает ~сотню живых GET, а не только числа. Порядок ветки ОБРАТЕН точечному пути
    (там сторож ПОСЛЕ котировки), и это не небрежность: точечной котировке живой ответ нужен сам по
    себе — её `status` судит занятость и без цены, — а сетке молчащей по цене занятость не нужна.

    ИНЪЕКЦИЯ ЖИВОЙ ДВЕРИ (getter/_fleet) ОСТАВЛЯЕТ ПУТЬ ПРЕЖНИМ, и это названо вслух. Признак
    боевого пути здесь тот же, которым уже живёт кэш строкой ниже (`getter is None and
    _fleet is None`): замоканный мост — это «судим ЖИВУЮ дверь», её тарифы фикстура и задаёт.
    Ветку правила в тестах включает ОТДЕЛЬНАЯ инъекция `_gate` (вердикт сторожа фикстурой) — так
    ветка проверяема на фикстурах и при этом не переписывает молча три десятка голденов сетки,
    снятых с мокнутого моста."""
    now = _now() if _now else time.time()
    c = _sheet_cache
    # --- ИСТОЧНИК ЦЕНЫ И СТОРОЖ: до кэша, до живых quote ---
    gate = _gate
    if gate is None and getter is None and _fleet is None:
        gate = price_gate.allow           # боевой путь; при инъекции двери — см. докстроку
    use_rule = False
    if gate is not None and not _SHEET_RULE_OFF:
        try:
            use_rule = bool(price_source.enabled())
        except Exception:                 # ручка не прочиталась → это НЕ откат к листу
            use_rule = True
    if use_rule:
        try:
            may, card = gate()
        except Exception as e:            # сторож не отработал → это НЕ разрешение
            may, card = False, ("ЦЕНА НЕ НАЗВАНА: сторож свежести не отработал (%s)."
                                % type(e).__name__)
        if not may:
            # Молчит ВЕСЬ список: пустой rows доводится до `_PRICE_SHEET_UNAVAILABLE` (без чисел,
            # без переспроса модели). Кэш сетки НЕ трогаем ни на чтение, ни на запись — иначе
            # отказ сторожа обслуживался бы вчерашними числами ещё _SHEET_TTL секунд.
            log.warning("price_gate: %s (ПРАЙС-СЕТКА ПАРКА — цен не называем ни по одной модели)",
                        card)
            return [], []
    if getter is None and _fleet is None and c["key"] == ds and c["rows"] is not None \
            and (now - c["ts"]) < _SHEET_TTL:
        return c["rows"], (c.get("skipped") or [])
    try:
        allow = park_allowlist(getter)
    except Exception:
        allow = None
    if not allow:
        return [], []
    models = [m for m in allow if _bike_key(m) not in _NON_RENTABLE_KEYS]
    bikes = _fleet if _fleet is not None else pricing.fleet(_get=getter)
    # Колонка какой ячейки чем минимизируется: сутки/неделя — по сумме, месяц — по кап-«от» величине.
    value_fn = {"day": _sheet_q_total, "week": _sheet_q_total, "month": _sheet_q_month}
    t0 = time.time()
    # План живых вызовов: (модель × срок × КАЖДЫЙ живой вариант). Квотируем ПАРАЛЛЕЛЬНО пулом
    # (класс-фикс 6м16с последовательного билда 20:59); memo (bike, de) страхует от дублей.
    plan = []                       # (label, variants, {key: [(bike, de), ...]})
    for m in models:
        variants = _sheet_variants(m, bikes)
        if not variants:
            continue
        # XMAX разворачиваем в два продукта-поколения (свои юниты у каждого); прочие — один продукт.
        for label, vs in _sheet_products(m, variants):
            per_term = {}
            for n, key in _SHEET_TERMS:
                de = _iso_plus(ds, n)
                per_term[key] = [(bike, de) for bike in vs] if de else []
            plan.append((label, vs, per_term))

    def _q_one(bike, de):
        """Один живой quote юнита; ЛЮБОЙ сбой → None с логом (битый юнит НЕ валит сетку)."""
        try:
            return pricing.quote(bike, ds, de, _get=getter)
        except Exception as e:
            log.info(f"SHEET: quote юнита {bike} {ds}..{de} упал ({type(e).__name__}) — пропущен")
            return None

    import concurrent.futures as _cf
    futs = {}                       # (bike, de) -> Future (memo в пределах построения)
    ex = _cf.ThreadPoolExecutor(max_workers=max(1, _SHEET_WORKERS))
    try:
        for _, _, per_term in plan:
            for pairs in per_term.values():
                for bd in pairs:
                    if bd not in futs:
                        futs[bd] = ex.submit(_q_one, *bd)
        deadline = t0 + _SHEET_DEADLINE
        results = {}
        for bd, fut in futs.items():
            try:                    # просрочка дедлайна/сбой юнита → None (skip с логом), не обвал
                results[bd] = fut.result(timeout=max(0.0, deadline - time.time()))
            except Exception:
                results[bd] = None
                log.info(f"SHEET: юнит {bd[0]} до {bd[1]} не уложился в дедлайн {_SHEET_DEADLINE}с — пропущен")
    finally:
        # НЕ ждём зависшие HTTP: невзятые в работу отменяем, взятые дотекут в фоне (демон-длинножитель).
        ex.shutdown(wait=False, cancel_futures=True)

    # Слово живой двери о сезоне («низкий сезон») переживает пересчёт ТОЛЬКО пока правило согласно:
    # иначе служебная пометка модератору утверждала бы низкий сезон рядом с пиковой ценой. Правило
    # не прочиталось (None) — слово листа не снимаем: гадать за сторожа не наше дело.
    keep_season = (_sheet_rule_low_season(ds) is not False) if use_rule else True
    rows, skipped = [], []
    for label, variants, per_term in plan:
        # Порядок квот = порядок вариантов парка (детерминизм при равенстве колонок); None — выпал.
        got = {key: [q for q in (results.get(bd) for bd in pairs) if q is not None]
               for key, pairs in per_term.items()}
        if _SHEET_AVAIL_OFF:                   # ручка отката: ветка не исполняется, путь прежний
            term_quotes = got
        else:
            verdict = _sheet_availability(got)
            if verdict != _SHEET_FREE:
                # Занятая (и непроверенная) модель в подбор НЕ идёт: цену за неё не называем вовсе.
                # Чем заменить занятую — ОТДЕЛЬНОЕ решение владельца, карты замен здесь нет.
                skipped.append({"model": label, "reason": verdict})
                log.info(f"SHEET: модель {label} в сетку НЕ вошла — {_SHEET_SKIP_WORD[verdict]}")
                continue
            # В колонки идут только свободные юниты: минимум-по-вариантам не смеет взять цену
            # занятого (у него она бывает НИЖЕ — старый дешёвый юнит как раз и разобран первым).
            term_quotes = {key: _sheet_free_quotes(qs) for key, qs in got.items()}
        if use_rule:
            # ЦЕНУ ставит правило — ПОСЛЕ отсева занятых: считать цену того, чего клиент не заберёт,
            # незачем, а занятость по-прежнему слово живой двери.
            ruled = _sheet_rule_quotes(term_quotes, label, ds, keep_season=keep_season)
            if ruled is None:
                skipped.append({"model": label, "reason": _SHEET_NORULE})
                log.info(f"SHEET: модель {label} в сетку НЕ вошла — {_SHEET_SKIP_WORD[_SHEET_NORULE]}")
                continue
            term_quotes = ruled
        cells = {key: _sheet_min_variant(term_quotes[key], value_fn[key]) for _, key in _SHEET_TERMS}
        rows.append({"model": label, "class": bike_class(label), "bike": variants[0], "cells": cells,
                     "deposit": _sheet_min_deposit(term_quotes)})
    n_ok = sum(1 for v in results.values() if v is not None)
    n_by = lambda why: sum(1 for s in skipped if s["reason"] == why)                     # noqa: E731
    log.info(f"SHEET: сетка построена за {time.time() - t0:.1f}с — {len(rows)} моделей, "
             f"{len(futs)} quote ({len(futs) - n_ok} пропущено), пул {_SHEET_WORKERS}; "
             f"источник цены {'ПРАВИЛО' if use_rule else 'живой лист'}; отсеяно по занятости "
             f"{n_by(_SHEET_BUSY)}, по непроверенности {n_by(_SHEET_UNCHECKED)}, "
             f"правилом не судится {n_by(_SHEET_NORULE)}")
    if getter is None and _fleet is None:
        c.update(key=ds, ts=now, rows=rows, skipped=skipped)
    return rows, skipped


def price_sheet(ds, getter=None, _now=None, _fleet=None, _gate=None):
    """Строки прайс-сетки (СОВМЕСТИМОСТЬ: только rows, без разреза отсеянного — сбой источника
    здесь неотличим от «все заняты»). Новый код обязан звать price_sheet_status()."""
    rows, _skipped = price_sheet_status(ds, getter=getter, _now=_now, _fleet=_fleet, _gate=_gate)
    return rows


# ================= ПОДБОР ПО КЛАССУ (правила владельца 20.08.2026, узел business_rules) =================
# Метка правила в мозге: «подбор по классу 20.08». Взято ПО ИМЕНИ из живого реестра моста, не из
# пересказа. Лестница классов названа владельцем и задаёт слово «выше»; разнос парка — снимок 20.08
# (37 сдаваемых единиц из 38; CLICK 125 в аренду не сдаётся никогда).
#
# ЗАБОР ЧЕСТЕРТОНА — зачем вообще стоял запрет «цены/депозиты ДРУГИХ моделей в этом ответе НЕ приводи»
# (жил в _wrap_single и _quote_marker_note до 20.08). Точечная котировка идёт МАРКЕРНЫМ режимом: LLM
# цифр не видит вовсе, каноническую строку столбца J вставляет КОД. Посчитана была РОВНО ОДНА модель,
# значит любое число по соседней могло прийти только из головы модели или из FAQ — то есть быть
# выдуманным, а инвариант «без котировки нет числа» рухнул бы молча. Запрет охранял НЕПОСЧИТАННЫЕ
# ЧИСЛА, а «называть модели» запрещал заодно — просто потому, что других посчитанных моделей на этом
# пути до сегодня не бывало.
#
# ЧТО ТЕРЯЕМ, СНИМАЯ. Из охраняемого — ничего: запрет не снят, а СУЖЕН до собственной посылки («числа
# по моделям, которых нет в блоке, не называй»), и блок теперь несёт НЕСКОЛЬКО посчитанных моделей.
# Платим двумя вещами, обе названы: (1) ЛАТЕНТНОСТЬ — живые quote по остальным моделям класса (пул +
# дедлайн _CLASS_OFFER_DEADLINE, просрочка = модель просто не попала в подбор, ответ не срывается);
# (2) ДЛИНА ответа — против неё стоит правило потолка сообщения (не обрезаем молча, см.
# _class_offer_block). Откат целиком — ручкой PRICE_CLASS_OFFER_OFF=1, без коммита.
_CLASS_SCOOTER, _CLASS_MAXI, _CLASS_HEAVY, _CLASS_MOTO = (
    "обычные скутеры", "макси-скутеры", "тяжёлые", "мотоциклы")
# Лестница СНИЗУ ВВЕРХ: индекс = ранг, «выше» = больший индекс. Порядок назван владельцем дословно.
_CLASS_LADDER = (_CLASS_SCOOTER, _CLASS_MAXI, _CLASS_HEAVY, _CLASS_MOTO)
# Разнос живого парка по классам (снимок 20.08.2026; ключи — _bike_key, тот же, что у allowlist).
# Моделей «отнести некуда» в снимке ноль. CLICK 125 сюда НЕ входит осознанно: класс у неё есть
# (обычный скутер), но аренды нет — её режет _NON_RENTABLE_KEYS раньше классов.
_PARK_CLASS = {
    "nmax155": _CLASS_SCOOTER,
    "adv350": _CLASS_MAXI, "xmax300": _CLASS_MAXI, "forza300": _CLASS_MAXI,
    "xadv750": _CLASS_HEAVY,
    "cbr650r": _CLASS_MOTO, "cb650r": _CLASS_MOTO, "cb300r": _CLASS_MOTO,
    "xsr155": _CLASS_MOTO, "ninja400": _CLASS_MOTO, "mt03": _CLASS_MOTO,
    "vulcan650s": _CLASS_MOTO,
}
# Длинные ключи первыми: «xmax300» обязан выиграть у более короткого совпадения, если такое заведут.
_PARK_CLASS_KEYS = tuple(sorted(_PARK_CLASS, key=len, reverse=True))

_CLASS_OFFER_OFF = (os.getenv("PRICE_CLASS_OFFER_OFF", "").strip() not in ("", "0"))
_CLASS_OFFER_WORKERS = int(os.getenv("PRICE_CLASS_OFFER_WORKERS", "8") or "8")
_CLASS_OFFER_DEADLINE = int(os.getenv("PRICE_CLASS_OFFER_DEADLINE_SEC", "60") or "60")
# Потолок сообщения Telegram. ЭТО ТЕХНИЧЕСКОЕ ОГРАНИЧЕНИЕ, А НЕ ПРАВИЛО ВЛАДЕЛЬЦА — правило прямо
# говорит, что предела по числу моделей нет, а не влезшее НЕ пропадает молча (см. _class_offer_block).
_CLASS_OFFER_MSG_MAX = 4096


def park_class(model):
    """Модель → класс лестницы владельца | None (класса нет в снимке 20.08).

    None — честный третий исход, а не «скутер по умолчанию»: неизвестной модели мы не знаем ни
    ранга, ни того, что считать «выше», и подбор по классу на ней НЕ строится вовсе (прежний путь)."""
    mk = _bike_key(model)
    if not mk:
        return None
    for k in _PARK_CLASS_KEYS:
        if k in mk:
            return _PARK_CLASS[k]
    return None


def _class_rank(model):
    """Ранг класса модели (0 — обычные скутеры … 3 — мотоциклы) | None."""
    c = park_class(model)
    return _CLASS_LADDER.index(c) if c in _CLASS_LADDER else None


def class_offer_scope(asked, heavy_ok=False, cheaper_ok=False):
    """Классы, которые бот вправе предложить САМ, дополнительно к спрошенной модели. → set | None
    (класс спрошенного неизвестен — подбора не строим).

    Два правила владельца сидят ровно здесь и больше нигде:
      • НИЖЕ КЛАССОМ БОТ САМ НЕ ПРЕДЛАГАЕТ НИКОГДА — пол списка равен рангу спрошенного; опускает
        пол только явная просьба клиента «дешевле/проще» (cheaper_ok);
      • ТЯЖЁЛЫЙ КЛАСС — только если клиент САМ сказал про мощность, размер или опыт (heavy_ok). Это
        исключение из «того же класса или выше»: сам бот в тяжёлый класс не поднимает никогда."""
    r = _class_rank(asked)
    if r is None:
        return None
    lo = 0 if cheaper_ok else r
    out = {c for i, c in enumerate(_CLASS_LADDER) if i >= lo}
    if not heavy_ok:
        out.discard(_CLASS_HEAVY)
    return out


def class_candidates(asked, allow, heavy_ok=False, cheaper_ok=False):
    """Модели парка, которые ПО КЛАССУ вправе идти дополнительно к спрошенной. → list[str] (порядок
    детерминирован: сначала свой класс, потом выше; внутри класса — порядок allowlist).

    Сама спрошенная модель отсюда исключена: она ОСНОВНОЙ вариант, а не «дополнительно». Несдаваемые
    (CLICK 125) отсекаются раньше классов — у них нет аренды, а не класса."""
    scope = class_offer_scope(asked, heavy_ok=heavy_ok, cheaper_ok=cheaper_ok)
    if scope is None:
        return []
    ak = _bike_key(asked)
    out = []
    for i, m in enumerate(allow or []):
        mk = _bike_key(m)
        if not mk or mk in _NON_RENTABLE_KEYS:
            continue
        if ak and (ak in mk or mk in ak):
            continue
        c = park_class(m)
        if c in scope:
            out.append((_CLASS_LADDER.index(c), i, m))
    return [m for _r, _i, m in sorted(out)]


def class_offer_status(asked, ds, de, hint_days=None, monthly=None, getter=None,
                       heavy_ok=False, cheaper_ok=False, want_old_gen=False, allow=None):
    """Свободные на ds..de модели того же класса или выше. → (free, skipped):
    free — list[(метка, фраза_цены, quote)]; skipped — list[{model, reason}], reason ∈
    {none (все юниты заняты), min (срок короче минимального), sanity, error}.

    Занятость судит та же живая дверь, что и точечная котировка (`_resolve_model_price` →
    `quote_for_model`: перебор юнитов, первый свободный → ok, иначе none_available) — двух мерок у
    одного признака быть не должно. В подбор идёт ТОЛЬКО исход `ok`: «не проверено»/«срок короче
    минимума»/«сбой» — это не свободная модель, и цену за них не называем.

    Квотируем ПАРАЛЛЕЛЬНО пулом с общим дедлайном: не успевшая модель просто не попала в подбор
    (ответ клиенту не срывается) — тот же класс страховки, что у прайс-сетки."""
    if allow is None:
        try:
            allow = park_allowlist(getter)
        except Exception:                          # парк недоступен → подбора нет (прежний путь)
            allow = None
    cands = class_candidates(asked, allow, heavy_ok=heavy_ok, cheaper_ok=cheaper_ok)
    products = [(label, m, nf) for m in cands
                for label, nf in _model_products_for_quote(m, want_old_gen=want_old_gen)]
    if not products:
        return [], []
    import concurrent.futures as _cf
    t0 = time.time()
    ex = _cf.ThreadPoolExecutor(max_workers=max(1, _CLASS_OFFER_WORKERS))
    res = {}
    try:
        futs = {i: ex.submit(_resolve_model_price, m, ds, de, hint_days, monthly, getter, nf)
                for i, (_label, m, nf) in enumerate(products)}
        deadline = t0 + _CLASS_OFFER_DEADLINE
        for i, fut in futs.items():
            try:
                res[i] = fut.result(timeout=max(0.0, deadline - time.time()))
            except Exception:
                res[i] = None
                log.info(f"CLASS-OFFER: {products[i][0]} не уложилась в дедлайн "
                         f"{_CLASS_OFFER_DEADLINE}с или упала — в подбор не идёт")
    finally:
        ex.shutdown(wait=False, cancel_futures=True)
    free, skipped = [], []
    for i, (label, _m, _nf) in enumerate(products):
        got = res.get(i)
        if not isinstance(got, tuple):
            skipped.append({"model": label, "reason": "error"})
            continue
        kind, phrase, q = got
        if kind == "ok":
            free.append((label, phrase, q))
        else:
            skipped.append({"model": label, "reason": kind})
    log.info(f"CLASS-OFFER: спрошено «{asked}» → кандидатов {len(products)}, свободных {len(free)}, "
             f"отсеяно {len(skipped)} за {time.time() - t0:.1f}с")
    return free, skipped


def _ru_models_word(n) -> str:
    """«модель / модели / моделей» по числу (11-14 — исключение из правила единиц)."""
    n = abs(int(n))
    if n % 100 in (11, 12, 13, 14):
        return "моделей"
    last = n % 10
    if last == 1:
        return "модель"
    if last in (2, 3, 4):
        return "модели"
    return "моделей"


def _class_offer_tail(n, lang="ru") -> str:
    """Хвост «список не влез»: сколько ещё свободно + просьба назвать класс. Правило владельца —
    молча потерянная модель хуже длинного списка, поэтому обрезка ВСЕГДА объявлена числом."""
    if lang == "en":
        return (f"{n} more models are free for these dates — tell me which class you are interested "
                f"in (scooters, maxi-scooters, motorcycles) and I will send their prices.")
    return (f"Свободно ещё {n} {_ru_models_word(n)} на эти даты — скажите, какой класс интересует "
            f"(скутеры, макси-скутеры, мотоциклы), и пришлю по ним цены.")


def _class_offer_block(primary, alt_lines, lang="ru", msg_max=None):
    """Клиентский блок подбора с потолком сообщения. → (текст, сколько НЕ влезло).

    ОСНОВНОЙ вариант не выбрасывается никогда (даже если один он перерастает потолок — иначе клиент
    остался бы без ответа на свой же вопрос). Не влезшие дополнительные НЕ пропадают молча: их число
    уезжает в хвост вместе с предложением назвать класс. Потолок — техническое ограничение, а не
    правило: правило говорит «предела по числу моделей нет»."""
    cap = int(msg_max or _CLASS_OFFER_MSG_MAX)
    head = [primary] if primary else []
    base = sum(len(x) + 1 for x in head)

    def _fit(reserve):
        used, kept = base, []
        for line in alt_lines:
            if used + len(line) + 1 + reserve > cap:
                break
            kept.append(line)
            used += len(line) + 1
        return kept

    kept = _fit(0)
    if len(kept) < len(alt_lines):                  # что-то не влезло → бронируем место под хвост
        kept = _fit(len(_class_offer_tail(len(alt_lines), lang)) + 1)
    more = len(alt_lines) - len(kept)
    lines = head + kept + ([_class_offer_tail(more, lang)] if more else [])
    return "\n".join(lines), more


def _class_offer_note(busy_primary: bool, lang: str = "ru") -> str:
    """Инструкция ЦЕНА для подбора по классу. Как и точечный quote — МАРКЕРНЫЙ режим: LLM цифр не
    видит вовсе, строки вставляет КОД на место [QUOTE], значит инвариант #92 «строка J дословно»
    держится по построению на КАЖДОЙ строке списка, а не только на основной."""
    common = ("Каноничные строки цен вставит КОД ДОСЛОВНО на место метки [QUOTE]: выведи метку "
              "[QUOTE] ОТДЕЛЬНОЙ строкой там, где в ответе должны стоять варианты. Сам НИКАКИЕ "
              "числа цены/итога/депозита НЕ называй, НЕ пересказывай и НЕ выдумывай (ни из FAQ, ни "
              "ориентиров) — они уже посчитаны и придут кодом. Моделей, которых в блоке НЕТ, не "
              "предлагай и цен по ним не называй. Классом НИЖЕ спрошенного сам ничего не предлагай "
              "— только если клиент сам попросит дешевле или проще.")
    if busy_primary:
        return ("ЦЕНА из Календаря бронирования: ЗАПРОШЕННАЯ МОДЕЛЬ ЗАНЯТА на эти даты (Календарь "
                "вернул «свободных юнитов нет»). Это НЕ отказ и НЕ повод отписаться: скажи коротко "
                "и прямо, что именно её на эти даты предложить не можем, и СРАЗУ дай замену — "
                "модели того же класса или выше, свободные на эти даты, уже посчитаны. " + common +
                " Занятость этой модели ПОСЧИТАНА Календарём, поэтому сказать «на эти даты её нет» "
                "здесь законно: правило наличия запрещает утверждать наличие БЕЗ данных, а данные "
                "тут есть. «Уточню наличие и вернусь» НЕ пиши — замена уже готова.")
    return ("ЦЕНА из Календаря бронирования ПОСЧИТАНА по НЕСКОЛЬКИМ моделям: первой в блоке идёт "
            "та, что спросил клиент — она ОСНОВНОЙ вариант; следом ДОПОЛНИТЕЛЬНО идут модели того "
            "же класса или выше, которые Календарь отдал свободными на эти даты. Перед меткой дай "
            "короткую подводку в духе «Вот что можем предложить на эти даты:». " + common +
            " «Уточню цену и вернусь» НЕ пиши: расчёт уже есть.")


def _class_offer_full_note(label, kind, phrase, q, ds, de, hints, lang="ru", getter=None,
                           passport_dep=False, skip=False):
    """ГОТОВАЯ инструкция ЦЕНА с подбором по классу | None (подбора нет — вызывающий идёт прежним
    путём БАЙТ-В-БАЙТ).

    None возвращается по пяти названным причинам, и каждая — сознательная рамка правки:
      • `skip` — процент от суммы («сколько будет 30 %») и «N юнитов одной модели»: у обоих СВОЙ
        разбор одной котировки, список моделей там не к месту;
      • ручка отката `PRICE_CLASS_OFFER_OFF=1`;
      • исход котировки не `ok`/`none` — «срок короче минимума», sanity-гард и сбой источника
        остаются прежними ответами (подбор не лечит несходящийся расчёт);
      • класса спрошенной модели нет в снимке парка — «выше» тогда не определено;
      • свободных того же класса или выше НЕТ ВОВСЕ. Тогда бот НЕ скатывается классом ниже сам:
        занятая модель честно уходит в прежний отказ, а свободная остаётся одна собой."""
    if skip or _CLASS_OFFER_OFF:
        return None
    if kind not in ("ok", "none"):
        return None
    if _class_rank(label) is None:
        return None
    free, skipped = class_offer_status(
        label, ds, de, hint_days=hints.get("hint_days"), monthly=hints.get("monthly"),
        getter=getter, heavy_ok=bool(hints.get("heavy_ok")),
        cheaper_ok=bool(hints.get("cheaper_ok")), want_old_gen=bool(hints.get("old_gen_q")))
    if not free:
        log.info(f"CLASS-OFFER: «{label}» — свободных того же класса или выше нет "
                 f"(отсеяно {len(skipped)}); классом НИЖЕ сами не предлагаем — путь прежний")
        return None
    alt_lines = []
    for alt_label, alt_phrase, alt_q in free:
        if passport_dep:
            alt_phrase = _deposit_as_passport(alt_phrase, lang)
        alt_lines.append(f"{alt_label} — {_scrub_gen_year(_quote_j_line(alt_q, alt_phrase, passport_dep))}.")
    primary = None
    if kind == "ok":
        qphrase = _scrub_gen_year(_quote_j_line(q, phrase, passport_dep))
        primary = (f"{label} — {qphrase}." if label else qphrase.rstrip(".") + ".")
    block, more = _class_offer_block(primary, alt_lines, lang)
    if more:
        log.info(f"CLASS-OFFER: в сообщение не влезло {more} модел. — их число ушло клиенту "
                 f"строкой с предложением назвать класс (молча НЕ обрезаем)")
    return (_class_offer_note(primary is None, lang)
            + "\n" + _QUOTE_OPEN + "\n" + block + "\n" + _QUOTE_CLOSE)


def _sheet_total_cell(q):
    """Сумма аренды из quote ('4928 ฿') или None (нет цифры — не выдумываем)."""
    if not isinstance(q, dict):
        return None
    t = q.get("total")
    return f"{t} ฿" if t is not None else None


def _sheet_month_cell(q, lang="ru"):
    """Месячная ячейка с КАПОМ низкого сезона — предикат РОВНО как в _client_price (общий
    _cap_applies → «от <cap> ฿»); иначе сумма месяца."""
    if not isinstance(q, dict):
        return None
    if _cap_applies(q):
        cap_price = q.get("cap_price")
        return (f"from {cap_price} ฿" if lang == "en" else f"от {cap_price} ฿")
    total = q.get("total")
    return f"{total} ฿" if total is not None else None


def _sheet_deposit(cells):
    for key in ("day", "week", "month"):
        q = cells.get(key)
        if isinstance(q, dict) and q.get("deposit") is not None:
            return q["deposit"]
    return None


def _iso_to_human(ds):
    try:
        d = datetime.date.fromisoformat(ds)
        return f"{d.day:02d}.{d.month:02d}.{d.year}"
    except Exception:
        return ds or ""


def _sheet_min_term_line(lang="ru") -> str:
    """Строка минимального срока из РЕАЛЬНОГО источника (SCOOTER_MIN_DAYS/MOTO_MIN_DAYS —
    правила цен v2, п.2), не литералы-цифры. Явно: колонка «1 день» — суточный ТАРИФ, а не
    право взять байк на одни сутки (ниже мин-срока не оформляем)."""
    if lang == "en":
        return (f"Minimum rental: scooters from {SCOOTER_MIN_DAYS} days, "
                f"motorcycles from {MOTO_MIN_DAYS} (the «1 day» column is the daily tariff, "
                "not a one-day rental).")
    return (f"Минимальный срок: скутеры от {SCOOTER_MIN_DAYS} дней, "
            f"мотоциклы от {MOTO_MIN_DAYS} (колонка «1 день» — суточный тариф, а не аренда на один день).")


def _sheet_low_season(rows) -> bool:
    """Низкий сезон ПО ЖИВОМУ quote (а не по прибитой дате): хоть по одной модели активен кап
    (cap_active) ИЛИ Bridge вернул season со словом low/низк. Капы существуют ТОЛЬКО в низкий
    сезон (см. _sheet_month_cell / _client_price) → активный кап = низкий сезон."""
    for r in rows:
        for q in (r.get("cells") or {}).values():
            if not isinstance(q, dict):
                continue
            if q.get("cap_active"):
                return True
            s = q.get("season")
            if isinstance(s, str) and ("low" in s.lower() or "низ" in s.lower()):
                return True
    return False


# Конец низкого сезона — ДОКУМЕНТИРОВАННАЯ граница парка (низкий сезон 16 мая–31 окт), не выдумка
# per-quote. САМ ФАКТ низкого сезона выводим из живого quote (cap_active/season, см. _sheet_low_season);
# дату конца берём из этой бизнес-константы (у quote поля конца сезона нет — параллельную дату-логику
# не вводим, только фиксированную границу окна).
_LOW_SEASON_END = {"ru": "31 октября", "en": "31 October"}


def _sheet_season_note(rows, lang="ru"):
    """Сезонная пометка — СЛУЖЕБНАЯ, для МОДЕРАТОРА (шаг 4/7 #253): в квадратных скобках, как
    «[уточнить: …]». В КЛИЕНТСКОЕ тело её больше не кладём (клиент не должен читать «низкий сезон /
    до 31 октября» в ответе). НАЛИЧИЕ низкого сезона — из живого quote (cap_active/season), конец
    сезона — документированная граница парка (_LOW_SEASON_END). Высокий сезон → None (сезон не
    утверждаем)."""
    if not _sheet_low_season(rows):
        return None
    if lang == "en":
        return f"[season: low, prices valid until {_LOW_SEASON_END['en']}]"
    return f"[сезон: низкий, цены действуют до {_LOW_SEASON_END['ru']}]"


def render_price_sheet(rows, ds, lang="ru") -> str:
    """Детерминированный прайс-блок (КОД, не LLM): группы «Скутеры:»/«Мотоциклы:» (по bike_class,
    kind неизвестен → хвост без заголовка), внутри — КАРТОЧКА на каждый байк (формат aae1ed2):
    заголовок модели + строки Сутки/Неделя/Месяц + Депозит (число/паспорт), между карточками
    ПУСТАЯ строка. ПЛОСКИЙ ТЕКСТ БЕЗ markdown-символов (** в Telegram не рендерится — живой
    провал вёрстки 21:36, черновик #276). Числа берём как есть из quote-ячеек (кап уже в месячной,
    «от <cap>»); НЕ пересчитываем. Пустые модели (без единой цифры) пропускаем — не выдумываем.
    → текст или '' (нет цифр)."""
    en = (lang == "en")
    na = "—"
    groups = {"scooter": [], "moto": [], None: []}
    for r in rows:
        cells = r.get("cells") or {}
        d = _sheet_total_cell(cells.get("day"))
        w = _sheet_total_cell(cells.get("week"))
        mo = _sheet_month_cell(cells.get("month"), lang)
        if not (d or w or mo):
            continue
        # Депозит — МИНИМУМ по вариантам (row["deposit"], считается в price_sheet); фолбэк на скан
        # ячеек для совместимости, если строку собрали без него.
        dep = r.get("deposit")
        if dep is None:
            dep = _sheet_deposit(cells)
        card = [r["model"]]
        if en:
            card.append(f"• Daily: {d or na}")
            card.append(f"• Week (7 days): {w or na}")
            card.append(f"• Month: {mo or na}")
            if dep is not None:
                card.append(f"• Deposit: {dep} ฿ / passport")
        else:
            card.append(f"• Сутки: {d or na}")
            card.append(f"• Неделя (7 дней): {w or na}")
            card.append(f"• Месяц: {mo or na}")
            if dep is not None:
                card.append(f"• Депозит: {dep} ฿ / паспорт")
        cls = r.get("class")
        kind = cls[0] if cls else None          # bike_class → (kind, min_days, label); XSR155 —
        if kind not in ("scooter", "moto"):     # kind='scooter' (мин-срок 5д) → группа «Скутеры»
            kind = None                         # неизвестный класс → хвост без заголовка
        groups[kind].append("\n".join(card))
    parts = []
    if groups["scooter"]:
        parts.append(("Scooters:" if en else "Скутеры:") + "\n\n" + "\n\n".join(groups["scooter"]))
    if groups["moto"]:
        parts.append(("Motorcycles:" if en else "Мотоциклы:") + "\n\n" + "\n\n".join(groups["moto"]))
    if groups[None]:
        parts.append("\n\n".join(groups[None]))
    return "\n\n".join(parts)


# --- подвыборка строк сетки: класс + рабочий объём cc, ДЕТЕРМИНИРОВАННО (КОД, не LLM-отбор) --------
# Точка правды — те же rows из price_sheet, что и полная сетка (цифры/формат не трогаем, рендер тот
# же). cc берём из метки модели: 3–4-значное число (150/300/750 …). Двузначные хвосты серии («MT-03»,
# «R7») рабочим объёмом НЕ считаем → cc=None; в подвыборке такую строку НЕ выкидываем (fail-open),
# иначе повторили бы живой провал «XADV 750 потерялся в скутерах 200+».
_MODEL_CC_RE = re.compile(r"\d{3,4}")


def _model_cc(label):
    """Рабочий объём (cc) из метки модели: первое 3–4-значное число. → int|None (не прочли)."""
    m = _MODEL_CC_RE.search(str(label or ""))
    return int(m.group(0)) if m else None


def _cc_in_range(cc, cc_min, cc_max):
    """cc в границах [cc_min, cc_max] (любая граница None = без ограничения). cc не прочли (None) →
    True: класс-совпадающую модель из подвыборки НЕ выбрасываем (анти-drop, XADV терялся у LLM)."""
    if cc is None:
        return True
    if cc_min is not None and cc < cc_min:
        return False
    if cc_max is not None and cc > cc_max:
        return False
    return True


def filter_sheet_rows(rows, kind=None, cc_min=None, cc_max=None):
    """Детерминированная подвыборка строк сетки (та же точка правды — rows из price_sheet): по классу
    байка (scooter/moto из bike_class) и рабочему объёму (cc из метки). Модели отбирает КОД, НЕ LLM;
    формат/цифры строк не трогаем. kind/границы None = без соответствующего ограничения. cc не
    прочли → строку оставляем (fail-open: «скутеры 200+» обязаны сохранить XADV 750). → list (может
    быть [] — вызывающий решает, что делать с пустой подвыборкой)."""
    out = []
    for r in rows:
        cls = r.get("class")
        rkind = cls[0] if cls else None
        if kind is not None and rkind != kind:
            continue
        if not _cc_in_range(_model_cc(r.get("model")), cc_min, cc_max):
            continue
        out.append(r)
    return out


def filter_rows_by_requested(rows, requested):
    """Гвард-модель (шаг 3/7 #274): строки сетки, соответствующие ЯВНОМУ запросу клиента
    (extract_requested_models) — конкретным моделям/сериям и/или cc-классу. Матч модели — по
    префиксу _bike_key (canon «PCX» накрывает PCX 150/160; «ADV» НЕ ловит XADV — тот с «x»);
    матч класса — по cc из метки (_model_cc). Нечитаемая кубатура (MT-03, R7) классом НЕ
    считается — здесь fail-open вернул бы чужой блок обратно, а цель гварда обратная:
    блоки чужих моделей НЕ включать (по своему canon такая модель матчится как раньше).
    → list (может быть [] — деградацию решает вызывающий)."""
    keys = [k for k in (_bike_key(it.get("canon")) for it in requested or []
                        if it.get("type") == "model") if k]
    bands = [(it["cc_min"], it["cc_max"]) for it in requested or []
             if it.get("type") == "cc_class"
             and it.get("cc_min") is not None and it.get("cc_max") is not None]
    out = []
    for r in rows:
        rkey = _bike_key(r.get("model"))
        cc = _model_cc(r.get("model"))
        if any(rkey.startswith(k) for k in keys) \
                or (cc is not None and any(lo <= cc <= hi for lo, hi in bands)):
            out.append(r)
    return out


# --- Гвард-модель, шаг 4/7 #274: браковка черновика по расхождению «заявленная модель ≠ блок» ----
# Текст черновика ЗАЯВЛЯЕТ модель предметом прайса («дам развёрнуто по Nmax»), а карточки
# прайс-блока — про ЧУЖУЮ (MT-03): черновик врёт о собственном теле. Кто из двух неправ — коду
# не видно (фильтр сетки упустил запрос ИЛИ LLM пообещал не то), чинить нечего — черновик
# бракуется ЦЕЛИКОМ штатным каналом отбраковки-до-модерации (см. врезку в on_client_message:
# причина в лог + видимая заметка в группу, карточки/IPC нет). Заявка ≠ голое упоминание:
# модель и ценовое слово должны стоять в ОДНОМ предложении — «NMAX — отличный выбор!» перед
# полной сеткой черновик не бракует.
_CLAIM_PRICE_CUE_RE = re.compile(
    r"\bпрайс\w*|\bцен\w*|\bстоимост\w*|\bтариф\w*|\bразв[её]рнут\w*|\bподробн\w*|\bрасклад\w*"
    r"|\bprice\w*|\bpricing\b|\brates?\b|\bcost\w*|\bdetail\w*|\bbreakdown\b", re.I)
# Токен модели в тексте ЧЕРНОВИКА — по границам букв (лукэраунды, как у кириллических синонимов):
# ложная заявка бракует ответ клиенту целиком, substring-семантика _MODEL_TOKENS дала бы «adv»
# в английском «advise». Цифры вплотную допустимы («adv350»).
_CLAIM_MODEL_RES = [
    (re.compile(r"(?<![a-zа-яё])" + re.escape(tok) + r"(?![a-zа-яё])"), tok)
    for tok in _MODEL_TOKENS
] + _MODEL_SYNONYM_RES


def _claimed_models(text):
    """Модели, ЗАЯВЛЕННЫЕ текстом черновика как предмет прайса: токен модели и ценовое слово в
    ОДНОМ предложении (_pc_segments). → список canon (как _detect_models), порядок появления;
    более длинная модель поглощает свой префикс (ADV ⊂ ADV350)."""
    found = []
    for seg, _sep in _pc_segments(str(text or "").lower()):
        if not _CLAIM_PRICE_CUE_RE.search(seg):
            continue
        for rx, tok in _CLAIM_MODEL_RES:
            if rx.search(seg):
                canon = tok.upper().replace(" ", "")
                if canon not in found:
                    found.append(canon)
    return [c for c in found if not any(o != c and o.startswith(c) for o in found)]


def _sheet_block_models(block):
    """Метки моделей, чьи КАРТОЧКИ стоят в прайс-блоке (формат render_price_sheet, aae1ed2):
    заголовок карточки — непустая строка НЕ с «•», за которой идёт строка с «•». Групповые шапки
    («Скутеры:»/«Motorcycles:») и хвост мин-срока под правило не подпадают (за ними пусто/текст)."""
    lines = (block or "").split("\n")
    return [ln.strip() for i, ln in enumerate(lines)
            if ln.strip() and not ln.strip().startswith("•")
            and i + 1 < len(lines) and lines[i + 1].strip().startswith("•")]


def model_claim_mismatch(draft, pricing_note):
    """Расхождение «в тексте черновика заявлена модель — в прайс-блоке карточки ЧУЖОЙ» → причина
    браковки (строка) | None (расхождения нет / не sheet-режим / заявки нет). Сверка тем же
    префикс-матчем _bike_key, что filter_rows_by_requested; хотя бы ОДНА заявленная модель в
    блоке есть (полная сетка, каталог) → расхождения нет. Сам КОД-блок и служебные хвосты
    ([собрано: модель …]) из текста-заявки исключены (client_facing_text)."""
    block = _sheet_block_from_note(pricing_note)
    if not block:
        return None
    in_sheet = _sheet_block_models(block)
    if not in_sheet:
        return None
    text = client_facing_text((draft or "").replace(block, ""))
    claimed = _claimed_models(text)
    if not claimed:
        return None
    block_keys = [_bike_key(m) for m in in_sheet]
    if any(bk.startswith(_bike_key(c)) for c in claimed for bk in block_keys):
        return None
    return (f"в тексте заявлено: {', '.join(claimed)}; в прайс-блоке: {', '.join(in_sheet)} — "
            f"карточки чужой модели")


# Сетка = НЕПРИКОСНОВЕННЫЙ блок (класс-фикс вёрстки 21:36, черновик #276: LLM пересобирал
# карточки в однострочники и вставлял сырые ** — markdown в Telegram не рендерится). Блок везём
# ВНУТРИ pricing_note между служебными скобками (транспорт: сигнатуры целы, IPC-перегенерация
# несёт блок автоматически), НО в промпт LLM он НЕ попадает (make_system_prompt вырезает) —
# переписать прайс модели НЕЧЕГО по построению. LLM ставит метку [PRICE_SHEET], финал собирает
# КОД: intro + вывод render_price_sheet ДОСЛОВНО + outro (compose_sheet_draft).
_SHEET_OPEN, _SHEET_CLOSE = "<<<SHEET>>>", "<<<END_SHEET>>>"
_SHEET_BLOCK_RE = re.compile(re.escape(_SHEET_OPEN) + r"\n(.*?)\n" + re.escape(_SHEET_CLOSE), re.S)
# Сезонная СЛУЖЕБНАЯ пометка (шаг 4/7 #253) едет тем же транспортом, что и SHEET-блок — внутри
# служебных скобок pricing_note: в промпт LLM НЕ попадает (make_system_prompt вырезает), в
# клиентское тело НЕ попадает; финал приклеивает её ХВОСТОМ черновика для модератора.
_SEASON_OPEN, _SEASON_CLOSE = "<<<SEASON>>>", "<<<END_SEASON>>>"
_SEASON_BLOCK_RE = re.compile(re.escape(_SEASON_OPEN) + r"\n(.*?)\n" + re.escape(_SEASON_CLOSE), re.S)
_SHEET_MARKER = "[PRICE_SHEET]"
# Метка в ответе LLM: отдельной строкой (\W покрывает скобки/кавычки/пунктуацию вокруг)
# ИЛИ инлайн «[PRICE_SHEET]» — режем по первому попаданию.
_SHEET_MARKER_LINE_RE = re.compile(r"^\W*PRICE[_ ]?SHEET\W*$", re.I | re.M)
_SHEET_MARKER_INLINE_RE = re.compile(r"\[?PRICE[_ ]?SHEET\]?", re.I)

# ТОЧЕЧНЫЙ quote (одна модель+даты) едет тем же транспортом, что SHEET-блок — детерминированная
# строка ЦЕНЫ в служебных скобках pricing_note: в промпт LLM НЕ попадает (make_system_prompt
# вырезает), а в финал её вставляет КОД (compose_quote_draft). С варианта Б развилки #274 режим
# МАРКЕРНЫЙ полностью — как [PRICE_SHEET]: LLM видит только инструкцию «поставь метку [QUOTE]»
# (цифр в промпте нет → парафраза нет), канон вставляется ВСЕГДА (дедуп #365 снят), инвариант #92
# «строка J дословно» держится по построению. Так strategy-перегенерация несёт цену Bridge КОДОМ
# и НЕ зависит от LLM (класс тот же, что у сетки #276).
_QUOTE_OPEN, _QUOTE_CLOSE = "<<<QUOTE>>>", "<<<END_QUOTE>>>"
_QUOTE_BLOCK_RE = re.compile(re.escape(_QUOTE_OPEN) + r"\n(.*?)\n" + re.escape(_QUOTE_CLOSE), re.S)
# Метка [QUOTE] в ответе LLM (точка вставки канона; инструкция велит ставить её ЯВНО): только
# явная скобочная форма, чтобы случайное слово «quote» в тексте её не триггерило.
_QUOTE_MARKER_RE = re.compile(r"\[\s*QUOTE\s*\]", re.I)

# Служебный блок ДОСТАВКИ (шаг 5/7 #12) — ТОТ ЖЕ транспорт, что <<<QUOTE>>>: цену доставки в финал
# вставляет КОД (compose_delivery_draft), из промпта блок ВЫРЕЗАЕТСЯ — LLM цифру доставки НЕ
# генерирует и НЕ правит. Отдельный блок (а НЕ внутри <<<QUOTE>>>), чтобы приклейка строки доставки
# не задваивала строку ЦЕНЫ аренды (у неё своё денежное число — guard compose_quote_draft иначе
# счёл бы весь quote-блок «недонесённым» и повторил бы цену аренды).
_DELIVERY_OPEN, _DELIVERY_CLOSE = "<<<DELIVERY>>>", "<<<END_DELIVERY>>>"
_DELIVERY_BLOCK_RE = re.compile(
    re.escape(_DELIVERY_OPEN) + r"\n(.*?)\n" + re.escape(_DELIVERY_CLOSE), re.S)

# ФОЛБЭК-блок ДОСТАВКИ (дефект #303/1): клиент дал локацию (ссылку/пин), но сопоставить её с зоной
# НЕ удалось (uncertain/[уточнить]) → инструкция LLM «спроси район, вот доступные районы». В отличие
# от <<<DELIVERY>>> этот блок НЕ несёт цену и ВИДЕН LLM (это подсказка «что спросить», не квитанция) —
# make_system_prompt вплетает его текст в Этап 2, а сырые маркеры из промпта вырезает.
_DELIVERY_ASK_OPEN, _DELIVERY_ASK_CLOSE = "<<<DELIVERY_ASK>>>", "<<<END_DELIVERY_ASK>>>"
_DELIVERY_ASK_BLOCK_RE = re.compile(
    re.escape(_DELIVERY_ASK_OPEN) + r"\n(.*?)\n" + re.escape(_DELIVERY_ASK_CLOSE), re.S)


def _sheet_block_from_note(pricing_note):
    """Чистый прайс-блок из служебных скобок pricing_note → текст | None (не sheet-режим /
    старый формат note без скобок — прежний путь)."""
    m = _SHEET_BLOCK_RE.search(pricing_note or "")
    return m.group(1) if m else None


def compose_sheet_draft(llm_text, block, lang="ru"):
    """Детерминированная сборка финального черновика: intro (LLM) + блок ДОСЛОВНО + outro (LLM).
    Метку [PRICE_SHEET] ищем строкой, затем инлайн; НЕТ метки → LLM-текст ОТБРАСЫВАЕМ целиком
    (он мог переписать прайс) и ставим детерминированные intro/outro (fail-safe: сетка дословно
    доходит ВСЕГДА). Пустые intro/outro просто пропускаются."""
    en = (lang == "en")
    t = (llm_text or "").strip()
    m = _SHEET_MARKER_LINE_RE.search(t) or _SHEET_MARKER_INLINE_RE.search(t)
    if m:
        intro, outro = t[:m.start()].strip(), t[m.end():].strip()
    else:
        log.warning("SHEET: LLM не выдал метку [PRICE_SHEET] — интро/концовка детерминированные")
        intro = "Here is our current price list:" if en else "Актуальный прайс по нашему парку:"
        outro = ("Tell me which model you like and your dates — I will check availability."
                 if en else
                 "Подскажите, какая модель вас заинтересовала и на какие даты — проверю наличие.")
    parts = [p for p in (intro, block, outro) if p]
    return "\n\n".join(parts)


def _quote_block_from_note(pricing_note):
    """Детерминированная строка ЦЕНЫ точечного quote (из служебных скобок pricing_note) → текст |
    None (не точечный-quote-режим). Питает compose_quote_draft."""
    m = _QUOTE_BLOCK_RE.search(pricing_note or "")
    return m.group(1) if m else None


def compose_quote_draft(llm_text, block, lang="ru"):
    """Точечный quote-блок Bridge попадает в финал ТОЛЬКО КОДОМ и ВСЕГДА (вариант Б развилки #274):
      • есть метка [QUOTE] → intro (LLM) + блок ДОСЛОВНО + outro (LLM);
      • метки нет → блок хвостом (FAIL-SAFE: канон доходит клиенту ВСЕГДА).
    Дедуп #365 «все денежные числа уже в тексте → не дублируем» СНЯТ решением владельца: он
    пропускал ПАРАФРАЗ с верными цифрами (живой смоук 23.07 — sonnet-5), и канонической строки J
    (#92 «дословно») у клиента не было. В маркерном режиме LLM цифры не видит вовсе → склеивать
    нечего, строки канонические по построению. В отличие от сетки, при отсутствии метки LLM-текст
    НЕ отбрасываем — точечная цена вплетена в живой ответ; отбросить его = потерять весь ответ."""
    t = (llm_text or "").strip()
    b = (block or "").strip()
    if not b:
        return t
    m = _QUOTE_MARKER_RE.search(t)
    if m:
        intro, outro = t[:m.start()].strip(), t[m.end():].strip()
        # LLM продублировал метку → остатки вычищаем (клиент сырую «[QUOTE]» видеть не должен)
        intro = _QUOTE_MARKER_RE.sub("", intro).strip()
        outro = _QUOTE_MARKER_RE.sub("", outro).strip()
        return "\n\n".join(p for p in (intro, b, outro) if p)
    if not t:
        return b
    log.warning("QUOTE: LLM не поставил метку [QUOTE] — строка цены добавлена КОДОМ хвостом")
    return t + "\n\n" + b


def _delivery_block_from_note(pricing_note):
    """Клиентская строка ЦЕНЫ доставки из служебных скобок pricing_note → текст | None (не
    delivery-режим). Питает compose_delivery_draft."""
    m = _DELIVERY_BLOCK_RE.search(pricing_note or "")
    return m.group(1) if m else None


def compose_delivery_draft(llm_text, block, lang="ru", transcript=None):
    """Строку ДОСТАВКИ Bridge в финал доносит КОД и ВСЕГДА (тот же класс, что compose_quote_draft;
    вариант Б развилки #274): цену доставки LLM не видит (блок вырезан из промпта make_system_prompt,
    Этап 2 запрещает называть цифру доставки) → приклеиваем хвостом. Дедуп #365 «число уже в теле →
    не дублируем» СНЯТ: живой смоук 23.07 — LLM угадал 590 ฿ (few-shot FAQ «Найхарн — 590 бат»),
    дедуп склейку пропустил, канонической строки доставки у клиента не было. ЕДИНСТВЕННЫЙ легитимный
    пропуск — transcript: тариф, УЖЕ названный клиенту в этом окне и НЕ изменившийся, второй раз НЕ
    повторяем (живой ТЕСТ-10: «Доставка в Банг Тао север — 290 ฿ …» слово-в-слово в каждом ответе —
    живой менеджер уже сказанное не повторяет, docs/sales-method-2026-07-22.md)."""
    t = (llm_text or "").strip()
    b = (block or "").strip()
    if not b:
        return t
    if not t:
        return b
    want = {f["value"] for f in extract_money_figures(b)}
    if want and transcript:
        said = {f["value"] for f in extract_money_figures(_manager_text(transcript))}
        if want <= said:
            log.info("compose_delivery_draft: тариф доставки уже назван в этом окне — не повторяем")
            return t
    return t + "\n\n" + b


def _delivery_client_line(res, lang="ru"):
    """Клиентская строка ДОСТАВКИ из результата резолва (dict resolve_delivery) → текст | None.
    zone → «Доставка в <зона> — N ฿ …» (называем ЗОНУ), out_belt → «Доставка — N ฿ …» (зоны нет);
    uncertain/None/битая цена → None (цифру НЕ выдумываем — уводим в фолбэк-вопрос про район).
    Дефект #303/1: при оплаченной доставке забор байка в конце аренды бесплатный."""
    if not isinstance(res, dict) or res.get("status") not in ("zone", "out_belt"):
        return None
    price = res.get("price")
    if isinstance(price, bool) or not isinstance(price, (int, float)):
        return None
    n = int(price)
    zone = res.get("zone")
    if lang == "en":
        where = f" to {zone}" if zone else ""
        return (f"Delivery{where} — {n} ฿ (with paid delivery, bike pickup at the end of the "
                f"rental is free).")
    where = f" в {zone}" if zone else ""
    return (f"Доставка{where} — {n} ฿ (при оплаченной доставке забор байка в конце аренды "
            f"бесплатный).")


def _delivery_quote_line(text, lang="ru", _resolve=None):
    """Клиентская строка ДОСТАВКИ по maps-ссылке клиента (несёт КОД, не LLM), либо None. Тонкая
    обёртка над резолвером+_delivery_client_line (сохранена для существующих мок-тестов). None →
    ссылки нет ИЛИ доставку не определили (uncertain): район уточнит менеджер, цифру НЕ выдумываем.
    _resolve — инъекция для тестов (по умолчанию delivery.resolve_delivery_from_text; сеть/Bridge)."""
    try:
        res = (_resolve or delivery.resolve_delivery_from_text)(text)
    except Exception as e:
        log.info(f"_delivery_quote_line: резолв упал ({type(e).__name__}) — без строки доставки")
        return None
    return _delivery_client_line(res, lang)


def _resolve_delivery_for_draft(hints, _resolve_coords=None, _resolve_text=None):
    """ЕДИНЫЙ резолв доставки для черновика (независим от ценового исхода). Порядок источников:
    сперва гео-ПИН (готовые координаты hints['geo_pin']), затем maps-ссылка (hints['maps_link']).
    Возвращает dict resolve_delivery (status=zone/out_belt/uncertain), либо None — клиент НЕ давал ни
    пина, ни ссылки (доставку не трогаем: обычный путь Этапа 2). Инъекции для тестов; не роняет код."""
    if not isinstance(hints, dict):
        return None
    pin = hints.get("geo_pin")
    if pin:
        try:
            res = (_resolve_coords or delivery.resolve_delivery_from_coords)(pin[0], pin[1])
        except Exception as e:
            log.info(f"_resolve_delivery_for_draft: пин упал ({type(e).__name__})")
            res = None
        if isinstance(res, dict):
            # Трассировка (родитель ТЕСТ-4: пин на Пхукете → 1490 out_belt): координаты пина +
            # исход резолва (зона/дистанция/пояс) в лог — чтобы «зона не та» была диагностируема
            # (out_belt = точка ВНЕ радиуса всех зон, но в поясе +5 км; это НЕ баг парсинга).
            log.info("DELIVERY пин %s → status=%s zone=%s price=%s dist=%s",
                     pin, res.get("status"), res.get("zone"), res.get("price"), res.get("distance_km"))
            return res
    text = hints.get("maps_link")
    if text:
        try:
            res = (_resolve_text or delivery.resolve_delivery_from_text)(text)
        except Exception as e:
            log.info(f"_resolve_delivery_for_draft: ссылка упала ({type(e).__name__})")
            res = None
        if isinstance(res, dict):
            return res
    return None


def _delivery_zone_names(_zones=None):
    """Имена зон доставки из Bridge (для фолбэк-перечня районов) → list[str] (может быть пустым).
    Не роняет вызывающий код: Bridge недоступен / мусор → []."""
    try:
        zones = _zones if _zones is not None else delivery.get_delivery_zones()
    except Exception:
        zones = None
    names = []
    for z in (zones or []):
        try:
            nm = delivery._zone_as_dict(z).get("name")
        except Exception:
            nm = None
        if nm:
            names.append(str(nm))
    return names


def _delivery_ask_block(lang="ru", _zones=None):
    """ФОЛБЭК-блок <<<DELIVERY_ASK>>>: клиент дал локацию, но зону НЕ определили — инструкция LLM
    спросить РАЙОН доставки, перечислив доступные районы (имена зон Bridge). Зоны недоступны → без
    списка (общий вопрос про район). Блок ВИДЕН LLM (это «что спросить», не цена)."""
    names = _delivery_zone_names(_zones)
    if lang == "en":
        body = ("DELIVERY (location not matched to a zone): the client shared a location, but we "
                "could NOT map it to a delivery zone — ask which district the delivery is for")
        if names:
            body += " (our districts: " + ", ".join(names) + ")"
        body += "; do NOT name any delivery price until the district is clear."
    else:
        body = ("ДОСТАВКА (локацию с зоной не сопоставили): клиент дал локацию, но сопоставить её с "
                "зоной доставки НЕ удалось — спроси у клиента, в какой РАЙОН нужна доставка")
        if names:
            body += " (наши районы: " + ", ".join(names) + ")"
        body += "; цену доставки НЕ называй, пока район не ясен."
    return "\n" + _DELIVERY_ASK_OPEN + "\n" + body + "\n" + _DELIVERY_ASK_CLOSE


def _delivery_note_block(hints, lang="ru", _resolve=None, _zones=None):
    """Секция ДОСТАВКИ для pricing_note (единая точка, НЕзависимая от ценового исхода — дефект
    #303/1). По локации клиента (пин ИЛИ maps-ссылка):
      • zone/out_belt → служебный <<<DELIVERY>>>-блок с клиентской строкой (цену доносит КОД через
        compose_delivery_draft; make_system_prompt по наличию блока НЕ велит спрашивать район);
      • uncertain (точку дали, но зону не свели) → <<<DELIVERY_ASK>>>-блок с перечнем районов
        (фолбэк-вопрос: район уточняем, цену не выдумываем);
      • ни пина, ни ссылки → '' (доставку не трогаем — обычный путь Этапа 2).
    _resolve/_zones — инъекция для тестов."""
    res = _resolve_delivery_for_draft(hints) if _resolve is None else _resolve(hints)
    if res is None:
        return ""                                    # ни пина, ни ссылки — доставку не трогаем
    line = _delivery_client_line(res, lang)
    if line:
        return "\n" + _DELIVERY_OPEN + "\n" + line + "\n" + _DELIVERY_CLOSE
    return _delivery_ask_block(lang, _zones=_zones)  # uncertain → фолбэк-вопрос с перечнем районов


def _wrap_price_sheet(body, ds, lang="ru", default_anchor=False) -> str:
    """Обёртка pricing_note: инструкция LLM (вступление + метка [PRICE_SHEET] + концовка, БЕЗ цен —
    сетку вставит КОД дословно) + сам блок в служебных скобках (для compose_sheet_draft; в промпт
    не попадает). default_anchor — дат клиент НЕ назвал: якорь = ближайшая дата (завтра); даты НЕ
    переспрашиваем (сетка готова)."""
    human = _iso_to_human(ds)
    if lang == "en":
        anchor = (f"Dates not specified — the price is calculated from the nearest date ({human}, "
                  "starting tomorrow); if the client names exact dates you will recalculate. Do NOT "
                  "ask for dates — the price list is already prepared."
                  if default_anchor else f"Reference start date: {human}.")
        instr = (
            "PARK PRICE LIST from the Calendar is READY — the CODE will insert it VERBATIM in place "
            "of your [PRICE_SHEET] marker; you must NOT rewrite, reformat or repeat it. Build your "
            "reply as: (1) a short intro (1–2 sentences, NO prices, NO model lists); (2) the marker "
            "[PRICE_SHEET] on its OWN line; (3) a short outro (one sentence: offer to check "
            "availability for the client's dates/model). Do not write any price or deposit numbers "
            "anywhere — they are already in the list. " + anchor)
    else:
        anchor = (f"Даты аренды клиент не назвал — прайс посчитан от ближайшей даты ({human}, старт "
                  "завтра); назовёт точные даты — пересчитаешь. НЕ переспрашивай даты: сетка уже готова."
                  if default_anchor else f"Дата отсчёта: {human}.")
        instr = (
            "ПРАЙС ПО ПАРКУ из Календаря ГОТОВ — его вставит КОД ДОСЛОВНО на место твоей метки "
            "[PRICE_SHEET]; переписывать, переформатировать или повторять прайс НЕЛЬЗЯ. Построй "
            "ответ так: (1) короткое вступление (1–2 предложения, БЕЗ цен и БЕЗ перечисления "
            "моделей); (2) ОТДЕЛЬНОЙ строкой ровно метка [PRICE_SHEET] — на её месте появится "
            "прайс; (3) короткая концовка (одно предложение: предложи проверить наличие по "
            "модели/датам клиента). Числа цен и депозитов сам НЕ пиши нигде — они уже в прайсе. "
            + anchor)
    return instr + "\n" + _SHEET_OPEN + "\n" + body + "\n" + _SHEET_CLOSE


# Прайс запрошен, даты есть, но живой источник не отдал ни одной цифры → честный фолбэк БЕЗ чисел
# и БЕЗ переспроса модели (не выдумываем и не зацикливаемся).
_PRICE_SHEET_UNAVAILABLE = (
    "ПРАЙС ПО ПАРКУ: точные цены из Календаря сейчас недоступны. НЕ называй никаких чисел (в т.ч. "
    "из FAQ) и НЕ переспрашивай модель/опыт; ответь, что соберёшь актуальный прайс по паркам на эти "
    "даты и вернёшься в ближайшее время.")


# ------------------- ДЛИННАЯ АРЕНДА: третий исход «зову человека» (правило владельца) -------------------
# ТРЕТИЙ ИСХОД, А НЕ МОЛЧАНИЕ. Правило запрещает и число, и немоту одинаково, поэтому записка
# требует ПРОИЗНЕСТИ вслух: срок сдаём, но считается отдельно, цену согласует человек. Ни одной
# ЦИФРЫ в тексте нет намеренно: белый список пост-чека строится из ЛЮБЫХ чисел ценовой записки
# (_pc_wl_price_numbers), и граничный «180» стал бы разрешённой к произнесению ценой.
_LONG_TERM_NOTE_RU = (
    "ДЛИННАЯ АРЕНДА: клиент просит срок от полугода. Цену НЕ называй ВООБЩЕ — ни за сутки, ни за "
    "неделю, ни за месяц, ни за весь срок, ни по одной модели, ни списком/прайсом по парку, ни "
    "«от … ฿», ни диапазоном, ни ориентиром, ни из FAQ. Величину скидки тоже НЕ называй: ни в "
    "процентах, ни в батах, ни словами вроде «отличная скидка выйдет» — её размер не фиксирован "
    "и правилом не является. МОЛЧАТЬ ТОЖЕ НЕЛЬЗЯ, ответ обязан прозвучать: скажи прямо, что такой "
    "срок мы сдаём, но считается он ОТДЕЛЬНО и цену на него согласует менеджер; скажи, что "
    "обсудить нужно две вещи — сам период и размер скидки; скажи, что передаёшь вопрос коллеге "
    "и он вернётся с условиями. Модель, даты и пожелания уточнить можно — цену нет. Отдельной "
    "строкой в конце поставь пометку менеджеру: «[уточнить: цена на длинный срок — согласует "
    "человек]».")
_LONG_TERM_NOTE_EN = (
    "LONG RENTAL: the client asks for six months or more. Do NOT quote ANY price — no daily rate, "
    "no weekly, no monthly, no total, no per-model figure, no fleet price list, no «from …», no "
    "range, no ballpark, nothing from the FAQ. Do NOT name the size of the discount either: "
    "neither in percent nor in baht, nor as «a great discount» — its size is not fixed and is not "
    "a rule. STAYING SILENT IS ALSO FORBIDDEN, you must answer: say plainly that we do rent for "
    "such a term, but it is priced SEPARATELY and a manager agrees the price; say the two things "
    "to discuss are the period itself and the size of the discount; say you are passing the "
    "question to a colleague who will come back with the terms. You may clarify the model, the "
    "dates and the client's wishes — but not the price. On a separate final line add the note for "
    "the manager: «[to check: long-term price — agreed by a human]».")


def _long_term_note(lang="ru") -> str:
    """Ценовая записка для срока от полугода: НИ ОДНОГО числа + прямое требование позвать человека."""
    return _LONG_TERM_NOTE_EN if lang == "en" else _LONG_TERM_NOTE_RU


# ------------------- ГЕЙТ ДАТ В ЦЕНОВОМ ПУТИ (прошедший старт / сегодня-завтра) -------------------
# Инструкции LLM БЕЗ ЕДИНОГО ЧИСЛА ЦЕНЫ: на прошедшем старте цену не называем вообще (пост-чек
# черновика строит белый список цен из pricing_note — здесь он пуст, значит ЛЮБОЕ число из ответа
# LLM будет заклеймлено). Текст RU/EN, тайского нет.
_MONTHS_GEN_RU = ("января", "февраля", "марта", "апреля", "мая", "июня",
                  "июля", "августа", "сентября", "октября", "ноября", "декабря")
_MONTHS_NOM_RU = ("январь", "февраль", "март", "апрель", "май", "июнь",
                  "июль", "август", "сентябрь", "октябрь", "ноябрь", "декабрь")
_MONTHS_EN = ("January", "February", "March", "April", "May", "June",
              "July", "August", "September", "October", "November", "December")


def _human_day(d, lang="ru") -> str:
    """Дата словами клиента: «20 июля» / «20 July» (без года — год в переспросе только запутает)."""
    if d is None:
        return ""
    return f"{d.day} {_MONTHS_EN[d.month - 1]}" if lang == "en" else f"{d.day} {_MONTHS_GEN_RU[d.month - 1]}"


def _next_month_name(today, lang="ru") -> str:
    """Название СЛЕДУЮЩЕГО месяца («август» / «August») — подсказка-вариант в переспросе дат."""
    idx = today.month % 12
    return _MONTHS_EN[idx] if lang == "en" else _MONTHS_NOM_RU[idx]


def _past_start_note(seen, today, lang="ru") -> str:
    """ЦЕНА-инструкция на ПРОШЕДШЕМ старте: НИКАКОЙ цены, вежливый переспрос дат + дословный пример."""
    seen_h, today_h = _human_day(seen, lang), _human_day(today, lang)
    nxt = _next_month_name(today, lang)
    if lang == "en":
        return ("PRICE: the rental start the client named is IN THE PAST — {seen} (today is {today}, "
                "Phuket time). Do NOT calculate and do NOT name ANY price (no exact figure, no "
                "estimate, no «from X ฿», no range, nothing from the FAQ), and do NOT silently move "
                "these dates to another year — first ask the client. Politely ask to confirm the "
                "dates, for example: «Could you confirm the dates, please — {seen} has already "
                "passed. Did you mean the coming days, or {nxt}?» We name the price right after the "
                "client confirms the dates.").format(seen=seen_h, today=today_h, nxt=nxt)
    return ("ЦЕНА: старт аренды, который назвал клиент, УЖЕ ПРОШЁЛ — {seen} (сегодня {today}, время "
            "Пхукета). НЕ считай и НЕ называй НИКАКУЮ цену (ни точную, ни ориентир, ни «от X ฿», ни "
            "диапазон, ни из FAQ) и НЕ переноси эти даты на другой год молча — сначала спроси "
            "клиента. Вежливо уточни даты, например: «Уточните, пожалуйста, даты — {seen} уже "
            "прошло. Вы имели в виду ближайшие дни или {nxt}?» Цену назовём сразу после того, как "
            "клиент подтвердит даты.").format(seen=seen_h, today=today_h, nxt=nxt)


def _pickup_time_note(status, seen, lang="ru") -> str:
    """Старт СЕГОДНЯ/ЗАВТРА: котируем штатно, но ОБЯЗАТЕЛЬНО уточняем ВРЕМЯ подачи."""
    if status not in ("today", "tomorrow"):
        return ""
    day_h = _human_day(seen, lang)
    if lang == "en":
        word = "today" if status == "today" else "tomorrow"
        return (" PICK-UP TIME: the rental starts {word} ({day}) — after the price, ask in ONE short "
                "question what time the client wants the bike delivered/picked up (do not add any "
                "numbers of your own).").format(word=word, day=day_h)
    word = "СЕГОДНЯ" if status == "today" else "ЗАВТРА"
    return (" ВРЕМЯ ПОДАЧИ: старт аренды {word} ({day}) — назвав цену, ОДНИМ коротким вопросом уточни "
            "удобное ВРЕМЯ подачи байка (своих чисел не добавляй).").format(word=word, day=day_h)


def _past_start_sheet_note(seen, today, lang="ru") -> str:
    """Тот же гейт для ПРАЙСА ПО ПАРКУ: сетку НЕ блокируем (решение владельца «даты не гейт», анти-луп),
    но считаем её от ближайшей даты, а не от прошедшей, и просим уточнить даты в концовке."""
    seen_h, today_h = _human_day(seen, lang), _human_day(today, lang)
    nxt = _next_month_name(today, lang)
    if lang == "en":
        return ("\nDATES: the start the client named has already passed ({seen}, today is {today}, "
                "Phuket) — the list above is calculated from the nearest date, NOT from those dates. "
                "In the outro ask to confirm the dates («{seen} has already passed — did you mean the "
                "coming days, or {nxt}?»); add no numbers of your own.").format(
                    seen=seen_h, today=today_h, nxt=nxt)
    return ("\nДАТЫ: названный клиентом старт уже прошёл ({seen}, сегодня {today}, Пхукет) — прайс "
            "выше посчитан от ближайшей даты, а НЕ по этим датам. В концовке попроси уточнить даты "
            "(«{seen} уже прошло — вы имели в виду ближайшие дни или {nxt}?»); своих чисел не "
            "добавляй.").format(seen=seen_h, today=today_h, nxt=nxt)


def _gate_start_date(hints, today=None):
    """Статус старта + дата в прочтении клиента → (status, seen_date). Готовый date_status из
    extract_booking_hints имеет приоритет (он посчитан на ТЕКСТЕ реплики — там виден явный год);
    hints, собранные вызывающим вручную, доводим по iso_start (fail-safe, без текста)."""
    hints = hints or {}
    today = today or today_phuket()
    seen = _iso_date(hints.get("start_seen")) or _nearest_start(hints.get("iso_start"), today)
    status = hints.get("date_status") or start_date_status(hints.get("iso_start"), today)
    return status, seen


def build_price_sheet_note(hints, lang="ru", getter=None, today=None, _gate=None):
    """Прайс-блок для промпта, если клиент просит прайс по парку. → строка ИЛИ None (интент не тот).
    None → обычный ценовой путь build_pricing_note. ДАТЫ НЕ ГЕЙТ (решение владельца): нет дат в
    диалоге → якорь = завтра (ближайшая дата старта), сетку считаем и выдаём САМИ, не переспрашивая.
    Даты в диалоге → считаем по ним. today инъектируется в тестах (боевой путь — реальная дата)."""
    if not hints.get("price_sheet_q"):
        return None
    base = today or today_phuket()
    ds = hints.get("iso_start")
    default_anchor = False
    # ГЕЙТ ДАТ (прайс-ветка): старт клиента уже ПРОШЁЛ → сетку НЕ блокируем (владелец: «даты не
    # гейт», анти-луп), но и по прошедшим/заролленным на год датам её НЕ считаем — падаем на
    # ближайший якорь и просим уточнить даты в концовке (см. _past_start_sheet_note ниже).
    past_seen = None
    if ds:
        _st, _seen = _gate_start_date(hints, base)
        if _st == "past":
            past_seen, ds = _seen, None
    if not ds:
        # НЕ спрашиваем даты: дефолтное окно от ближайшей даты (старт = завтра).
        ds = (base + datetime.timedelta(days=1)).isoformat()
        default_anchor = True
    rows = price_sheet(ds, getter=getter, _gate=_gate)
    # Подвыборка («скутеры 200+», «мотоциклы до 400») — КОД по данным сетки, не LLM-отбор. Пустая
    # подвыборка (ничего не совпало) → показываем ПОЛНУЮ сетку, не немеем и не выдумываем.
    sf = hints.get("sheet_filter")
    if sf:
        sub = filter_sheet_rows(rows, kind=sf.get("kind"),
                                cc_min=sf.get("cc_min"), cc_max=sf.get("cc_max"))
        if sub:
            rows = sub
    # Гвард-модель (шаг 3/7 #274): клиент ЯВНО запросил модели/класс (requested_models из
    # extract_requested_models) → в прайс-блоке ТОЛЬКО они, карточки чужих моделей не включаем.
    # Запроса нет (None) → поведение прежнее. Пустое пересечение (запрошенного в сетке нет) →
    # полная сетка, как у подвыборки выше (не немеем и не выдумываем — владельческое решение).
    req = hints.get("requested_models")
    if req:
        sub = filter_rows_by_requested(rows, req)
        if sub:
            rows = sub
    body = render_price_sheet(rows, ds, lang)
    if not body.strip():
        return _PRICE_SHEET_UNAVAILABLE
    # Детерминированные строки КОДА (не LLM): мин-срок из констант — хвостом ПОД карточками моделей.
    # Числа/формат карточек рендерит render_price_sheet. Сезонность (шаг 4/7 #253) в КЛИЕНТСКОЕ
    # тело больше НЕ кладём — она уходит модератору отдельным служебным каналом (SEASON-скобки ниже).
    block = body + "\n\n" + _sheet_min_term_line(lang)
    note = _wrap_price_sheet(block, ds, lang, default_anchor=default_anchor)
    if past_seen is not None:
        note += _past_start_sheet_note(past_seen, base, lang)
    season = _sheet_season_note(rows, lang)
    if season:
        note += "\n" + _SEASON_OPEN + "\n" + season + "\n" + _SEASON_CLOSE
    return note


def build_pricing_note(hints: dict, lang: str = "ru", getter=None, today=None) -> str:
    """Инструкция по цене для промпта + секция ДОСТАВКИ. ЦЕНОВУЮ часть считает _build_pricing_note_core;
    доставку (пин/ссылка → зона/цена ЛИБО фолбэк-вопрос про район) добавляет _delivery_note_block ОДИН
    раз, НЕзависимо от ценового исхода (дефект #303/1: район не спрашиваем, если зону определили)."""
    note = _build_pricing_note_core(hints, lang=lang, getter=getter, today=today) or ""
    return note + _delivery_note_block(hints, lang)


def _build_pricing_note_core(hints: dict, lang: str = "ru", getter=None, today=None) -> str:
    """Инструкция по цене для промпта. ИНВАРИАНТ: без котировки из Календаря — без числа.
    Правила цен v2: кап низкого сезона (п.1), минимальный срок (п.2), несколько моделей одной
    строкой каждая (п.3), депозит при нескольких байках (п.4), J-текст дословно (п.5).
    Сценарий price_sheet (прайс по всему парку) перехватывается ПЕРВЫМ.
    ДОСТАВКУ здесь НЕ добавляем — её централизованно доклеивает build_pricing_note (обёртка)."""
    # (п.4) депозит при нескольких байках — инструкция дописывается к ЛЮБОМУ исходу цены.
    dep = (" " + DEPOSIT_MULTI_NOTE) if hints.get("deposit_multi_q") else ""
    # «N юнитов одной модели» (пара XMAX): цена/депозит Bridge = ЗА КАЖДЫЙ, общий итог не выдумываем.
    _uc = hints.get("units_count")
    units = _units_count_note(_uc, lang) if (_uc and _uc >= 2) else ""
    # ДЛИННАЯ АРЕНДА — ПЕРВОЙ ВЕТКОЙ, РАНЬШЕ ВСЕХ ЦЕНОВЫХ. Стои́т здесь, а не внутри одной из них,
    # ровно потому, что ценовых веток ТРИ (сетка парка, точечная котировка, подбор по классу) и
    # правило обязано погасить ВСЕ ТРИ ОДИНАКОВО: замок в одной оставил бы две говорящими, и
    # «молчат все строки списка» превратилось бы в «молчит часть». Возврат ДО
    # build_price_sheet_note снимает и маркер [PRICE_SHEET], и маркер [QUOTE] — значит КОД не
    # вставит ни сетку, ни строку J, а ensure_price_figure не найдёт что дописать
    # (computed_price_figures на записке без цифр пуст). Молчания при этом не наступает: записка
    # ТРЕБУЕТ сказать вслух, что срок считается отдельно, и позвать человека.
    if hints.get("long_term"):
        return _long_term_note(lang) + dep
    sheet = build_price_sheet_note(hints, lang=lang, getter=getter, today=today)
    if sheet is not None:
        return sheet + dep
    # ГЕЙТ СТАРТА ДО КОТИРОВКИ (живой дефект ТЕСТ-7 22.07): старт РАНЬШЕ сегодняшнего дня (по
    # Пхукету) → цену НЕ считаем и НЕ называем, вежливо переспрашиваем даты. Стоит ПОСЛЕ прайс-
    # ветки (у неё свой режим: сетка + просьба уточнить) и ДО любого обращения к Календарю.
    _today = today or today_phuket()
    status, seen = _gate_start_date(hints, _today)
    if status == "past" and seen is not None:
        return _past_start_note(seen, _today, lang) + dep
    # Старт сегодня/завтра → котируем штатно, но добавляем уточнение ВРЕМЕНИ подачи (ниже, к
    # ветками с живой ценой).
    pickup = _pickup_time_note(status, seen, lang)
    if not hints.get("has_dates"):
        return ("ЦЕНА: дат аренды в диалоге НЕТ — попроси у клиента даты (начало/конец) и срок. "
                "НЕ называй НИКАКУЮ цену: ни точную, ни ориентир, ни «от X ฿», ни диапазон "
                "(«X–Y ฿»), ни «from X» — вообще никаких чисел цены, в т.ч. из FAQ. "
                "Цену назовём только после дат, из Календаря.") + dep
    ds, de = hints.get("iso_start"), hints.get("iso_end")
    models = hints.get("models") or ([hints["model"]] if hints.get("model") else [])
    if not (models and ds and de):
        # даты есть словами, но модель/полные даты не разобрались → фолбэк БЕЗ числа
        return ("ЦЕНА: не удалось однозначно разобрать модель/даты для Календаря — НЕ называй "
                "никакого числа (в т.ч. из FAQ); уточни модель и точные даты и скажи, что "
                "назовёшь цену по датам.") + dep
    hint_days, monthly = hints.get("hint_days"), hints.get("monthly")

    # ДЕТЕРМИНИРОВАННЫЙ РЕЗОЛВ модели в КОНКРЕТНУЮ модель парка (Лист1/_bike_key, алиасы) ДО quote:
    # специфичная фраза → своя модель (не лупный серийный корень, который матчил бы чужие юниты);
    # неоднозначная серия (в парке и XSR155, и XSR900) → НЕ угадываем и НЕ подставляем чужую
    # карточку, а просим клиента уточнить модель. 'unknown' (парк недоступен/модель вне серии) →
    # оставляем исходный canon (прежний путь, fail-safe).
    # Резолвим ТОЛЬКО серийные корни (XSR/ADV/PCX/CB) — именно они матчат несколько юнитов и рискуют
    # подставить чужую карточку. Конкретные модели (NMAX/MT-03/…) уже однозначны — их не трогаем.
    resolved = []
    for m in models:
        if _bike_key(m) in _MODEL_SERIES:
            st, disp, _key = resolve_park_model(m, getter=getter)
            if st == "ambiguous":
                opts = ", ".join(disp) if isinstance(disp, list) else str(disp)
                return ("ЦЕНА: клиент назвал серию (" + str(m) + "), а в парке несколько вариантов ("
                        + opts + ") с РАЗНОЙ ценой/классом — НЕ называй никакого числа и НЕ выбирай "
                        "модель сам (чужую карточку не подставляй); уточни у клиента, какая именно "
                        "модель нужна, и назови цену уже после уточнения.") + dep
            resolved.append(disp if (st == "ok" and disp) else m)
        else:
            resolved.append(m)
    models = resolved

    # Разворачиваем модели в ПРОДУКТЫ через ЕДИНЫЙ гэттер поколений: XMAX по умолчанию → ТОЛЬКО
    # актуальное поколение (New Gen) одной строкой, без годов; прежнее поколение (старое + New Gen
    # двумя строками) — лишь по явному запросу клиента (old_gen_q, «а старый xmax есть?»). Прочие
    # модели — один продукт как раньше. (label, модель_для_quote, name_filter-по-имени-юнита.)
    want_old_gen = bool(hints.get("old_gen_q"))
    products = [(label, m, nf) for m in models
                for label, nf in _model_products_for_quote(m, want_old_gen=want_old_gen)]

    # Клиент выбрал ПАСПОРТ как депозит (KB: деньги ЛИБО паспорт, не оба): сумму депозита из Bridge в
    # строке цены меняем на «депозит: паспорт» ДО _wrap_single — так и инструкция LLM (тело ответа), и
    # quote-хвост несут паспорт, а не число (иначе тело=«паспорт», хвост=«депозит 3000 ฿» — противоречие).
    passport_dep = bool(hints.get("deposit_passport_q"))

    if len(products) == 1:
        label, m, nf = products[0]
        kind, phrase, q = _resolve_model_price(m, ds, de, hint_days, monthly, getter=getter,
                                               name_filter=nf)
        if passport_dep:
            phrase = _deposit_as_passport(phrase, lang)
        # «сколько будет N%» → процент считаем КОДОМ от суммы ЭТОГО расчёта (шаг 2/7 #253); число
        # ложится в блок ЦЕНА → пройдёт пост-чек. Есть live-quote (ok/min) → считаем; иначе просим
        # уточнить без числа. Процент — прежний фразовый путь (единой клиентской строки ЦЕНЫ нет,
        # сумма вплетена в инструкцию → LLM обязан видеть цифры).
        pct = hints.get("percent_q")
        # Вариант Б развилки #274 (шаг 7): живой точечный quote идёт МАРКЕРНЫМ режимом — как
        # [PRICE_SHEET]: LLM видит только инструкцию «поставь метку [QUOTE]», а цифры (столбец J)
        # живут в служебных скобках и в финал попадают ТОЛЬКО КОДОМ (compose_quote_draft). LLM
        # цифры не видит → не перефразирует; строка J у клиента ДОСЛОВНА по построению (#92).
        marker_mode = (kind == "ok" and not pct)
        # ПОДБОР ПО КЛАССУ (правило владельца 20.08): спрошенная модель идёт ОСНОВНЫМ вариантом,
        # следом — все свободные на эти даты модели того же класса или выше. Занята спрошенная —
        # это больше не отказ, а замена теми же классами. Отдельной карты замен НЕТ и не заводится:
        # её роль исполняет класс. Ветка возвращает готовую note ЦЕЛИКОМ либо None (прежний путь).
        offer = _class_offer_full_note(label, kind, phrase, q, ds, de, hints, lang,
                                       getter=getter, passport_dep=passport_dep,
                                       skip=bool(pct or units))
        if offer is not None:
            return offer + dep + pickup
        note = _quote_marker_note() if marker_mode else _wrap_single(kind, phrase)
        if pct:
            note += _percent_line(pct, q if kind in ("ok", "min") else None)
        note += dep + units + pickup
        # Точечный quote → детерминированную строку ЦЕНЫ кладём в служебные скобки: strategy-
        # перегенерация донесёт цену Bridge КОДОМ (compose_quote_draft в generate/regenerate), не
        # полагаясь на то, что LLM её перепишет. N ЮНИТОВ одной модели — блок несём ТОЖЕ, но с
        # пометкой «цена/депозит ЗА КАЖДЫЙ юнит» (итог за N шт. КОД НЕ суммирует — числа только из
        # Bridge). Процент — единой клиентской строки ЦЕНЫ нет (сумма вплетена в инструкцию), пропуск.
        if marker_mode:
            # В quote-блок кладём ДОСЛОВНУЮ строку столбца J (со «Скидкой за срок N%») БЕЗ пересборки
            # клиентского пути; паспорт/кап-инварианты доезжают через phrase (см. _quote_j_line).
            # Год поколения из сырого имени юнита (J-текст Bridge) в блок не течёт: поколение несёт
            # метка label (New Gen), год выпуска убираем — как в клиентском теле (см. _scrub_gen_year).
            qphrase = _scrub_gen_year(_quote_j_line(q, phrase, passport_dep))
            base = f"{label} — {qphrase}" if label else qphrase.rstrip(".")
            qline = (base + ". " + _units_per_each_line(_uc, lang)) if units else (base + ".")
            note += "\n" + _QUOTE_OPEN + "\n" + qline + "\n" + _QUOTE_CLOSE
        return note

    # (п.3) несколько продуктов (несколько моделей ИЛИ два поколения XMAX) — раздельная цена по
    # каждому, отдельной строкой в одном сообщении.
    bullets = []
    ok_lines = []
    for label, m, nf in products:
        kind, phrase, q = _resolve_model_price(m, ds, de, hint_days, monthly, getter=getter,
                                               name_filter=nf)
        if passport_dep:
            phrase = _deposit_as_passport(phrase, lang)
        bullets.append(f"- {label}: {phrase}")
        if kind == "ok":                    # только строки с ЖИВОЙ ценой Bridge едут в quote-блок
            # тот же транспорт: ДОСЛОВНЫЙ столбец J (со «Скидкой за срок») без пересборки, год не течёт
            ok_lines.append(f"- {label}: {_scrub_gen_year(_quote_j_line(q, phrase, passport_dep))}")
    header = ("ЦЕНЫ ПО МОДЕЛЯМ (клиент запросил несколько / модель с вариантами) — назови КАЖДУЮ "
              "отдельной строкой в ОДНОМ сообщении, цену использовать ДОСЛОВНО (не переформатируй и "
              "НЕ опускай часть про скидку за срок «(Скидка за срок N%, … в день)»), модели/варианты "
              "НЕ смешивай и НЕ суммируй:\n")
    note = header + "\n".join(bullets) + dep + units + pickup
    # N ЮНИТОВ одной модели с вариантами (пара XMAX: два поколения) → живые цены поколений тоже
    # несём в служебный quote-блок для strategy-пути; цена/депозит ЗА КАЖДЫЙ юнит, итог за N шт.
    # КОД НЕ суммирует (units set ТОЛЬКО при ОДНОЙ модели — _units_count даёт None на len(models)≥2).
    if units and ok_lines:
        block = "\n".join(ok_lines) + "\n" + _units_per_each_line(_uc, lang)
        note += "\n" + _QUOTE_OPEN + "\n" + block + "\n" + _QUOTE_CLOSE
    return note


def _pressure_block(pressure) -> str:
    """Блок УРОВНЯ НАПОРА — НА УРОВНЕ базовой установки (высокий приоритет, выше playbook). normal → ''
    (базовое поведение без изменений). Инварианты (цена/депозит/парк/без обмана) НЕ ослабляет — они ниже
    и держатся; firm лишь расширяет допустимый диапазон настойчивости (не агрессии, не лжи)."""
    p = (pressure or "normal").strip().lower()
    if p == "firm":
        return (
            "\n\nУРОВЕНЬ НАСТОЙЧИВОСТИ: FIRM (активные продажи). Веди клиента к следующему шагу "
            "решительнее: ответив на вопрос, делай ЯВНЫЙ призыв к действию — предложи забронировать и "
            "внести предоплату, чтобы зафиксировать байк и даты, назови ближайший конкретный шаг. "
            "Подчёркивай выгоду и что популярные даты/байки быстро разбирают. Оставайся вежливым и "
            "ПРАВДИВЫМ: без агрессии и манипуляций, без выдуманного дефицита и лживых обещаний; "
            "ценовую политику, депозит и парк ниже НЕ нарушай."
        )
    if p == "soft":
        return (
            "\n\nУРОВЕНЬ НАСТОЙЧИВОСТИ: SOFT: максимально мягко, без нажима — информируй и отвечай на "
            "вопрос, инициативу брони оставляй клиенту, призыв к действию только по явному интересу."
        )
    return ""   # normal — базовое поведение без изменений (регресс не трогаем)


# АНТИ-ЛУП: против переспросов уже известного (симптом «лупили какая модель/какой опыт» при
# готовом ответе в диалоге) и против обещаний «пришлю прайс позже» при наличии блока ЦЕНА/ПРАЙС.
ANTI_LOOP_NOTE = (
    "\n\nБЕЗ ПЕРЕСПРОСОВ (СТРОГО): не спрашивай повторно то, что клиент УЖЕ сообщил или что видно "
    "из диалога — даты/период аренды, «нужны все модели / весь прайс», что клиент сам менеджер/агент, "
    "уже названный опыт. Есть в истории — бери оттуда, не переспрашивай. Если ниже передан блок "
    "ЦЕНА/ПРАЙС с цифрами — приведи эти цифры и НЕ обещай «пришлю прайс/цены позже», «подготовлю "
    "отдельно», «вернусь с прайсом»: нужные числа уже здесь, дай их сразу. Если передан блок ПРАЙС "
    "ПО ПАРКУ — вопрос про даты клиенту НЕ задавай: даты лишь уточняют расчёт, но НЕ нужны для "
    "выдачи сетки (она уже посчитана от ближайшей даты)."
)


def make_system_prompt(faq: str, lang: str, is_first_contact: bool = False, pricing_note: str = "",
                       directive: str = "", park_models=None, playbook: str = "", pressure=None,
                       collected=None, ready: bool = False, just=None, vehicle_type: str = "bike",
                       is_partner: bool = False) -> str:
    lang_name = "русском" if lang == "ru" else "английском"
    if is_first_contact:
        greet = (
            "\n\nЭто ПЕРВЫЙ ответ в этом диалоге — НАЧНИ ответ с фирменного приветствия из "
            "FAQ («Здравствуйте! …»), затем переходи к сути."
        )
    else:
        greet = (
            "\n\nЭто ПРОДОЛЖЕНИЕ диалога (клиент уже поздоровался/получил автоприветствие) — "
            "НЕ здоровайся повторно. НЕ начинай ответ с «Здравствуйте/Привет/Приветствую/Добрый "
            "день|утро|вечер/Спасибо, что написали|выбрали нас/Hello/Hi» и подобных зачинов — "
            "сразу отвечай по сути. И НЕ повторяй СОЦ-ДОКАЗАТЕЛЬСТВО (отзывы, рейтинг, «точки на "
            "карте / на Google Maps с отзывами», «N+ довольных клиентов/аренд», ссылки на отзывы) — "
            "оно уместно ТОЛЬКО в первом приветствии; в продолжении диалога его НЕ дублируй, отвечай "
            "лаконично по сути запроса."
        )
    # Живой провал 20:59 (черновик #275): сетка ПРАЙС ПО ПАРКУ дошла до промпта, но policy ниже
    # («СТРОГО»: «Дат нет — сперва спроси даты», цена только из блока «ЦЕНА из Календаря») её не
    # знала — LLM 9/10 следовал политике и переспрашивал даты/опыт, выбрасывая готовую сетку.
    # Класс-фикс У ИСТОЧНИКА конфликта: когда pricing_note — прайс по парку, сама политика говорит
    # «это И ЕСТЬ цена из Календаря — выдай дословно, даты не переспрашивай». Обычный путь (ЦЕНА
    # по датам / нет цены) — прежний текст байт-в-байт.
    # Маркерный sheet-режим (блок в служебных скобках): сетку вставляет КОД, LLM цифры не видит и
    # не пишет — класс «модель прайс не переписывает никогда» гарантирован по построению (живой
    # провал вёрстки 21:36 #276: однострочники + сырые **). Legacy sheet (старая note без скобок,
    # напр. из IPC при перегенерации) — прежняя политика «приведи дословно».
    sheet_block = _sheet_block_from_note(pricing_note)
    sheet_mode = bool(pricing_note) and (sheet_block is not None
                                         or "ПРАЙС ПО ПАРКУ" in pricing_note
                                         or "PARK PRICE LIST" in pricing_note)
    if sheet_block is not None:
        policy = (
            "\n\nЦЕНОВАЯ ПОЛИТИКА (СТРОГО): прайс по всему парку УЖЕ посчитан из Календаря и "
            "будет вставлен КОДОМ ДОСЛОВНО на место метки [PRICE_SHEET] — сам НИКАКИЕ цифры цен "
            "и депозитов НЕ пиши (ни из FAQ, ни ориентиры, ни диапазоны). Твой ответ: короткое "
            "вступление БЕЗ цен и БЕЗ перечисления моделей → ОТДЕЛЬНОЙ строкой ровно [PRICE_SHEET] "
            "→ короткая концовка (предложи проверить наличие). Даты НЕ переспрашивай и НЕ жди их: "
            "сетка посчитана от ближайшей даты, точные даты лишь уточнят расчёт потом. Вопрос об "
            "опыте НЕ заменяет выдачу прайса. Про уменьшение депозита при нескольких байках сам "
            "НЕ предлагай и НЕ обещай; на прямой вопрос клиента ответь ровно «уточню у менеджера»."
        )
    elif sheet_mode:
        policy = (
            "\n\nЦЕНОВАЯ ПОЛИТИКА (СТРОГО): ниже передан ГОТОВЫЙ блок «ПРАЙС ПО ПАРКУ из "
            "Календаря» — это И ЕСТЬ цена из Календаря, уже посчитанная по всему парку. Приведи "
            "его цифры и строки мин-срока/сезона клиенту ДОСЛОВНО В ЭТОМ ЖЕ ответе. Даты НЕ "
            "переспрашивай и НЕ жди их: сетка посчитана от ближайшей даты, точные даты лишь "
            "уточнят расчёт потом. Вопрос об опыте НЕ заменяет выдачу прайса: сперва прайс, "
            "остальное можно уточнить после него. НИКАКИХ других цен (FAQ/ориентиры/диапазоны) "
            "не называй. Про уменьшение депозита при нескольких байках сам НЕ предлагай и НЕ "
            "обещай; на прямой вопрос клиента ответь ровно «уточню у менеджера»."
        )
    elif (_QUOTE_BLOCK_RE.search(pricing_note or "")
          and _QUOTE_MARKER_RE.search(pricing_note or "")):
        # МАРКЕРНЫЙ quote-режим (вариант Б #274): цена по датам УЖЕ посчитана, строку вставит КОД
        # на место [QUOTE] — политика говорит это ЯВНО, иначе generic-ветка ниже («цену называй
        # только из блока ЦЕНА», а цифры-то LLM не видит) толкала бы LLM в отписку «уточню цену
        # и вернусь». Legacy-ноты без метки (IPC до деплоя) идут прежней generic-веткой.
        policy = (
            "\n\nЦЕНОВАЯ ПОЛИТИКА (СТРОГО): цена по датам клиента УЖЕ посчитана Календарём — "
            "КОД вставит каноническую строку цены ДОСЛОВНО на место метки [QUOTE] (поставь её "
            "ОТДЕЛЬНОЙ строкой, см. блок ЦЕНА ниже). Сам НИКАКИЕ числа цены/депозита НЕ называй "
            "(ни из FAQ, ни ориентиры, ни диапазоны) и НЕ пиши «уточню цену/наличие и вернусь» — "
            "цена уже есть и придёт кодом. Про уменьшение депозита при нескольких байках сам НЕ "
            "предлагай и НЕ обещай; на прямой вопрос клиента ответь ровно «уточню у менеджера»."
        )
    else:
        policy = (
            "\n\nЦЕНОВАЯ ПОЛИТИКА (СТРОГО): цену клиенту называй ТОЛЬКО если она передана ниже в "
            "блоке «ЦЕНА из Календаря». Пока такой цены нет (или дат в диалоге нет) — НЕ называй "
            "клиенту НИКАКУЮ цену: ни точную, ни ориентир, ни «от X», ни диапазон, ни «from», ни "
            "ставку из FAQ. Дат нет — сперва спроси даты. Цена недоступна — скажи, что уточнишь "
            "цену по датам и вернёшься, БЕЗ числа. Дневные ставки FAQ — ориентир ДЛЯ МЕНЕДЖЕРА, "
            "не для клиента. Про уменьшение депозита при нескольких байках сам НЕ предлагай и НЕ "
            "обещай; на прямой вопрос клиента ответь ровно «уточню у менеджера»."
        )
    if sheet_block is not None:
        stage1 = ("Этап 1 — ЦЕНА: выведи ОТДЕЛЬНОЙ строкой метку [PRICE_SHEET] — прайс на её "
                  "место вставит код; даты для этого НЕ нужны. ")
    elif sheet_mode:
        stage1 = ("Этап 1 — ЦЕНА: приведи прайс-сетку из блока «ПРАЙС ПО ПАРКУ» ДОСЛОВНО — это "
                  "и есть цена; даты для этого НЕ нужны. ")
    else:
        stage1 = "Этап 1 — ЦЕНА: назови цену по датам из Календаря (если она в блоке ЦЕНА выше). "
    # Этап 2 — ДОСТАВКА (дефект #303/1): если по локации клиента (пин/ссылка) зона и цена доставки
    # УЖЕ определены (служебный <<<DELIVERY>>>-блок ниже) — район НЕ переспрашиваем, цену доносит КОД.
    # Если локацию с зоной свести не удалось (<<<DELIVERY_ASK>>>-блок) — спрашиваем район с перечнем
    # районов (фолбэк). Локации нет вовсе — прежний общий путь «уточни район доставки».
    _dlv_resolved = bool(_DELIVERY_BLOCK_RE.search(pricing_note or ""))
    _dlv_ask_m = _DELIVERY_ASK_BLOCK_RE.search(pricing_note or "")
    if _dlv_resolved:
        # Вариант Б #274: цифру доставки LLM не только НЕ видит (блок вырезан), но и явно НЕ
        # называет сам — живой смоук 23.07: sonnet-5 взял «590 бат» из few-shot FAQ (Найхарн) и
        # вписал в тело; строку с ценой вставляет ТОЛЬКО КОД (compose_delivery_draft).
        stage2 = (
            "Этап 2 — ДОСТАВКА: зона и стоимость доставки УЖЕ определены по локации клиента и "
            "будут добавлены КОДОМ — район у клиента НЕ переспрашивай и перечень районов НЕ давай; "
            "подтверди доставку в его зону БЕЗ ЧИСЕЛ (стоимость доставки сам НЕ называй — ни из "
            "FAQ, ни из примеров: строку доставки с ценой вставит КОД) и добавь, что забор байка "
            "в конце аренды БЕСПЛАТНЫЙ ПРИ ОПЛАЧЕННОЙ доставке (при самовывозе бесплатного забора "
            "НЕ обещай).\n")
    elif _dlv_ask_m:
        stage2 = (
            "Этап 2 — " + _dlv_ask_m.group(1).strip() + " Добавь, что забор байка в конце аренды "
            "БЕСПЛАТНЫЙ ПРИ ОПЛАЧЕННОЙ доставке (при самовывозе бесплатного забора НЕ обещай).\n")
    else:
        stage2 = (
            "Этап 2 — ДОСТАВКА: когда клиент заинтересовался ценой — уточни район доставки и назови "
            "её стоимость по прайсу районов; добавь, что забор байка в конце аренды БЕСПЛАТНЫЙ ПРИ "
            "ОПЛАЧЕННОЙ доставке (если клиент забирает сам/самовывоз — бесплатного забора НЕ обещай).\n")
    scenario = (
        "\n\n[ВНУТРЕННИЙ КОНТЕКСТ — только для тебя, клиенту НЕ показывать; номера этапов и "
        "слова «этап»/«стадия» в самом ответе НЕ упоминать]\n"
        "ПОРЯДОК ДИАЛОГА (СТРОГО по этапам, не забегай вперёд):\n"
        + stage1 +
        "На этом этапе НЕ проси паспорт, апартаменты и шлемы — только цена и наличие.\n"
        + stage2 +
        "Этап 3 — БРОНЬ: только когда клиент готов бронировать — запроси качественное фото "
        "паспорта, название апартаментов (или ссылку Google Maps), количество шлемов и "
        "номер(а) телефона. Раньше этапа 3 документы/апартаменты/шлемы не запрашивай.\n"
        "Это разметка ТВОЕЙ логики: определи текущий этап про себя и действуй по нему — но в "
        "тексте клиенту про этапы/стадии/«менеджер не назвал цену» не пиши, отвечай сразу по сути."
    )
    # Маркерный sheet-режим: сам блок из промпта ВЫРЕЗАЕМ (LLM цифры не видит → переписать
    # нечего); остаётся инструкция + пометка, что сетку вставит код на место [PRICE_SHEET].
    pn_prompt = pricing_note
    if sheet_block is not None:
        pn_prompt = _SHEET_BLOCK_RE.sub(
            "(прайс-сетка уже посчитана — КОД вставит её ДОСЛОВНО на место метки [PRICE_SHEET])",
            pricing_note)
    # Сезонная СЛУЖЕБНАЯ пометка (шаг 4/7 #253) — только для модератора: из промпта LLM её ВЫРЕЗАЕМ,
    # чтобы LLM не выдал «низкий сезон / до 31 октября» в клиентское тело.
    if _SEASON_BLOCK_RE.search(pn_prompt or ""):
        pn_prompt = _SEASON_BLOCK_RE.sub("", pn_prompt).rstrip()
    # Точечный quote-блок — служебный транспорт для compose_quote_draft (цена Bridge вставится КОДОМ):
    # из промпта его ВЫРЕЗАЕМ (сама цена уже есть в инструкции ЦЕНА выше — дубль LLM не нужен).
    if _QUOTE_BLOCK_RE.search(pn_prompt or ""):
        pn_prompt = _QUOTE_BLOCK_RE.sub("", pn_prompt).rstrip()
    # Блок ДОСТАВКИ (шаг 5/7 #12) — служебный транспорт для compose_delivery_draft: из промпта его
    # ВЫРЕЗАЕМ, чтобы LLM цену доставки не видел (не сгенерировал/не переписал); вставит её КОД.
    if _DELIVERY_BLOCK_RE.search(pn_prompt or ""):
        pn_prompt = _DELIVERY_BLOCK_RE.sub("", pn_prompt).rstrip()
    # Фолбэк-блок ДОСТАВКИ (<<<DELIVERY_ASK>>>): его текст УЖЕ вплетён в Этап 2 сценария — сырые
    # маркеры из промпта ВЫРЕЗАЕМ (дубля и утечки «<<<…>>>» клиенту быть не должно).
    if _DELIVERY_ASK_BLOCK_RE.search(pn_prompt or ""):
        pn_prompt = _DELIVERY_ASK_BLOCK_RE.sub("", pn_prompt).rstrip()
    price_block = ("\n\n" + pn_prompt) if pn_prompt else ""
    # СТРАТЕГИЯ-директива менеджера: высший приоритет по СОДЕРЖАНИЮ/логике/тону ответа, НО
    # ценовую политику и критичные факты НЕ отменяет (они ниже — незыблемы).
    directive_block = ""
    if (directive or "").strip():
        directive_block = (
            "\n\n★ ДИРЕКТИВА МЕНЕДЖЕРА (ВЫСШИЙ приоритет по стратегии/логике/тону — строй ответ "
            "именно так): " + directive.strip()
            + "\nВАЖНО: эта директива задаёт ЧТО и КАК предлагать, но НЕ отменяет ценовую политику "
            "и критичные факты ниже — цену клиенту только из блока ЦЕНА, критфакты дословно."
        )
    # ПАРК (Лист1): если allowlist реально получен — ЖЁСТКО ограничиваем модели, что бот называет
    # клиенту. Пусто/None (источник недоступен) → блока нет (FAIL-SAFE, ограничения не применяем).
    park_block = ""
    if park_models:
        park_block = (
            "\n\n★ ПАРК (СТРОГО): предлагай, перечисляй и упоминай клиенту ТОЛЬКО модели реального "
            "парка: " + ", ".join(park_models) + ". Любые ДРУГИЕ модели клиенту НЕ предлагай и НЕ "
            "называй — даже если они есть в справочнике/FAQ ниже или как «замена» (напр. PCX150/160, "
            "ADV150/160, Rebel300, XSR900, R7, CB650R — их НЕТ в парке). Этот список парка приоритетнее "
            "любых списков моделей из справочника."
        )
    # КНИГА ПРАВИЛ (playbook): СТРОГО НИЖЕ кап-цены и CRITICAL_FACTS — соблюдать, но НЕ отменяет их.
    # Пусто → блока нет (FAIL-SAFE, генерация цела).
    playbook_block = ""
    if (playbook or "").strip():
        playbook_block = (
            "\n\nКНИГА ПРАВИЛ (стиль/факты/запреты/выученные правки — СОБЛЮДАЙ; но она НЕ отменяет "
            "ценовую политику и критичные факты ВЫШЕ — те приоритетнее):\n" + playbook.strip()
        )
    # §243/6: СОБРАННОЕ по диалогу/вложениям — «уже получено, не переспрашивай». Пусто → блока нет.
    collected_block = collected_prompt_note(collected, lang) if collected else ""
    # ЗАВЕРШАЮЩИЙ ВОПРОС (живой ТЕСТ-7): ответ обязан двигать клиента ровно на ОДИН следующий шаг.
    # Шаг считаем по недостающему в collected (тот же трекер, что и «не переспрашивай») — значит
    # правило по построению не спорит с фильтром #241 и с гейтом дат.
    next_step_block = next_step_note(collected or {}, lang, sheet_mode=sheet_mode, ready=ready,
                                     just=just)
    # УРОВЕНЬ НАПОРА — на уровне базовой установки (высокий приоритет, ВЫШЕ playbook «без давления»).
    pressure_block = _pressure_block(pressure if pressure is not None else SALES_PRESSURE)
    # ТИП ТС (шаг 2/6 родитель #4; переписан 29.07.2026): дефолт «байк» не хардкодим — тип берём из
    # detectVehicleType по тексту треда. ЗАПРЕТ СЛОВА СНЯТ: прежняя формулировка «слово „байк“ НЕ
    # используй» била ДО генерации по 45 живым БАЙКОВЫМ тредам из 178 (ложный 'car' от подстроки
    # «авто» в «автовокзал»). Теперь блок про ФАКТЫ, а не про словарь, и опирается на бизнес-правило
    # владельца: авто в нашем парке НЕТ, но запросить у партнёров можем — значит отказ клиенту не
    # даём, наличие/модели/цены авто не называем (мы их не знаем), запрос ведём к менеджеру.
    # 'mixed' → словарь не ограничен вовсе; 'unknown' → нейтральное «технику»; 'bike' → блока нет
    # (регресс байт-в-байт). Пометку модератору держит enforce_vehicle_word на финале.
    if vehicle_type == "car":
        vehicle_block = (
            "\n\n★ ТИП ТС (ВЫСШИЙ приоритет — по ФАКТАМ, не по словарю): клиент спрашивает про "
            "АВТО. Отвечай про тот транспорт, о котором спросил клиент; запрета на слово «байк» "
            "нет. Авто в нашем парке НЕТ, но мы можем запросить его у партнёров — поэтому ОТКАЗ "
            "(«у нас нет авто», «мы авто не сдаём») НЕ давай. Наличие, модели, цены и сроки по "
            "авто НЕ называй и НЕ выдумывай — ты их не знаешь. Скажи, что уточним по авто и "
            "вернёмся с вариантами; запрос ведём к менеджеру."
        )
    elif vehicle_type == "mixed":
        vehicle_block = (
            "\n\n★ ТИП ТС: клиент упомянул И авто, И байк. Про байки говори как обычно — словарь "
            "НЕ ограничен. Только по АВТО: наличие, модели и цены НЕ называй и НЕ выдумывай, "
            "отказ НЕ давай — скажи, что уточним и вернёмся с вариантами."
        )
    elif vehicle_type == "unknown":
        vehicle_block = (
            "\n\n★ ТИП ТС: клиент ещё НЕ уточнил, какой транспорт нужен — используй НЕЙТРАЛЬНОЕ "
            "слово «техника»/«технику», не навязывай «байк», пока клиент не назвал тип или модель."
        )
    else:
        vehicle_block = ""   # bike/дефолт — формулировку не меняем (регресс байт-в-байт)
    # ПАРТНЁРСКИЙ ЧАТ (шаг 3/6 родитель #4): собеседник — партнёр, не конечный клиент. Доставку/подачу
    # байка от НАШЕГО лица не подтверждаем и не организуем; про подачу — уточняющий вопрос БЕЗ
    # обязательств. Дефолт False → блока нет (регресс байт-в-байт). Детерминированную страховку на
    # is_partner держит enforce_partner_delivery_guard на финале generate_draft/regenerate_draft.
    if is_partner:
        partner_block = (
            "\n\n★ ПАРТНЁРСКИЙ ЧАТ (ВЫСШИЙ приоритет по формулировке): собеседник — ПАРТНЁР, а НЕ "
            "конечный клиент. Доставку/подачу байка от НАШЕГО лица НЕ подтверждай и НЕ организуй: "
            "слова «подадим», «привезём», «доставим», «во сколько подать» — под запретом. Если речь о "
            "подаче/доставке — задай УТОЧНЯЮЩИЙ вопрос партнёру БЕЗ обязательств с нашей стороны (кто "
            "её организует и во сколько), саму доставку на себя не бери."
        )
    else:
        partner_block = ""   # обычный клиентский чат — формулировку не меняем (регресс байт-в-байт)
    return (
        "Ты — менеджер проката мотобайков TurboBaby (Пхукет). По переписке с клиентом "
        f"составь ОДИН короткий, вежливый ответ на {lang_name} языке (язык клиента). "
        "Отвечай только на то, что ещё НЕ отвечено менеджером в диалоге; не повторяй уже "
        "сказанное; держи контекст сделки, но НИКОГДА не пересказывай его клиенту. Не "
        "выдумывай данные и наличие. Верни ТОЛЬКО текст ответа клиенту — без пояснений, "
        "без кавычек, без префиксов. НЕ начинай ответ с описания ситуации, стадии/этапа "
        "сделки или статуса клиента: никаких «Клиент готов…», «менеджер ещё не назвал "
        "цену», «сейчас Этап N», «Этап 1/2/3», «стадия…» — это ВНУТРЕННИЕ пометки для тебя, "
        "клиент их видеть НЕ должен. Ответ начинай СРАЗУ по сути (первый контакт → "
        "приветствие → суть; иначе → сразу суть)."
        + vehicle_block
        + partner_block
        + pressure_block
        + directive_block + park_block + collected_block + greet + policy + scenario
        + next_step_block + ANTI_LOOP_NOTE + price_block + "\n\n"
        + CRITICAL_FACTS + EXPERIENCE_SAFETY_RULE + APPROVAL_WHITELIST_RULE
        + AVAILABILITY_INVARIANT_RULE + GENERATION_DEFAULT_RULE + PICKUP_RULE + RECEIPT_LEXICON_RULE
        + playbook_block
        + "\n\nFAQ и эталонные формулировки:\n" + (faq or "(FAQ недоступен — опирайся на критичные факты выше)")
        + STYLE_FEWSHOT
    )


def default_llm_caller():
    """Публичный доступ к текущей голове LLM (CLI по подписке Max либо API-ключ) — тем же
    выбором, что generate_draft. Нужен внешним потребителям (напр. гипотезы «🎓 Обучить»
    в тренажёре, процесс модербота), чтобы не дёргать приватные _cli_llm/_default_llm."""
    return _cli_llm if SUGGEST_LLM_VIA_CLI else _default_llm


def _default_llm(system: str, user: str) -> str:
    if not ANTHROPIC_API_KEY:
        raise RuntimeError(
            "ANTHROPIC_API_KEY is not configured; set it in the process environment "
            "or enable SUGGEST_LLM_VIA_CLI=1."
        )
    import anthropic
    c = anthropic.Anthropic(api_key=ANTHROPIC_API_KEY)
    resp = c.messages.create(
        model=ANTHROPIC_MODEL,
        max_tokens=LLM_MAX_TOKENS,
        system=system,
        messages=[{"role": "user", "content": user}],
    )
    return "".join(getattr(b, "text", "") for b in resp.content).strip()


REPO_ENV = os.path.join(BASE_DIR, ".env")   # .env репо по __file__ (НЕ по cwd/окружению)


def _env_file_claude_bin():
    """CLAUDE_BIN, прочитанный ПРЯМО из .env-файла репо (путь по __file__, не из окружения процесса).
    КОРЕНЬ БАГА: userbot запущен в СЕРВИС-контексте (services.exe→…→python) — %APPDATA% указывает на
    systemprofile, load_dotenv не подхватил .env, поэтому ни glob по %APPDATA%, ни env-var CLAUDE_BIN
    не срабатывали → «claude CLI не найден» ТОЛЬКО в бою. Чтение файла напрямую от окружения не зависит.
    Берём ТОЛЬКО строку CLAUDE_BIN (секреты не читаем/не логируем). → путь если существует, иначе ''."""
    try:
        # utf-8-sig: снимает BOM (PowerShell 5.1 `Set-Content -Encoding utf8` пишет его на первой
        # строке — иначе startswith мимо); errors=replace: одинокий не-utf8 байт на ЧУЖОЙ строке
        # не должен уронить парс до строки CLAUDE_BIN. Иначе фикс сервис-контекста тихо ломается.
        with open(REPO_ENV, encoding="utf-8-sig", errors="replace") as f:
            for ln in f:
                s = ln.strip()
                if s.startswith("CLAUDE_BIN=") and not s.startswith("#"):
                    val = s.split("=", 1)[1].strip().strip('"').strip("'")
                    if val and os.path.isabs(val) and os.path.isfile(val):
                        return val
    except Exception:
        pass
    return ""


def _claude_base_dirs():
    """Базовые папки версий claude-code. Включает:
    (1) обычные Roaming\\Claude\\claude-code по всем профилям — НО у Store/MSIX-установки Claude это
        ВИРТУАЛЬНЫЙ редирект (виден только в интерактивной сессии; процессы Планировщика/userbot
        получают FileNotFoundError → «claude CLI не найден в бою»);
    (2) РЕАЛЬНЫЙ путь MSIX-пакета AppData\\Local\\Packages\\Claude_*\\LocalCache\\Roaming\\Claude\\
        claude-code — доступен из ЛЮБОГО контекста (это и есть фикс)."""
    out = []
    up = os.getenv("USERPROFILE")
    home = os.path.expanduser("~")
    local = os.getenv("LOCALAPPDATA") or os.path.join(up or home, "AppData", "Local")
    roots = []
    for r in (os.getenv("APPDATA"),
              (os.path.join(up, "AppData", "Roaming") if up else None),
              os.path.join(home, "AppData", "Roaming")):
        if r and r not in roots:
            roots.append(r)
            out.append(os.path.join(r, "Claude", "claude-code"))
    try:  # реальные MSIX-базы (Claude_<хэш-издателя> — wildcard, чтобы пережить смену пакета)
        for cc in glob.glob(os.path.join(local, "Packages", "Claude_*", "LocalCache",
                                         "Roaming", "Claude", "claude-code")):
            if cc not in out:
                out.append(cc)
    except Exception:
        pass
    return out


# Совместимость: часть кода ссылается на _CLAUDE_BASE (первый корень).
_CLAUDE_BASE = (_claude_base_dirs() or
                [os.path.join(os.path.expanduser("~"), "AppData", "Roaming", "Claude", "claude-code")])[0]


_RE_VER_DIR = re.compile(r"^\d+(?:\.\d+)+$")


def _ver_key(name):
    nums = re.findall(r"\d+", name or "")
    return tuple(int(n) for n in nums) if nums else (0,)


def _pinned_version(path):
    """Версия ВЕРСИОННОЙ установки по пути (…/claude-code/2.1.217/claude.exe → (2,1,217));
    иная схема установки → None (такой пин — осознанный выбор пути, не отставшая версия)."""
    parent = os.path.basename(os.path.dirname(path or ""))
    return _ver_key(parent) if _RE_VER_DIR.match(parent or "") else None


def _newest_versioned():
    """(ключ_версии, путь) новейшей версионной установки по всем базам, или None."""
    try:
        cands = []
        for base in _claude_base_dirs():
            for d in glob.glob(os.path.join(base, "*")):
                exe = os.path.join(d, "claude.exe")
                if os.path.isfile(exe):
                    cands.append((_ver_key(os.path.basename(d)), exe))
        if cands:
            cands.sort()
            return cands[-1]
    except Exception:
        pass
    return None


def _honor_pin(pin, newest):
    """Пин версии — ПОЛ, а не потолок: живой, но ОТСТАВШИЙ от автообновления версионный пин не
    смеет побеждать новейшую установку (живой факт: CLAUDE_BIN=…\\2.1.215 при наличии 2.1.217).
    Не-версионный пин и рубильник CLAUDE_BIN_STRICT=1 уважаем как есть."""
    if (os.getenv("CLAUDE_BIN_STRICT", "") or "").strip() not in ("", "0"):
        return pin
    pv = _pinned_version(pin)
    if pv is None or newest is None or newest[0] <= pv:
        return pin
    return newest[1]


def _resolve_claude_once():
    """Один проход резолва (без ретраев). Порядок: PATH-шим → CLAUDE_BIN из окружения (если жив и
    не отстал) → CLAUDE_BIN ПРЯМО из .env-файла (спасает сервис-контекст) → новейшая версия
    claude-code по ВСЕМ профилям → кандидаты иных схем установки. → путь|None."""
    w = shutil.which("claude")
    if w and os.path.isfile(w):
        return w
    newest = _newest_versioned()                # нужен и сам по себе, и для сверки с пином
    if CLAUDE_BIN and os.path.isabs(CLAUDE_BIN) and os.path.isfile(CLAUDE_BIN):
        return _honor_pin(CLAUDE_BIN, newest)
    envbin = _env_file_claude_bin()             # ← КЛЮЧ: не зависит от %APPDATA%/load_dotenv/cwd
    if envbin:
        return _honor_pin(envbin, newest)
    if newest:
        return newest[1]
    home = os.path.expanduser("~")
    local = os.getenv("LOCALAPPDATA") or os.path.join(home, "AppData", "Local")
    for c in (os.path.join(home, ".local", "bin", "claude.exe"),
              os.path.join(home, ".local", "bin", "claude.cmd"),
              os.path.join(local, "Programs", "claude", "claude.exe")):
        if os.path.isfile(c):
            return c
    return None


def _resolve_claude(retries=1, retry_sleep=2.0):
    """Версионно-независимый резолв claude CLI (порт pc_orchestrator.resolve_claude, коммит 45bdd75 —
    не импортируем pc_orchestrator, чтобы не тянуть его logging.basicConfig/Bridge в userbot).
    НЕ сдаёмся с первой осечки: транзиентный os.path.isfile()==False на 236-МБ claude.exe
    (AV-скан/локация файла — кейс теста 00:33 и задачи #35) не должен убивать черновик — короткий
    ретрай (2 попытки, пауза ~2с). → путь (str) | None (после ретраев — реально нигде нет)."""
    for i in range(retries + 1):
        p = _resolve_claude_once()
        if p:
            return p
        if i < retries:
            log.warning("SUGGEST: claude CLI не найден (проход %s/%s) — транзиент? повтор через %sс",
                        i + 1, retries + 1, retry_sleep)
            time.sleep(retry_sleep)
    return None


_MU_INPUT_FIELDS = ("inputTokens", "cacheReadInputTokens", "cacheCreationInputTokens")


def _mu_input_total(usage) -> int:
    """ПОЛНЫЙ вход головы из записи modelUsage: свежие + прочитанные из кэша + записанные в кэш.
    Считать надо ВСЕ три поля — см. _real_model_from_json."""
    u = usage or {}
    total = 0
    for f in _MU_INPUT_FIELDS:
        try:
            total += int(u.get(f) or 0)
        except (TypeError, ValueError):
            pass
    return total


def _real_model_from_json(data: dict) -> str:
    """Реально отработавшая ГОЛОВА из modelUsage (--output-format json). CLI под капотом дёргает
    служебный haiku-помощник (заголовок сессии и т.п.) — у него всегда крошечный фикс-вход (~505 ткн),
    поэтому реальную голову опознаём по ОБЪЁМУ ВХОДА, а НЕ по outputTokens: при фолбэке основная
    модель может дать МЕНЬШЕ output, чем служебный haiku (замер: sonnet=4 vs haiku=12) — по output лог
    соврал бы про модель.
    ★ ВХОД СЧИТАЕМ ПОЛНОСТЬЮ (замер 23.07.2026, живой claude 2.1.217): с включённым КЭШЕМ ПРОМПТА у
    настоящей головы поле inputTokens почти пустое, а весь system-промпт лежит в cacheRead/
    cacheCreation — живой ответ был {sonnet: input=2, cacheRead=29339, cacheCreation=16329} против
    {haiku: input=551}. Сравнение по ОДНОМУ inputTokens объявляло головой служебный haiku, и лог
    месяцами врал владельцу, что клиентам отвечает haiku, хотя отвечал sonnet. Нет modelUsage → ''."""
    mu = data.get("modelUsage") if isinstance(data, dict) else None
    if not isinstance(mu, dict) or not mu:
        return ""
    try:
        return max(mu.items(), key=lambda kv: _mu_input_total(kv[1]))[0]
    except Exception:
        return ""


def _parse_cli_json(raw: str):
    """Разобрать --output-format json от claude CLI. → (text, real_model). text — поле result (готовый
    ответ клиенту), real_model — реально отработавшая голова (см. _real_model_from_json). Битый JSON или
    is_error → ('', real_model): upstream трактует пустой текст как 'пустой черновик' → пропуск."""
    try:
        data = json.loads(raw or "")
    except Exception:
        return "", ""
    if not isinstance(data, dict):
        return "", ""
    real = _real_model_from_json(data)
    if data.get("is_error"):
        return "", real
    return (data.get("result") or "").strip(), real


def _cli_llm(system: str, user: str) -> str:
    """Генерация через claude CLI по подписке Max (не платный API-ключ → нет 'credit balance too low').
    ЧИСТЫЙ генератор текста, НЕ агент: --allowed-tools '' + нейтральный cwd (НЕ репо) → CLI не читает
    .claude/settings.json+pretool_guard и не дёргает инструменты. ANTHROPIC_API_KEY вычищен из env,
    иначе CLI пошёл бы по платному ключу. Голова: SUGGEST_MODEL с кондуктором-фолбэком SUGGEST_MODEL_FALLBACK
    (--fallback-model — САМ CLI одним вызовом добивает фолбэком, свой ретрай не нужен). --output-format json:
    достаём поле result и реально отработавшую голову (modelUsage) в лог. Таймаут/ошибка → '' (upstream:
    'пустой черновик' → пропуск)."""
    cbin = _resolve_claude()
    if not cbin:
        raise RuntimeError("claude CLI не найден (PATH/CLAUDE_BIN/AppData) — генерация через CLI невозможна")
    env = dict(os.environ)
    env.pop("ANTHROPIC_API_KEY", None)          # ← ключ НЕ утекает: CLI идёт по подписке Max
    env.pop("OPENAI_API_KEY", None)
    cmd = [cbin, "-p", user, "--system-prompt", system, "--model", SUGGEST_MODEL,
           "--output-format", "json", "--allowed-tools", ""]
    if SUGGEST_MODEL_FALLBACK:                   # кондуктор: фолбэк исполняет сам CLI в этом же вызове
        cmd += ["--fallback-model", SUGGEST_MODEL_FALLBACK]
    try:
        p = subprocess.run(
            cmd,
            cwd=tempfile.gettempdir(),          # нейтральный cwd: без settings.json/pretool_guard репо
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            env=env, timeout=CLI_TIMEOUT,
        )
    except subprocess.TimeoutExpired:
        log.warning("SUGGEST: claude CLI таймаут %sс — пустой черновик", CLI_TIMEOUT)
        return ""
    if p.returncode != 0:
        log.warning("SUGGEST: claude CLI rc=%s — %s", p.returncode, (p.stderr or "").strip()[-300:])
        return ""
    text, real = _parse_cli_json(p.stdout or "")
    log.info("SUGGEST: голова=%s (просили %s, фолбэк %s)",
             real or "?", SUGGEST_MODEL, SUGGEST_MODEL_FALLBACK or "—")
    return text


# --- защита от утечки служебного контекста в тело черновика -------------------
# LLM иногда предваряет ответ ВНУТРЕННЕЙ пометкой о стадии сделки («Клиент готов…,
# менеджер ещё не назвал цену — сейчас Этап 1»). Промпт это запрещает (см.
# make_system_prompt), но как дешёвая страховка срезаем ВЕДУЩИЙ служебный сегмент.
# Консервативно: трогаем ТОЛЬКО начало и только при явных внутренних маркерах —
# приветствие/цена/суть (без этих маркеров) не затрагиваются; пусто не возвращаем.
_SERVICE_MARKERS = re.compile(
    r"(?:сейчас\s+этап|это\s+этап|\bэтап\s*№?\s*\d|клиент\s+(?:сейчас\s+)?готов\s+брониров|"
    r"менеджер\s+(?:ещё|еще)?\s*не\s+назвал|(?:внутренн\w*\s+)?контекст\s+сделк|"
    r"стади\w*\s+сделк|служебн\w*\s+пометк|\[\s*внутренн)",
    re.IGNORECASE,
)


def _strip_service_prefix(text: str) -> str:
    """Срезать ведущую служебную строку/предложение о стадии сделки, если LLM его всё же
    вставил в начало. НИКОГДА не возвращает пусто при непустом входе (иначе потеряли бы
    весь ответ — лучше отдать как есть, модератор увидит и отклонит)."""
    t = (text or "").strip()
    if not t:
        return t
    for _ in range(3):                      # до 3 ведущих служебных сегментов подряд
        nl = t.find("\n")
        first = t if nl < 0 else t[:nl]
        if not _SERVICE_MARKERS.search(first):
            break                           # ведущего служебного маркера нет — стоп
        if nl >= 0:                         # служебное отдельной строкой → срезаем строку
            rest = t[nl + 1:].strip()
        else:                               # служебное и ответ на ОДНОЙ строке → режем по концу предложения
            m = re.search(r"[.!?…]\s+(?=\S)", first)
            rest = first[m.end():].strip() if m else ""
        if not rest:                        # осмысленного продолжения нет — не вычищаем в пусто
            return t
        t = rest
    return t


# --- ПОСТ-ЧЕК ЧЕРНОВИКА: утверждения ВНЕ белого списка → «уточню»-форма ----------
# Шаг 4/7 (родитель #243). Промпт УЖЕ запрещает утверждать цвет/наличие/цену вне данных
# (APPROVAL_WHITELIST_RULE), но LLM 12.07 всё равно выдавал живые провалы: «выбора по цвету, к
# сожалению, нет», «светлого ADV 350 сейчас нет — есть чёрный», «9000 бат за 10 дней». Пост-чек —
# детерминированная СТРАХОВКА поверх промпта: сканируем ГОТОВЫЙ черновик по сегментам, клеймим
# ЯВНЫЕ нарушения кодом (цвет — любое утверждение о цвете; наличие — «сейчас нет / занят / свободен
# на …»; цена — ИТОГ «<N> бат за <M> дней», которого нет в белом источнике цен), спорные («есть
# ADV 350» — парк-перечень ИЛИ наличие-на-даты?) отдаём LLM-тайбрейку. Нарушение → сегмент
# переписываем в «Уточню у команды и вернусь», а в КОНЦЕ добавляем пометку модератору
# «[уточнить: …]» (её _strip_service_prefix не режет — маркер «[внутренн», не «[уточнить»).
# FAIL-SAFE: нарушений нет → возвращаем ВХОД байт-в-байт; LLM-тайбрейк недоступен/спорно → НЕ трогаем.

# Цвет: клиенту УТВЕРЖДАТЬ нельзя вообще (не в белом списке) → любой цвет-токен = нарушение.
# \b перед основами, чтобы «прекрасный» (⊃ «красн») и т.п. не ловились.
_PC_COLOR_RE = re.compile(
    r"\bцвет\w*|\bcolou?rs?\b|"
    r"\bч[ёе]рн(?:ый|ого|ому|ым|ом|ая|ой|ую|ое|ые|ых|еньк\w*)|"
    r"\bбел(?:ый|ого|ая|ое|ые|ым|ой|еньк\w*)|\bсветл\w*|\bтёмн\w*|\bтемн\w*|"
    r"\bкрасн(?:ый|ого|ому|ым|ом|ая|ой|ую|ое|ые|ых|еньк\w*)|\bсин(?:ий|его|яя|юю|ее|им\w*|их)|"
    r"\bголуб(?:ой|ого|ому|ым|ом|ая|ой|ую|ое|ые|ых)|\bзелён\w*|\bзелен(?:ый|ого|ому|ым|ом|ая|ой|ую|ое|ые|ых)|"
    r"\bсеребр\w*|\bсер(?:ый|ого|ая|ое|ые|ым|ой)|\bзолот\w*|\bоранж\w*|\bжёлт\w*|\bжелт\w*|"
    r"\bкорич\w*|\bфиолет\w*|\bрозов\w*|\bбордов\w*|"
    r"\bblack\b|\bwhite\b|\bred\b|\bblue\b|\bgreen\b|\bsilver\b|\bgold(?:en)?\b|\borange\b|\byellow\b|\bbrown\b",
    re.I)

# Наличие КОНКРЕТНОГО байка на даты/сейчас — вне белого списка. Ловим явные состояния склада
# (не «есть <модель>» вообще — это парк-перечень, он РАЗРЕШЕН; такой спорный случай → LLM-тайбрейк).
# ПОРЯДОК СЛОВ КЛЕЙМУ НЕ ХОЗЯИН (правка 23.08.2026, живой промах). Утверждающие формы стояли
# СВЯЗКОЙ «свободен\s+на», то есть ловились только в прямом порядке; живой черновик кейса 10
# (прогон 3, 23.08) сказал то же самое инверсией — «депозит 3 000 ฿ — НА ЭТИ ДАТЫ СВОБОДЕН» — и
# прошёл пояс насквозь. Утверждение несёт САМО СЛОВО-СКАЗУЕМОЕ, а не его соседство с предлогом,
# поэтому связка снята, а слово взято ПО ПРАВИЛУ СЛОВА (см. word_hit :7346): левая граница
# `(?<!\w)` обязательна, чтобы корень внутри чужого слова не считался клеймом. Замер живого
# корпуса переписок (client_chats.anon.jsonl, 710 записей) называет цену границы поимённо:
# «безналичный/безналичная/…» ×15 держат корень «налич» (прямой близнец «безопасным» ⊃ «опасн»),
# «освободится/освободиться/…» ×31 держат «свобод», «недоступен/…» ×20 держат «доступ».
# Хвост здесь ЗАКРЫТ списком коротких форм сказуемого (ен|на|но|ны) сознательно: это не смягчение
# правила, а его предмет — клейм наличия несут именно предикативные формы («байк свободен»), а
# полные («свободное время», «доступная модель») утверждением о складе не являются.
_PC_AVAIL_RE = re.compile(
    r"сейчас\s+нет|уже\s+нет|пока\s+нет|нет\s+в\s+нали\w+|не\s+в\s+нали\w+|нету\b|"
    r"не\s+остал\w+|разобрал\w*|\bзанят\w*|недоступ\w*|нет\s+свободн\w*|осталось\s+\d|"
    r"(?<!\w)свобод(?:ен|на|но|ны)\b|(?<!\w)доступ(?:ен|на|но|ны)\b|(?<!\w)в\s+наличии\b|"
    r"есть\s+в\s+нали\w+|в\s+наличии\s+есть|"
    r"sold\s*out|not\s+available|unavailable|out\s+of\s+stock|already\s+booked|in\s+stock",
    re.I)

# Цена/депозит клиенту — ТОЛЬКО дословно из белого источника (quote/сетка). Разбор денежных чисел
# черновика (итог-за-период / суточная ставка / депозит) делаем ЕДИНОЙ функцией extract_money_figures
# (ниже): она отделяет суточную ставку «449฿/день» (kind='rate', НЕ клеймим) от итога-за-срок
# (kind='total') и депозита, распознаёт срок при любой формулировке («за/на/—/for N дней», «N дней:»).
# Клеймление чисел вне белого источника — в _pc_classify. Прежний узкий _PC_PRICE_TOTAL_RE («за» без
# «на»/«—»/«for») пропускал живой итог окна 504608015 «на 5 дней — 2 245 ฿» — заменён этим разбором
# (#310: гард guard_quote_price свёрнут в пост-чек, точка правды разбора денег одна).

# Разбиение на сегменты С СОХРАНЕНИЕМ разделителей (точный round-trip): границы предложений и
# переводы строк. Тире «—» границей НЕ считаем — «светлого ADV 350 сейчас нет — есть чёрный»
# должно остаться ОДНИМ сегментом и клеймиться целиком.
_PC_SPLIT_RE = re.compile(r'([.!?…]+["»)\]]?\s+|\n+)')


def _pc_num(s):
    """Число из строки-денежного-токена → int (снимаем пробелы/разделители тысяч) или None."""
    d = re.sub(r"\D", "", str(s or ""))
    return int(d) if d else None


def _pc_wl_price_numbers(pricing_note: str):
    """Белый источник цен — множество чисел из блока ЦЕНА/ПРАЙС (quote/сетка). Итог в черновике,
    совпавший с этим множеством, считаем законным (пришёл из Календаря). Пусто → пустое множество
    (тогда ЛЮБОЙ итог-за-период = утверждение вне данных)."""
    return {v for tok in re.findall(r"\d[\d.,\s]*\d|\d", pricing_note or "")
            for v in (_pc_num(tok),) if v is not None}


# --- Разбор денежных чисел из ТЕКСТА ответа бота (шаг 2/5 родитель #310) --------------------
# extract_money_figures: достаёт ВСЕ денежные числа ответа с грубой классификацией — суточная
# ставка «฿/день» (rate), итог за период (total), депозит (deposit), прочая денежная сумма
# (amount). Единая точка правды разбора денег: питает пост-чек черновика (_pc_classify клеймит
# total/deposit вне белого источника). Живой провал окна 504608015 «NMAX 155 на 5 дней — 2 245 ฿
# (449 ฿/день)» → total=2245, rate=449; при этом «155» (модель) и «5» (срок) деньгами НЕ считаются.
# Терпима к форматам «2 245 ฿», «449฿/день», «3000», «депозит 3000 бат», «1685 THB», «337 THB/day».
# Каждый фиг несёт has_cur — был ли валютный токен рядом с числом (пост-чек клеймит total/deposit
# только с валютой, отсекая счётчики вроде «на 5 дней для 2 гостей»).
# --- ВАЛЮТЫ И РОЛИ ДЕНЕГ — ВНЕШНИЙ КОНФИГ (money_currencies.json) -----------------------------
# Родитель: живой случай 07.07 (карточки 204/205, окно @marcoit41) — «222 USDT — депозит», а через
# МИНУТУ «Депозит за байк — 289 USDT». Денежный пост-чек этого НЕ увидел: _MF_CUR знал ТОЛЬКО
# батовые токены (฿|бат|baht|thb), поэтому у «222 USDT» has_cur=False, а _pc_classify такие фиги
# пропускает («if not fig.get("has_cur"): continue») — суммы в USDT/USD/EUR/рублях уходили клиенту
# НАСКВОЗЬ, мимо всей денежной страховки. Разведка корпуса 29.07: usdt звучит в 19 черновиках и в
# 31 реплике тредов, доллары/рубли/крипта — ещё в 35 тредах.
# Список валют и РОЛЕВЫХ слов (депозит/доставка/аренда/допы/итого) вынесен в money_currencies.json:
# ДОПОЛНЯЕТСЯ БЕЗ ИЗМЕНЕНИЯ ЛОГИКИ (как team_registry.json). FAIL-SAFE здесь ИНОЙ, чем у реестра
# команды: нет файла/битый/не-словарь → работает ВСТРОЕННЫЙ минимум ниже (пустой набор обнулил бы и
# батовую ветку — регресс хуже отсутствия фичи). Записи файла МЕРЖАТСЯ поверх минимума.
MONEY_CONFIG_FILE = os.path.join(BASE_DIR, "money_currencies.json")

_MONEY_CUR_FALLBACK = [
    {"code": "THB",  "label": "฿",    "label_en": "THB",  "tokens": ["฿", "бат", "baht", "thb"]},
    {"code": "USDT", "label": "USDT", "label_en": "USDT", "tokens": ["usdt", "tether"]},
    {"code": "USD",  "label": "$",    "label_en": "$",    "tokens": ["$", "usd", "доллар", "dollar"]},
    {"code": "EUR",  "label": "€",    "label_en": "€",    "tokens": ["€", "eur", "евро"]},
    {"code": "RUB",  "label": "₽",    "label_en": "RUB",  "tokens": ["₽", "rub", "руб", "рубл"]},
]
# Порядок ролей = ПРИОРИТЕТ при нескольких ролевых словах в одной клаузе: «Итого к оплате сейчас за
# депозит: 289 USDT» — это ДЕПОЗИТ, а не итог.
_MONEY_ROLE_FALLBACK = [
    {"key": "deposit",  "label": "депозит",  "label_en": "deposit",  "tokens": ["депозит", "залог", "deposit"]},
    {"key": "delivery", "label": "доставка", "label_en": "delivery", "tokens": ["доставк", "подвез", "delivery"]},
    {"key": "rent",     "label": "аренда",   "label_en": "rental",   "tokens": ["аренд", "прокат", "стоимост", "rental", "rent"]},
    {"key": "extra",    "label": "допы",     "label_en": "extras",   "tokens": ["кофр", "шлем", "helmet", "top box"]},
    {"key": "total",    "label": "итого",    "label_en": "total",    "tokens": ["итого", "всего", "к оплате", "total"]},
]


def _money_token_pat(tok):
    """Токен конфига → кусок регекса. Латиница — ТОЧНОЕ слово (\\busd\\b не ловится внутри «usdt»);
    кириллица — основа + окончание («бат» → баты/батов/батами); символ (฿ $ € ₽) — как есть."""
    t = str(tok or "").strip()
    if not t:
        return None
    esc = re.escape(t)
    if t[0].isalpha():
        return r"\b" + esc + (r"\b" if t.isascii() else r"\w*")
    return esc


def _money_merge(base, extra, key):
    """Записи файла поверх встроенного минимума: совпал code/key — токены ДОПОЛНЯЮТ встроенные
    (порядок сохраняем), новый code/key — добавляется целиком в конец. Мусор игнорируем молча."""
    out = [dict(e, tokens=list(e["tokens"])) for e in base]
    idx = {e[key]: e for e in out}
    for e in (extra or []):
        if not isinstance(e, dict):
            continue
        k = str(e.get(key) or "").strip()
        if not k:
            continue
        cur = idx.get(k)
        if cur is None:
            cur = {key: k, "label": str(e.get("label") or k),
                   "label_en": str(e.get("label_en") or e.get("label") or k), "tokens": []}
            out.append(cur)
            idx[k] = cur
        else:
            if e.get("label"):
                cur["label"] = str(e["label"])
            if e.get("label_en"):
                cur["label_en"] = str(e["label_en"])
        for t in (e.get("tokens") or []):
            t = str(t).strip()
            if t and t not in cur["tokens"]:
                cur["tokens"].append(t)
    return out


def _load_money_config(path=None):
    """Валюты/роли денежного пост-чека: встроенный минимум + money_currencies.json поверх него.
    FAIL-SAFE: нет файла/битый/не-словарь → ровно встроенный минимум (детект НЕ обнуляется)."""
    path = path or MONEY_CONFIG_FILE
    try:
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        data = {}
    if not isinstance(data, dict):
        data = {}
    curs = _money_merge(_MONEY_CUR_FALLBACK, data.get("currencies"), "code")
    roles = _money_merge(_MONEY_ROLE_FALLBACK, data.get("roles"), "key")
    for e in curs + roles:
        pats = [p for p in (_money_token_pat(t) for t in e["tokens"]) if p]
        e["alt"] = "|".join(pats)
        e["re"] = re.compile("(?:" + e["alt"] + ")", re.I) if pats else re.compile(r"(?!x)x")
    return {"currencies": curs, "roles": roles,
            "cur_alt": "|".join(e["alt"] for e in curs if e["alt"]) or "฿"}


MONEY_CONFIG = _load_money_config()
_MF_NUM = r"\d[\d\s .,]*\d|\d"


def _build_money_regexes():
    """Пересобрать регексы разбора денег из MONEY_CONFIG (на импорте и при горячей замене конфига).
    Валютная альтернация — единственное, что тут меняется от конфига; форма чисел и коннекторы
    ставки остались прежними (батовая ветка обязана вести себя байт-в-байт)."""
    global _MF_CUR, _MF_SCAN_RE, _MF_RATE_TAIL, _MONEY_ANY_CUR_RE, _MONEY_CUR_PREFIX_RE
    _MF_CUR = "(?:" + MONEY_CONFIG["cur_alt"] + ")"
    _MF_SCAN_RE = re.compile(r"(?<![\d.,])(" + _MF_NUM + r")\s*(" + _MF_CUR + r")?", re.I)
    # ставка «/день»: между числом и «день» ОБЯЗАТЕЛЕН коннектор (/ | в | за | per | a) — иначе
    # «5 дней» (счётчик срока) ложно попал бы в суточную ставку.
    _MF_RATE_TAIL = re.compile(
        r"^\s*(?:/\s*|за\s+|в\s+|per\s+|a\s+)" + _MF_CUR + r"?\s*(?:день|дн\w*|сут\w*|day)\b", re.I)
    _MONEY_ANY_CUR_RE = re.compile(_MF_CUR, re.I)
    # валюта ВПЛОТНУЮ ПЕРЕД числом («$100», «€50», «฿590») — суффиксный скан её не видит.
    _MONEY_CUR_PREFIX_RE = re.compile("(" + _MF_CUR + r")\s*$", re.I)


_build_money_regexes()


def reload_money_config(path=None):
    """Перечитать money_currencies.json (горячая замена/тесты) и пересобрать регексы. → MONEY_CONFIG."""
    global MONEY_CONFIG
    MONEY_CONFIG = _load_money_config(path)
    _build_money_regexes()
    return MONEY_CONFIG


def _money_cur_code(tok):
    """Валютный токен («USDT», «батов», «฿») → код валюты из конфига или None."""
    t = str(tok or "").strip()
    if not t:
        return None
    for c in MONEY_CONFIG["currencies"]:
        if c["re"].fullmatch(t):
            return c["code"]
    return None


def _money_cur_label(code, en=False):
    """Код валюты → ярлык для пометки модератору («THB» → «฿», «USDT» → «USDT»). Нет кода → ''."""
    for c in MONEY_CONFIG["currencies"]:
        if c["code"] == code:
            return c["label_en"] if en else c["label"]
    return ""


# Период-фраза «N дней/недель/месяцев». Предлог за/на/for/в — НЕОБЯЗАТЕЛЕН: живые итоги-за-срок
# пишут по-разному — «за 5 дней», «на 5 дней», «— 5 дней», «for 5 days», «5 дней:». Узкое «за»
# пропускало живой провал окна 504608015 «на 5 дней — 2 245 ฿». Падежи покрыты дн\w*/недел\w*/мес\w*.
_MF_PERIOD = re.compile(
    r"(?:за|на|for|в)?\s*\d{1,3}\s*(?:дн\w*|день|сут\w*|недел\w*|нед\b|мес\w*|months?|weeks?|days?)",
    re.I)
_MF_DEPOSIT = re.compile(r"депозит|залог|deposit", re.I)
_MF_TOTAL_KW = re.compile(r"итог\w*|всего|total|сумм\w*", re.I)
_MF_MODEL_TAIL = re.compile(
    r"(?:nmax|adv|pcx|click|forza|xmax|vario|aerox|filano|scoopy|grand|fino|burgman|lead|zoomer)"
    r"\s*$", re.I)
_MF_UNIT_HEAD = re.compile(
    r"^\s*(?:cc\b|куб\w*|км\b|km\b|%|час\w*|год\b|лет\b|шт\b|дн\w*|день|сут\w*|недел\w*|нед\b|"
    r"мес\w*|day|week|month)", re.I)


def extract_money_figures(text: str):
    """Денежные числа из текста ответа → список dict(kind, value, raw, has_cur, cur, pos) в порядке
    появления. kind ∈ {'rate','deposit','total','amount'}; cur — КОД валюты из money_currencies.json
    (THB/USDT/USD/EUR/RUB/…) или None, если валютного токена рядом не было. Модельные числа
    (NMAX 155) и счётчики срока (5 дней) деньгами НЕ считаются. value — int (пробелы/разделители
    тысяч сняты). Валюта считается «рядом» и СУФФИКСОМ («289 USDT»), и ПРЕФИКСОМ («$100», «฿590»)."""
    s = text or ""
    out = []
    for m in _MF_SCAN_RE.finditer(s):
        value = _pc_num(m.group(1))
        if value is None:
            continue
        before = s[max(0, m.start(1) - 28):m.start(1)]
        after = s[m.end():m.end() + 18]
        pre = _MONEY_CUR_PREFIX_RE.search(before)          # «$100» / «฿590» — валюта перед числом
        cur = _money_cur_code(m.group(2)) or (_money_cur_code(pre.group(1)) if pre else None)
        has_cur = bool(m.group(2)) or bool(pre)
        is_rate = bool(_MF_RATE_TAIL.search(after))
        near = before.lower() + " " + after.lower()
        is_deposit = bool(_MF_DEPOSIT.search(near))
        is_total = bool(_MF_PERIOD.search(near) or _MF_TOTAL_KW.search(before.lower()))
        # без валюты и вне явного денежного контекста — отсекаем модельные числа (NMAX 155)
        # и единицы/счётчики (5 дней, 155 cc); голое число оставляем только если оно похоже
        # на цену (итог-за-период ИЛИ >=1000).
        if not has_cur and not is_rate and not is_deposit:
            if _MF_MODEL_TAIL.search(before) or _MF_UNIT_HEAD.match(after):
                continue
            if not is_total and value < 1000:
                continue
        if is_rate:
            kind = "rate"
        elif is_deposit:
            kind = "deposit"
        elif is_total:
            kind = "total"
        else:
            kind = "amount"
        out.append({"kind": kind, "value": value, "raw": m.group(0).strip(), "has_cur": has_cur,
                    "cur": cur, "pos": m.start(1), "end": m.end()})
    return out


def _pc_segments(text: str):
    """Список [сегмент, разделитель] с точным round-trip: ''.join(s+p) == text."""
    parts = _PC_SPLIT_RE.split(text or "")
    return [[parts[i], parts[i + 1] if i + 1 < len(parts) else ""] for i in range(0, len(parts), 2)]


def _pc_is_ask_form(low: str) -> bool:
    """Сегмент уже в «уточню»-форме / это пометка модератору → повторно не клеймим."""
    return ("уточн" in low or "[уточнить" in low
            or "check with the team" in low or "get back to you" in low)


def _pc_maybe(low: str, model) -> bool:
    """Спорный случай для LLM-тайбрейка: назван КОНКРЕТНЫЙ байк + слово владения/готовности, но
    без явного склад-состояния (детерминированные RE выше не сработали). «Есть ADV 350» — это
    парк-перечень (разрешено) ИЛИ наличие-на-даты (запрещено)? Решает LLM.

    БЕГЛАЯ ГЛАСНАЯ (правка 23.08.2026, живой промах). Стем стоял «свободн\\w*», и слова «свободен»
    в нём НЕТ вовсе: в короткой форме мужского рода между «свобод» и «н» встаёт беглая «е»
    (свобод-Е-н). Поэтому запасной тайбрейк не запускался ровно на той форме, которую бот и пишет
    чаще всего (99 вхождений «свободен» на 84 живых черновика). Корень взят настоящий — «свобод»,
    хвост ОТКРЫТ (корень, а не слово: «свободен/свободна/свободны» обязаны ловиться), левая граница
    `(?<!\\w)` — по общему правилу слова (word_hit :7346), иначе тайбрейк дёргался бы на
    «освободится» (31 вхождение в живом корпусе переписок). Тем же правилом закрыт «доступ»:
    «недоступен» разбирает детерминированная ветка выше, тайбрейку он не адресован."""
    return bool(model) and bool(
        re.search(r"\bесть\b|(?<!\w)имеется|(?<!\w)доступ\w*|(?<!\w)свобод\w*|"
                  r"(?<!\w)в\s+наличии|(?<!\w)привез\w*|\bготов\w*", low))


def _pc_llm_tiebreak(seg: str, transcript, call_llm):
    """LLM-тайбрейк спорного сегмента. → 'color'|'avail'|'price' (нарушение) или None (чисто/сбой).
    FAIL-SAFE: любая ошибка/непарс → None (не переписываем на сомнении)."""
    sys = (
        "Ты контролёр черновика менеджера аренды. Менеджеру НЕЛЬЗЯ УТВЕРЖДАТЬ клиенту как факт: "
        "(1) цвет байка; (2) наличие КОНКРЕТНОГО байка на даты/сейчас; (3) точную цену/итог вне "
        "прайса. РАЗРЕШЕНО: перечень моделей парка, депозит-правило, минимальные сроки, цены "
        "дословно из прайса. Верни СТРОГО JSON без пояснений: "
        "{\"violation\": true|false, \"kind\": \"color|avail|price|none\"}.")
    try:
        raw = call_llm(sys, "Фраза менеджера: " + (seg or ""))
        m = re.search(r"\{.*\}", raw or "", re.S)
        data = json.loads(m.group(0)) if m else {}
        if data.get("violation"):
            k = str(data.get("kind", "")).lower()
            return k if k in ("color", "avail", "price") else "avail"
    except Exception:
        return None
    return None


def _pc_classify(seg: str, allowed, call_llm=None, transcript=None):
    """Нарушения в сегменте → список (kind, mention). Пусто = сегмент чист.
    Детерминированно: цвет/наличие/итог-цена-вне-данных; спорное → LLM-тайбрейк (если дан call_llm)."""
    low = (seg or "").lower()
    if not low.strip() or _pc_is_ask_form(low):
        return []
    models = _detect_models(low)
    model = models[0] if models else None
    found = []
    if _PC_COLOR_RE.search(seg):
        found.append(("color", model))
    if _PC_AVAIL_RE.search(low):
        found.append(("avail", model))
    # Цена/депозит: разбор чисел делегируем extract_money_figures (единая точка правды разбора денег,
    # #310 — сюда свёрнут гард guard_quote_price). Клеймим ИТОГ-за-период (kind='total') и ДЕПОЗИТ с
    # валютным токеном, чьё число вне белого источника; суточную ставку («449฿/день» → kind='rate') и
    # голые немонетарные числа НЕ трогаем. Итог ловится при любой формулировке срока («за/на/—/for N
    # дней», «N дней:») — _MF_PERIOD распознаёт период без обязательного предлога. Валютный токен рядом
    # обязателен (has_cur) — как в прежнем _PC_PRICE_TOTAL_RE: отсекает счётчики («на 5 дней для 2
    # гостей»). Депозит сверяем ТОЛЬКО при непустом белом источнике (есть live-quote), как прежде.
    for fig in extract_money_figures(seg):
        # ПЕРЕПИСЫВАНИЕ сегмента в «уточню» оставлено на БАТОВОЙ ветке — ровно там, где оно
        # отлажено голденами и живыми провалами. Валюты сверх бата (USDT/USD/EUR/руб) закрывает
        # НОВЫЙ денежный пост-чек postcheck_money — ПОМЕТКОЙ модератору, без правки клиентского
        # текста (курс 28.07: «пометка менеджеру вместо слепой замены»; деструктивную ветку на
        # новые валюты не тянем — цена ложного переписывания выше цены лишней пометки).
        if not fig.get("has_cur") or fig.get("cur") != "THB":
            continue
        if fig["kind"] == "total" and fig["value"] not in allowed:
            found.append(("price", str(fig["value"])))
        elif fig["kind"] == "deposit" and allowed and fig["value"] not in allowed:
            found.append(("price", str(fig["value"])))
    if found:
        return found
    if call_llm and _pc_maybe(low, model):
        k = _pc_llm_tiebreak(seg, transcript, call_llm)
        if k:
            return [(k, model if k != "price" else None)]
    return []


def _pc_manager_note(issues, en: bool) -> str:
    """Пометка модератору «[уточнить: …]» из накопленных нарушений (для клиента её не видно —
    _strip_service_prefix не режет, а модератор уточнит и правит перед одобрением)."""
    label = {"color": "цвет" if not en else "colour",
             "avail": "наличие" if not en else "availability",
             "price": "цена" if not en else "price"}
    parts = []
    for kind in ("color", "avail", "price"):
        ms = [m for k, m in issues if k == kind]
        if not ms:
            continue
        uniq = []
        for m in ms:
            if m and m not in uniq:
                uniq.append(m)
        parts.append(label[kind] + ((" " + " ".join(uniq)) if uniq else ""))
    return ("[уточнить: " + "; ".join(parts) + "]") if parts else ""


def postcheck_draft(draft: str, lang: str = "ru", pricing_note: str = "",
                    call_llm=None, transcript: str = None) -> str:
    """Пост-чек ГОТОВОГО черновика: утверждения о цвете/наличии/цене ВНЕ белого списка → «уточню».
    Нарушений нет → вход возвращается БАЙТ-В-БАЙТ (fail-safe). Сегмент-нарушение переписываем в
    «Уточню у команды и вернусь», в конце — пометка модератору «[уточнить: …]»."""
    text = draft or ""
    if not text.strip():
        return draft
    allowed = _pc_wl_price_numbers(pricing_note)
    en = (lang == "en")
    ask = "Let me check with the team and get back to you." if en else "Уточню у команды и вернусь."
    issues, out, changed, prev_ask = [], [], False, False
    for seg, sep in _pc_segments(text):
        hits = _pc_classify(seg, allowed, call_llm=call_llm, transcript=transcript)
        if not hits:
            out.append([seg, sep])
            prev_ask = False
            continue
        changed = True
        issues.extend(hits)
        if prev_ask:                     # схлопываем подряд идущие «уточню» в одно
            continue
        newsep = "\n" if "\n" in sep else (" " if sep else "")
        out.append([ask, newsep])
        prev_ask = True
    if not changed:
        return draft
    body = "".join(s + p for s, p in out).strip()
    note = _pc_manager_note(issues, en)
    return (body + "\n" + note) if note else body


# --- ДЕНЕЖНЫЙ ПОСТ-ЧЕК: ОДНА СУММА ЗА ОДНО И ТО ЖЕ, И НИ ОДНОГО ЧИСЛА ИЗ ГОЛОВЫ ----------------
# Родитель — живой случай 07.07 в окне @marcoit41 (карточки 204/205, разбор корпуса
# docs/artifacts/2026-07-29-draft-audit.md, класс 1): за ОДНУ МИНУТУ клиенту ушло «222 USDT —
# депозит, 289 USDT — аренда», а следом «Депозит за байк — 289 USDT». Ни один прежний чек этого не
# ловил: батовый _MF_CUR не видел USDT вовсе, а сверки «одна роль — одна сумма» не было НИ ОДНОЙ.
#
# Чек делает ДВЕ вещи и НИЧЕГО не переписывает — черновик уходит модератору С ПОМЕТКОЙ:
#   1) ПРОТИВОРЕЧИЕ: одна и та же РОЛЬ суммы (депозит/доставка/аренда — не путая разные позиции)
#      с РАЗНЫМИ числами в одной валюте — внутри черновика и/или против того, что менеджер уже
#      назвал в ЭТОМ окне. Пометка называет ОБЕ суммы: «⚠️ противоречие: депозит 222 USDT и 289 USDT».
#   2) СУММА НЕ ИЗ ИСТОЧНИКОВ: числа, которых нет НИ в расчёте/прайсе (pricing_note), НИ в репликах
#      треда (клиент + менеджер). Бот не называет чисел из головы — расширение «сочинённой цены»
#      (прежде только батовый итог-за-период) на ВСЕ валюты и роли.
# FAIL-SAFE: нечего сказать → черновик возвращается БАЙТ-В-БАЙТ (тот же объект).

# Клауза — кусок предложения между разделителями позиций. ТИРЕ разделителем НЕ считаем: «222 USDT —
# депозит» обязано остаться ОДНОЙ клаузой, иначе число потеряет свою роль. «⏎» — так транскрипт
# хранит перевод строки.
_MONEY_CLAUSE_SPLIT_RE = re.compile(r"[,;.!?\n\r…⏎()|«»\"]+")
_MONEY_LINE_SPLIT_RE = re.compile(r"[\n\r⏎]+")
# Срок как КВАЛИФИКАТОР позиции: «7 дней» и «14 дней» — РАЗНЫЕ позиции, их суммы сравнивать нельзя.
_MONEY_PERIOD_RE = re.compile(
    r"(\d{1,3})\s*(?:дн\w*|день|сут\w*|недел\w*|нед\b|мес\w*|days?|weeks?|months?)", re.I)
# Роли, по которым СРАВНИВАЕМ суммы. «итого»/«допы» намеренно вне сверки: итог законно меняется от
# состава (аренда+депозит+доставка), а допы — это разные позиции с одним словом.
_MONEY_ROLES_CHECKED = ("deposit", "delivery", "rent")
# Насколько далеко ищем валюту для числа, при котором её не написали («+222 депозит» после строки
# «289 usdt» — это USDT). Назад окно шире: валюту называют РАНЬШЕ суммы.
_MONEY_CUR_BACK, _MONEY_CUR_FWD = 300, 120
# Насколько близко к БЕЗВАЛЮТНОМУ числу обязано стоять ролевое слово, чтобы число считалось этой
# суммой, и ниже какой суммы безвалютное число ценой не считаем (шлемы/даты/проценты).
_MONEY_ROLE_NEAR, _MONEY_BARE_MIN = 10, 100
# Как далеко ВВЕРХ ищем модель-квалификатор, если в своей строке её нет (заголовок блока прайса).
_MONEY_MODEL_BACK = 300


def _money_clause_at(s: str, pos: int):
    """(клауза, её смещение в тексте) — кусок между разделителями позиций, внутри которого стоит
    символ pos. Плюс примыкающий БЕСЦИФРОВОЙ короткий хвост: «6406 (аренда) + 7000 (депозит)» —
    роль стоит в СЛЕДУЮЩЕЙ клаузе, но относится к этому числу. Хвост с цифрами не берём — это уже
    соседняя позиция."""
    left = 0
    for m in _MONEY_CLAUSE_SPLIT_RE.finditer(s, 0, pos):
        left = m.end()
    m = _MONEY_CLAUSE_SPLIT_RE.search(s, pos)
    clause = s[left:(m.start() if m else len(s))]
    if m:
        m2 = _MONEY_CLAUSE_SPLIT_RE.search(s, m.end())
        nxt = s[m.end():(m2.start() if m2 else len(s))]
        if nxt.strip() and len(nxt) <= 20 and not any(ch.isdigit() for ch in nxt):
            clause += " " + nxt
    return clause, left


def _money_line_at(s: str, pos: int) -> str:
    """Строка текста, внутри которой стоит символ pos (модель-квалификатор ищем по строке: в
    строке-ряду сетки «NMAX 155CC | дней: 7, стоимость: 3 099 бат» модель стоит ДО клаузы суммы)."""
    left = 0
    for m in _MONEY_LINE_SPLIT_RE.finditer(s, 0, pos):
        left = m.end()
    m = _MONEY_LINE_SPLIT_RE.search(s, pos)
    return s[left:(m.start() if m else len(s))]


def _money_models_at(s: str, pos: int):
    """Модель-КВАЛИФИКАТОР суммы: из своей строки, иначе из БЛИЖАЙШЕЙ строки ВЫШЕ. Карточка прайса
    печатает модель заголовком блока («NMAX 155» ⏎ «• Депозит: 3000 ฿»), поэтому по одной строке
    модель не видна — и депозиты РАЗНЫХ моделей ложно слипались в одно «противоречие» (живой
    ложняк корпуса 29.07: 8 карточек прайс-листа из 22)."""
    got = _detect_models(_money_line_at(s, pos).lower())
    if got:
        return tuple(got)
    head = s[max(0, pos - _MONEY_MODEL_BACK):pos]
    for ln in reversed(_MONEY_LINE_SPLIT_RE.split(head)[:-1]):
        got = _detect_models(ln.lower())
        if got:
            return tuple(got)
    return ()


def _money_role_at(text: str, at: int, at_end: int):
    """(роль, расстояние в символах) для числа [at, at_end) внутри клаузы: берём БЛИЖАЙШЕЕ ролевое
    слово, при равном расстоянии — по порядку ролей в конфиге. Живой ложняк 29.07 (карточка 311):
    «доставка 290 бат + депозит 7 000 бат» при фиксированном приоритете делала ДОСТАВКУ депозитом и
    рождала пустое «противоречие: депозит 290 и 7000». Ролевого слова нет → (None, None)."""
    s = text or ""
    best, best_d, best_i = None, None, None
    for i, r in enumerate(MONEY_CONFIG["roles"]):
        for m in r["re"].finditer(s):
            d = (at - m.end()) if m.end() <= at else (m.start() - at_end)
            d = max(d, 0)
            if best_d is None or d < best_d or (d == best_d and i < best_i):
                best, best_d, best_i = r["key"], d, i
    return best, best_d


def _money_role_of(text: str):
    """Роль по ролевым словам текста без привязки к позиции (порядок конфига = приоритет)."""
    for r in MONEY_CONFIG["roles"]:
        if r["re"].search(text or ""):
            return r["key"]
    return None


def _money_role_label(key, en: bool = False) -> str:
    for r in MONEY_CONFIG["roles"]:
        if r["key"] == key:
            return r["label_en"] if en else r["label"]
    return str(key or "")


def _money_infer_cur(s: str, pos: int):
    """Валюта числа, при котором её не написали, — по БЛИЖАЙШЕМУ валютному токену вокруг («+222
    депозит» сразу после «289 usdt» → USDT). Валюты рядом нет → None (в сверку такое число попадёт
    только со своими же безвалютными — бат с USDT не столкнём)."""
    lo, hi = max(0, pos - _MONEY_CUR_BACK), min(len(s), pos + _MONEY_CUR_FWD)
    best, best_d = None, None
    for m in _MONEY_ANY_CUR_RE.finditer(s, lo, hi):
        d = (pos - m.end()) if m.end() <= pos else (m.start() - pos)
        if best_d is None or d < best_d:
            best, best_d = _money_cur_code(m.group(0)), d
    return best


def money_role_figures(text: str):
    """Деньги текста в РОЛЕВОМ разрезе: [{value, cur, role, models, period, has_cur, raw, kind}].
    role — по словам КЛАУЗЫ (депозит/доставка/аренда/допы/итого), models/period — квалификаторы
    позиции: суммы сравнимы, только если это ОДНА И ТА ЖЕ позиция (та же модель, тот же срок)."""
    s = text or ""
    out = []
    for f in extract_money_figures(s):
        pos, end = f.get("pos", 0), f.get("end", 0)
        if not f["has_cur"]:
            # Число БЕЗ валюты рядом — деньги только по строгим признакам. Иначе в роль «депозит»
            # затягивало кубатуру («NMAX 155 … депозит 3000 ฿»), проценты скидки («скидка 27%,
            # депозит: 7000 бат»), числа дат («20–25 июля, залог паспортом») — живые ложняки
            # корпуса 29.07: 30 карточек из 34 в первом прогоне были именно такими.
            if _MF_MODEL_TAIL.search(s[max(0, pos - 28):pos]) or _MF_UNIT_HEAD.match(s[end:end + 18]):
                continue
        clause, left = _money_clause_at(s, pos)
        line = _money_line_at(s, pos)
        role, dist = _money_role_at(clause, pos - left, end - left)
        if role and not f["has_cur"] and (dist > _MONEY_ROLE_NEAR or f["value"] < _MONEY_BARE_MIN):
            # безвалютное число берём в роль, только если ролевое слово стоит ВПЛОТНУЮ («+222
            # депозит» — живая реплика менеджера окна @marcoit41) и сумма правдоподобна как цена
            role = None
        per = _MONEY_PERIOD_RE.search(clause) or _MONEY_PERIOD_RE.search(line)
        out.append({"value": f["value"], "cur": f.get("cur") or _money_infer_cur(s, pos),
                    "role": role, "has_cur": f.get("has_cur", False), "raw": f["raw"],
                    "kind": f["kind"], "models": _money_models_at(s, pos),
                    "period": _pc_num(per.group(1)) if per else None})
    return out


def money_contradictions(draft: str, transcript: str = ""):
    """Противоречия «одна роль — разные суммы»: [(role, cur, [сумма, сумма, …])] в порядке роли.
    Сравниваем ТОЛЬКО одинаковые позиции: та же роль + та же валюта + та же модель + тот же срок.
    Источники — сам черновик и реплики МЕНЕДЖЕРА этого окна (что клиент от нас уже слышал).
    Флагим, только если хотя бы одна из сумм — из ЧЕРНОВИКА (чужой давний разнобой не наш повод)."""
    dfigs = [f for f in money_role_figures(draft or "") if f["role"] in _MONEY_ROLES_CHECKED]
    if not dfigs:
        return []
    tfigs = [f for f in money_role_figures(_manager_text(transcript or ""))
             if f["role"] in _MONEY_ROLES_CHECKED]
    buckets = {}
    for f, from_draft in [(f, True) for f in dfigs] + [(f, False) for f in tfigs]:
        key = (f["role"], f["cur"], f["models"], f["period"])
        b = buckets.setdefault(key, {"vals": [], "draft": set()})
        if f["value"] not in b["vals"]:
            b["vals"].append(f["value"])
        if from_draft:
            b["draft"].add(f["value"])
    out = []
    for (role, cur, _m, _p), b in buckets.items():
        if len(b["vals"]) > 1 and b["draft"]:
            out.append((role, cur, sorted(b["vals"])))
    order = {r: i for i, r in enumerate(_MONEY_ROLES_CHECKED)}
    return sorted(out, key=lambda t: (order.get(t[0], 9), t[2]))


def _money_source_numbers(pricing_note: str = "", transcript: str = "") -> set:
    """Числа, которые где-то РЕАЛЬНО прозвучали: расчёт/прайс карточки + ВЕСЬ тред (реплики клиента
    и менеджера). Сумма черновика вне этого множества — названа ботом из головы."""
    return _pc_wl_price_numbers(pricing_note) | _pc_wl_price_numbers(transcript)


def money_unsourced(draft: str, pricing_note: str = "", transcript: str = ""):
    """Суммы черновика, которых НЕТ ни в одном источнике → [(значение, код валюты)] по порядку.
    Берём только настоящие деньги: число с ВАЛЮТОЙ рядом либо с ролью (депозит/доставка/аренда) —
    так год «2020», кубатура «155cc» и счётчики срока в пометку не попадают."""
    src = _money_source_numbers(pricing_note, transcript)
    out, seen = [], set()
    for f in money_role_figures(draft or ""):
        if not (f["has_cur"] or f["role"] in _MONEY_ROLES_CHECKED):
            continue
        if f["value"] in src or f["value"] in seen:
            continue
        seen.add(f["value"])
        out.append((f["value"], f["cur"] if f["has_cur"] else None))
    return out


def _money_strip_code_blocks(body: str, pricing_note: str = "") -> str:
    """Убрать из анализа ДОСЛОВНЫЙ блок расчёта/сетки/доставки. Его строки печатает КОД из
    Bridge/Календаря, а не сочиняет модель: депозиты РАЗНЫХ моделей в прайс-карточке законно
    разные, и противоречием это не является (живой ложняк корпуса 29.07 — 7 карточек прайс-листа
    из 18). Разнобой ищем в тексте, который написала МОДЕЛЬ, и против сказанного клиенту."""
    out = body or ""
    for get in (_sheet_block_from_note, _quote_block_from_note, _delivery_block_from_note):
        blk = (get(pricing_note or "") or "").strip()
        if blk and blk in out:
            out = out.replace(blk, "\n")
    return out


def money_manager_note(contras, unsourced, lang: str = "ru") -> str:
    """Пометка модератору «[деньги: …]» — называет ОБЕ спорные суммы и все суммы из головы.
    Клиент её не видит: client_facing_text/stripInternalMarkers срезают строку по маркеру."""
    en = str(lang or "").lower().startswith("en")
    parts = []
    for role, cur, vals in (contras or []):
        lbl = _money_cur_label(cur, en)
        joined = (" vs " if en else " и ").join(f"{v} {lbl}".strip() for v in vals)
        parts.append(("⚠️ conflict: " if en else "⚠️ противоречие: ")
                     + _money_role_label(role, en) + " " + joined)
    if unsourced:
        vals = ", ".join(f"{v} {_money_cur_label(c, en)}".strip() for v, c in unsourced)
        parts.append(("⚠️ figure not from any source: " if en else "⚠️ сумма не из источников: ") + vals)
    if not parts:
        return ""
    return ("[money: " if en else "[деньги: ") + "; ".join(parts) + "]"


def postcheck_money(draft: str, pricing_note: str = "", transcript: str = "",
                    lang: str = "ru") -> str:
    """Денежный пост-чек ВСЕХ валют: противоречие «одна роль — разные суммы» и сумма из головы →
    ПОМЕТКА модератору в хвост. Текст черновика НЕ трогаем (её решает человек). Претензий нет /
    пустой вход → черновик БАЙТ-В-БАЙТ (fail-safe)."""
    text = draft or ""
    if not text.strip():
        return draft
    # анализируем КЛИЕНТСКОЕ тело без служебных пометок (их числа — не деньги) и без дословного
    # КОД-блока расчёта (он не сочинён моделью и внутри себя не противоречив).
    body = _money_strip_code_blocks(client_facing_text(text), pricing_note)
    note = money_manager_note(money_contradictions(body, transcript),
                              money_unsourced(body, pricing_note, transcript), lang)
    if not note or note in text:
        return draft
    log.warning("postcheck_money: %s", note)
    return text.rstrip() + "\n" + note


# --- ПОСТ-ЧЕК ЗАБОРА: бесплатный забор ТОЛЬКО при оплаченной доставке (шаг 5/7 #22) ----------
# Пара к PICKUP_RULE (детерминированная страховка поверх промпта). «Забор байка в конце аренды —
# бесплатный» — это перк ОПЛАЧЕННОЙ доставки (мы привезли — мы же бесплатно забрали). Без доставки
# (клиент забирает сам / самовывоз / «точка без доставки») бесплатного забора НЕТ: обратный забор
# стоит как доставка той же зоны. Самопротиворечие «заберём бесплатно» + «заберёте сами / самовывоз /
# без доставки» в одном черновике ЗАПРЕЩЕНО. Пост-чек снимает ОБЕЩАНИЕ бесплатного забора, если в
# черновике есть сигнал самовывоза ЛИБО delivery_paid явно False. Нет обещания / доставка оплачена
# (и самовывоза в тексте нет) → вход БАЙТ-В-БАЙТ (fail-safe).
# ВАЖНО: КОД-строку доставки (compose_delivery_draft, «Доставка — N ฿ (забор … бесплатный)») этот чек
# НЕ трогает — он идёт по LLM-тексту ДО приклейки dblock, где бесплатный забор при ОПЛАЧЕННОЙ доставке
# легитимен; сам dblock КОД добавляет только при резолвнутой (то есть оплачиваемой) зоне.

# Обещание БЕСПЛАТНОГО ЗАБОРА (в любом порядке слов): «забор … бесплатный» / «бесплатный … забор» /
# EN «pickup … free» / «free … pickup». Границы клаузы — без точек/переводов строки внутри.
# Основа «забор/забрать» в любой форме: «забор», «заберём/заберёте», «забираем» — но НЕ «забота»/«забыть».
_FP_TAKE = r"(?:забор\w*|забер[её]\w*|забир\w*)"
_FP_FREE_RE = re.compile(
    _FP_TAKE + r"[^.\n]*?бесплатн\w*"
    r"|бесплатн\w*[^.\n]*?" + _FP_TAKE +
    r"|(?:bike\s+)?pick[\s-]?up\w*[^.\n]*?\bfree\b"
    r"|\bfree\b[^.\n]*?pick[\s-]?up\w*", re.I)

# Сигнал САМОВЫВОЗА / «точки без доставки»: клиент забирает-сдаёт байк сам, доставку не берёт.
_FP_SELF_RE = re.compile(
    r"самовывоз\w*|забер[её]те\s+сам\w*|забер[её]шь\s+сам\w*|забира\w*\s+сам\w*"
    r"|приед\w*\s+сам\w*|приед\w*\s+за\s+байк\w*|за\s+байком\s+сам\w*|без\s+доставк\w*"
    r"|self[\s-]?pick[\s-]?up|pick[\s-]?(?:it\s+)?up\s+(?:it\s+)?yourself"
    r"|collect[\s-]?(?:it\s+)?yourself|come\s+(?:and\s+)?(?:pick|get)", re.I)

# Клауза-обещание внутри сегмента, которую можно ВЫРЕЗАТЬ, оставив остальное: (а) в скобках
# «(забор … бесплатный)» либо (б) хвост после запятой/тире «, забор … бесплатный».
_FP_CLAUSE_RE = re.compile(
    r"[ \t]*[（(][^()（）\n]*?(?:" + _FP_TAKE + r"[^()（）\n]*?бесплатн\w*"
    r"|бесплатн\w*[^()（）\n]*?" + _FP_TAKE + r"|pick[\s-]?up\w*[^()（）\n]*?free|free[^()（）\n]*?pick[\s-]?up\w*)"
    r"[^()（）\n]*?[)）]"
    r"|[ \t]*[,;—–-]+[ \t]*(?:" + _FP_TAKE + r"[^.\n]*?бесплатн\w*|бесплатн\w*[^.\n]*?" + _FP_TAKE +
    r"|(?:bike\s+)?pick[\s-]?up\w*[^.\n]*?\bfree\b|\bfree\b[^.\n]*?pick[\s-]?up\w*)",
    re.I)


def postcheck_free_pickup(draft: str, lang: str = "ru", delivery_paid=None) -> str:
    """Пост-чек черновика на противоречие ЗАБОРА (шаг 5/7 #22): бесплатный забор в конце аренды —
    ТОЛЬКО при ОПЛАЧЕННОЙ доставке. Обещание бесплатного забора снимаем, если в черновике есть сигнал
    САМОВЫВОЗА (заберёте сами / самовывоз / без доставки) ЛИБО delivery_paid явно False. Иначе вход
    возвращается БАЙТ-В-БАЙТ (fail-safe): нет обещания, либо доставка оплачена и самовывоза нет."""
    text = draft or ""
    if not text.strip() or not _FP_FREE_RE.search(text):
        return draft
    # Снимаем обещание ТОЛЬКО при противоречии: самовывоз в тексте ИЛИ доставка явно НЕ оплачена.
    contradiction = bool(_FP_SELF_RE.search(text)) or (delivery_paid is False)
    if not contradiction:
        return draft
    out, changed = [], False
    for seg, sep in _pc_segments(text):
        if not _FP_FREE_RE.search(seg):
            out.append([seg, sep])
            continue
        cleaned = _FP_CLAUSE_RE.sub("", seg)            # вырезаем клаузу-обещание, оставляя остальное
        cleaned = re.sub(r"[（(]\s*[)）]", "", cleaned)   # осевшие пустые скобки
        cleaned = re.sub(r"[ \t]*[,;—–-]+[ \t]*$", "", cleaned.rstrip())  # хвостовой разделитель
        cleaned = re.sub(r"[ \t]{2,}", " ", cleaned)
        if _FP_FREE_RE.search(cleaned) or not cleaned.strip():
            # клауза не выделилась ⇒ сегмент — само обещание целиком: выбрасываем его (и разделитель)
            changed = True
            continue
        if cleaned != seg:
            changed = True
        out.append([cleaned, sep])
    if not changed:
        return draft
    body = "".join(s + p for s, p in out).strip()
    return body if body else draft


# --- СТРАХОВКА ЗАВЕРШАЮЩЕГО ВОПРОСА (пара к next_step_note, как postcheck_free_pickup к PICKUP_RULE) ---
# Живой ТЕСТ-7: LLM ответил на вопрос и замолчал — воронка встала. КОД гарантирует то, о чём просит
# промпт: если в клиентском теле черновика вопроса НЕТ — дописываем РОВНО ОДИН по приоритету
# недостающего (next_step). Вопрос в теле УЖЕ есть → вход БАЙТ-В-БАЙТ (второго не добавляем никогда:
# «не больше одного вопроса за раз»). Служебные пометки модератору ([уточнить:…]/[собрано:…]/[сезон:…])
# живут хвостом — вопрос вставляем ПЕРЕД ними, чтобы он остался в клиентском теле.
_CLOSING_Q_RE = re.compile(r"[?？]")
_SERVICE_TAIL_RE = re.compile(
    r"(?:[ \t]*\n[ \t]*\[(?:уточнить|собрано|collected|сезон|season|деньги|money)\b[^\n]*\][ \t]*)+"
    r"\s*\Z", re.I)


def ensure_closing_question(draft: str, facts: dict, lang: str = "ru",
                            sheet_mode: bool = False, ready: bool = False, just=None) -> str:
    """Дописать завершающий вопрос, если черновик его потерял. Вопрос уже есть / пустой вход →
    БАЙТ-В-БАЙТ (fail-safe). Вопрос берём из next_step по тем же collected_facts, поэтому уже
    собранное НЕ переспрашивается, а прошедший старт даёт уточнение дат, а не шаг воронки.
    just — поля из ТЕКУЩЕЙ реплики клиента: их не переспрашиваем (см. next_step)."""
    text = draft or ""
    if not text.strip():
        return draft
    m = _SERVICE_TAIL_RE.search(text)
    body, tail = (text[:m.start()], text[m.start():]) if m else (text, "")
    if not body.strip() or _CLOSING_Q_RE.search(body):
        return draft
    q = next_step_question(next_step(facts, sheet_mode, ready, just), lang)
    if not q:
        return draft
    sep = "\n\n" if "\n" in body.strip() else " "
    return body.rstrip() + sep + q + tail


# --- ЗАПРЕТ ПЕРЕСПРОСА УЖЕ СОБРАННОГО (детерминированная пара к «НЕ переспрашивай» в промпте) ---
# ЖИВОЙ ТЕСТ-10: клиент дал даты — ответ подтвердил «даты учли» и ТУТ ЖЕ спросил «Подскажите даты
# — с какого числа и на какой срок?». Промптовое «не переспрашивай» это не удержало. КОД режет
# вопрос-предложение, ВСЕ поля которого уже собраны (тот же матчинг полей, что filter_booking_questions
# — _QUESTION_FIELD_PATTERNS). Вопрос без совпадения с полем НЕ трогаем (не знаем — не режем);
# если после реза вопросов не осталось, ровно один нужный допишет ensure_closing_question.
# Служебный хвост ([уточнить:…]/[собрано:…]) не трогаем — он живёт после клиентского тела.


def _is_question_segment(seg: str, sep: str = "") -> bool:
    """Сегмент _pc_segments — ВОПРОС? Знак «?» уезжает в РАЗДЕЛИТЕЛЬ (_PC_SPLIT_RE забирает
    терминальную пунктуацию вместе с пробелом), поэтому смотрим сегмент ВМЕСТЕ с его хвостом —
    иначе вопрос в середине ответа детектором не виден вовсе."""
    return bool(_CLOSING_Q_RE.search((seg or "") + (sep or "")))


def drop_answered_questions(draft: str, facts: dict, lang: str = "ru") -> str:
    """Убрать из черновика вопросы про поля, которые клиент УЖЕ дал (facts=collected_facts).
    Нечего резать / пустой вход → БАЙТ-В-БАЙТ (fail-safe). Каждый вырезанный вопрос логируем."""
    text = draft or ""
    collected = {k for k, v in (facts or {}).items() if v}
    if not text.strip() or not collected:
        return draft
    m = _SERVICE_TAIL_RE.search(text)
    body, tail = (text[:m.start()], text[m.start():]) if m else (text, "")
    out, changed = [], False
    for seg, sep in _pc_segments(body):
        if _is_question_segment(seg, sep):
            matched = {key for key, pat in _QUESTION_FIELD_PATTERNS if pat.search(seg)}
            if matched and matched <= collected:
                log.info("drop_answered_questions: вырезан вопрос [уже собрано: %s] — %r",
                         ", ".join(sorted(matched)), seg.strip())
                changed = True
                continue
        out.append([seg, sep])
    if not changed:
        return draft
    new_body = "".join(s + p for s, p in out).strip()
    new_body = re.sub(r"\n{3,}", "\n\n", new_body)
    if not new_body:
        return draft                      # весь ответ был переспросом — лучше отдать как есть
    return new_body + (("\n" + tail.strip()) if tail.strip() else "")


# --- УЖЕ ОЗВУЧЕННЫЙ И НЕИЗМЕНИВШИЙСЯ БЛОК НЕ ПОВТОРЯЕМ (тариф доставки) ------------------------
# Живой ТЕСТ-10: строка «Доставка в Банг Тао север — 290 ฿ (при оплаченной доставке забор байка в
# конце аренды бесплатный)» звучала клиенту слово-в-слово в КАЖДОМ ответе. Живой менеджер уже
# сказанное не повторяет (docs/sales-method-2026-07-22.md, §2: соц-доказательство и повтор блоков —
# ровно один раз). compose_delivery_draft закрывает повтор КОД-блока; здесь режем повтор, который
# сделал сам LLM. ИСКЛЮЧЕНИЕ: клиент спросил про доставку в ТЕКУЩЕЙ реплике — тогда ответ уместен
# и мы не немеем.
_DELIVERY_MENTION_RE = re.compile(r"доставк\w*|подвез\w*|\bdelivery\b|\bdeliver\b", re.I)


def drop_repeated_delivery(draft: str, transcript: str = None, lang: str = "ru") -> str:
    """Убрать из черновика повтор тарифа ДОСТАВКИ, который уже прозвучал в этом окне с ТЕМ ЖЕ
    числом. Тариф не звучал / изменился / клиент спросил про доставку сейчас / резать нечего →
    БАЙТ-В-БАЙТ (fail-safe)."""
    text = draft or ""
    if not text.strip() or not (transcript or "").strip():
        return draft
    if _DELIVERY_MENTION_RE.search(last_client_message(transcript)):
        return draft                       # клиент спросил про доставку сейчас — отвечаем
    said_lines = [l for l in _manager_text(transcript).splitlines()
                  if _DELIVERY_MENTION_RE.search(l)]
    said = {f["value"] for f in extract_money_figures("\n".join(said_lines))}
    if not said:
        return draft
    m = _SERVICE_TAIL_RE.search(text)
    body, tail = (text[:m.start()], text[m.start():]) if m else (text, "")
    out, changed = [], False
    for seg, sep in _pc_segments(body):
        figs = {f["value"] for f in extract_money_figures(seg)}
        if _DELIVERY_MENTION_RE.search(seg) and figs and figs <= said:
            log.info("drop_repeated_delivery: тариф доставки уже звучал в окне — повтор снят: %r",
                     seg.strip())
            changed = True
            continue
        out.append([seg, sep])
    if not changed:
        return draft
    new_body = re.sub(r"\n{3,}", "\n\n", "".join(s + p for s, p in out).strip())
    if not new_body:
        return draft
    return new_body + (("\n" + tail.strip()) if tail.strip() else "")


def _append_collected_note(draft: str, facts: dict, lang: str = "ru", unconfirmed=None) -> str:
    """§243/6: дописать в хвост черновика СЛУЖЕБНУЮ пометку модератору «[собрано: гео ✅ …]».
    Ничего не собрано → черновик БАЙТ-В-БАЙТ (fail-safe). Хвост → _strip_service_prefix не режет.
    unconfirmed — поля с «❓» (названы клиентом, но не подтверждены), см. unconfirmed_fields."""
    note = collected_manager_note(facts, lang, unconfirmed)
    if not note:
        return draft
    return ((draft or "").rstrip() + "\n" + note) if (draft or "").strip() else draft


# --- ОТПИСКА «УТОЧНЮ И ВЕРНУСЬ» ПРИ ГОТОВОМ РАСЧЁТЕ (детерминированная пара к стилевому правилу) ---
# ЖИВЫЕ ТЕСТ-7 (23:38) и ТЕСТ-10 (23:49): «Уточню наличие на эти даты и вернусь с точной стоимостью».
# ПОЧЕМУ ветка «после дозаполнения» этот класс пропускала — по факту ДВЕ дыры сразу:
#   1) расчёта в тот момент действительно НЕ БЫЛО: даты клиента не разобрались (порядковая форма
#      «25ого/30ое», см. norm_day_ordinals) → гейт дат заблокировал котировку → стилевое правило
#      «если расчёт готов — не отписывайся» по условию не применялось вовсе;
#   2) сам пост-чек черновика такой сегмент НЕ смотрит: _pc_is_ask_form видит слово «уточн» и
#      считает сегмент уже безопасной «уточню»-формой — то есть отписка проходит НАСКВОЗЬ.
# Дыра 1 закрыта разбором дат. Дыра 2 закрывается здесь: когда цифры ПОСЧИТАНЫ источником (Bridge:
# служебные блоки <<<QUOTE>>>/<<<SHEET>>>/<<<DELIVERY>>> или инструкция «ЦЕНА из Календаря») и
# реально доехали до клиентского тела — предложение-отписку вырезаем КОДОМ. Нет посчитанных цифр →
# черновик БАЙТ-В-БАЙТ: там «уточню и вернусь» легитимно и остаётся предохранителем.
_PRICE_OK_MARKS = ("ЦЕНА из Календаря бронирования", "ЦЕНЫ ПО МОДЕЛЯМ")
# Отписка = обещание вернуться позже (в любой форме) ИЛИ «уточню наличие/цену» с обещанием.
_DEFLECT_RE = re.compile(
    r"верн[уёе]\w*\s+(?:к\s+вам\s+)?(?:с\s+\w+\s+)?(?:позже|чуть\s+позже)?"
    r"|верн[уёе]мся|вернусь\b|отпишус[ья]\b|напишу\s+(?:вам\s+)?позже|сообщу\s+позже"
    r"|пришлю\s+(?:вам\s+)?(?:расч[её]т|цену|стоимость|прайс)\s+позже"
    r"|get\s+back\s+to\s+you|come\s+back\s+to\s+you|let\s+you\s+know\s+later"
    r"|check\s+with\s+the\s+team", re.I)


def computed_price_figures(pricing_note: str) -> set:
    """Денежные числа, реально ПОСЧИТАННЫЕ источником (Bridge), а не выдуманные LLM: из служебных
    блоков <<<QUOTE>>>/<<<SHEET>>>/<<<DELIVERY>>>, а при их отсутствии — из блока ЦЕНА, помеченного
    живым расчётом Календаря. Нет расчёта → пустое множество (гарантии цифры не требуем)."""
    note = pricing_note or ""
    blocks = [m.group(1) for rx in (_QUOTE_BLOCK_RE, _SHEET_BLOCK_RE, _DELIVERY_BLOCK_RE)
              for m in rx.finditer(note)]
    if not blocks and any(mark in note for mark in _PRICE_OK_MARKS):
        blocks = [note]
    return {f["value"] for b in blocks for f in extract_money_figures(b)}


def drop_price_deflection(draft: str, pricing_note: str = "", lang: str = "ru") -> str:
    """Вырезать предложения-отписки («уточню наличие и вернусь», «вернусь с точной стоимостью»),
    когда расчёт ГОТОВ и его цифра уже в клиентском теле. Нет расчёта / цифра до клиента не дошла /
    резать нечего → черновик БАЙТ-В-БАЙТ (fail-safe: предохранитель «уточню» не трогаем).
    Предложение с ПОСЧИТАННОЙ цифрой не режем никогда (иначе унесли бы саму цену)."""
    text = draft or ""
    figures = computed_price_figures(pricing_note)
    if not text.strip() or not figures:
        return draft
    m = _SERVICE_TAIL_RE.search(text)
    body, tail = (text[:m.start()], text[m.start():]) if m else (text, "")
    if not {f["value"] for f in extract_money_figures(client_facing_text(body))} & figures:
        return draft                        # цифры клиенту не доехали — отписка пока честная
    out, changed = [], False
    for seg, sep in _pc_segments(body):
        if _DEFLECT_RE.search(seg) and not ({f["value"] for f in extract_money_figures(seg)} & figures):
            log.warning("drop_price_deflection: вырезана отписка при готовом расчёте — %r", seg.strip())
            changed = True
            continue
        out.append([seg, sep])
    if not changed:
        return draft
    new_body = re.sub(r"\n{3,}", "\n\n", "".join(s + p for s, p in out).strip())
    if not new_body:
        return draft                        # весь ответ был отпиской — лучше отдать как есть
    return new_body + (("\n" + tail.strip()) if tail.strip() else "")


def ensure_price_figure(draft: str, pricing_note: str = "", lang: str = "ru") -> str:
    """ЦИФРА ЦЕНЫ ОБЯЗАНА ЗВУЧАТЬ КЛИЕНТУ: расчёт есть (Bridge посчитал), а в клиентском теле ни
    одного его числа — дописываем ДОСЛОВНУЮ строку расчёта хвостом. Служебная пометка модератору
    «[уточнить: цена N]» цифру НЕ заменяет: её клиент не видит (client_facing_text срезает).
    Нет расчёта / цифра уже в теле / нечего вставить → БАЙТ-В-БАЙТ (fail-safe)."""
    text = draft or ""
    figures = computed_price_figures(pricing_note)
    if not text.strip() or not figures:
        return draft
    m = _SERVICE_TAIL_RE.search(text)
    body, tail = (text[:m.start()], text[m.start():]) if m else (text, "")
    if {f["value"] for f in extract_money_figures(client_facing_text(body))} & figures:
        return draft
    block = _quote_block_from_note(pricing_note) or _delivery_block_from_note(pricing_note) \
        or _sheet_block_from_note(pricing_note)
    if not (block or "").strip():
        return draft
    log.warning("ensure_price_figure: цена посчитана, но в теле её не было — строка расчёта "
                "добавлена КОДОМ (пометка модератору цифру не заменяет)")
    return body.rstrip() + "\n\n" + block.strip() + (("\n" + tail.strip()) if tail.strip() else "")


def _season_service_note(pricing_note: str) -> str:
    """Сезонная СЛУЖЕБНАЯ пометка «[сезон: …]» из служебных скобок pricing_note → текст | ''
    (нет низкого сезона / не sheet-режим)."""
    m = _SEASON_BLOCK_RE.search(pricing_note or "")
    return m.group(1).strip() if m else ""


def _append_season_note(draft: str, pricing_note: str) -> str:
    """Шаг 4/7 #253: дописать в хвост черновика СЛУЖЕБНУЮ сезонную пометку «[сезон: …]» (для
    модератора; client_facing_text её срезает — в клиентском теле сезонности нет). Нет пометки →
    черновик БАЙТ-В-БАЙТ (fail-safe)."""
    note = _season_service_note(pricing_note)
    if not note:
        return draft
    return ((draft or "").rstrip() + "\n" + note) if (draft or "").strip() else draft


# Служебные пометки модератору в теле черновика — квадратные скобки с известным маркером,
# КАЖДАЯ отдельной строкой в хвосте ([уточнить: …]/[собрано: …]/[сезон: …] и EN-аналоги). Клиент
# их видеть не должен: client_facing_text срезает такие строки перед отправкой (шаг 4/7 #253).
_SERVICE_NOTE_LINE_RE = re.compile(
    r"^[ \t]*\[(?:уточнить|собрано|collected|сезон|season|тип ТС|vehicle type"
    r"|деньги|money"                        # денежная пометка (противоречие/сумма из головы, 29.07)
    r"|партн[её]рский чат|partner chat)\b[^\n]*\][ \t]*$", re.I | re.M)


def client_facing_text(draft: str) -> str:
    """Текст, который увидит КЛИЕНТ: черновик БЕЗ служебных пометок модератору
    ([уточнить: …]/[собрано: …]/[сезон: …]). Пометки живут в служебной части карточки, не в теле
    ответа. Пустой вход → как есть (fail-safe)."""
    if not (draft or "").strip():
        return draft
    out = _SERVICE_NOTE_LINE_RE.sub("", draft)
    return re.sub(r"\n{3,}", "\n\n", out).strip()


# --- Чистый строчный фильтр ВНУТРЕННИХ маркеров (шаг 1/5 родитель #55) ------------------------
# Отдельно от client_facing_text: тот срезает только хвостовые пометки-скобки «[уточнить…]/[собрано…]».
# Этот вычищает ЛЮБУЮ строку со следом ВНУТРЕННЕЙ стадии сделки, куда бы LLM её ни вставил, —
# «Этап N», «менеджер ещё не назвал (цену)», «собрано», «[уточнить». Клиент такого видеть не должен.
# ЧИСТАЯ функция (без сайд-эффектов, без сети/IO). ПОКА ТОЛЬКО ЭКСПОРТ — точку отправки не трогаем
# (подключим отдельным шагом чейна). Регистр не учитываем (re.I).
_INTERNAL_MARKER_RE = re.compile(
    r"Этап\s*\d|менеджер\s+(?:ещё|еще)\s+не\s+назвал|собрано|\[уточнить"
    r"|\[тип ТС|\[vehicle type"             # пометка о конфликте типа ТС — тоже служебная (28.07)
    r"|\[деньги|\[money"                    # …и денежная пометка пост-чека всех валют (29.07)
    r"|\[партн[её]рский чат|\[partner chat", re.I)   # …и пометка партнёрского гарда (28.07)


def stripInternalMarkers(text: str) -> str:
    """Убрать из текста внутренние служебные маркеры и нормализовать пробелы.

    Удаляет ЦЕЛИКОМ каждую строку, в которой встречается любой из маркеров
    («Этап N», «менеджер ещё не назвал…», «собрано», «[уточнить…»), схлопывает
    задвоенные пробелы/табы внутри строк и лишние пустые строки (3+ подряд → 1),
    обрезает края. Регистр не учитывается. Пустой/None-вход → как есть (fail-safe)."""
    if not text:
        return text
    kept = []
    for ln in text.splitlines():
        if _INTERNAL_MARKER_RE.search(ln):
            continue                        # строка со следом внутреннего маркера — целиком вон
        kept.append(re.sub(r"[ \t]{2,}", " ", ln).rstrip())
    out = "\n".join(kept)
    return re.sub(r"\n{3,}", "\n\n", out).strip()


def _strip_internal_markers_for_send(text: str, window) -> str:
    """Обёртка над stripInternalMarkers для ТОЧКИ ОТПРАВКИ клиенту (шаг 2/5 родитель #55):
    чистит исходящий текст от внутренних маркеров и, ЕСЛИ что-то вырезано, пишет в штатный лог
    ЧТО (сами строки-маркеры) и в каком ОКНЕ (window = id клиента/диалога). Строки вычисляем по
    тому же _INTERNAL_MARKER_RE, что и сам strip, — так лог показывает ровно удалённое. Ничего не
    сработало → тихо возвращает очищенный текст (с точностью до нормализации пробелов)."""
    cleaned = stripInternalMarkers(text)
    removed = [ln.strip() for ln in (text or "").splitlines()
               if _INTERNAL_MARKER_RE.search(ln)]
    if removed:
        log.warning(
            f"SUGGEST[stripInternalMarkers] окно={window}: вырезано перед отправкой — "
            f"{' | '.join(removed)}")
    return cleaned


# ===================== ГАРД НАЛИЧИЯ/ДЕФИЦИТА/ОСОБЫХ УСЛОВИЙ (родитель4, шаг 4/6) =====================
# Пара к AVAILABILITY_INVARIANT_RULE: детерминированная страховка ПЕРЕД отправкой, по образцу удалённого
# guard_quote_price (#310) — та же форма (сверка текста ↔ данные → перегенерация → фолбэк). Инвариант:
# бот НЕ утверждает наличие/занятость конкретного байка, дефицит/срочность и особые/персональные условия
# БЕЗ данных. Данные о наличии — только из Bridge (quote.available / quote_for_model.status); дефицита и
# спецусловий у бота источника НЕТ вовсе → такие клеймы нарушают инвариант ВСЕГДА. Нарушение → ответ НЕ
# уходит: лог (окно/модель/даты/клеймы) + перегенерация с жёсткой директивой (regenerate(directive)); после
# N неудач — безопасный фолбэк «уточню наличие и вернусь». Нет клеймов наличия → черновик байт-в-байт.
# Пост-чек postcheck_draft клеймит наличие переписыванием сегмента в «уточню» (мягко, для модератора);
# этот гард — жёсткий пояс с перегенерацией/фолбэком, дополняет пост-чек, а не дублирует его.

# Наличие ОТРИЦАЕТСЯ (занят/нет/разобрали) — состояние склада, вне данных без Bridge.
_AV_NEG_RE = re.compile(
    r"сейчас\s+нет|уже\s+нет|пока\s+нет|нет\s+в\s+нали\w+|не\s+в\s+нали\w+|нету\b|"
    r"не\s+остал\w+|разобран\w*|\bзанят\w*|недоступ\w*|нет\s+свободн\w*|"
    r"sold\s*out|not\s+available|unavailable|out\s+of\s+stock|already\s+booked", re.I)
# Наличие УТВЕРЖДАЕТСЯ (свободен/в наличии/доступен на даты) — тоже вне данных без Bridge.
# Границы слева добавлены 23.08.2026 тем же правилом слова, что и в _PC_AVAIL_RE (word_hit :7346):
# без них «недоступен» (20 вхождений в живом корпусе) читался как УТВЕРЖДЕНИЕ наличия по куску
# строки «доступен», а «нетдоступна» — мимо ветки отрицания вовсе. Формы среднего/множественного
# («свободно/свободны», «доступно/доступны») добавлены заодно: клейм тот же, а списка их не было.
_AV_POS_RE = re.compile(
    r"(?<!\w)есть\s+в\s+нали\w+|(?<!\w)в\s+нали\w+\b|(?<!\w)свобод(?:ен|на|но|ны)\b|"
    r"(?<!\w)доступ(?:ен|на|но|ны)\b|\bavailable\b|(?<!\w)in\s+stock", re.I)
# ДЕФИЦИТ/СРОЧНОСТЬ — источника данных НЕТ, клейм запрещён ВСЕГДА.
_AV_SCARCITY_RE = re.compile(
    r"послед\w+\s+(?:байк\w*|штук\w*|шт\b|один|одна|экземпляр\w*)|остал\w+\s+(?:один|одна|1\b)|"
    r"осталось\s+\d|мало\s+остал\w+|почти\s+(?:всё|все)\s+разобрал\w*|разбира\w+|успевай\w*|"
    r"успей\w*|спеши\w+|торопи\w+|только\s+сегодня\b|"
    r"last\s+one|only\s+\d+\s+left|almost\s+gone|selling\s+fast|hurry|going\s+fast|only\s+today", re.I)
# ОСОБЫЕ/ПЕРСОНАЛЬНЫЕ УСЛОВИЯ и спеццены — назначает менеджер, у бота источника НЕТ, запрещено ВСЕГДА.
_AV_SPECIAL_RE = re.compile(
    r"особ\w+\s+услови\w+|специальн\w+\s+(?:услови\w+|предложени\w+|цен\w+)|"
    r"персональн\w+\s+(?:скидк\w+|цен\w+|услови\w+)|скидк\w+\s+(?:специально\s+)?(?:для\s+вас|лично\s+вам)|"
    r"только\s+для\s+вас|эксклюзив\w*|"
    r"special\s+(?:offer|deal|conditions?|price|discount)|just\s+for\s+you|exclusive\b|personal\s+discount",
    re.I)


def availability_claims(draft: str) -> list:
    """Клеймы наличия/дефицита/особых условий в ТЕКСТЕ ответа → список dict(kind, raw) в порядке
    появления. kind ∈ {'avail_pos','avail_neg','scarcity','special'}. avail_pos не считаем внутри
    отрицания («нет в наличии» = только avail_neg, не avail_pos). Пусто → клеймов нет."""
    s = draft or ""
    claims, neg_spans = [], []
    for m in _AV_NEG_RE.finditer(s):
        neg_spans.append((m.start(), m.end()))
        claims.append({"kind": "avail_neg", "raw": m.group(0).strip()})
    for m in _AV_POS_RE.finditer(s):
        span = (m.start(), m.end())
        if any(span[0] < e and s0 < span[1] for s0, e in neg_spans):
            continue                                   # «в наличии» внутри «нет в наличии» — уже avail_neg
        pre = s[max(0, m.start() - 6):m.start()].lower()
        if re.search(r"\b(?:не|нет)\s*$", pre):        # непосредственно отрицаемое «свободен» и т.п.
            continue
        claims.append({"kind": "avail_pos", "raw": m.group(0).strip()})
    for m in _AV_SCARCITY_RE.finditer(s):
        # ОТРИЦАНИЕ снимает срочность так же, как у avail_pos выше: «НЕ разбирают», «НЕ спешите».
        # Обработки не было, и вместе с чересчур широким токеном «успева\w+» это дало живой ложняк
        # id=360 (окно 45349667): «раньше ночи НЕ успеваем» — про время подачи, а не про дефицит,
        # и с отрицанием, то есть обратное срочности. Срочность несут повелительные формы
        # («успевайте», «успей»), они и остались в паттерне.
        pre = s[max(0, m.start() - 6):m.start()].lower()
        if re.search(r"\b(?:не|нет)\s*$", pre):
            continue
        claims.append({"kind": "scarcity", "raw": m.group(0).strip()})
    for m in _AV_SPECIAL_RE.finditer(s):
        claims.append({"kind": "special", "raw": m.group(0).strip()})
    return claims


def availability_state(avail):
    """Состояние наличия из данных Bridge → True (свободен) / False (занят) / None (данных нет).
    Принимает bool, quote-dict (поле available), результат quote_for_model ({status}). Дефицит и
    особые условия НИКОГДА не подтверждаются данными — их обрабатывает availability_violations."""
    if isinstance(avail, bool):
        return avail
    if isinstance(avail, dict):
        if isinstance(avail.get("available"), bool):
            return avail["available"]
        st = avail.get("status")
        if st == "ok":
            return True
        if st == "none_available":
            return False
    return None


# ДОСЛОВНАЯ фраза, которой КОД подтверждает наличие. Печатает её `_client_price` и РОВНО под
# `if q.get("available")` — обе точки (:3458 и :3477), другого источника у неё нет. Литерал держим
# рядом с читателем и сверяем тестом: разойдётся печать и чтение — гард начнёт звать правду
# выдумкой, а это ровно тот дефект, из-за которого 23.08 покраснел кейс 10.
_AVAIL_CODE_PHRASE = "свободен на эти даты"


def availability_from_note(pricing_note):
    """Наличие, ПОДТВЕРЖДЁННОЕ КОДОМ, из ценовой записки → True либо None (данных нет).

    Носитель ОДИН и он дословный: `_client_price` дописывает `_AVAIL_CODE_PHRASE` только тогда,
    когда мост вернул свободный юнит. Занятость запиской не переносится вовсе (кода, который писал
    бы «занят», нет) — поэтому False отсюда не приходит НИКОГДА, и это честно: «не подтверждено»
    здесь означает «данных нет», а не «занят». Fail-closed: нет фразы → None → любой клейм наличия
    в тексте головы считается неподтверждённым.

    Почему записка, а не quote-блок: quote-блок собирается не на всех ветках (в ветке минимального
    срока его нет вовсе), и чтение наличия оттуда даёт пустое значение при живом носителе — замер
    23.08 на 84 живых черновиках: по quote-блоку гард ложно срабатывал 1 раз из 84 (правдивая
    фраза кейса 10), по записке — 0 из 84."""
    return True if _AVAIL_CODE_PHRASE in (pricing_note or "") else None


def _av_unsupported(claims, state) -> list:
    """Клеймы, НЕ подтверждённые данными: avail_pos ок только при state=True, avail_neg только при
    state=False; scarcity/special — данных-источника нет → всегда нарушение."""
    bad = []
    for c in claims:
        if c["kind"] == "avail_pos" and state is True:
            continue
        if c["kind"] == "avail_neg" and state is False:
            continue
        bad.append(c)
    return bad


def availability_violations(draft: str, avail=None) -> list:
    """Клеймы наличия/дефицита/особых условий из текста, НЕ подтверждённые данными Bridge (avail).
    Пусто = черновик согласован (клеймов нет ИЛИ наличие точно подтверждено данными)."""
    return _av_unsupported(availability_claims(draft), availability_state(avail))


def _availability_hard_directive(lang: str = "ru") -> str:
    """Директива-верхнего-уровня для перегенерации: запрет утверждать наличие/дефицит/особые условия
    без данных, вместо этого — «уточню наличие и вернусь». В regenerate_draft(directive=…)."""
    if lang == "en":
        return ("Do NOT assert availability of a specific bike (\"free\"/\"in stock\", "
                "\"booked\"/\"not available\"), do NOT create scarcity or urgency (\"last one\", "
                "\"almost gone\", \"hurry\", \"only today\") and do NOT promise any special or "
                "personal conditions, prices or discounts — there is NO data for any of that. "
                "Instead say you will check availability for the client's dates/model with the team "
                "and get back. Write no other availability, scarcity or special-offer claims.")
    return ("НЕ утверждай наличие конкретного байка («свободен»/«в наличии», «занят»/«нет в "
            "наличии»), НЕ создавай дефицит и срочность («последний», «почти разобрали», "
            "«успевайте», «только сегодня») и НЕ обещай никакие особые/персональные условия, "
            "спеццены или скидки — данных на это НЕТ. Вместо этого напиши, что уточнишь наличие по "
            "датам/модели у команды и вернёшься. Других утверждений о наличии, дефиците или "
            "спецпредложениях не пиши.")


def availability_fallback(model=None, ds=None, de=None, lang: str = "ru") -> str:
    """Детерминированный безопасный фолбэк, если перегенерация не смогла: обещаем проверить наличие
    и вернуться, без утверждений о складе/дефиците/скидках. Сам не содержит клеймов наличия."""
    who = (" " + str(model)) if model else ""
    if lang == "en":
        return f"Let me check availability{who} for your dates with the team and get back to you."
    return f"Уточню наличие{who} по вашим датам у команды и вернусь."


def guard_availability(draft: str, avail=None, model=None, ds=None, de=None, lang: str = "ru",
                       regenerate=None, max_retries: int = 2, window=None) -> dict:
    """Гард ПЕРЕД отправкой: черновик не должен УТВЕРЖДАТЬ наличие/дефицит/особые условия без данных.
    Нет клеймов наличия → отдаём черновик как есть (source='clean'). Клеймы, подтверждённые данными
    Bridge (avail) → как есть (source='draft'). Клейм БЕЗ данных → лог + перегенерация с жёсткой
    директивой (regenerate(directive)->str, до max_retries раз); после N неудач → безопасный фолбэк
    (source='fallback'). Возвращает dict(text, ok, source∈{clean,draft,regen,fallback}, attempts,
    violations). По образцу удалённого guard_quote_price (#310)."""
    state = availability_state(avail)
    claims = availability_claims(draft)
    if not claims:
        return {"text": draft, "ok": True, "source": "clean", "attempts": 0, "violations": []}
    bad = _av_unsupported(claims, state)
    if not bad:
        return {"text": draft, "ok": True, "source": "draft", "attempts": 0, "violations": []}

    def _log(stage, items, text):
        log.warning(
            "guard_availability VIOLATION [%s] окно=%s модель=%s даты=%s..%s | клеймы=%s | draft=%r",
            stage, window, model, ds, de,
            [{"kind": b["kind"], "raw": b["raw"]} for b in items], (text or "")[:200])

    _log("initial", bad, draft)
    directive = _availability_hard_directive(lang)
    attempts, last_bad = 0, bad
    if callable(regenerate):
        for _ in range(max(0, int(max_retries))):
            attempts += 1
            try:
                cand = regenerate(directive)
            except Exception:
                log.warning("guard_availability: перегенерация упала (окно=%s), попытка %s", window, attempts)
                break
            cand_bad = availability_violations(cand, avail)
            if not cand_bad:
                return {"text": cand, "ok": True, "source": "regen", "attempts": attempts,
                        "violations": bad}
            last_bad = cand_bad
            _log(f"regen#{attempts}", cand_bad, cand)

    fb = availability_fallback(model, ds, de, lang)
    log.warning("guard_availability: после %s попыток → безопасный фолбэк (окно=%s): %r",
                attempts, window, fb)
    return {"text": fb, "ok": bool(fb), "source": "fallback", "attempts": attempts,
            "violations": last_bad}


# ============ ПОЯС ОБЯЗАТЕЛЬНОГО УПОМИНАНИЯ ОПЫТА/МЕНЕДЖЕРА (23.08.2026) ============
# ЗЕРКАЛО ПОЯСА НАЛИЧИЯ, повёрнутое на 180°: тот ловит СКАЗАННОЕ ЛИШНЕЕ (клейм наличия без данных),
# этот — НЕСКАЗАННОЕ ОБЯЗАТЕЛЬНОЕ (упоминание опыта/менеджера там, где наставление его требует).
# Сам пояс наличия НЕ переделывается ни строкой: он закрыт и проверен, здесь он только образец.
#
# ЗАБОР ЧЕСТЕРТОНА ОТВЕЧЕН ИСТОРИЕЙ, и ответ ДРУГОЙ, чем у наличия. У наличия гард был написан
# 15.07 (9c45837) и не подключён. Здесь ВЕТКИ НЕ БЫЛО НИКОГДА: правило живёт только в наставлении
# (`EXPERIENCE_SAFETY_RULE`, внесено 8cd68a6 от 06.07 вместе с голденами A.2/A.3 и БЕЗ единой
# строки кода), а поиск по всей истории имён `guard_experience` / `enforce_experience` /
# `ensure_experience` / `experience_mention` даёт НОЛЬ коммитов. Снимать нечего — заводим впервые.
#
# ЗАЧЕМ (живой замер 23.08). Тренажёр на 8 прогонах ОДНОГО коммита `1ded105` дал одно красное:
# кейс 5 (A.3), чек «обязательное упоминание». Правило исполнялось примерно 5 раз из 6, и на каком
# кейсе сорвётся — дело случая: до починок тем же чеком краснел кейс 6 (A.2). То есть дефект в
# ПРАВИЛЕ, а не в кейсе, и настроение головы обязано перестать быть его носителем.
#
# ГРАНИЦЫ ВЕТКИ ВЫБРАНЫ ЗАМЕРОМ, А НЕ ВКУСОМ (96 сохранённых живых черновиков, 8 прогонов × 12):
#   • «первый контакт + про опыт не говорили» — сработало бы на 69 черновиках из 96. Отвергнуто:
#     это переписывание половины продукта, и оно прямо спорит с самим наставлением («Вопрос об
#     опыте НЕ заменяет выдачу прайса»);
#   • то же, сужённое до «клиент ещё ничего не назвал» — 8 из 96, и все восемь садятся на кейс 4
#     («только про депозит»), чья суть — НЕ вываливать лишнего. Тоже отвергнуто;
#   • ОСТАВЛЕНО: клиент ЯВНО без опыта (`_HEAVY_BLOCK_RE` — уже существующий детектор ручки
#     тяжёлого класса, «без опыта/новичок/впервые/никогда не ездил/beginner/never ridden»).
#     Срабатывание — 1 черновик из 96, и это РОВНО тот, что покраснел в прогоне 28.
# Вторая половина жёсткого правила («просит мощный/крупный байк БЕЗ подтверждённого опыта») здесь
# НЕ покрыта честно и намеренно: детектора «мощность/размер» отдельно от «опыта» в коде нет —
# `_HEAVY_OK_RE` мешает их в одной альтернативе, и разделение было бы новым детектором, а не
# зеркалом. Названо как остаток, а не замолчано.
#
# СЛОВАРЬ — ИЗ НАСТАВЛЕНИЯ, А НЕ ИЗ ЧЕКА. Правило говорит «мягко уточни опыт (на чём и как долго
# ездил) И/ИЛИ скажи, что подберёшь вариант вместе с МЕНЕДЖЕРОМ», и «вывод даёт ТОЛЬКО менеджер».
# Поэтому носителей два: разговор про ОПЫТ либо передача ЧЕЛОВЕКУ, названному менеджером/коллегой.
# Слово «команда» в носители НЕ входит сознательно: клиенту оно не сообщает, что решение примет
# человек-специалист, и именно им прогон 28 подменил обязательное упоминание («уточню детали у
# команды»). Совпадение с корпусом тренажёрного чека — следствие общего источника (кейс 5 снят с
# голдена A.3 дословно), а не подгонка под измеритель: чек не ослаблен и не тронут ни строкой.
#
# СРАВНЕНИЕ ПО СЛОВУ — уже введённым правилом `word_hit` (23.08), второго не заводим: токены здесь
# КОРНИ («опыт», «ездил», «менеджер»), им нужна левая граница и открытый хвост.
_MENTION_EXPERIENCE = ("опыт", "ездил", "ездит", "катал", "водил", "стаж", "управлял",
                       "на чём", "на чем", "как долго",
                       "experience", "ridden", "riding", "rode", "how long")
_MENTION_HUMAN = ("менеджер", "коллег", "manager", "colleague")


def experience_rule_applies(transcript: str, is_first_contact=None, facts: dict = None,
                            sheet_mode: bool = False) -> str:
    """Наставление ТРЕБУЕТ обязательного упоминания в этом диалоге? → '' | 'a3' | 'a2'.

    Строка, а не bool, СОЗНАТЕЛЬНО: половин у правила две, и им нужны РАЗНЫЕ слова (см.
    `mention_fallback`). Пустая строка ложна, поэтому все прежние вызывающие `if applies:` и
    `assertFalse` работают как работали.

    'a3' — ЖЁСТКОЕ правило безопасности `EXPERIENCE_SAFETY_RULE`: клиент САМ сказал, что опыта нет
        («без опыта», «новичок», «впервые», «никогда не ездил», beginner, never ridden) — детектор
        `_HEAVY_BLOCK_RE`, уже стоявший в коде. Ветка не тронута ни на символ.

    'a2' — ФОРМА ПЕРВОГО ОТВЕТА. До 25.08.2026 она была СТИЛЕВОЙ (первая пара
        `STYLE_FEWSHOT_PAIRS`, взятая из живой базы переписок), и пояс её не держал. РЕШЕНИЕ
        ВЛАДЕЛЬЦА 25.08.2026: спросить про опыт в первом ответе — требование БЕЗОПАСНОСТИ, а не
        стиль, поэтому половина поднята до жёсткой. Живой повод: 25.08 первый же прогон через
        штатный канал ворот стал КРАСНЫМ ровно на ней (кейс 6, чек «обязательное упоминание»,
        11 кейсов из 12) — голова спросила даты и срок и не спросила про опыт.

    ГРАНИЦА 'a2' — САМАЯ УЗКАЯ ИЗ ПОСЧИТАННЫХ, которая закрывает этот случай (замер по 96
    сохранённым живым черновикам, `docs/artifacts/2026-08-25-a2-experience-rule-fork.md` §5):
      • широкая «первый контакт + про опыт не говорили» — 80 черновиков под веткой, дописала бы
        72: спорит и с «вопрос об опыте НЕ заменяет выдачу прайса», и с «не вываливать лишнего»;
      • средняя «+ модель не названа и прайс не просят» — 16 под веткой, дописала бы 8, и ВСЕ 8
        садятся на кейс 4 «Требуется ли депозит?», чья суть — не вываливать лишнего;
      • ВЗЯТАЯ «+ клиент НАЗВАЛ СРОК» — включается ровно на кейсе 6 из двенадцати, 8 черновиков
        под веткой, дописок в корпусе 0. Срок без модели и без просьбы прайса — это и есть
        «подбери мне что-нибудь», а подбирать, не зная опыта, наставление запрещает.
    Каждое условие ниже отсекает СВОЁ правило, и снять любое значит нарушить именно его:
      • «про опыт не говорили» держит «не вываливать лишнего» — переспрашивать того, кто уже
        назвал опыт, запрещено (то же, что `ANTI_LOOP_NOTE`: «уже названный опыт — бери оттуда»);
      • «прайс не просят» держит «вопрос об опыте НЕ заменяет выдачу прайса»;
      • «модель не названа» + «срок назван» отделяют просьбу ПОДОБРАТЬ от узкого вопроса.

    `is_first_contact` — если не передан, выводится из транскрипта отсутствием строк `[менеджер]:`
    (та же посылка, что у `trainer.has_manager_turn`). Fail-safe: пустой вход → '' , пояс молчит.
    """
    tr = transcript or ""
    client = _client_text(tr)
    if _HEAVY_BLOCK_RE.search(client):
        return "a3"
    if is_first_contact is None:
        is_first_contact = not any(ln.startswith("[менеджер]:") for ln in tr.splitlines())
    if not is_first_contact:
        return ""
    if _HEAVY_OK_RE.search(client):
        return ""                                  # клиент САМ заговорил про опыт — не переспрашиваем
    f = facts if facts is not None else collected_facts(tr)
    if f.get("model"):
        return ""                                  # модель названа — это не просьба подобрать
    if sheet_mode or _asks_price_sheet(client, client):
        return ""                                  # просит прайс — опыт его не заменяет
    return "a2" if f.get("term") else ""            # срок назван → «подбери что-нибудь на срок»


def _branch(applies) -> str:
    """Вердикт `experience_rule_applies` → имя половины. bool принимается как 'a3' (совместимость
    с вызывающими, заведёнными 23.08, когда половина была одна)."""
    s = str(applies or "") if not isinstance(applies, bool) else ("a3" if applies else "")
    return s if s in ("a2", "a3") else ("a3" if applies else "")


def mention_hits(draft: str, branch: str = "a3") -> list:
    """Носители обязательного упоминания, найденные в КЛИЕНТСКОМ теле черновика → список токенов.
    Служебные пометки модератору ([уточнить: …]/[собрано: …]) в счёт НЕ идут: клиент их не видит,
    и зачесть их значило бы отчитаться работой, которой клиент не получил.

    ПОЛОВИНЫ ПРАВИЛА СЧИТАЮТ РАЗНОЕ, и это не придирка (25.08.2026): у 'a3' носителей два —
    разговор про ОПЫТ ЛИБО передача МЕНЕДЖЕРУ (так и говорит жёсткое правило: «уточни опыт И/ИЛИ
    скажи, что подберёшь вместе с менеджером»), а у 'a2' носитель ОДИН — только про ОПЫТ. Проверено
    дословно: фраза «Подберём подходящий вариант вместе с менеджером» удовлетворяет кейс 5 и НЕ
    удовлетворяет кейс 6, у которого в `require_any` нет слова «менеджер» вовсе. Считать их
    одинаково значило бы отчитаться работой, которой клиент не получил."""
    low = client_facing_text(draft or "").lower()
    toks = _MENTION_EXPERIENCE if str(branch or "") == "a2" else (_MENTION_EXPERIENCE + _MENTION_HUMAN)
    return [t for t in toks if word_hit(t, low)]


def mention_violation(draft: str, applies) -> bool:
    """Правило применимо, а обязательного упоминания в клиентском теле НЕТ → True.
    `applies` — вердикт `experience_rule_applies` ('' | 'a3' | 'a2'); bool принимается как 'a3'."""
    return bool(applies) and not mention_hits(draft, _branch(applies))


def _mention_hard_directive(lang: str = "ru", branch: str = "a3") -> str:
    """Директива-верхнего-уровня для перегенерации: обязательное упоминание должно ПРОЗВУЧАТЬ
    клиенту, и по-прежнему БЕЗ собственной оценки безопасности (EXPERIENCE_SAFETY_RULE в силе).

    У половины 'a2' директива ДРУГАЯ и она обязана назвать оба ограничения сразу: спросить про
    опыт, но НЕ ценой прайса («вопрос об опыте НЕ заменяет выдачу прайса») и НЕ вторым вопросом
    («на один вопрос — один ответ»)."""
    if str(branch or "") == "a2":
        if lang == "en":
            return ("This is the first reply and the client has not said anything about their "
                    "riding experience. In your reply you MUST ask about it — what they rode and "
                    "for how long — in the SAME sentence flow as the rest, not as a second "
                    "separate question. Keep everything else you were going to say, including any "
                    "price figures: asking about experience does NOT replace giving the price.")
        return ("Это ПЕРВЫЙ ответ, и клиент ничего не сказал про свой опыт вождения. В ответе "
                "ОБЯЗАТЕЛЬНО спроси про него — на чём и как долго ездил — В ТОМ ЖЕ потоке фразы, "
                "а НЕ вторым отдельным вопросом. Всё остальное, что собирался сказать, оставь, "
                "включая цифры цены: вопрос об опыте НЕ заменяет выдачу прайса.")
    if lang == "en":
        return ("The client has said they have no riding experience. In your reply you MUST either "
                "gently ask about their experience (what they rode and for how long) or say you "
                "will pick a suitable option together with the manager and get back — use the word "
                "\"manager\". Do NOT give your own safety or suitability assessment of any model, "
                "do not discourage and do not confirm suitability.")
    return ("Клиент сказал, что опыта вождения у него нет. В ответе клиенту ОБЯЗАТЕЛЬНО должно "
            "прозвучать одно из двух: мягкое уточнение опыта (на чём и как долго ездил) ЛИБО что "
            "подберёшь подходящий вариант вместе с МЕНЕДЖЕРОМ и вернёшься — словом «менеджер», а "
            "не «команда». Собственную оценку безопасности или пригодности модели НЕ давай, не "
            "отговаривай и не подтверждай пригодность.")


def mention_fallback(lang: str = "ru", branch: str = "a3") -> str:
    """Детерминированная дописка ОДНИМ предложением, если перегенерация не смогла. Формулировка
    взята из САМОГО наставления, поэтому читается как обычная фраза менеджера, а не как шов.
    Сама оценок безопасности не содержит.

    У половин РАЗНЫЕ фразы, потому что у них разные носители (см. `mention_hits`):
      • 'a3' — передача человеку (жёсткое правило: «подберёшь вариант вместе с менеджером»);
      • 'a2' — вопрос про ОПЫТ, дословно из первой пары `STYLE_FEWSHOT_PAIRS` (образец взят из
        живой базы переписок с клиентами): «И пару слов про опыт вождения — на чём и как долго
        ездили, так проще подобрать вариант».
    ФРАЗА 'a2' НАМЕРЕННО НЕ ВОПРОС (в ней нет «?»): правило стиля «на один вопрос — один ответ»
    держится кодом `ensure_closing_question`, который дописывает завершающий вопрос ТОЛЬКО когда
    его нет. Второй вопрос нарушил бы это правило, а просьба «и пару слов про…» — нет, и ровно так
    оба требования стоят рядом в самом образце наставления."""
    if str(branch or "") == "a2":
        if lang == "en":
            return ("And a couple of words about your riding experience — what you rode and for "
                    "how long, so it is easier to pick the right option.")
        return ("И пару слов про опыт вождения — на чём и как долго ездили, так проще подобрать "
                "вариант.")
    if lang == "en":
        return "Let me pick a suitable option together with our manager and I'll get back to you."
    return "Подберём подходящий вариант вместе с менеджером — вернусь с предложением."


def _append_to_client_body(draft: str, sentence: str) -> str:
    """Дописать предложение в КЛИЕНТСКОЕ тело — ПЕРЕД служебными пометками модератору, а не в самый
    хвост карточки. Иначе фраза встала бы после «[собрано: …]» и читалась бы швом. Пустой вход или
    пустое предложение → черновик БАЙТ-В-БАЙТ (fail-safe)."""
    if not (draft or "").strip() or not (sentence or "").strip():
        return draft
    lines = draft.splitlines()
    cut = len(lines)
    while cut > 0 and (not lines[cut - 1].strip() or _SERVICE_NOTE_LINE_RE.match(lines[cut - 1])):
        cut -= 1
    body, tail = lines[:cut], lines[cut:]
    if body and body[-1].strip():
        body[-1] = body[-1].rstrip() + " " + sentence.strip()
    else:
        body.append(sentence.strip())
    return "\n".join(body + tail)


def guard_experience_mention(draft: str, applies: bool = False, lang: str = "ru",
                             regenerate=None, max_retries: int = 2, window=None) -> dict:
    """Пояс ПЕРЕД отправкой: там, где наставление требует упоминания опыта/менеджера, оно обязано
    ПРОЗВУЧАТЬ клиенту. Правило неприменимо ИЛИ упоминание есть → черновик как есть (source='clean'
    / 'draft'). Нет → перегенерация с жёсткой директивой (до max_retries раз), и лишь затем
    детерминированная дописка одним предложением (source='fallback').

    ПОЧЕМУ ПЕРЕГЕНЕРАЦИЯ ПЕРВОЙ, А ДОПИСКА ВТОРОЙ. Дописка обязана читаться естественно, а не швом:
    голова вплетает упоминание в СВОЙ ответ («раз опыта пока не было, подберём вариант вместе с
    менеджером»), а код может только приклеить готовую фразу в конец. Поэтому естественный путь —
    основной, а шов — страховка на случай, когда голова недоступна или упрямится. Это ОТЛИЧИЕ ОТ
    ПОЯСА НАЛИЧИЯ, и оно намеренное: там грех — СКАЗАННОЕ лишнее, и безопасный фолбэк ЗАМЕНЯЕТ весь
    черновик; здесь грех — НЕСКАЗАННОЕ, и заменять весь ответ значило бы выбросить правильную часть
    (цену, даты, расчёт). Поэтому фолбэк ДОПИСЫВАЕТ, а не заменяет.

    `applies` — вердикт `experience_rule_applies` ('' | 'a3' | 'a2'); bool принимается как 'a3'.
    Половина ведёт ВСЁ: и что считать носителем, и чем перегенерировать, и что дописать.

    Возвращает dict(text, ok, source∈{clean,draft,regen,fallback}, attempts, missing, branch)."""
    branch = _branch(applies)
    if not branch:
        return {"text": draft, "ok": True, "source": "clean", "attempts": 0, "missing": False,
                "branch": ""}
    if mention_hits(draft, branch):
        return {"text": draft, "ok": True, "source": "draft", "attempts": 0, "missing": False,
                "branch": branch}

    log.warning("guard_experience_mention VIOLATION [initial/%s] окно=%s | обязательного упоминания "
                "нет | draft=%r", branch, window, (draft or "")[:200])
    directive = _mention_hard_directive(lang, branch)
    attempts = 0
    if callable(regenerate):
        for _ in range(max(0, int(max_retries))):
            attempts += 1
            try:
                cand = regenerate(directive)
            except Exception:                                    # noqa: BLE001 — голова недоступна
                log.warning("guard_experience_mention: перегенерация упала (окно=%s), попытка %s",
                            window, attempts)
                break
            if mention_hits(cand, branch):
                return {"text": cand, "ok": True, "source": "regen", "attempts": attempts,
                        "missing": True, "branch": branch}
            log.warning("guard_experience_mention VIOLATION [regen#%s/%s] окно=%s | draft=%r",
                        attempts, branch, window, (cand or "")[:200])

    out = _append_to_client_body(draft, mention_fallback(lang, branch))
    log.warning("guard_experience_mention: после %s попыток → дописка одним предложением (%s, "
                "окно=%s)", attempts, branch, window)
    return {"text": out, "ok": bool(mention_hits(out, branch)), "source": "fallback",
            "attempts": attempts, "missing": True, "branch": branch}


# ===================== ГАРД ГОДА ВЫПУСКА В КЛИЕНТСКОМ ТЕЛЕ (31.07.2026) =====================
# Пара к GEN_DEFAULT_RULE промпта («поколение несёт МЕТКА New Gen, года выпуска НЕ пиши») —
# детерминированная страховка ПЕРЕД карточкой, тем же классом, что enforce_vehicle_word/
# strip_greeting_for_window. Промпта оказалось мало: живой черновик id=292 (окно 529849022,
# 14.07, status=posted) назвал год ДВАЖДЫ и своей волей — КОД-блоков в его pricing_note не было:
#     XMAX 300 (2020-2022) | 5 дней: 2965 бат …
#     XMAX 300 New Gen (2023+) | 5 дней: 3520 бат …
# ДОСЛОВНЫЕ БЛОКИ КОДА (quote/сетка/доставка) не трогаем: их печатает КОД из Календаря, год из
# сырого имени юнита там снят ещё на сборке (_scrub_gen_year, :4358/:4376), а побайтовая сверка
# «строка J дословно»/«сетка прайса дословно» обязана сойтись — правка блока красила бы её.

def enforce_no_gen_year(draft: str, pricing_note: str = "", window=None) -> str:
    """Год выпуска поколения из ТЕКСТА МОДЕЛИ вон (поколение несёт метка «New Gen», не год).
    Дословные блоки КОДА пропускаем байт-в-байт. Года в тексте нет → вход БАЙТ-В-БАЙТ (fail-safe)."""
    text = draft or ""
    if not text.strip() or not _GEN_YEAR_RE.search(text):
        return draft
    protected = set()
    for get in (_sheet_block_from_note, _quote_block_from_note, _delivery_block_from_note):
        try:
            blk = get(pricing_note or "") or ""
        except Exception:                       # noqa: BLE001 — гард не имеет права ронять черновик
            blk = ""
        if blk.strip() and blk.strip() in text:
            protected.update(ln.strip() for ln in blk.split("\n") if ln.strip())
    out, removed = [], []
    for ln in text.split("\n"):
        if ln.strip() in protected or not _GEN_YEAR_RE.search(ln):
            out.append(ln)
            continue
        removed += _GEN_YEAR_RE.findall(ln)
        lead = ln[:len(ln) - len(ln.lstrip())]        # отступ строки сохраняем: _scrub_gen_year strip-ает
        out.append(lead + _scrub_gen_year(ln))
    if not removed:
        return draft
    log.warning("enforce_no_gen_year окно=%s: год выпуска вырезан из клиентского тела — %s",
                window, ", ".join(removed))
    return "\n".join(out)


def generate_draft(transcript: str, lang: str, faq: str,
                   is_first_contact: bool = False, pricing_note: str = "", call_llm=None,
                   park_models=None, playbook: str = "", is_partner: bool = False) -> str:
    """Сгенерировать черновик. call_llm(system, user)->str инъектируется в тестах; иначе по флагу
    SUGGEST_LLM_VIA_CLI — claude CLI (подписка Max) либо _default_llm (платный API-ключ).
    park_models — allowlist моделей реального парка (Лист1); None → без ограничения (fail-safe).
    playbook — книга правил (ниже кап-цены/критфактов); '' → без блока (fail-safe).
    is_partner — партнёрский чат (шаг 3/6 #4): доставку от нашего лица не подтверждаем; дефолт
    False → регресс байт-в-байт."""
    call_llm = call_llm or (_cli_llm if SUGGEST_LLM_VIA_CLI else _default_llm)
    # §243/6: что клиент УЖЕ прислал (модель/даты/гео/паспорт/тел/оплата) — не переспрашиваем.
    facts = collected_facts(transcript)
    ready = client_ready_to_book(transcript)
    just = client_just_provided(transcript)     # названное В ТЕКУЩЕЙ реплике — переспрос запрещён
    sheet_mode = _sheet_block_from_note(pricing_note) is not None or "ПРАЙС ПО ПАРКУ" in (pricing_note or "")
    # Тип ТС — по тексту треда (шаг 2/6 #4): дефолт «байк» не хардкодим. Направляет модель ДО
    # генерации через промпт-блок «ТИП ТС»; на финале enforce_vehicle_word текст НЕ правит, а вешает
    # служебную пометку модератору, если модель всё равно предложила байк на авто-запросе (28.07).
    vehicle_type = detectVehicleType(transcript)
    system = make_system_prompt(faq, lang, is_first_contact, pricing_note,
                                park_models=park_models, playbook=playbook, collected=facts,
                                ready=ready, just=just, vehicle_type=vehicle_type, is_partner=is_partner)
    out = _strip_service_prefix(call_llm(system, transcript))
    # Пост-чек ДО сборки сетки: сканируем LLM-текст (intro/outro), дословный прайс-блок КОДА не
    # трогаем. Утверждения цвет/наличие/цена вне белого списка → «уточню»-форма + пометка модератору.
    out = postcheck_draft(out, lang, pricing_note=pricing_note, call_llm=call_llm, transcript=transcript)
    # Забор бесплатный ТОЛЬКО при оплаченной доставке: снимаем самопротиворечие «заберём бесплатно —
    # заберите сами» из LLM-текста ДО приклейки КОД-блока доставки (там забор при оплате легитимен).
    out = postcheck_free_pickup(out, lang)
    # Сетка = неприкосновенный блок: финал собирает КОД (intro + render ДОСЛОВНО + outro).
    block = _sheet_block_from_note(pricing_note)
    if block is not None:
        out = compose_sheet_draft(out, block, lang)
    # Точечный quote: цену Bridge в финал доносит КОД (fail-safe, если LLM её не привёл).
    qblock = _quote_block_from_note(pricing_note)
    if qblock is not None:
        out = compose_quote_draft(out, qblock, lang)
    # Цену доставки (если резолвер её посчитал) в финал доносит КОД тем же классом, что quote.
    dblock = _delivery_block_from_note(pricing_note)
    if dblock is not None:
        out = compose_delivery_draft(out, dblock, lang, transcript=transcript)
    # Тариф доставки, уже названный в этом окне и не изменившийся, второй раз не звучит.
    out = drop_repeated_delivery(out, transcript, lang)
    # ЦЕНА ПОСЧИТАНА → цифра обязана звучать клиенту, а отписке «уточню и вернусь» места нет
    # (живые ТЕСТ-7/ТЕСТ-10). Порядок: сперва донести цифру, потом снять отписку — иначе
    # «уточню…» вырезалось бы у ответа, где цены ещё нет в теле.
    out = ensure_price_figure(out, pricing_note, lang)
    out = drop_price_deflection(out, pricing_note, lang)
    # ТЕСТ-10: вопрос про уже собранное — вон; ТЕСТ-7: вопроса нет вовсе — КОД дописывает ровно один.
    out = drop_answered_questions(out, facts, lang)
    out = ensure_closing_question(out, facts, lang, sheet_mode=sheet_mode, ready=ready, just=just)
    # Деньги ВСЕХ валют — по ГОТОВОМУ тексту (после дописок КОДА): противоречие «одна роль — разные
    # суммы» и сумма из головы → ПОМЕТКА модератору. Текст не трогаем (живой случай 204/205: USDT
    # проходил насквозь, потому что денежный разбор знал только баты).
    out = postcheck_money(out, pricing_note, transcript, lang)
    out = _append_collected_note(out, facts, lang, unconfirmed_fields(transcript, facts))
    out = _append_season_note(out, pricing_note)
    # Год выпуска поколения из текста МОДЕЛИ вон (живой id=292): дословные блоки КОДА не трогаем.
    out = enforce_no_gen_year(out, pricing_note)
    # Тип ТС ПОСЛЕДНИМ шагом (после дописок КОДА): на 'car'-треде с байком в тексте — ПОМЕТКА
    # модератору, текст черновика не трогаем (слепая замена слова снята 28.07).
    out = enforce_vehicle_word(out, vehicle_type, lang)
    # Гард партнёрского чата — САМЫМ последним (поверх всех дописок/страховок): утверждающе-
    # организующую доставку от нашего лица → уточняющий вопрос партнёру без обязательств.
    out = enforce_partner_delivery_guard(out, is_partner, lang)
    # ГАРД НАЛИЧИЯ ПЕРЕД ОТПРАВКОЙ (включён 23.08.2026). Гард написан 15.07 (коммит 9c45837,
    # шаг 4/6 родителя #365) вместе с юнитами и с тех пор НЕ ВЫЗЫВАЛСЯ в продукте ни одной
    # строкой — не «отключён», а не подключён: ни один коммит истории вызова не удалял, три
    # документа (17.08, 20.08, 21.08) фиксируют то же состояние без решения владельца.
    # Наличие берём ЕДИНСТВЕННЫМ носителем — дословной фразой, которую печатает сам КОД под
    # `if q.get("available")` (availability_from_note): текст головы, повторивший ПРАВДУ кода,
    # проходит как есть (source='draft'), а клейм БЕЗ этого носителя → перегенерация с жёсткой
    # директивой и лишь затем безопасный фолбэк. Перегенерация даётся ОБЯЗАТЕЛЬНО: без неё первый
    # же клейм менял бы ответ на отписку вместе с посчитанной ценой (курс 28.07 «пометка вместо
    # слепой замены»); regenerate_draft гарда в себе не несёт — рекурсии нет, попыток максимум две.
    # Замер до включения: на 84 живых черновиках 12 кейсов гард сработал бы 0 раз.
    def _regen_without_claim(hard_directive):
        return regenerate_draft(transcript, lang, faq, is_first_contact, pricing_note,
                                hard_directive, call_llm=call_llm, park_models=park_models,
                                playbook=playbook, is_partner=is_partner)

    # ПОЯС ОБЯЗАТЕЛЬНОГО УПОМИНАНИЯ (23.08.2026) — ПЕРЕД гардом наличия, а не после, и это
    # намеренный порядок: последнее слово остаётся за гардом наличия (жёсткое правило безопасности,
    # закрыто и проверено), поэтому текст, перегенерированный ради упоминания, всё равно проходит
    # его проверку. Цена порядка названа честно: если гард наличия уйдёт в свой безопасный фолбэк,
    # он ЗАМЕНИТ черновик целиком и упоминание пропадёт вместе с ним. Живая частота этого пути за
    # 8 прогонов × 12 кейсов — 0 (единственное срабатывание гарда наличия, прогон 27, ушло в regen).
    # 25.08.2026 — половин у правила ДВЕ, и вторая ('a2', форма первого ответа) поднята решением
    # владельца из стилевой в ЖЁСТКУЮ. Признаки ей нужны те, что уже посчитаны ВЫШЕ по этой же
    # функции — `is_first_contact`, `facts`, `sheet_mode`: второй раз их не считаем и второго
    # детектора не заводим, иначе они разъедутся с тем, чем живёт остальной ответ.
    out = guard_experience_mention(
        out,
        applies=experience_rule_applies(transcript, is_first_contact=is_first_contact,
                                        facts=facts, sheet_mode=sheet_mode),
        lang=lang, regenerate=_regen_without_claim)["text"]
    return guard_availability(out, avail=availability_from_note(pricing_note), lang=lang,
                              regenerate=_regen_without_claim)["text"]


def regenerate_draft(transcript: str, lang: str, faq: str, is_first_contact: bool,
                     pricing_note: str, directive: str, call_llm=None, park_models=None,
                     playbook: str = "", is_partner: bool = False) -> str:
    """СТРАТЕГИЯ-перегенерация черновика С НУЛЯ: реплика модератора идёт как ДИРЕКТИВА ВЕРХНЕГО
    УРОВНЯ поверх ИСХОДНОГО клиентского контекста (транскрипт+FAQ+кап-цена), а НЕ как патч к старому
    тексту. Инварианты (ценовая политика/критфакты/парк/playbook) сохраняются — они в make_system_prompt."""
    call_llm = call_llm or (_cli_llm if SUGGEST_LLM_VIA_CLI else _default_llm)
    facts = collected_facts(transcript)
    ready = client_ready_to_book(transcript)
    just = client_just_provided(transcript)
    sheet_mode = _sheet_block_from_note(pricing_note) is not None or "ПРАЙС ПО ПАРКУ" in (pricing_note or "")
    # Тип ТС по тексту треда — тот же класс, что в generate_draft (шаг 2/6 #4): дефолт «байк» не хардкодим.
    vehicle_type = detectVehicleType(transcript)
    system = make_system_prompt(faq, lang, is_first_contact, pricing_note,
                                directive=directive, park_models=park_models, playbook=playbook,
                                collected=facts, ready=ready, just=just, vehicle_type=vehicle_type,
                                is_partner=is_partner)
    out = _strip_service_prefix(call_llm(system, transcript))
    # Тот же пост-чек, что в generate_draft (до сборки сетки): цвет/наличие/цена вне данных → «уточню».
    out = postcheck_draft(out, lang, pricing_note=pricing_note, call_llm=call_llm, transcript=transcript)
    # Тот же пост-чек забора, что в generate_draft: бесплатный забор ТОЛЬКО при оплаченной доставке.
    out = postcheck_free_pickup(out, lang)
    # Тот же класс, что в generate_draft: сетку в финал вставляет КОД, не LLM.
    block = _sheet_block_from_note(pricing_note)
    if block is not None:
        out = compose_sheet_draft(out, block, lang)
    # Точечный quote-блок: strategy-перегенерация несёт цену Bridge КОДОМ — не зависит от того,
    # донёс ли LLM цифры (главная цель шага; сетка была покрыта, точечный quote — теперь).
    qblock = _quote_block_from_note(pricing_note)
    if qblock is not None:
        out = compose_quote_draft(out, qblock, lang)
    # Тот же класс: strategy-перегенерация несёт цену доставки КОДОМ (не зависит от LLM).
    dblock = _delivery_block_from_note(pricing_note)
    if dblock is not None:
        out = compose_delivery_draft(out, dblock, lang, transcript=transcript)
    # Тот же класс, что в generate_draft: повтора блока нет, цифра расчёта у клиента, отписки нет,
    # переспроса нет, ответ не заканчивается «в пустоту».
    out = drop_repeated_delivery(out, transcript, lang)
    out = ensure_price_figure(out, pricing_note, lang)
    out = drop_price_deflection(out, pricing_note, lang)
    out = drop_answered_questions(out, facts, lang)
    out = ensure_closing_question(out, facts, lang, sheet_mode=sheet_mode, ready=ready, just=just)
    # Тот же денежный пост-чек всех валют, что в generate_draft: strategy-перегенерация тоже уходит
    # клиенту через карточку — противоречие сумм и число из головы обязаны быть видны модератору.
    out = postcheck_money(out, pricing_note, transcript, lang)
    out = _append_collected_note(out, facts, lang, unconfirmed_fields(transcript, facts))
    out = _append_season_note(out, pricing_note)
    # Гард повторного приветствия ПЕРЕД ОТПРАВКОЙ (родитель #311 → #56): strategy-перегенерация
    # уходит клиенту через карточку модерации МИМО on_client_message, где живёт основной гард.
    # Если в окне уже был наш ответ/автоприветствие Business, а LLM снова поздоровался — срезаем
    # зачин детерминированно (belt поверх промпта «не здоровайся повторно»). Первый контакт
    # (в транскрипте нет строки [менеджер]:) → черновик не трогаем, фирменное приветствие цело.
    out = strip_greeting_for_window(out, transcript)
    # Тот же класс-фикс, что в generate_draft (правило «класс-фикс — сразу на ОБЕ полосы»): год
    # выпуска поколения из текста МОДЕЛИ вон, дословные блоки КОДА не трогаем.
    out = enforce_no_gen_year(out, pricing_note)
    # Тип ТС ПОСЛЕДНИМ шагом (тот же класс, что в generate_draft): на 'car'-треде с байком в тексте —
    # ПОМЕТКА модератору, текст черновика не трогаем (слепая замена снята 28.07).
    out = enforce_vehicle_word(out, vehicle_type, lang)
    # Гард партнёрского чата — САМЫМ последним (тот же класс, что в generate_draft): доставку от
    # нашего лица → уточняющий вопрос партнёру без обязательств.
    return enforce_partner_delivery_guard(out, is_partner, lang)


# ============================ E2E-СМОУК (TEST_MODE) ==========================
# runLiveSmoke — СКВОЗНОЙ e2e-смоук ЖИВОГО контура suggest ПОД TEST_MODE (SUGGEST_TEST_MODE):
# шлёт в ТЕСТОВОЕ окно пробу «модель + даты + якорная maps-ссылка», ждёт готовый черновик и
# проверяет, что транспорт (<<<QUOTE>>>/<<<DELIVERY>>>, #92 и смежные) донёс инварианты:
#   • строка столбца J — ДОСЛОВНО (посимвольно) в черновике клиента;
#   • доставка = цена ЗОНЫ по ссылке (Раваи → 590), а НЕ выдумка/[уточнить];
#   • год поколения (20xx) в клиентское тело не утёк;
#   • при ПОЛНЫХ данных (модель+даты+ссылка) нет отписки «вернусь/уточню и вернусь»;
#   • нет УТВЕРЖДЕНИЙ о наличии без данных Bridge;
#   • депозит без самопротиворечия (одна сумма ЛИБО паспорт, не два значения сразу).
# Провал → status='failed' + КАРТОЧКА с диффом ОЖИДАНИЕ/ФАКТ по каждому провалившемуся чеку
# (её печатает шаг/оркестратор). BEЗОПАСНОСТЬ: смоук пишет ТОЛЬКО в тестовое окно и ТОЛЬКО при
# SUGGEST_TEST_MODE=on; вне TEST_MODE не делает НИЧЕГО (status='skipped') — живого клиента проба
# не касается. send/wait_draft/getter/resolve_delivery/call_llm инъектируются (мок-тесты копируют
# ЖИВОЙ формат прода: позиционные зоны листа + строка столбца J дословно — правило-класс CLAUDE.md).

_SMOKE_MONTHS_GEN = ("", "января", "февраля", "марта", "апреля", "мая", "июня",
                     "июля", "августа", "сентября", "октября", "ноября", "декабря")

# Отписка-реаск «вернусь/уточню и вернусь/пришлю позже» — при ПОЛНЫХ данных это уход от ответа
# (цена и зона уже посчитаны). EN-аналоги тоже. «уточню район?» без «вернусь» не ловим (легитимно).
_SMOKE_REASK_RE = re.compile(
    r"верн[её]мся|вернусь|верн[её]т(?:есь|ся)|"
    r"пришл[юё][^.\n]{0,30}(?:позже|потом|прайс)|напиш[уеё][^.\n]{0,20}позже|"
    r"уточн\w+[^.\n]{0,40}\bверн|подготовл\w+[^.\n]{0,20}(?:позже|отдельно)|"
    r"get\s+back\s+to\s+you|will\s+get\s+back|i['’]?ll\s+get\s+back",
    re.I)


def _smoke_today(today=None):
    return today or today_phuket()


def _smoke_default_probe(today=None):
    """Проба по умолчанию: NMAX 155 на 5 дней (окно СЛЕДУЮЩЕГО месяца, всегда в будущем и в ОДНОМ
    месяце) + якорная ссылка с координатами зоны Раваи (fixtures/delivery_zones_get.live.json:
    [\"Раваи\", 7.771, 98.327, 590, 4] → цена 590). Зона/цена — ожидание чека доставки."""
    d = _smoke_today(today)
    yr = d.year + (1 if d.month == 12 else 0)
    mo = d.month % 12 + 1
    ds = datetime.date(yr, mo, 6)
    de = datetime.date(yr, mo, 11)
    return {"model": "NMAX 155", "iso_start": ds.isoformat(), "iso_end": de.isoformat(),
            "maps_link": "https://www.google.com/maps/place/Rawai+Beach/@7.771,98.327,15z",
            "lang": "ru", "zone": "Раваи", "zone_price": 590}


def _smoke_client_lines(probe):
    """Реплики пробы (БЕЗ транскрипт-префикса — так уходят в живое тестовое окно). ДВА сообщения:
    (1) модель + даты словами, (2) якорная maps-ссылка ОТДЕЛЬНО — как реальный клиент шлёт пин
    самостоятельным сообщением (иначе числа в URL забивают парсер дат — «мок = живой формат»)."""
    ds = datetime.date.fromisoformat(probe["iso_start"])
    de = datetime.date.fromisoformat(probe["iso_end"])
    if ds.month == de.month:
        when = f"с {ds.day} по {de.day} {_SMOKE_MONTHS_GEN[de.month]}"
    else:
        when = (f"с {ds.day} {_SMOKE_MONTHS_GEN[ds.month]} "
                f"по {de.day} {_SMOKE_MONTHS_GEN[de.month]}")
    return [f"Здравствуйте! Хочу арендовать {probe['model']} {when}.",
            f"Вот точка доставки: {probe['maps_link']}"]


def _with_delivery_resolver(resolve_delivery, fn):
    """Выполнить fn(), временно подменив delivery.resolve_delivery_from_text инъекцией (смоук/тесты).
    Без инъекции — как есть (живой Bridge). ВСЕГДА восстанавливает исходный резолвер (finally)."""
    if resolve_delivery is None:
        return fn()
    saved = delivery.resolve_delivery_from_text
    delivery.resolve_delivery_from_text = resolve_delivery
    try:
        return fn()
    finally:
        delivery.resolve_delivery_from_text = saved


def _smoke_local_draft(transcript, probe, getter, resolve_delivery, call_llm, today, faq):
    """Локальный прогон ТОГО ЖЕ кода (build_pricing_note → generate_draft) — дефолт, если живой
    wait_draft не задан (CI/self-contained смоук). Delivery резолвится через инъекцию (позиц. зоны)."""
    lang = probe.get("lang", "ru")

    def _build():
        note = build_pricing_note(extract_booking_hints(transcript, today=_smoke_today(today)),
                                  lang=lang, getter=getter, today=_smoke_today(today))
        return generate_draft(transcript, lang, faq or "", pricing_note=note, call_llm=call_llm)

    return _with_delivery_resolver(resolve_delivery, _build)


def _smoke_expectations(transcript, probe, getter, resolve_delivery, today):
    """Ожидания смоука из ТЕХ ЖЕ живых источников, что питают черновик: строку столбца J и строку
    доставки берём из служебных блоков pricing_note (транспорт), зону/цену — из ЖИВОГО ответа
    резолвера (точка правды), иначе — из пробы (fail-safe)."""
    lang = probe.get("lang", "ru")
    hints = extract_booking_hints(transcript, today=_smoke_today(today))

    def _build():
        return build_pricing_note(hints, lang=lang, getter=getter, today=_smoke_today(today))

    note = _with_delivery_resolver(resolve_delivery, _build)
    zone, zprice = probe.get("zone"), probe.get("zone_price")
    try:
        res = (resolve_delivery or delivery.resolve_delivery_from_text)(probe.get("maps_link"))
    except Exception:
        res = None
    if isinstance(res, dict) and res.get("status") == "zone":
        zone = res.get("zone", zone)
        if isinstance(res.get("price"), (int, float)) and not isinstance(res.get("price"), bool):
            zprice = res.get("price")
    return {
        "j_line": _quote_block_from_note(note),
        # НАЛИЧИЕ — из ТОГО ЖЕ источника, куда его печатает КОД (правка 23.08.2026, третий и
        # последний случай класса «проверяющий получает пустое значение»). Фразу «свободен на эти
        # даты» пишет `_client_price` ровно под `if q.get("available")` (:3458/:3477) — и пишет её
        # В ЗАПИСКУ. До 23.08 читатель брал наличие из служебного quote-блока, а блок кладётся
        # ТОЛЬКО на ветке `ok` (`marker_mode = (kind == "ok" and not pct)`, :5143): ветка `min`
        # (срок короче минимального, :3526) печатает ту же фразу прямо в текст записки и блока не
        # выпускает — и проверяющий получал пустоту при ЖИВОМ носителе. Замер контраста:
        # сутки → блока нет → None при `свободен` в записке; пять дней → блок есть → True.
        # Второй котировки не заводим (это было бы ДРУГОЕ чтение склада в другой миг) — носитель
        # тот же, просто читается целиком. Fail-closed цел: занят → фразы в записке нет вовсе
        # (она под `if`) → None, и отрицание/дефицит/спеццены судятся ровно как прежде.
        "avail": availability_from_note(note),
        "delivery_line": _delivery_block_from_note(note),
        "zone": zone, "zone_price": zprice,
        "full_data": bool(hints.get("model") and hints.get("has_dates") and hints.get("maps_link")),
    }


# Сумму депозита берём ТОЛЬКО у слова-якоря «депозит/залог/deposit» (не по всему тексту: иначе цена
# доставки «590 ฿» из соседней строки ложно зачлась бы депозитом — extract_money_figures ловит «депозит»
# из ПРЕДЫДУЩЕЙ строки в своё окно контекста). «паспорт как депозит» — отдельный якорь.
_SMOKE_DEP_AMOUNT_RE = re.compile(
    r"(?:депозит|залог|deposit)\D{0,14}?(\d[\d\s]{0,6}\d|\d)\s*(?:฿|бат|thb|baht)", re.I)
_SMOKE_DEP_PASSPORT_RE = re.compile(
    r"(?:депозит|залог)[^.\n]{0,16}паспорт|паспорт[^.\n]{0,20}(?:депозит|залог)|"
    r"deposit[^.\n]{0,16}passport", re.I)


# ВЫБОР предложен — это НОРМА, а не конфликт (KB: депозит = деньги ЛИБО паспорт). Живые формы прода
# 31.07: «депозит 3000 ฿ — ПАСПОРТОМ МОЖНО», «МОЖНО оставить паспорт ВМЕСТО денег», разделитель «/»
# из прайс-блока КОДА («Депозит: 3000 ฿ / паспорт»). Слэш ловим ТОЛЬКО вплотную к слову «паспорт»:
# иначе «337 ฿/день» из соседней фразы молча снимал бы НАСТОЯЩУЮ находку.
_SMOKE_DEP_CHOICE_RE = re.compile(
    r"\bили\b|\bлибо\b|\bor\b|вместо\b|instead\b|можн[оа]\b|"
    r"/\s*(?:загран)?паспорт|(?:загран)?паспорт\w*\s*/", re.I | re.U)


def _clause_at(text: str, pos: int) -> str:
    """Клауза (предложение) вокруг позиции: до ближайших «.!?» или перевода строки. Нужна, чтобы
    судить о депозите по ТОЙ ЖЕ фразе, а не по соседней (живой ложняк: «…как вы И хотели»)."""
    s = text or ""
    left = max(s.rfind(ch, 0, pos) for ch in ".!?\n")
    rights = [r for r in (s.find(ch, pos) for ch in ".!?\n") if r != -1]
    return s[left + 1: (min(rights) if rights else len(s))]


def _smoke_deposit_conflict(text) -> str:
    """Противоречие депозита → строка-описание, иначе ''. Конфликт: ДВЕ разные суммы депозита ИЛИ
    сумма депозита и «паспорт» ТРЕБУЮТСЯ ОБА (KB: деньги ЛИБО паспорт, не оба).

    Пара «сумма+паспорт» считается конфликтом, только когда обе стоят В ОДНОЙ клаузе и выбор в ней
    НЕ предложен. Прежняя ветка «есть сумма и где-то есть слово паспорт» давала ложняк на живом
    ОТПРАВЛЕННОМ клиенту тексте id=213 («депозит 3000 ฿ — паспортом можно, всё верно») и на строке
    прайс-блока, которую печатает КОД («Депозит: 3000 ฿ / паспорт»), — то есть красила ровно то
    поведение, которого правило и требует. Ложная находка здесь дороже пропуска: она уходит
    ревизору и порождает цепь, правящую клиентского бота (разбор 31.07, §Гипотеза «(а)»)."""
    s = text or ""
    deps = sorted({int(m.group(1).replace(" ", "")) for m in _SMOKE_DEP_AMOUNT_RE.finditer(s)})
    if len(deps) > 1:
        return "разные суммы депозита: " + ", ".join(f"{v} ฿" for v in deps)
    for m in _SMOKE_DEP_PASSPORT_RE.finditer(s):
        clause = _clause_at(s, m.start())
        amount = _SMOKE_DEP_AMOUNT_RE.search(clause)
        if not amount or _SMOKE_DEP_CHOICE_RE.search(clause):
            continue                          # суммы в этой фразе нет ЛИБО выбор предложен — норма
        return (f"и сумма депозита ({int(amount.group(1).replace(' ', ''))} ฿), "
                f"и «паспорт» одновременно")
    return ""


# ─────────── ОДНО ПРАВИЛО СРАВНЕНИЯ: ПО СЛОВУ, А НЕ ПО КУСКУ СТРОКИ (23.08.2026) ──────────────
# ЗАЧЕМ. Класс «проверка судит по куску строки там, где смысл требует слова» укусил трижды за трое
# суток; последний раз — живьём 23.08: тренажёрный чек «без «опасн»» покраснел на слове
# «безопасным» («подберём вариант, который будет комфортным и БЕЗОПАСНым»), то есть уличил бота
# ровно в том поведении, которого голден A.3 и добивается. Замер по СОХРАНЁННЫМ живым черновикам:
# вхождений «опасн» ровно 1 и оно ЦЕЛИКОМ внутри «безопасн» — 3 прогона из 7
# (docs/artifacts/2026-08-23-trainer-live-gap.md §п.2).
#
# ПРАВИЛО, одно на всех потребителей:
#   • токен обязан НАЧИНАТЬСЯ НА ГРАНИЦЕ СЛОВА — перед ним не стои́т буква, цифра или подчёркивание;
#   • ХВОСТ ОТКРЫТ: токены корпуса — это КОРНИ («опасн», «коллег», «ездил», «менеджер»), и закрытый
#     хвост отменил бы чек целиком («опасно», «опасный» перестали бы ловиться. Это не смягчение
#     ради красоты: закрыть хвост = снять проверку);
#   • ЕДИНСТВЕННОЕ исключение — ЧИСЛА: у числа корня не бывает, «от 3» и «от 30» — разные числа,
#     поэтому токен, КОНЧАЮЩИЙСЯ ЦИФРОЙ, закрывается справа от цифры («5 дней» больше не
#     засчитывается внутри «15 дней», «590» — внутри «5900»).
#
# ЧЕГО ПРАВИЛО НЕ ДЕЛАЕТ (и потому не лечит соседние ложняки): оно не разбирает отрицаний, не
# нормализует ё/е и не судит смысл — только отвечает, слово это или кусок чужого слова. Ложняк
# ревизора на «уже разбираемся» им НЕ снимается: там токен `разбира\w+` ловит ЦЕЛОЕ слово с начала
# слова, и это другой класс (слишком широкий токен), лечится сужением словаря, а не границей.
def word_hit(token, text):
    """Токен найден в тексте КАК СЛОВО (с начала слова), а не как кусок чужого слова. → bool.

    Регистр НЕ трогаем — вызывающий приводит обе стороны сам (так было и до правки).
    Токен, начинающийся не с буквы/цифры (маркер, знак), левой границы не получает: её там нет.
    """
    tok = str(token or "")
    if not tok:
        return False
    left = r"(?<!\w)" if re.match(r"\w", tok) else ""
    right = r"(?!\d)" if tok[-1].isdigit() else ""
    return re.search(left + re.escape(tok) + right, str(text or "")) is not None


def _smoke_checks(draft, exp) -> list:
    """Чеки инвариантов #92 и смежных по ГОТОВОМУ черновику → список dict(name, ok, expected, fact)."""
    client = client_facing_text(draft)
    checks = []

    # 1) строка столбца J — ДОСЛОВНО (посимвольно) в клиентском тексте
    j = exp.get("j_line")
    j_lines = [ln.strip() for ln in (j or "").split("\n") if ln.strip()]
    missing = [ln for ln in j_lines if ln not in client]
    checks.append({
        "name": "строка J дословно",
        "ok": bool(j_lines) and not missing,
        "expected": j if j_lines else "(строка столбца J из quote-блока)",
        "fact": ("quote-блок не собран — цена не доехала" if not j_lines
                 else ("не найдено дословно: " + " | ".join(missing) if missing
                       else "строка J в черновике посимвольно")),
    })

    # 2) доставка = цена ЗОНЫ (Раваи 590), а не выдумка/[уточнить]
    dl = exp.get("delivery_line")
    zprice, zone = exp.get("zone_price"), exp.get("zone")
    # цена зоны — ЧИСЛО, а не кусок строки: «590» внутри «5900 ฿» это ДРУГАЯ цена (правило word_hit)
    dl_ok = bool(dl) and dl in client and zprice is not None and word_hit(str(int(zprice)), dl)
    checks.append({
        "name": "доставка = цена зоны",
        "ok": dl_ok,
        "expected": dl if dl else f"строка доставки с ценой зоны {zone} ({zprice} ฿)",
        "fact": (dl if (dl and dl in client)
                 else ("строки доставки нет в черновике" if dl else "доставка не резолвилась в зону")),
    })

    # 3) год поколения (20xx) в клиентское тело НЕ утёк
    yrs = _GEN_YEAR_RE.findall(client)
    checks.append({
        "name": "нет годов",
        "ok": not yrs,
        "expected": "год поколения (20xx) в тексте отсутствует",
        "fact": ("годы в тексте: " + ", ".join(sorted(set(yrs))) if yrs else "годов нет"),
    })

    # 4) при ПОЛНЫХ данных нет отписки «вернусь/уточню и вернусь»
    m = _SMOKE_REASK_RE.search(client) if exp.get("full_data") else None
    checks.append({
        "name": "нет «вернусь/уточним» при полных данных",
        "ok": m is None,
        "expected": "при полных данных — конкретный ответ без «вернусь/уточню и вернусь»",
        "fact": (f"отписка: «{m.group(0).strip()}»" if m else "отписки нет"),
    })

    # 5) нет УТВЕРЖДЕНИЙ о наличии без данных Bridge. ДАННЫЕ ЕСТЬ ровно тогда, когда цену напечатал
    # КОД: «свободен на эти даты» дописывается в ЦЕНОВУЮ ЗАПИСКУ ТОЛЬКО под `if q.get("available")`
    # (_client_price :3458/:3477), а ветка `ok` выдаётся лишь по СВОБОДНОМУ юниту (pricing:278) —
    # значит наличие в exp["avail"] и есть то самое q["available"], принесённое ЕДИНСТВЕННЫМ
    # носителем, который переходит границу «печать → проверяющий» (второй котировки не заводим:
    # это было бы ДРУГОЕ чтение склада в другой миг). Записка читается ЦЕЛИКОМ, а не служебный
    # quote-блок: блок кладётся только на ветке `ok`, и на ветке `min` (срок короче минимального)
    # проверяющий получал пустоту при ЖИВОМ носителе — см. _smoke_expectations (23.08.2026).
    # Нет фразы → None, как раньше: fail-closed цел, отрицание/дефицит/спеццены судятся как были.
    viol = availability_violations(client, avail=exp.get("avail"))
    checks.append({
        "name": "нет утверждений о наличии",
        "ok": not viol,
        "expected": "наличие/дефицит/особые условия без данных не утверждаются",
        "fact": ("клеймы наличия: " + "; ".join(c["raw"] for c in viol) if viol
                 else "клеймов наличия нет"),
    })

    # 6) депозит без самопротиворечия
    conflict = _smoke_deposit_conflict(client)
    checks.append({
        "name": "депозит без противоречий",
        "ok": not conflict,
        "expected": "депозит один: сумма ЛИБО паспорт, без двух значений",
        "fact": (conflict or "депозит согласован"),
    })
    return checks


def _smoke_card(probe, checks, note=None) -> str:
    """Карточка провала: дифф ОЖИДАНИЕ/ФАКТ по КАЖДОМУ провалившемуся чеку (для шага/оркестратора)."""
    p = probe or {}
    head = (f"проба: {p.get('model')} {p.get('iso_start')}..{p.get('iso_end')} "
            f"зона {p.get('zone')} ({p.get('zone_price')} ฿)")
    lines = ["🧪 E2E-СМОУК ПРОВАЛЕН — дифф ОЖИДАНИЕ/ФАКТ:", head]
    if note:
        lines.append(f"— причина: {note}")
    for c in (checks or []):
        if c.get("ok"):
            continue
        lines.append(f"— [{c['name']}]")
        lines.append(f"    ожидание: {c['expected']}")
        lines.append(f"    факт:     {c['fact']}")
    return "\n".join(lines)


def _smoke_result(status, ok, probe, checks=None, card="", draft="", reason=""):
    return {"status": status, "ok": ok, "probe": probe, "checks": checks or [],
            "card": card, "draft": draft, "reason": reason}


async def runLiveSmoke(*, probe=None, test_window=None, send=None, wait_draft=None,
                       getter=None, resolve_delivery=None, call_llm=None, today=None,
                       faq="", require_test_mode=True) -> dict:
    """Сквозной e2e-смоук ЖИВОГО контура suggest ПОД TEST_MODE. Возвращает dict(status∈{passed,
    failed,skipped}, ok, probe, checks, card, draft, reason). Провал → status='failed' + card
    с диффом ОЖИДАНИЕ/ФАКТ (шаг/оркестратор его печатает и помечает шаг failed).

    send(test_window, text)  — доставка пробы в ТЕСТОВОЕ окно (инъекция; вне неё проба не уходит);
    wait_draft(test_window)  — ожидание готового черновика из живого контура; None → локальный
                               прогон того же кода (getter/resolve_delivery/call_llm — инъекции).
    БЕЗОПАСНОСТЬ: без SUGGEST_TEST_MODE не делаем НИЧЕГО (skipped) — живого клиента не касаемся."""
    if require_test_mode and not SUGGEST_TEST_MODE:
        log.info("runLiveSmoke: SUGGEST_TEST_MODE=off — смоук ПРОПУЩЕН (живого клиента не касаемся).")
        return _smoke_result("skipped", True, None, reason="SUGGEST_TEST_MODE off")

    probe = probe or _smoke_default_probe(today)
    lines = _smoke_client_lines(probe)
    transcript = "\n".join("[клиент]: " + ln for ln in lines)

    # 1) шлём пробу в тестовое окно (только через инъекцию send — иначе проба никуда не уходит).
    # Каждую реплику ОТДЕЛЬНЫМ сообщением — как реальный клиент (пин самостоятельным сообщением).
    if send is not None:
        try:
            for ln in lines:
                await send(test_window, ln)
        except Exception as e:
            reason = f"send упал: {type(e).__name__}: {e}"
            log.warning("runLiveSmoke: %s", reason)
            return _smoke_result("failed", False, probe, card=_smoke_card(probe, [], reason),
                                 reason=reason)

    # 2) ждём готовый черновик (живой контур) ИЛИ локальный прогон того же кода
    try:
        if wait_draft is not None:
            draft = await wait_draft(test_window)
        else:
            draft = _smoke_local_draft(transcript, probe, getter, resolve_delivery, call_llm,
                                       today, faq)
    except Exception as e:
        reason = f"черновик не получен: {type(e).__name__}: {e}"
        log.warning("runLiveSmoke: %s", reason)
        return _smoke_result("failed", False, probe, card=_smoke_card(probe, [], reason),
                             reason=reason)
    if not (draft or "").strip():
        reason = "черновик пуст"
        return _smoke_result("failed", False, probe, card=_smoke_card(probe, [], reason),
                             reason=reason)

    # 3) ожидания из тех же живых источников + 4) чеки инвариантов
    exp = _smoke_expectations(transcript, probe, getter, resolve_delivery, today)
    checks = _smoke_checks(draft, exp)
    ok = all(c["ok"] for c in checks)
    card = "" if ok else _smoke_card(probe, checks)
    if not ok:
        log.warning("runLiveSmoke: ПРОВАЛ\n%s", card)
    return _smoke_result("passed" if ok else "failed", ok, probe, checks=checks, card=card,
                         draft=draft)


# ------------------------------- rate-limit ----------------------------------

class RateLimiter:
    """Лимит отправок: не больше per_hour в час и per_day в сутки. now — инъекция."""

    def __init__(self, per_hour: int, per_day: int, now=time.time):
        self.per_hour = per_hour
        self.per_day = per_day
        self.now = now
        self._sends = []

    def allow(self):
        t = self.now()
        self._sends = [s for s in self._sends if t - s < 86400]
        in_hour = [s for s in self._sends if t - s < 3600]
        if len(self._sends) >= self.per_day:
            return False, f"дневной лимит {self.per_day} исчерпан"
        if len(in_hour) >= self.per_hour:
            return False, f"часовой лимит {self.per_hour} исчерпан"
        return True, None

    def record(self):
        self._sends.append(self.now())


limiter = RateLimiter(RATE_PER_HOUR, RATE_PER_DAY)


# ------------------------------- pending-store -------------------------------

class PendingStore:
    """map moderation_msg_id → {client_id, draft, lang, incoming}. In-memory + durable
    jsonl-журнал событий (add/del), переживает рестарт процесса."""

    def __init__(self, path: str = PENDING_FILE):
        self.path = path
        self._d = {}
        self._load()

    def _load(self):
        try:
            with open(self.path, encoding="utf-8") as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    ev = json.loads(line)
                    if ev.get("ev") == "add":
                        self._d[int(ev["mid"])] = ev["rec"]
                    elif ev.get("ev") == "del":
                        self._d.pop(int(ev["mid"]), None)
        except FileNotFoundError:
            pass
        except Exception as e:
            log.warning(f"SUGGEST: pending _load: {e}")

    def _append(self, obj):
        try:
            with open(self.path, "a", encoding="utf-8") as f:
                f.write(json.dumps(obj, ensure_ascii=False) + "\n")
        except Exception as e:
            log.warning(f"SUGGEST: pending _append: {e}")

    def add(self, mid: int, rec: dict):
        self._d[int(mid)] = rec
        self._append({"ev": "add", "mid": int(mid), "rec": rec})

    def get(self, mid: int):
        return self._d.get(int(mid))

    def pop(self, mid: int):
        rec = self._d.pop(int(mid), None)
        if rec is not None:
            self._append({"ev": "del", "mid": int(mid)})
        return rec


pending = PendingStore()


# ------------------------------- лог обучения --------------------------------

def _edit_diff(draft: str, final: str) -> str:
    """Компактный след правки: '' если не правили, иначе финал (перекрывает черновик)."""
    return "" if (final or "").strip() == (draft or "").strip() else final


def record_pair(rec: dict, path: str = None):
    """Запись пары обучения в suggest_pairs.jsonl:
    {ts, client, lang, incoming, draft, action, final_sent, edit}."""
    path = path or PAIRS_FILE
    try:
        with open(path, "a", encoding="utf-8") as f:
            f.write(json.dumps(rec, ensure_ascii=False) + "\n")
    except Exception as e:
        log.warning(f"SUGGEST: record_pair: {e}")


# ------------------------------- отправка ------------------------------------

async def send_to_client(client, client_id, text, sleep=None, jitter=None):
    """Отправка клиенту с гардами. Возвращает (ok, reason). При флуде — авто-стоп.
    Defense-in-depth: в TEST_MODE отправка клиенту заблокирована и ЗДЕСЬ (второй слой,
    помимо гейта в on_moderation_reply) — чтобы никакой путь не смог написать клиенту."""
    if SUGGEST_TEST_MODE:
        log.info("SUGGEST[TEST_MODE] send_to_client заблокирован — клиенту ничего не уходит.")
        return False, "TEST_MODE"
    sleep = sleep or asyncio.sleep
    jitter = jitter or (lambda: random.uniform(PAUSE_MIN, PAUSE_MAX))

    ok, reason = limiter.allow()
    if not ok:
        log.warning(f"SUGGEST: отправка отклонена — {reason}")
        return False, reason
    # Гард исходящих (шаг 2/5 родитель #55): ЛЮБОЙ текст клиенту чистим от ВНУТРЕННИХ маркеров
    # («Этап N»/«менеджер ещё не назвал»/«собрано»/«[уточнить») СТРОГО ДО фактического send —
    # клиент внутренней кухни сделки видеть не должен. Сработало → в штатный лог (что / окно).
    text = _strip_internal_markers_for_send(text, client_id)
    try:
        async with client.action(client_id, "typing"):
            await sleep(jitter())
            await client.send_message(client_id, text)
    except FLOOD_ERRORS as e:  # FloodWait/PeerFlood → стоп
        disable(f"flood при отправке: {e}")
        return False, "flood"
    except Exception as e:
        log.warning(f"SUGGEST: ошибка отправки: {e}")
        return False, str(e)
    limiter.record()
    return True, None


# ---------------------- оркестрация (зовётся из хендлеров) -------------------

async def post_draft(client, draft: str, client_ref: str):
    """Отправить черновик на модерацию. Есть MOD_GROUP_ID → в группу, иначе в лог.
    Возвращает moderation_msg_id (int) — ключ pending. При логе — синтетический id."""
    header = f"✏️ Черновик ответа клиенту {client_ref}\n(reply: «+»/«да» — отправить, свой текст — правка, «-» — отклонить)\n\n"
    if MOD_GROUP_ID is not None:
        msg = await client.send_message(MOD_GROUP_ID, header + draft)
        return int(getattr(msg, "id", 0))
    # нет группы (или обкатка без группы) — черновик в лог, синтетический id
    mid = int(time.time() * 1000) % 2147483647
    log.info(f"SUGGEST[draft→log mid={mid}] {client_ref}: {draft}")
    return mid


async def post_mod_note(client, text: str):
    """Служебная заметка в группу «Модерация» (НЕ клиенту!). Конец слепоты: любой сбой генерации
    виден сразу в группе, без раскопок лога. Есть MOD_GROUP_ID → в группу, иначе в лог. Не падает."""
    try:
        if MOD_GROUP_ID is not None:
            await client.send_message(MOD_GROUP_ID, text)
        else:
            log.warning(f"SUGGEST[note→log] {text}")
    except Exception as e:
        log.warning(f"SUGGEST: post_mod_note упал: {e} | {text}")


async def resolve_mod_group(client):
    """Если MOD_GROUP_ID пуст и задано MOD_GROUP_NAME — найти группу по title через
    iter_dialogs и подставить её id. Возвращает id или None. Не падает: не нашли →
    лог + None (черновики пойдут в лог, как при отсутствии ID)."""
    global MOD_GROUP_ID
    if MOD_GROUP_ID is not None:
        return MOD_GROUP_ID
    if not MOD_GROUP_NAME:
        return None
    try:
        async for d in client.iter_dialogs():
            title = getattr(d, "title", None) or getattr(d, "name", None)
            if title == MOD_GROUP_NAME:
                MOD_GROUP_ID = int(d.id)
                log.info(f"SUGGEST: MOD_GROUP resolved: {MOD_GROUP_ID} (по имени «{MOD_GROUP_NAME}»).")
                return MOD_GROUP_ID
        log.warning(
            f"SUGGEST: группа «{MOD_GROUP_NAME}» не найдена среди диалогов — "
            f"черновики пойдут в ЛОГ (approve недоступен, отправки клиенту нет)."
        )
    except Exception as e:
        log.warning(f"SUGGEST: resolve_mod_group упал: {e} — черновики в лог.")
    return None


def bot_mode_active():
    """Активен ли бот-модератор (задача-2): есть токен И свежий heartbeat в IPC.
    Нет → деградация в reply-режим userbot (текущее поведение). Без токена IPC не трогаем."""
    if not MODERBOT_TOKEN:
        return False
    try:
        import moderation_ipc
        return moderation_ipc.is_bot_alive()
    except Exception as e:
        log.warning(f"SUGGEST: проверка bot-mode упала ({e}) — деградация в reply-режим.")
        return False


async def poll_and_send(client, sender=None, jitter=None, sleep=None):
    """Исполнитель userbot: разобрать решения бота (status='ready') из IPC и отправить
    клиенту. ЕДИНСТВЕННАЯ точка отправки клиенту в bot-режиме. Double-lock: в TEST_MODE
    send_to_client откажет (сюда 'ready' в TEST_MODE и не должен попасть — бот ставит
    'test_held'). Возвращает число обработанных."""
    if not is_enabled():
        return 0
    try:
        import moderation_ipc
        rows = moderation_ipc.fetch_ready()
    except Exception as e:
        log.warning(f"SUGGEST: poll_and_send: IPC недоступен ({e}).")
        return 0
    n = 0
    _send = sender or send_to_client
    for r in rows:
        final = r.get("final_text") or ""
        if not final:
            moderation_ipc.mark(r["id"], "failed", reason="пустой final_text")
            continue
        ok, reason = await _send(client, r["client_id"], final, sleep=sleep, jitter=jitter)
        moderation_ipc.mark(r["id"], "sent" if ok else "failed", reason=reason)
        record_pair({
            "ts": _now_iso(), "client": r.get("client_ref"), "lang": r.get("lang"),
            "incoming": r.get("incoming"), "draft": r.get("draft"),
            "action": "bot_decision", "final_sent": final if ok else "",
            "edit": _edit_diff(r.get("draft") or "", final), "first_contact": bool(r.get("first_contact")),
            "sent": ok, "reason": reason, "via": "moderation_bot",
        })
        n += 1
    return n


# ------------------- O3-2c: пост «🆕 БРОНЬ» во «Входящие брони» ----------------
# bot-to-bot невидимость: карточку INTAKE не видит бот-аккаунт → постить должен USERBOT
# (этот Telethon user-аккаунт). Адресат — СТРОГО INBOX_GROUP_ID (внутренняя группа), НИКОГДА
# не клиент. С ПК только ПОСТ во «Входящие», НИКАКОЙ прямой записи в CRM. Финальное «да» —
# живой авторизатор в группе. Триггер-префикс поста — «🆕 БРОНЬ».
INBOX_GROUP_ID = int(os.getenv("INBOX_GROUP_ID", "-1003997419806") or "-1003997419806")
INTAKE_POST_PREFIX = "🆕 БРОНЬ"


async def _last_client_photo(client, client_id, limit=50):
    """O3-2.1: последнее ВХОДЯЩЕЕ фото клиента в личке (паспорт шлют на этапе брони) →
    Message | None. Read-only; ЛЮБОЙ сбой → None (fail-safe: пост карточки от фото не зависит)."""
    try:
        msgs = await client.get_messages(client_id, limit=limit)
        for m in msgs:                                # newest-first
            if getattr(m, "photo", None) is not None and not getattr(m, "out", False):
                return m
    except Exception as e:
        log.info(f"SUGGEST: поиск фото у id{client_id} не удался ({type(e).__name__}) — пропуск")
    return None


async def poll_and_post_intake(client, poster=None, group_id=None, photo_finder=None,
                               forwarder=None):
    """Исполнитель userbot: забрать подтверждённые заявки (intake status='pending') и ПОСТ во
    «Входящие брони» этим userbot-аккаунтом. SAFETY: адресат строго INBOX_GROUP_ID (константа),
    zero-out клиента сохранён; постим ТОЛЬКО текст, начинающийся с «🆕 БРОНЬ» (иначе INTAKE не
    распознает). O3-2.1: если в записи есть client_id и клиент присылал фото (паспорт) — фото
    пересылается СРАЗУ ЗА карточкой (окно привязки Splinter 5 мин); нет фото/сбой → как раньше,
    INTAKE-страж честно попросит сам. poster(client, group_id, text)->msg_id,
    photo_finder(client, client_id)->Message|None, forwarder(client, gid, msg) — инъекции для
    тестов. → число обработанных."""
    try:
        import moderation_ipc
        rows = moderation_ipc.fetch_pending_intake()
    except Exception as e:
        log.warning(f"SUGGEST: poll_and_post_intake: IPC недоступен ({e}).")
        return 0
    gid = group_id if group_id is not None else INBOX_GROUP_ID
    n = 0
    for r in rows:
        # СЛОЙ 2 (defense-in-depth к блоку on_client_message): даже если заявка команды как-то
        # доехала до очереди — не постим её во «Входящие брони». intake-строка несёт client_id
        # (без username) → сверяем по id-реестру команды. Помечаем 'skipped', наружу ничего.
        if is_internal_user_id(r.get("client_id")):
            moderation_ipc.mark_intake(r["id"], "skipped", reason="внутренний аккаунт команды (реестр)")
            log.info(f"SUGGEST: intake #{r['id']} от внутреннего id{r.get('client_id')} — "
                     f"пропущен (реестр команды, слой 2).")
            continue
        text = (r.get("text") or "").strip()
        if not text.startswith(INTAKE_POST_PREFIX):   # защита: не тот формат — не постим наружу
            moderation_ipc.mark_intake(r["id"], "failed", reason="текст не начинается с 🆕 БРОНЬ")
            continue
        try:
            if poster is not None:
                mid = await poster(client, gid, text)
            else:
                sent = await client.send_message(gid, text)   # userbot-аккаунт → внутренняя группа
                mid = getattr(sent, "id", None)
            moderation_ipc.mark_intake(r["id"], "posted", posted_msg_id=mid)
            log.info(f"SUGGEST: заявка intake #{r['id']} → Входящие брони (msg {mid}).")
            n += 1
        except Exception as e:
            moderation_ipc.mark_intake(r["id"], "failed", reason=" ".join(str(e).split())[:200])
            log.warning(f"SUGGEST: пост заявки intake #{r['id']} упал: {type(e).__name__}: {e}")
            continue
        # O3-2.1: фото паспорта из диалога — СРАЗУ ЗА карточкой. Best-effort ПОСЛЕ mark posted:
        # сбой пересылки НЕ трогает статус заявки (карточка уже стоит, страж попросит фото сам).
        # SAFETY: forward строго в gid (внутренняя группа), клиенту ничего не шлём.
        cid = r.get("client_id")
        if cid:
            try:
                photo = await (photo_finder or _last_client_photo)(client, cid)
                if photo is not None:
                    if forwarder is not None:
                        await forwarder(client, gid, photo)
                    else:
                        await client.forward_messages(gid, photo)
                    log.info(f"SUGGEST: intake #{r['id']} — фото из диалога переслано за карточкой.")
            except Exception as e:
                log.warning(f"SUGGEST: intake #{r['id']} пересылка фото не удалась "
                            f"({type(e).__name__}) — страж попросит сам.")
    return n


async def on_client_message(client, sender, me_id, call_llm=None, faq=None):
    """Врезка в on_incoming: собрать диалог → черновик → на модерацию.
    bot-режим → в IPC (бот запостит карточку с кнопками); иначе reply-режим (в группу)."""
    if not is_enabled():
        return None
    # ЖЁСТКИЙ блок КОДОМ ДО LLM (слой 1; родитель: инцидент @Pleummmm 15.07 11:23): сообщение
    # от участника команды/внутреннего аккаунта → окно ИСКЛЮЧЕНО из конвейера ЦЕЛИКОМ — НУЛЕВАЯ
    # реакция (ни _fetch_messages, ни generate_draft, ни приветствия, ни intake ниже по потоку).
    if is_internal_sender(sender):
        ref = (f"@{sender.username}" if getattr(sender, "username", None)
               else f"id{getattr(sender, 'id', None)}")
        log.info(f"SUGGEST: внутренний аккаунт команды {ref} — окно вне клиентского конвейера "
                 f"(без черновика/приветствия/intake).")
        return None
    # СЛОЙ 2 (аудит корпуса 29.07, класс 5): окно НЕ клиентское, но и не наша команда — партнёр/
    # контрагент из nonclient_*-реестра. Выход ЗДЕСЬ, ДО _fetch_messages/прайса/generate_draft:
    # черновик не «собирается и прячется», а НЕ СОЗДАЁТСЯ ВОВСЕ — ни одного вызова модели.
    non_client = non_client_window_ref(sender)
    if non_client:
        log.info(f"SUGGEST: неклиентское окно {non_client} — вне клиентского конвейера "
                 f"(без черновика/приветствия/intake).")
        return None
    client_id = sender.id
    client_ref = f"@{sender.username}" if getattr(sender, "username", None) else f"id{sender.id}"
    msgs = await _fetch_messages(client, sender)
    transcript = transcript_from(msgs, me_id)
    # Приветствие ОДИН РАЗ на диалог. Два независимых сигнала из истории окна:
    #  • is_first_bot_reply — это первый ответ бота (нет наших сообщений) И слово-приветствие
    #    ещё не уходило прошлым нашим ответом;
    #  • has_autogreeting — в окне уже было автоприветствие Telegram Business «спасибо, что
    #    выбрали нас…» (класс «е»; _GREETING_RE его не ловит, поэтому нужен отдельный детект).
    # Здороваемся только когда это первый ответ бота И автогритинга не было.
    is_first_bot_reply = first_contact_from(msgs, me_id) and not greeting_already_sent(transcript)
    has_autogreeting = autogreeting_already_sent(transcript)
    first = is_first_bot_reply and not has_autogreeting
    last_client_line = ""
    for ln in reversed(transcript.split("\n")):
        if ln.startswith("[клиент]:"):
            last_client_line = ln[len("[клиент]:"):].strip()
            break
    # Язык — по ВСЕМУ клиенту, не по последней реплике: латинское название модели («Adv 350»)
    # в русском диалоге НЕ должно переключать ответ на EN.
    lang = detect_lang_from_client(transcript)
    faq = faq if faq is not None else load_faq()
    # Двухфазная цена: даты есть → пробуем Календарь (pricing.quote), иначе/None → фолбэк.
    # В ПОТОКЕ (to_thread): построение сетки — живые HTTP-quote; синхронно оно морозило Telethon
    # event loop (живой провал 20:52→20:59: 6м16с заморозки → «Security error… Too many messages
    # had to be ignored» от Telegram). Поток снимает заморозку; сам билд ускорен пулом в price_sheet.
    price_note = await asyncio.to_thread(
        build_pricing_note, extract_booking_hints(transcript), lang=lang)
    try:                                   # allowlist парка (Лист1) + ОТКУДА он взят
        allow, park_src = park_allowlist_status()
    except Exception as e:
        allow, park_src = None, PARK_NONE
        log.info(f"SUGGEST: park_allowlist упал ({type(e).__name__}) — парк считаю НЕполученным")
    if park_src == PARK_NONE:
        # Класс 28.07 09:24: мост отдал 404, парк не получен НИ ОТКУДА, а черновик всё равно
        # собирался — LLM без ограничения моделей мог предложить то, чего в парке нет. Нет данных →
        # нет черновика: клиенту молчим, менеджеру говорим. «Парк реально пуст» (PARK_EMPTY) и
        # «моста в контуре нет» (PARK_UNCONFIGURED) сюда НЕ попадают — это не сбой.
        log.warning(f"SUGGEST: парк НЕ получен для {client_ref} — черновик не собираю")
        await post_mod_note(client, f"⚠️ Черновик НЕ собран для {client_ref}: данные парка "
                                    f"недоступны (ни Bridge, ни снимок park_list.md) — проверьте мост")
        return None
    try:                                   # книга правил; недоступна → '' (fail-safe)
        pb = load_playbook()
    except Exception:
        pb = ""
    # Партнёрский чат (шаг 3/6 #4): признак по имени окна (title/username). Обычный клиентский DM →
    # False (регресс байт-в-байт); партнёрское окно → гард не даёт черновику подтверждать доставку
    # партнёра от нашего лица. Групповую маршрутизацию партнёрок держит вызывающий контур (userbot).
    is_partner = is_partner_chat(sender)
    try:
        draft = generate_draft(transcript, lang, faq, is_first_contact=first,
                               pricing_note=price_note, call_llm=call_llm, park_models=allow,
                               playbook=pb, is_partner=is_partner)
    except Exception as e:   # сбой генератора (напр. claude CLI не найден / API-ошибка) — НЕ молчим
        reason = " ".join(str(e).split())[:200] or type(e).__name__
        log.warning(f"SUGGEST: сбой генерации для {client_ref}: {reason}")
        await post_mod_note(client, f"⚠️ Черновик НЕ сгенерирован для {client_ref}: {reason}")
        return None
    if not draft:            # пустой вывод LLM — раньше молчали, теперь видно в группе (конец слепоты)
        log.warning(f"SUGGEST: пустой черновик для {client_ref} — пропускаю.")
        await post_mod_note(client, f"⚠️ Черновик НЕ сгенерирован для {client_ref}: пустой вывод LLM")
        return None
    # Гард повторного приветствия (родитель #311): LLM порой здоровается вопреки промпту. Если это
    # НЕ первый ответ бота ИЛИ уже было автоприветствие Business — детерминированно срезаем зачин
    # из черновика перед отправкой (belt-and-suspenders поверх промпта «не здоровайся повторно»).
    if (not is_first_bot_reply) or has_autogreeting:
        stripped = strip_greeting(draft)
        if stripped != draft:
            why = "автоприветствие Business в окне" if has_autogreeting else "не первый ответ бота"
            log.info(f"SUGGEST: срезано повторное приветствие в черновике для {client_ref} ({why}).")
            draft = stripped
    # Гвард-модель (шаг 4/7 #274): текст черновика заявляет модель («дам развёрнуто по Nmax»),
    # а карточки прайс-блока — чужой (MT-03) ⇒ черновик врёт о собственном теле. Бракуем ШТАТНЫМ
    # каналом отбраковки-до-модерации (тем же, что сбой/пустая генерация): причина в лог + видимая
    # заметка в группу, карточки/IPC нет — кривой прайс не доезжает ни до модератора, ни до клиента.
    mismatch = model_claim_mismatch(draft, price_note)
    if mismatch:
        log.warning(f"SUGGEST: черновик ЗАБРАКОВАН (гвард-модель) для {client_ref}: {mismatch}")
        await post_mod_note(client, f"🛑 Черновик ЗАБРАКОВАН (гвард-модель) для {client_ref}: {mismatch}")
        return None

    rec = {
        "client_id": client_id, "client_ref": client_ref, "lang": lang,
        "incoming": last_client_line, "draft": draft, "first_contact": first,
        # контекст для СТРАТЕГИЯ-перегенерации (реплика модератора → директива поверх этого):
        "transcript": transcript, "pricing_note": price_note,
        # first_name профиля — для D-колонки карточки «Бронь», если клиент в тексте не назвался:
        "client_name": getattr(sender, "first_name", None),
    }
    # bot-режим: кладём в IPC, карточку с кнопками запостит moderation_bot.
    if bot_mode_active():
        try:
            import moderation_ipc
            did = moderation_ipc.enqueue_draft(rec)
            log.info(f"SUGGEST: черновик #{did} → IPC (bot-режим) для {client_ref}.")
            return f"ipc:{did}"
        except Exception as e:
            log.warning(f"SUGGEST: IPC-enqueue упал ({e}) — деградация в reply-режим.")
    # reply-режим (деградация / бот не поднят): постим в группу сами + pending.
    mid = await post_draft(client, draft, client_ref)
    rec["ts"] = _now_iso()
    pending.add(mid, rec)
    return mid


async def _sender_username(event):
    """Юзернейм автора reply (для проверки прав). Без падения."""
    s = getattr(event, "sender", None)
    if s is None and hasattr(event, "get_sender"):
        try:
            s = await event.get_sender()
        except Exception:
            s = None
    return getattr(s, "username", None)


async def _ack(event, draft_msg_id, text):
    """Видимый ответ userbot'а на сообщение-черновик в ГРУППЕ МОДЕРАЦИИ (не клиенту)."""
    try:
        chat = getattr(event, "chat_id", None)
        if chat is None:
            chat = getattr(getattr(event, "message", None), "chat_id", None)
        await event.client.send_message(chat, text, reply_to=draft_msg_id)
    except Exception as e:
        log.warning(f"SUGGEST: не смог отправить ack модерации: {e}")


async def on_moderation_reply(event, sender=None, jitter=None, sleep=None):
    """Врезка во второй хендлер: reply менеджера в группе модерации → approve/edit/reject.
    NO-SILENT-PATHS: каждый reply получает видимый ответ userbot'а (reply на черновик).
    Права approve/edit/reject — по APPROVER-whitelist. sender/jitter/sleep — инъекция для тестов."""
    if not is_enabled():
        return None
    reply_to = None
    if getattr(event, "is_reply", False):
        reply_to = getattr(event, "reply_to_msg_id", None)
    if reply_to is None:
        return None
    rec = pending.get(reply_to)
    if rec is None:
        return None  # reply не на наш черновик

    # Права: не-approver → ⛔ и НЕ трогаем pending (пусть approver ещё сможет решить).
    username = await _sender_username(event)
    if not is_approver(username):
        await _ack(event, reply_to, "⛔ Нет прав на approve")
        return {"action": "denied", "sent": False, "reason": "not_approver", "final": None}

    action, payload = parse_approval(getattr(event, "raw_text", "") or getattr(event, "text", ""))
    final = None
    sent = False
    reason = None
    if action == "reject":
        ack = "❌ Отклонено"
    else:
        final = rec["draft"] if action == "approve" else payload
        if SUGGEST_TEST_MODE:
            # SAFETY: в TEST_MODE send_to_client НЕ вызываем — клиенту ничего не уходит.
            reason = "TEST_MODE"
            log.info(f"SUGGEST[TEST_MODE] одобрено, НЕ шлю клиенту {rec['client_ref']}: {final}")
            ack = ("🧪 Принято (TEST_MODE — клиенту НЕ отправлено)" if action == "approve"
                   else "✅ Правка принята 🧪 (TEST_MODE — клиенту НЕ отправлено)")
        else:
            _send = sender or send_to_client
            sent, reason = await _send(event.client, rec["client_id"], final, sleep=sleep, jitter=jitter)
            if action == "approve":
                ack = "✅ Отправлено клиенту" if sent else f"⚠️ Не отправлено: {reason}"
            else:
                ack = ("✅ Правка принята — отправлено клиенту" if sent
                       else f"✅ Правка принята, ⚠️ не отправлено: {reason}")

    await _ack(event, reply_to, ack)
    record_pair({
        "ts": _now_iso(), "client": rec["client_ref"], "lang": rec["lang"],
        "incoming": rec["incoming"], "draft": rec["draft"], "action": action,
        "final_sent": final if sent else ("" if action == "reject" else final),
        "edit": _edit_diff(rec["draft"], final or ""),
        "first_contact": rec.get("first_contact"), "sent": sent, "reason": reason, "ack": ack,
    })
    pending.pop(reply_to)
    return {"action": action, "sent": sent, "reason": reason, "final": final, "ack": ack}
